/// C code generator.
///
/// Strategy:
///   • Fully-typed functions (FuncBody.is_typed == true) → pure C functions.
///   • Everything else    → calls routed through the duo Lua runtime shim.
///   • `print(x)` with a typed x is mapped to printf/puts directly.
///   • `math.*` for typed numerics maps to <math.h>.
///
/// The emitted file is a valid, self-contained C99 program ready for
///   clang -O3 -o <out> <file>.c -lm
const std = @import("std");
const Allocator = std.mem.Allocator;
const ast = @import("ast.zig");
const types = @import("types.zig");
const RT = types.ResolvedType;
const term = @import("term.zig");
const sema = @import("sema.zig");
const mono = @import("mono.zig");
const arc = @import("arc.zig");
const async_lower = @import("async_lower.zig");
const comptime_eval = @import("comptime.zig");
const directives = @import("directives.zig");
const meta_directives = @import("meta_directives.zig");
const sema_mod = @import("sema.zig");
const debug_trace = @import("debug_trace.zig");
const ml_kernels = @import("ml_kernels.zig");
const jit = @import("jit.zig");
const subject_home = @import("subject_home.zig");
const meta_codegen = @import("meta_codegen.zig");
const meta_module = @import("meta_module.zig");
const semantic_algebra = @import("semantic_algebra.zig");
const transform_engine = @import("transform_engine.zig");
const meta_dispatch = @import("meta_dispatch.zig");
const backend_identity = @import("backend_identity.zig");
const dynamic_boundary = @import("dynamic_boundary.zig");
const lua_metamethod = @import("lua_metamethod.zig");
const relation = @import("relation.zig");
const collection_relation = @import("collection_relation.zig");
const lexer_bridge = @import("lexer_bridge.zig");
const home_resolve = @import("home_resolve.zig");

/// SH-03: an embedded module tokenizes through the SAME lexer the compile
/// driver uses.
///
/// The production path uses the generated Idol lexer projection. Only
/// `main.zig`'s driver originally routed through it. Every module-embed
/// path below built its own `Lexer` and ran the host scanner, so a single
/// compilation tokenized the entry point with `lib/compiler/lexer.duo` and
/// its `req`-ed modules with `src/lexer.zig`. Two scanners deciding one
/// compilation is the shape that hides a divergence — the embed decision and
/// the driver would disagree about a source and nothing would report it.
///
/// Returns false on a Duo-side REJECTION. That is a malformed source, and the
/// caller must decline the embed rather than continue on a stream it did not
/// get; the host scanner would reject the same bytes a few lines later, in
/// parse, where the diagnostic is worse.
fn openEmbedLexer(src: []const u8, path: []const u8) @import("lexer.zig").Lexer {
    return @import("lexer.zig").Lexer.initFacts(src, path, lexer_bridge.sourceFacts(path));
}

fn routeEmbedThroughDuoLexer(
    alloc: Allocator,
    lex: *@import("lexer.zig").Lexer,
    src: []const u8,
    path: []const u8,
) bool {
    _ = @import("lexer_dispatch.zig").route(alloc, lex, src, path) catch return false;
    return true;
}

pub var native_diag: bool = false;
/// gap[082]: conversions the trie found a route for and the class lattice
/// REFUSED. Counted rather than returned because a refusal is a diagnostic
/// about the program, not a failure of the code generator — but it must still
/// stop the build, or "never silently compose into a lossy conversion" is a
/// comment rather than a rule.
pub var refused_conversions: u32 = 0;
/// `DUO_WHY_CONVERT=1` prints every derived conversion's witness. The witness
/// also ships inside the generated artifact; this is the interactive face of
/// the same fact.
pub var why_convert: bool = false;
/// `DUO_SER=1` reports the relation's semantic expansion ratio WITH ITS N.
pub var ser_census: bool = false;
/// True when the module body assigns `name` at top level (e.g. `M = {}`).
/// Such a global stays live even in native-direct modules: its field writes and
/// the module's `return M` are still emitted, so its declaration must survive.
/// True when every top-level assignment to `name` is a `req`/`require` call —
/// i.e. the binding is only ever declared, never re-assigned. Used ONLY by the
/// embedded-module initializer skip; `module_top_level_assigns` keeps its
/// existing meaning for every other caller.
fn req_decl_is_sole_assignment(mod: *const ast.Module, name: []const u8) bool {
    var saw_decl = false;
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .assign) continue;
        const a = &stmt.assign;
        for (a.targets, 0..) |t, i| {
            if (t.* != .name or !std.mem.eql(u8, t.name.ident, name)) continue;
            if (i >= a.values.len) return false;
            const v = a.values[i];
            if (v.* != .call) return false;
            const c = &v.call;
            if (c.func.* != .name) return false;
            const fname = c.func.name.ident;
            if (!std.mem.eql(u8, fname, "req") and !std.mem.eql(u8, fname, "require")) return false;
            if (c.args.len != 1 or c.args[0].* != .quoted) return false;
            saw_decl = true;
        }
    }
    return saw_decl;
}

fn module_top_level_assigns(mod: *const ast.Module, name: []const u8) bool {
    for (mod.body.stmts) |*stmt| {
        switch (stmt.*) {
            .assign => |*a| for (a.targets) |t| {
                if (t.* == .name and std.mem.eql(u8, t.name.ident, name)) return true;
            },
            // `global x = req "..."` is a declaration, not an assignment, but it
            // is just as live: the module body reads x, so its C declaration
            // must be emitted even in a native-direct module.
            .global_decl => |*gd| {
                if (gd.inits.len == 0) continue;
                for (gd.names) |n| {
                    if (std.mem.eql(u8, n.ident, name)) return true;
                }
            },
            .local_decl => |*ld| {
                if (ld.inits.len == 0) continue;
                for (ld.names) |n| {
                    if (std.mem.eql(u8, n.ident, name)) return true;
                }
            },
            else => {},
        }
    }
    return false;
}

/// A TypeExpr's shape, for a diagnostic. `.named` carries the actual spelling,
/// which is the whole point — "some type is not native" sends a reader looking
/// at the wrong declaration; "ret type: any" does not.
fn typeLabel(t: ast.TypeExpr) []const u8 {
    return switch (t) {
        .named => |n| n,
        .inferred => "inferred",
        else => @tagName(t),
    };
}

pub const CodeGenError = error{
    Unsupported,
    InternalError,
} || Allocator.Error || std.Io.Writer.Error;

pub const E = Allocator.Error || std.Io.Writer.Error || error{NoAllocViolation};

const W = *std.Io.Writer;

const Io = std.Io;

pub const CodeGen = struct {
    alloc: Allocator,
    io: Io,
    type_map: *sema.TypeMap,
    module_globals: ?*const std.StringHashMapUnmanaged(RT) = null,
    /// True while emitting the main module's top-level statements (inside the
    /// generated driver), so module-scope bindings promoted to module globals
    /// are emitted as `duo_g_*` assignments instead of driver locals.
    at_module_top_level: bool = false,
    /// Serial for the per-loop temporaries `while_bound_hoist` introduces, so
    /// two hoisted loops in one function cannot collide on a name.
    while_bound_serial: usize = 0,
    /// Serial for the per-loop temporaries `loop_version_plan` introduces.
    loop_version_serial: usize = 0,
    /// True while emitting the FAST arm of a versioned loop: every dense-table
    /// index in scope has been proved inside `[0, cap)` by a guard the loop is
    /// nested under, so the accessors emit raw indexing. Saved and restored
    /// around the arm; nothing else may set it.
    dense_unchecked: bool = false,
    local_scopes: std.ArrayList(std.StringHashMapUnmanaged(RT)) = .empty,
    comptime_scopes: std.ArrayList(std.StringHashMapUnmanaged(comptime_eval.Value)) = .empty,
    close_scopes: std.ArrayList(std.ArrayListUnmanaged([]const u8)) = .empty,
    arc_scopes: std.ArrayList(std.ArrayListUnmanaged(ArcLocal)) = .empty,
    /// Per-scope stack of pending `defer` bodies, parallel to `local_scopes`.
    /// A `defer ... end` statement registers its body here instead of emitting
    /// it inline; the bodies are flushed in LIFO order at scope exit (Task 12.2).
    defer_scopes: std.ArrayList(std.ArrayListUnmanaged(*const ast.Block)) = .empty,
    break_scope_bases: std.ArrayList(usize) = .empty,
    indent: u32,
    w: W,
    current_ret: RT = .void,
    /// True while emitting module top-level statements into the C `main`
    /// driver. A bare `return` there must yield `return 0;`, not `return;`,
    /// since `main` is `int`-returning. This is what makes Lua/Python-style
    /// implicit entry points (top-level code, no `main` function) work.
    emitting_main_driver: bool = false,
    /// True while emitting an embedded module whose export table (`M.foo = foo`)
    /// names functions. Such a module still hands lua_Values to the parent, so
    /// its `__lua` thunks must be emitted even when it otherwise qualifies as
    /// fully native-scalar.
    embedded_module_exports_funcs: bool = false,
    dense_table: ?[]const u8 = null,
    dense_table_cap: ?[]const u8 = null,
    /// Module-scope dense literal tables (1-based positional keys) lowered to native C arrays.
    native_dense_module_tables: std.StringHashMapUnmanaged(NativeDenseModuleTable) = .empty,
    /// Module-scope literal DESCRIPTORS — `kind = { eof = 0, ident = 1 }` — the
    /// keyed twin of `native_dense_module_tables`. Every field is a scalar
    /// literal and the name is only ever read as `Kind.field`, so the whole
    /// binding is a compile-time constant map: no storage, and each projection
    /// folds to its literal. This is what the direct backend already does
    /// (DNB007); without it the C backend emitted `static lua_Value duo_g_Kind`
    /// into a translation unit that had just decided to declare no runtime.
    native_const_descriptors: std.StringHashMapUnmanaged(NativeConstDescriptor) = .empty,
    /// FUNCTION-LOCAL dense literal tables — the local twin of
    /// `native_dense_module_tables`, and the reason it exists is a silent wrong
    /// answer rather than a missing optimisation.
    ///
    /// A full-native function that binds a table of literals codegen could not
    /// type used to emit `void* glyph = NULL` and DISCARD THE INITIALIZER, then
    /// read every element back as NULL. `examples/boring/roman.id` is exactly
    /// that: `glyph = { "M", "CM", … }` became `void* glyph = NULL`, `g =
    /// glyph(i)` became `void* g = NULL`, and `duo_str_concat(out, g)` reached
    /// `strlen(NULL)` — SIGSEGV 139 with no diagnostic anywhere. The module-level
    /// form of the same table has been lowered natively for some time; only the
    /// function-local one fell through.
    native_dense_local_tables: std.StringHashMapUnmanaged(NativeDenseModuleTable) = .empty,
    /// Dense tables whose literal initializer is entirely FLOAT, where the
    /// upstream classification said integer. `parts = { 1.5, 2.5, 3.5 }` inside
    /// a function emitted `int64_t* __dt_parts` and
    /// `duo_dt_set_i64(&__dt_parts, …, 1, 1.5e0)`: three doubles truncated on
    /// the way into an integer buffer, and `parts(2)` answered 2 instead of 2.5.
    /// No diagnostic, exit 0. The initializer is right here at the declaration,
    /// so the element kind does not have to be taken on trust.
    dense_float_locals: std.StringHashMapUnmanaged(void) = .empty,
    /// Function-local `t = {}` lowered to `t_items[]` + `t_len` (no lua tables).
    native_str_list_locals: std.StringHashMapUnmanaged(void) = .empty,
    /// Function-local `parts = s:split(sep)` in a full-native module. The split
    /// result is an ordinal list of `const char*` plus its backing storage, so
    /// the emitter must name that representation directly instead of refusing an
    /// `.any` binding or reintroducing the Lua table runtime.
    ///
    /// FUNCTION-SCOPED, like `native_str_list_locals` above: saved/restored
    /// around every function body. The first cut kept one module-wide set, and
    /// the guard's "already seen → not mine" check then made the SECOND
    /// `rows = x:split(...)` in a later function refuse with exactly the
    /// "no native representation" error the lowering exists to close — the
    /// registry leaked a binding from one C scope into the next. A binding
    /// re-declared in a new function is a fresh declaration, so presence in
    /// this set is never a reason to bail.
    native_split_str_list_locals: std.StringHashMapUnmanaged(void) = .empty,
    /// Names in the current block that must NOT take the `t_items[]` lowering
    /// because they are used as keyed tables (`t.field = v` / `t["k"] = v`).
    /// Populated per-block before emission; see `note_str_list_disqualifications`.
    str_list_disqualified: std.StringHashMapUnmanaged(void) = .empty,
    /// Local binding name → embedded module C symbol prefix (from `X = req "path"`).
    req_module_bindings: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Req bindings that omit `lua_require` / `duo_g_*` storage (native-direct embedded modules).
    req_native_direct: std.StringHashMapUnmanaged(void) = .empty,
    /// L1 — req module bindings assumed sealed after load unless invalidated.
    module_sealed_bindings: std.StringHashMapUnmanaged(void) = .empty,
    /// L2 — interned field IDs for fallback `.field` access. Field name -> stable
    /// integer ID emitted at every fallback access site (duo_fallback_get_* markers).
    fallback_interned_fields: std.StringHashMapUnmanaged(u32) = .empty,
    /// File paths of embedded modules (dedupe + dependency-first ordering).
    /// Embedded module file path -> the C name its `duo_mod_*` function was
    /// emitted under. Two require names can resolve to the same file (e.g.
    /// `src.wasm` and `src.wasm.init` when the former resolves via the
    /// directory's init.duo); the second must register the cname that actually
    /// exists, not a fresh one derived from its own name.
    embedded_module_paths: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    /// Embedded module path -> whether it was actually emitted in native-scalar
    /// mode. Producer and consumer used to decide this independently and could
    /// disagree: a table-exporting module emitted a real lua table while its
    /// consumer still flattened `m.x` to a native `mod__x` symbol that nothing
    /// defined. This is the single record both sides now read.
    embedded_module_native: std.StringHashMapUnmanaged(bool) = .empty,
    trace_embed: bool = true,
    /// Names reassigned inside conditionally-executed code. Their declaration
    /// initializer must never be folded against, so binding them is refused.
    comptime_poisoned: std.StringHashMapUnmanaged(void) = .empty,
    src_path: []const u8 = "",
    stdlib_root: ?[]const u8 = null,
    closure_ctx: ?*const ast.FuncBody = null,
    emitted_closures: std.AutoArrayHashMapUnmanaged(u32, void) = .empty,
    /// Closure struct/make/free already emitted (req-module embed + main pass share IDs).
    emitted_closure_structs: std.AutoArrayHashMapUnmanaged(u32, void) = .empty,
    all_closures: std.ArrayList(*ast.FuncBody) = .empty,
    ack_impl_emitted: bool = false,
    ml_kernels_emitted: bool = false,
    mandel_native: bool = false,
    load_chunk: bool = false,
    lib_mode: bool = false,
    idol_mode: bool = false,
    /// When set, foreign module constant field reads may fold in native precheck.
    checked_sema: ?*const sema.Sema = null,
    native_scalar_mode: bool = false,
    /// First native-scalar refusal for this generator. Formatted evidence is
    /// copied here so concurrent or nested generators cannot alias it.
    native_diag_note: [96]u8 = undefined,
    native_diag_note_len: u8 = 0,
    native_diag_line: u32 = 0,
    /// module-wide knowledge level; set alongside `native_scalar_mode`.
    module_knowledge: semantic_algebra.KnowledgeLevel = .unknown,
    /// Per-function native scalar: when true, the module has both native-eligible
    /// and non-native functions. Native-eligible functions get C codegen; the rest
    /// use Lua thunks. The full Lua runtime is included.
    mixed_scalar_mode: bool = false,
    /// All module functions are native-eligible and embedded req deps are native-direct:
    /// omit Lua runtime/thunks while still compiling via C or direct backend.
    substrate_native_mode: bool = false,
    /// Whether this translation unit emits the lua runtime declarations. Captured
    /// once at preamble time; `moduleNeedsLuaRuntime()` answers for the module
    /// currently being emitted, which is the wrong question inside embedded modules.
    tu_needs_lua_runtime: bool = true,
    /// True while emitting an embedded req module under a full-native parent.
    embed_parent_full_native: bool = false,
    /// Set of function names that are native-eligible in mixed mode.
    native_scalar_funcs: std.StringHashMapUnmanaged(void) = .empty,
    /// Types the native-scalar PRECHECK knows for the function body it is
    /// walking. Live only for the duration of one `block_is_native_scalar`
    /// call; see `precheck_collect_types`.
    ///
    /// The precheck runs before any emit, so `local_scopes` is empty and
    /// `expr_type` answered `.any` for every function-local binding. That is
    /// what the `print-arg:any` refusal was: 10 programs in examples/, and
    /// nothing wrong with any of them — `n = 1  print("{n}")` was outside the
    /// direct subset because nobody had told the precheck what `n` was.
    precheck_types: std.StringHashMapUnmanaged(RT) = .empty,
    test_mode: bool = false,
    bench_mode: bool = false,
    /// WP-01: explicit benchmark representation profile.
    bench_backend: backend_identity.BenchBackend = .c_specialized,
    test_structured_output: bool = false,
    test_filter: ?[]const u8 = null,
    test_entries: []const sema_mod.Sema.TestEntry = &.{},
    target: []const u8 = "native",
    current_module_cname: []const u8 = "",
    /// `req` alias -> module export symbols for the module being emitted, so a
    /// qualified call `Alias.fn(...)` can lower to a direct C call instead of a
    /// boxed table lookup. Null until `emit_module` collects it.
    current_module: ?*const ast.Module = null,
    emit_stmt_blocks_as_returns: bool = false,
    /// GAP-070 — TRUE only while the statement being emitted belongs to a block
    /// in return context (`.implicit_return`), the same fact `dnir_lower.zig`
    /// carries as `ctx.block_answering`. `control_block_should_return` is a
    /// TYPE test; without this position fact it fired inside loop bodies, and a
    /// value-typed `if` arm in a `while` body became a `return` from the
    /// enclosing function — measured: `count(3)` answered 5 through this face
    /// where the DNIR/C99 path answered 3. A loop body never answers the
    /// relation, so the type test may only fire where the block does.
    stmt_block_answering: bool = false,
    /// GAP-174 — set only for the duration of `block_tail_type`. See
    /// `local_type`.
    local_type_overlay: ?*const std.StringHashMapUnmanaged(RT) = null,
    vararg_funcs: std.StringHashMapUnmanaged([]const u8) = .empty,
    func_bodies: std.StringHashMapUnmanaged(*const ast.FuncBody) = .empty,
    /// Module-scope function declarations (attributes for effect/call algebra).
    func_decls: std.StringHashMapUnmanaged(*const ast.FuncDecl) = .empty,
    /// `(subject descriptor, relation)` -> embedded relation symbol. This is an
    /// acceleration of declared identities, not another operation namespace.
    /// An empty value records an ambiguous family and is never selected.
    subject_relations: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Qualified descriptors exported by embedded homes. Homes identify the
    /// descriptor; they do not authorize an operation.
    subject_descriptors: std.StringHashMapUnmanaged(RT) = .empty,
    /// gap[082]: the relation store. Declared edges land here from
    /// `family(dest)(src) = conv`; `emit_convert_edge` asks the `to` family
    /// BEFORE the four hardcoded primitive arms, so an authored edge outranks
    /// the projection and a DERIVED edge exists at all. Every relation family
    /// (to, eq, ...) is a row of this one store — see `relation.Store`.
    relations: relation.Store = .{},
    /// Set of anonymous record hashes for which we have already emitted a
    /// C `struct` typedef. Lets us emit the typedef exactly once per
    /// unique record shape, even if the shape is used at many sites.
    emitted_records: std.AutoHashMapUnmanaged(u64, void) = .empty,
    emitted_specs: std.AutoHashMapUnmanaged(u64, void) = .empty,
    /// Map of enum type name -> whether any variant carries a payload. Used
    /// to choose the C representation: payload-free enums become a plain C
    /// `enum` (matched with `==`), payloaded enums become a tagged struct
    /// (matched on `.tag`). Populated by `emit_enum_decls` (Task 12.6).
    enum_has_payload: std.StringHashMapUnmanaged(bool) = .empty,
    enum_defs: std.StringHashMapUnmanaged(*const ast.EnumDef) = .empty,
    /// `name --is--> descriptor`. The SAME type Sema uses (`sema.AliasRegistry`),
    /// with the same derivation and the same membership decisions — CodeGen no
    /// longer re-derives or re-decides anything about aliases. This instance is a
    /// second SCOPE of that one record, not a second answer: during embedded
    /// module emission it holds the parent module's descriptors unioned with the
    /// submodule's, which the submodule's throwaway `Sema` cannot express. See
    /// `sema.AliasRegistry` and `docs/registry_collapse.md` rows 1 and 2.
    alias_defs: sema.AliasRegistry = .{},
    record_aliases: std.StringHashMapUnmanaged(RT) = .empty,
    function_c_names: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Methods associated with alias types (collected from `fun TypeName:method()` declarations).
    /// Maps alias type name → list of method names (for zero-cost dispatch and auto-metatable).
    alias_methods: std.StringHashMapUnmanaged(std.ArrayListUnmanaged([]const u8)) = .empty,
    /// Functions referenced only as @comp.* combinator callbacks (no runtime calls).
    comptime_only_funcs: std.StringHashMapUnmanaged(void) = .empty,
    /// P6-07: guards unified meta combinator fold from re-entering itself.
    meta_combinator_fold_depth: u32 = 0,
    /// Monomorphized generic specializations produced by the mono pass, made
    /// available to codegen so it can emit one concrete C function per
    /// specialization (Task 12.1). Null when there are no generics.
    mono: ?*mono.Monomorphizer = null,
    current_mono_spec: ?*const mono.Specialization = null,
    /// ARC annotations (retain/release/close) computed by the ARC pass, made
    /// available so codegen can emit the reference-counting calls (Task 12.3).
    /// Null when ARC analysis was not run.
    arc: ?*const arc.ArcPass = null,
    /// Async lowering descriptors, made available so codegen can emit frame
    /// structs and step functions for `async` functions (Task 12.4). Null when
    /// async analysis was not run.
    async_lower: ?*const async_lower.AsyncLower = null,
    next_closure_id: u32 = 0,
    current_func_body: ?*const ast.FuncBody = null,
    current_func_name: ?[]const u8 = null,
    // Module `const` decls are emitted as `static const <mod>__<name>`, but
    // sema also records them as module globals, so `emit_var_name_mode` spelled
    // every read `duo_g_<mod>_<name>` — a name nothing declares. Names recorded
    // here are const-declared *and* never assigned by any function in the
    // module, so reads must use the declaration's own name. Names that ARE
    // assigned stay out: `y = -100` folded to a const then written as `y = 1`
    // needs real `duo_g_` storage, which is the case this must not break.
    const_read_only: std.StringHashMapUnmanaged(void) = .{},
    // Names for which an embedded module actually emitted `duo_g_<mod>_<name>`
    // storage. Declaration and readers kept picking different spellings for
    // the same binding; this records what was really declared so reads can follow it.
    // Keyed `<mod>|<name>` because the same name lives in many modules.
    emitted_global_storage: std.StringHashMapUnmanaged(void) = .{},
    // Scalar identities that an embedded module actually emitted at file
    // scope. A mixed module can still own native constants even when its
    // callable surface needs the runtime; consumers may fold only these
    // recorded identities instead of reading the module's boxed export table.
    // Keyed `<mod>|<name>` to match emitted_global_storage.
    emitted_module_scalars: std.StringHashMapUnmanaged(void) = .{},
    /// active function carries @noalloc — heap emit sites call guardNoAlloc.
    current_func_noalloc: bool = false,
    noalloc_violation: ?[]const u8 = null,
    /// First `std.<name>` reference whose module this compiler cannot find, and
    /// the location that needs it. Recorded by `collect_require_names` and
    /// refused by `refuseUnresolvableStdModule`. See that function for the
    /// measurement — it is a SIGSEGV today, not a diagnostic.
    unresolved_std_module: ?struct { path: []const u8, loc: ast.Loc } = null,
    /// Per-scope set of `lua_Value` locals known to hold numbers only (safe to
    /// unbox in binops without going through metamethod dispatch).
    numeric_lua_scopes: std.ArrayList(std.StringHashMapUnmanaged(void)) = .empty,
    /// gap[027]: parameter names of the function being emitted. See is_param_name.
    current_params: std.StringHashMapUnmanaged(void) = .empty,
    /// Index in `local_scopes` at which the function body being emitted begins.
    /// `local_scopes` holds module-top-level bindings and function-body bindings
    /// in one stack, and their STORAGE differs — a module-level `local x` lives
    /// in `duo_g_x`, a function-body `local x` in a C local. Without the
    /// boundary, `is_local_name` cannot tell which one a name reached, which is
    /// why only parameters were allowed to shadow. Null outside a function body.
    func_scope_base: ?usize = null,
    /// Sema-tracked field types for dynamic table locals (`t.x` after `t.x = n`).
    table_field_types: ?*const std.StringHashMapUnmanaged(RT) = null,
    concepts: ?*const std.StringHashMapUnmanaged(sema.ConceptInfo) = null,
    table_methods: ?*const std.StringHashMapUnmanaged(std.ArrayListUnmanaged([]const u8)) = null,
    /// imported C record descriptors from sema.
    foreign_records: ?*const std.StringHashMapUnmanaged(RT) = null,
    /// imported C function descriptors from sema.
    foreign_functions: ?*const std.StringHashMapUnmanaged(@import("foreign_adapter.zig").ForeignFunc) = null,

    const NativeDenseElem = enum { i64, f64, str };

    const NativeDenseModuleTable = struct {
        c_symbol: []const u8,
        module_cname: []const u8,
        elem: NativeDenseElem,
        len: usize,
        init: *const ast.Expr,
    };

    const NativeConstDescriptor = struct {
        module_cname: []const u8,
        /// The `.table` expression, with any `@{}` (`.compile` unop) wrapper
        /// already stripped, so field lookup reads `init.table.fields` directly.
        init: *const ast.Expr,
    };

    const ArcLocal = struct {
        name: []const u8,
        ty: RT,
        is_close: bool,
    };

    fn funcRequiresNoalloc(attrs: []const ast.Attribute) bool {
        return semantic_algebra.effectSetFromAttributes(attrs).contains(.noalloc);
    }

    fn guardNoAlloc(self: *CodeGen, site: []const u8) E!void {
        if (!self.current_func_noalloc or self.noalloc_violation != null) return;
        const fname = self.current_func_name orelse "?";
        const msg = try std.fmt.allocPrint(self.alloc, "@noalloc violated in function '{s}': heap allocation at {s}", .{ fname, site });
        self.noalloc_violation = msg;
        const optimization_outcome = @import("optimization_outcome.zig");
        optimization_outcome.logOutcome(
            self.alloc,
            "contract.noalloc",
            fname,
            .rejected,
            .proven,
            .emit_call,
            try std.fmt.allocPrint(self.alloc, "heap allocation required at {s}", .{site}),
            "dynamic",
            "heap",
            0,
            0,
        ) catch {};
        return error.NoAllocViolation;
    }

    fn mangled_name(self: *CodeGen, name: []const u8, buf: []u8) []const u8 {
        if (self.current_module_cname.len == 0) return name;
        return std.fmt.bufPrint(buf, "{s}__{s}", .{ self.current_module_cname, name }) catch name;
    }

    /// The compile-time half of the runtime's `calc_hash`. The two MUST agree
    /// bit for bit: a literal's hash is baked into the emitted C
    /// (`lua_val_from_literal(s, <hash>, len)`) and later compared against a
    /// hash the runtime computed, so a divergence is a silent lookup miss, not
    /// a crash. An edit here is an edit to `duo_runtime`'s `calc_hash` and to
    /// `sema.calc_lua_hash` in the same commit; `duo run
    /// examples/hash_agreement.duo` differences all three.
    ///
    /// Strings of 32 bytes or fewer hash EVERY byte, exactly as before. That
    /// keeps every identifier, field name and metamethod key bit-identical,
    /// including the ones baked into the tracked generated
    /// `src/lexer_tokenize.c`, whose longest literal is 32 bytes and which
    /// carries its own copy of this function and its own string pool.
    ///
    /// Longer strings sample the first 16 bytes, the LAST 16 bytes and at most
    /// 33 more on a stride, and mix the length in -- at most 65 mixes for any
    /// length. Hashing every byte of a long string is O(n) down a serial
    /// dependent multiply chain, and it is paid on the way IN to the intern
    /// pool -- on every string a program builds, whether or not anything ever
    /// looks it up again. Measured: FNV-1a over the 850 KB that
    /// `string.rep("alpha beta gamma ", 50000)` produces costs 1.03 ms, while
    /// BUILDING that string costs 0.03 ms. The hash was 35x the work it was
    /// guarding, and it is why four string benchmark rows lost to reference C
    /// whose emitted inner loops were character-for-character identical to C's.
    /// Lua 5.1's `luaS_newlstr` sampled on a `step = (l >> 5) + 1` stride for
    /// exactly this reason.
    ///
    /// THE TWO 16-BYTE WINDOWS ARE NOT DECORATION. A bare stride anchored at 0
    /// leaves an unsampled tail -- for an 850 KB string the last 26 KB, for a
    /// 503-byte string the last 6 bytes -- so records that share a prefix and
    /// differ in a suffix all hash the SAME. Counted: 500 JSON records with a
    /// 4 KB shared header and a distinct 6-digit id produce **1** distinct
    /// hash under a bare stride and 500 under this rule; the 200 long keys in
    /// `examples/hash_agreement.duo` produce **3** and 200. Correctness never
    /// depended on it -- the memcmp confirm keeps those keys distinct either
    /// way -- but a pool that puts 500 ordinary keys in one bucket has turned
    /// an O(1) intern into an O(n) one, which is the cost this change exists
    /// to remove. Bucket spread now matches full FNV-1a (152 vs 146 of 200
    /// buckets at capacity 256).
    ///
    /// This is a HASH, not an identity. Every consumer confirms with a length
    /// check and a `memcmp` -- the intern pool in `lua_val_from_str_len`, the
    /// table key path in `lua_string_key_eq_lit`. Sampling can cost a probe. It
    /// cannot produce a wrong answer.
    fn calc_lua_hash(s: []const u8) u32 {
        var h: u32 = 2166136261;
        if (s.len <= 32) {
            for (s) |c| {
                h ^= @as(u32, c);
                h = h *% 16777619;
            }
            return h;
        }
        h ^= @as(u32, @truncate(s.len));
        h = h *% 16777619;
        var i: usize = 0;
        while (i < 16) : (i += 1) {
            h ^= @as(u32, s[i]);
            h = h *% 16777619;
        }
        i = s.len - 16;
        while (i < s.len) : (i += 1) {
            h ^= @as(u32, s[i]);
            h = h *% 16777619;
        }
        const step: usize = (s.len >> 5) + 1;
        i = 0;
        while (i < s.len) : (i += step) {
            h ^= @as(u32, s[i]);
            h = h *% 16777619;
        }
        return h;
    }

    fn emit_metafield_literal(self: *CodeGen, value_expr: []const u8, name: []const u8) void {
        self.p("lua_get_metafield_lit({s}, \"{s}\", {d}u, {d})", .{
            value_expr,
            name,
            calc_lua_hash(name),
            name.len,
        });
    }

    fn positive_int_key(e: *const ast.Expr) ?i64 {
        return switch (e.*) {
            .int_lit => |v| if (v.val >= 1) v.val else null,
            else => null,
        };
    }

    fn is_integer_key(self: *CodeGen, e: *const ast.Expr) bool {
        if (self.expr_type(e).is_integer()) return true;
        if (e.* == .name and self.is_numeric_lua_local(e.name.ident)) return true;
        return false;
    }

    /// Emit an expression suitable as the `int64_t` index argument to
    /// `lua_table_get_i64` / `lua_table_set_i64`.
    fn emit_i64_index_key(self: *CodeGen, key: *const ast.Expr) E!void {
        if (self.expr_type(key).is_integer()) {
            try self.emit_expr(key);
            return;
        }
        if (key.* == .name and self.is_numeric_lua_local(key.name.ident)) {
            self.p("(int64_t)lua_to_num(", .{});
            try self.emit_expr(key);
            self.p(")", .{});
            return;
        }
        try self.emit_expr(key);
    }

    pub fn init(
        alloc: Allocator,
        io: Io,
        type_map: *sema.TypeMap,
        module_globals: ?*const std.StringHashMapUnmanaged(RT),
        w: W,
        next_closure_id: u32,
        table_field_types: ?*const std.StringHashMapUnmanaged(RT),
        concepts: ?*const std.StringHashMapUnmanaged(sema.ConceptInfo),
    ) CodeGen {
        return .{
            .alloc = alloc,
            .io = io,
            .type_map = type_map,
            .module_globals = module_globals,
            .indent = 0,
            .w = w,
            .current_ret = .void,
            .next_closure_id = next_closure_id,
            .table_field_types = table_field_types,
            .concepts = concepts,
        };
    }

    fn resetNativeScalarReason(self: *CodeGen) void {
        self.native_diag_note_len = 0;
        self.native_diag_line = 0;
    }

    fn nativeDiagFail(self: *CodeGen, note: []const u8) void {
        if (self.native_diag_note_len != 0 or self.native_diag_line != 0) return;
        const len = @min(note.len, self.native_diag_note.len);
        self.native_diag_note_len = @intCast(len);
        @memcpy(self.native_diag_note[0..len], note[0..len]);
        if (native_diag) std.debug.print("[native-diag] first fail: {s}\n", .{self.native_diag_note[0..self.native_diag_note_len]});
    }

    fn nativeDiagFailFmt(self: *CodeGen, comptime fmt: []const u8, args: anytype) void {
        if (self.native_diag_note_len != 0 or self.native_diag_line != 0) return;
        const note = std.fmt.bufPrint(&self.native_diag_note, fmt, args) catch return;
        self.native_diag_note_len = @intCast(note.len);
        if (native_diag) std.debug.print("[native-diag] first fail: {s}\n", .{note});
    }

    fn nofit(self: *CodeGen, src: std.builtin.SourceLocation) bool {
        if (self.native_diag_note_len == 0 and self.native_diag_line == 0) self.native_diag_line = src.line;
        return false;
    }

    pub fn nativeScalarReason(self: *const CodeGen, buf: []u8) ?[]const u8 {
        if (self.native_diag_note_len != 0) return self.native_diag_note[0..self.native_diag_note_len];
        if (self.native_diag_line == 0) return null;
        return std.fmt.bufPrint(buf, "codegen.zig:{d}", .{self.native_diag_line}) catch null;
    }

    fn lookup_tracked_table_field(self: *const CodeGen, table_name: []const u8, field_name: []const u8) ?RT {
        const map = self.table_field_types orelse return null;
        var key_buf: [384]u8 = undefined;
        const key = if (self.current_func_name) |fn_name|
            std.fmt.bufPrint(&key_buf, "{s}.{s}.{s}", .{ fn_name, table_name, field_name }) catch return null
        else
            std.fmt.bufPrint(&key_buf, "{s}.{s}", .{ table_name, field_name }) catch return null;
        return map.get(key);
    }

    fn push_local_scope(self: *CodeGen) E!void {
        try self.local_scopes.append(self.alloc, std.StringHashMapUnmanaged(RT).empty);
        try self.comptime_scopes.append(self.alloc, std.StringHashMapUnmanaged(comptime_eval.Value).empty);
        try self.numeric_lua_scopes.append(self.alloc, std.StringHashMapUnmanaged(void).empty);
        try self.close_scopes.append(self.alloc, .empty);
        try self.arc_scopes.append(self.alloc, .empty);
        try self.defer_scopes.append(self.alloc, .empty);
    }

    fn pop_local_scope(self: *CodeGen) void {
        if (self.defer_scopes.items.len > 0) {
            var d = self.defer_scopes.pop().?;
            d.deinit(self.alloc);
        }
        if (self.arc_scopes.items.len > 0) {
            var arc_locals = self.arc_scopes.pop().?;
            var i = arc_locals.items.len;
            while (i > 0) {
                i -= 1;
                const local = arc_locals.items[i];
                self.emit_arc_drop(local.name, local.ty, local.is_close);
            }
            arc_locals.deinit(self.alloc);
        }
        if (self.close_scopes.items.len > 0) {
            var closes = self.close_scopes.pop().?;
            var i = closes.items.len;
            while (i > 0) {
                i -= 1;
                const name = closes.items[i];
                self.ind();
                self.p("lua_close_local(", .{});
                self.emit_var_name(name);
                self.p(");\n", .{});
            }
            closes.deinit(self.alloc);
        }
        if (self.local_scopes.items.len == 0) return;
        var m = self.local_scopes.pop().?;
        m.deinit(self.alloc);
        if (self.comptime_scopes.items.len > 0) {
            var cm = self.comptime_scopes.pop().?;
            cm.deinit(self.alloc);
        }
        if (self.numeric_lua_scopes.items.len > 0) {
            var nm = self.numeric_lua_scopes.pop().?;
            nm.deinit(self.alloc);
        }
    }

    fn note_numeric_lua_local(self: *CodeGen, name: []const u8) !void {
        if (self.numeric_lua_scopes.items.len == 0) return;
        try self.numeric_lua_scopes.items[self.numeric_lua_scopes.items.len - 1].put(self.alloc, name, {});
    }

    fn clear_numeric_lua_local(self: *CodeGen, name: []const u8) void {
        if (self.numeric_lua_scopes.items.len == 0) return;
        _ = self.numeric_lua_scopes.items[self.numeric_lua_scopes.items.len - 1].remove(name);
    }

    fn is_numeric_lua_local(self: *const CodeGen, name: []const u8) bool {
        var i = self.numeric_lua_scopes.items.len;
        while (i > 0) {
            i -= 1;
            if (self.numeric_lua_scopes.items[i].contains(name)) return true;
        }
        return false;
    }

    fn expr_is_dynamic_table(self: *CodeGen, e: *const ast.Expr) bool {
        const t = self.expr_type(e);
        if (t == .any) return true;
        if (t == .array and t.array.elem.* == .any) return true;
        return false;
    }

    fn assign_preserves_numeric_lua_local(self: *CodeGen, val: *const ast.Expr) bool {
        const vt = self.expr_type(val);
        if (vt.is_numeric()) return true;
        return switch (val.*) {
            .int_lit, .float_lit => true,
            else => false,
        };
    }

    fn assign_clears_numeric_lua_local(self: *CodeGen, val: *const ast.Expr) bool {
        const vt = self.expr_type(val);
        if (vt == .str or vt == .bool) return true;
        return switch (val.*) {
            .quoted, .true_lit, .false_lit, .nil, .table, .func_expr => true,
            else => false,
        };
    }

    fn update_numeric_lua_local(self: *CodeGen, name: []const u8, val: *const ast.Expr) !void {
        const lt = self.local_type(name) orelse return;
        if (lt != .any) return;
        if (self.assign_preserves_numeric_lua_local(val)) {
            try self.note_numeric_lua_local(name);
        } else if (self.assign_clears_numeric_lua_local(val)) {
            self.clear_numeric_lua_local(name);
        } else {
            self.clear_numeric_lua_local(name);
        }
    }

    fn note_close_local(self: *CodeGen, name: []const u8) !void {
        if (self.close_scopes.items.len == 0) return;
        try self.close_scopes.items[self.close_scopes.items.len - 1].append(self.alloc, name);
    }

    fn note_local(self: *CodeGen, name: []const u8) !void {
        if (self.local_scopes.items.len == 0) return;
        try self.local_scopes.items[self.local_scopes.items.len - 1].put(self.alloc, name, .any);
    }

    fn note_local_type(self: *CodeGen, name: []const u8, rt: RT) !void {
        if (self.local_scopes.items.len == 0) return;
        try self.local_scopes.items[self.local_scopes.items.len - 1].put(self.alloc, name, rt);
    }

    fn comptime_bindings(self: *const CodeGen) comptime_eval.Bindings {
        return .{ .scopes = self.comptime_scopes.items };
    }

    fn comptime_eval_options(self: *const CodeGen) comptime_eval.Options {
        return .{
            .alloc = self.alloc,
            .satisfies_hook = comptimeSatisfiesHook,
            .satisfies_ctx = @ptrCast(@constCast(self)),
            .meta_hook = comptimeMetaHook,
            .meta_ctx = @ptrCast(@constCast(self)),
        };
    }

    fn meta_host(self: *CodeGen) meta_codegen.Host {
        return .{
            .alloc = self.alloc,
            .mod = self.current_module,
            .record_aliases = &self.record_aliases,
            .alias_defs = &self.alias_defs.map,
            .concepts = self.concepts,
            .bindings = self.comptime_bindings(),
            .options = self.comptime_eval_options(),
            .codegen_ctx = @ptrCast(self),
        };
    }

    fn comptimeSatisfiesHook(ctx: ?*anyopaque, type_expr: *const ast.Expr, concept_name: []const u8) ?bool {
        const self: *CodeGen = @ptrCast(@alignCast(ctx orelse return null));
        var concept_lit = ast.Expr{ .quoted = .{ .loc = type_expr.loc(), .val = concept_name } };
        var args = [_]*ast.Expr{ @constCast(type_expr), &concept_lit };
        return self.eval_satisfies(&args);
    }

    /// G-059: Meta hook for @comp.* combinator calls inside comptime callback bodies.
    /// Receives pre-evaluated Value args from the comptime evaluator (callback
    /// locals like m.pattern are already resolved to Values).
    fn comptimeMetaHook(ctx: ?*anyopaque, name: []const u8, args: []const comptime_eval.Value) ?comptime_eval.Value {
        const self: *CodeGen = @ptrCast(@alignCast(ctx orelse return null));
        if (transform_engine.publicNameForInternal(name) != null and
            !transform_engine.requireMetaDispatchBeforeHook(name))
            return null;
        const result = meta_dispatch.dispatchAtSite(self.meta_host(), name, args, self.alloc, .nested_callback);
        return switch (result) {
            .string => |s| comptime_eval.Value{ .string = s },
            .int => |i| comptime_eval.Value{ .int = i },
            .boolean => |b| comptime_eval.Value{ .bool = b },
            .not_applicable, .eval_failed => null,
        };
    }

    /// A binding recorded from a declaration's initializer is only valid while
    /// the variable is never reassigned. Conditionally-executed code (loop and
    /// `if` bodies) may reassign it, and folding a later condition against the
    /// stale initializer miscompiles the branch away entirely. Before emitting
    /// such a body, mark every name it assigns as unavailable for folding.
    fn poison_assigned_in_block(self: *CodeGen, block: *const ast.Block) E!void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .assign => |*a| for (a.targets) |t| {
                    if (t.* == .name) {
                        try self.comptime_poisoned.put(self.alloc, t.name.ident, {});
                        try self.note_comptime_unavailable(t.name.ident);
                    }
                },
                .local_decl => |*ld| for (ld.names) |n| {
                    try self.comptime_poisoned.put(self.alloc, n.ident, {});
                    try self.note_comptime_unavailable(n.ident);
                },
                .do_block => |*db| try self.poison_assigned_in_block(&db.body),
                .while_loop => |*wl| try self.poison_assigned_in_block(&wl.body),
                .repeat_loop => |*rl| try self.poison_assigned_in_block(&rl.body),
                .num_for => |*nf| try self.poison_assigned_in_block(&nf.body),
                .gen_for => |*gf| try self.poison_assigned_in_block(&gf.body),
                .func_decl => |*fd| try self.poison_assigned_in_block(&fd.func.body),
                .if_stmt => |*is| {
                    try self.poison_assigned_in_block(&is.then);
                    for (is.elseifs) |*ei| try self.poison_assigned_in_block(&ei.body);
                    if (is.else_body) |*eb| try self.poison_assigned_in_block(eb);
                },
                else => {},
            }
        }
    }

    fn note_comptime_binding(self: *CodeGen, name: []const u8, expr: *const ast.Expr) !void {
        if (self.comptime_scopes.items.len == 0) return;
        if (self.comptime_poisoned.contains(name)) return self.note_comptime_unavailable(name);
        const value = comptime_eval.evalWithBindings(expr, self.comptime_bindings(), self.comptime_eval_options()) catch comptime_eval.Value.unavailable;
        try self.comptime_scopes.items[self.comptime_scopes.items.len - 1].put(self.alloc, name, value);
    }

    fn note_comptime_unavailable(self: *CodeGen, name: []const u8) !void {
        if (self.comptime_scopes.items.len == 0) return;
        try self.comptime_scopes.items[self.comptime_scopes.items.len - 1].put(self.alloc, name, .unavailable);
    }

    fn note_comptime_string(self: *CodeGen, name: []const u8, value: []const u8) !void {
        if (self.comptime_scopes.items.len == 0) return;
        try self.comptime_scopes.items[self.comptime_scopes.items.len - 1].put(self.alloc, name, .{ .string = value });
    }

    fn note_comptime_func(self: *CodeGen, name: []const u8, func: *const ast.FuncBody) !void {
        if (self.comptime_scopes.items.len == 0) return;
        const value = comptime_eval.funcValue(func, self.comptime_bindings(), self.comptime_eval_options()) catch comptime_eval.Value.unavailable;
        try self.comptime_scopes.items[self.comptime_scopes.items.len - 1].put(self.alloc, name, value);
    }

    fn note_func_body(self: *CodeGen, name: []const u8, func: *const ast.FuncBody) !void {
        var buf: [256]u8 = undefined;
        const key = self.mangled_name(name, &buf);
        const owned = try self.alloc.dupe(u8, key);
        try self.func_bodies.put(self.alloc, owned, func);
    }

    fn note_func_decl(self: *CodeGen, name: []const u8, fd: *const ast.FuncDecl) !void {
        var buf: [256]u8 = undefined;
        const key = self.mangled_name(name, &buf);
        const owned = try self.alloc.dupe(u8, key);
        try self.func_decls.put(self.alloc, owned, fd);
        if (fd.func.params.len == 0 or fd.func.params[0].typ != .named) return;
        const descriptor = fd.func.params[0].typ.named;
        const index = try std.fmt.allocPrint(self.alloc, "{s}|{s}", .{ descriptor, name });
        if (self.subject_relations.get(index)) |prior| {
            defer self.alloc.free(index);
            if (!std.mem.eql(u8, prior, owned)) {
                try self.subject_relations.put(self.alloc, index, "");
            }
        } else {
            try self.subject_relations.put(self.alloc, index, owned);
        }
    }

    /// level edge `audit(path) = (pattern) …` → symbol `audit__path`.
    /// Subject-first `path:audit(pattern)` resolves against the family symbol.
    fn relationEdgeFuncDecl(self: *CodeGen, method: []const u8, arg_count: usize) ?*const ast.FuncDecl {
        if (arg_count != 1) return null;
        var prefix_buf: [128]u8 = undefined;
        const prefix = std.fmt.bufPrint(&prefix_buf, "{s}__", .{method}) catch return null;
        var it = self.func_decls.iterator();
        while (it.next()) |entry| {
            if (std.mem.startsWith(u8, entry.key_ptr.*, prefix)) return entry.value_ptr.*;
        }
        return null;
    }

    /// Try to evaluate an expression's boolean condition at compile time.
    /// Returns `true` (always true), `false` (always false), or `null` (unknown).
    /// Used for dead-branch elimination in if/while/repeat.
    fn try_eval_const_condition(self: *CodeGen, cond: *const ast.Expr) ?bool {
        // Direct boolean literals
        switch (cond.*) {
            .true_lit => return true,
            .false_lit => return false,
            .nil => return false,
            .int_lit => |v| return v.val != 0,
            .float_lit => |v| return v.val != 0.0,
            .quoted => return true, // non-nil, non-false = truthy
            .name => |n| {
                // Check if name resolves to a comptime-known value
                if (self.comptime_bindings().get(n.ident)) |val| {
                    return switch (val) {
                        .unavailable => null,
                        .nil => false,
                        .bool => |b| b,
                        .int => |i| i != 0,
                        .float => |f| f != 0.0,
                        .decimal => |d| !d.isZero(),
                        .string => true,
                        .table => true,
                        .func => true,
                    };
                }
                return null;
            },
            .unop => |u| {
                if (u.op == .not) {
                    if (self.try_eval_const_condition(u.operand)) |inner| {
                        return !inner;
                    }
                }
                return null;
            },
            .binop => |*b| {
                // Try constant folding for comparison/logical operators
                if (b.op == .@"and") {
                    const lhs = self.try_eval_const_condition(b.lhs);
                    if (lhs != null and !lhs.?) return false;
                    const rhs = self.try_eval_const_condition(b.rhs);
                    if (lhs != null and lhs.? and rhs != null) return rhs.?;
                    return null;
                }
                if (b.op == .@"or") {
                    const lhs = self.try_eval_const_condition(b.lhs);
                    if (lhs != null and lhs.?) return true;
                    const rhs = self.try_eval_const_condition(b.rhs);
                    if (lhs != null and !lhs.? and rhs != null) return rhs.?;
                    return null;
                }
                // Integer comparison folding
                if (b.lhs.* == .int_lit and b.rhs.* == .int_lit) {
                    const lv = b.lhs.int_lit.val;
                    const rv = b.rhs.int_lit.val;
                    return switch (b.op) {
                        .eq => lv == rv,
                        .neq => lv != rv,
                        .lt => lv < rv,
                        .gt => lv > rv,
                        .leq => lv <= rv,
                        .geq => lv >= rv,
                        else => null,
                    };
                }
                return null;
            },
            .call => |c| {
                if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__satisfies") and c.args.len == 2) {
                    if (self.eval_satisfies(c.args)) |known| return known;
                }
                const val = comptime_eval.evalWithBindings(cond, self.comptime_bindings(), self.comptime_eval_options()) catch return null;
                return switch (val) {
                    .unavailable => null,
                    .nil => false,
                    .bool => |b| b,
                    .int => |i| i != 0,
                    .float => |f| f != 0.0,
                    .decimal => |d| !d.isZero(),
                    .string => true,
                    .table => true,
                    .func => true,
                };
            },
            else => {
                // Try full comptime evaluation as last resort
                const val = comptime_eval.evalWithBindings(cond, self.comptime_bindings(), self.comptime_eval_options()) catch return null;
                return switch (val) {
                    .unavailable => null,
                    .nil => false,
                    .bool => |b| b,
                    .int => |i| i != 0,
                    .float => |f| f != 0.0,
                    .decimal => |d| !d.isZero(),
                    .string => true,
                    .table => true,
                    .func => true,
                };
            },
        }
    }

    fn note_arc_local(self: *CodeGen, name: []const u8, rt: RT, is_close: bool) !void {
        if (self.arc_scopes.items.len == 0 or !self.codegen_needs_arc(rt)) return;
        if (!self.should_arc_local(name)) return;
        try self.arc_scopes.items[self.arc_scopes.items.len - 1].append(self.alloc, .{
            .name = name,
            .ty = rt,
            .is_close = is_close,
        });
    }

    fn emit_arc_retain(self: *CodeGen, name: []const u8, rt: RT) void {
        if (!self.codegen_needs_arc(rt)) return;
        if (!self.should_arc_local(name)) return;
        self.ind();
        self.p("duo_retain((void*)(", .{});
        self.emit_var_name(name);
        self.p("));\n", .{});
    }

    fn emit_arc_drop(self: *CodeGen, name: []const u8, rt: RT, is_close: bool) void {
        if (!self.codegen_needs_arc(rt)) return;
        if (!self.should_arc_local(name)) return;
        if (is_close) {
            self.ind();
            self.p("duo_close((void*)(", .{});
            self.emit_var_name(name);
            self.p("));\n", .{});
        }
        self.ind();
        self.p("duo_release((void*)(", .{});
        self.emit_var_name(name);
        self.p("));\n", .{});
    }

    fn codegen_needs_arc(self: *CodeGen, rt: RT) bool {
        // law.nominal (§46): MEMORY BEHAVIOUR IS A PHYSICAL FACT, so it reads
        // through the identity to the representation. Without this the `.
        // @"struct"` row below emitted `duo_retain((void*)(d))` for a `feet`
        // that is a `double` — the C compiler caught it ("operand of type
        // 'double' cannot be cast to a pointer type"), but the shape of the
        // bug is the one to remember: every switch that lists `.@"struct"` as
        // boxed is a place a nominal descriptor can acquire overhead. gap[097]
        // owes an enumeration of them.
        if (types.nominalReprOf(rt)) |repr| return self.codegen_needs_arc(repr);
        if (self.enum_name_of(rt) != null) return false;
        // Native scalar / mixed modules use const char* for str — no refcounting.
        if (rt == .str and (self.moduleUsesFullNativeLowering() or self.mixed_scalar_mode)) return false;
        return switch (rt) {
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .f32, .f64 => false,
            .bool, .void, .nil, .never => false,
            .v4f64, .v4i64, .v8f32, .v8i32 => false,
            .any => false,
            .tensor => false,
            .table_type, .enum_type => false,
            .str, .array, .pointer, .func, .@"struct" => true,
            .result, .option, .channel, .instantiated, .generic_param => true,
        };
    }

    /// Returns true if this local variable should actually get ARC retain/release.
    /// When the ARC pass has populated its escaping set, non-escaping locals are
    /// pruned (no retain/release). If no ARC pass is attached or the escaping set
    /// is empty, we keep ARC for all locals (safe default).
    fn should_arc_local(self: *CodeGen, name: []const u8) bool {
        if (self.arc) |pass| {
            // When the escaping set is populated, only escaping names get ARC.
            if (pass.escaping.count() > 0)
                return pass.escaping.contains(name);
        }
        return true;
    }

    fn attr_is_close(attrib: ?[]const u8) bool {
        const a = attrib orelse return false;
        return std.mem.eql(u8, a, "close");
    }

    /// Register a `defer` body to run on exit of the current (innermost) scope.
    fn note_defer(self: *CodeGen, body: *const ast.Block) !void {
        if (self.defer_scopes.items.len == 0) return;
        try self.defer_scopes.items[self.defer_scopes.items.len - 1].append(self.alloc, body);
    }

    /// True if any active scope has a pending defer. Lets the common
    /// defer-free path stay byte-identical to before (zero overhead).
    fn has_pending_defers(self: *CodeGen) bool {
        for (self.defer_scopes.items) |s| {
            if (s.items.len > 0) return true;
        }
        return false;
    }

    /// Emit one defer body as an isolated C block. Uses `emit_block` so the
    /// body gets its own scope (nested defers inside a defer body are scoped
    /// to that body, not the enclosing scope).
    fn emit_defer_body(self: *CodeGen, body: *const ast.Block) E!void {
        self.ind();
        self.p("{{ /* defer */\n", .{});
        self.indent += 1;
        try self.emit_block(body);
        self.indent -= 1;
        self.ind();
        self.p("}}\n", .{});
    }

    /// Flush the innermost scope's pending defers in LIFO order. Called at
    /// normal (fall-through) exit of a block.
    fn emit_top_defers(self: *CodeGen) E!void {
        if (self.defer_scopes.items.len == 0) return;
        const top = &self.defer_scopes.items[self.defer_scopes.items.len - 1];
        var i = top.items.len;
        while (i > 0) {
            i -= 1;
            try self.emit_defer_body(top.items[i]);
        }
    }

    /// Flush every active scope's pending defers, innermost scope first and
    /// LIFO within each scope. Called before an early `return` so that all
    /// enclosing defers run before the function unwinds. Does not clear the
    /// pending lists — fall-through flushing in `emit_block_stmts` is a
    /// separate control path and emits its own (unreachable after the return).
    fn emit_all_pending_defers(self: *CodeGen) E!void {
        try self.emit_pending_defers_from(0);
    }

    fn emit_pending_defers_from(self: *CodeGen, base: usize) E!void {
        var si = self.defer_scopes.items.len;
        while (si > base) {
            si -= 1;
            const scope = &self.defer_scopes.items[si];
            var di = scope.items.len;
            while (di > 0) {
                di -= 1;
                try self.emit_defer_body(scope.items[di]);
            }
        }
    }

    fn push_break_scope(self: *CodeGen) !void {
        try self.break_scope_bases.append(self.alloc, self.local_scopes.items.len);
    }

    fn pop_break_scope(self: *CodeGen) void {
        if (self.break_scope_bases.items.len > 0) _ = self.break_scope_bases.pop().?;
    }

    fn current_break_scope_base(self: *CodeGen) usize {
        if (self.break_scope_bases.items.len == 0) return 0;
        return self.break_scope_bases.items[self.break_scope_bases.items.len - 1];
    }

    /// gap[027]: names bound as PARAMETERS of the function being emitted.
    ///
    /// Kept apart from `local_scopes` on purpose. A module-level `local x` is
    /// recorded BOTH as a local and as a global — its storage is `duo_g_x` —
    /// so letting every local shadow would mis-spell module-level call sites
    /// (`sum_point(p)` reaching for a `p` that has no C storage). A parameter
    /// is the one binding that unambiguously shadows: it has its own C name and
    /// LAW-SCOPE rung 1 says lexical wins.
    fn is_param_name(self: *CodeGen, name: []const u8) bool {
        return self.current_params.contains(name);
    }

    /// A binding declared inside the function body currently being emitted, so
    /// its C storage is the local the declaration emitted under its own name.
    /// LAW-SCOPE rung 1: this outranks a module global of the same spelling.
    fn is_func_local_name(self: *CodeGen, name: []const u8) bool {
        const base = self.func_scope_base orelse return false;
        var i = self.local_scopes.items.len;
        while (i > base) {
            i -= 1;
            if (self.local_scopes.items[i].contains(name)) return true;
        }
        return false;
    }

    fn is_local_name(self: *CodeGen, name: []const u8) bool {
        var i = self.local_scopes.items.len;
        while (i > 0) {
            i -= 1;
            if (self.local_scopes.items[i].contains(name)) return true;
        }
        return false;
    }

    fn local_type(self: *CodeGen, name: []const u8) ?RT {
        var i = self.local_scopes.items.len;
        while (i > 0) {
            i -= 1;
            if (self.local_scopes.items[i].get(name)) |rt| return rt;
        }
        // GAP-174 — the names a block is ABOUT to bind, for the one predicate
        // that has to ask about a block before emitting it. Consulted last, so
        // a real scope always wins; null except inside `block_tail_type`.
        if (self.local_type_overlay) |ov| {
            if (ov.get(name)) |rt| return rt;
        }
        return null;
    }

    fn is_global_name(self: *CodeGen, name: []const u8) bool {
        if (self.module_globals) |globals| {
            return globals.contains(name);
        }
        return false;
    }

    fn global_type(self: *CodeGen, name: []const u8) ?RT {
        if (self.module_globals) |globals| return globals.get(name);
        return null;
    }

    fn is_runtime_global(name: []const u8) bool {
        const runtime_globals = [_][]const u8{
            "package",      "math",     "utf8",     "debug",    "coroutine",   "string",        "table",
            "io",           "os",       "jit",      "ffi",      "duo_modules", "current_input", "current_output",
            "_VERSION",     "net",      "mem",      "atomic",   "__constexpr", "req",           "require",
            "print",        "tostring", "tonumber", "type",     "assert",      "error",         "pcall",
            "xpcall",       "select",   "rawlen",   "rawequal", "rawget",      "rawset",        "setmetatable",
            "getmetatable", "pairs",    "ipairs",   "next",     "unpack",
        };
        for (runtime_globals) |g| {
            if (std.mem.eql(u8, name, g)) return true;
        }
        return false;
    }

    /// True when the PROGRAM bound `name` in the function the precheck is
    /// walking — a parameter, or a local/global declaration in its body.
    ///
    /// AN INJECTED WORLD ADDS REACH, IT NEVER TAKES A NAME. `is_world_symbol`
    /// and `is_runtime_global` below are pure NAME tests with no scope in them,
    /// so `io`, `os`, `string`, `print` answered for the world no matter what
    /// the author had bound. Measured: `main: i64 = () / string = 9 / return
    /// string` bailed the whole module with `runtime-global:string`, while the
    /// identical program spelled `zz` compiled and answered 9. A bound name is
    /// an ORDINARY LOCAL and the native path lowers it as one.
    fn precheck_name_is_bound(self: *const CodeGen, name: []const u8) bool {
        return self.precheck_types.contains(name);
    }

    /// World symbols used in `dot(io)(code)` / `dot(std)(io, code)` specialization
    /// slots are not runtime-global table access for native precheck purposes.
    fn is_world_symbol(name: []const u8) bool {
        return std.mem.eql(u8, name, "io") or
            std.mem.eql(u8, name, "os") or
            std.mem.eql(u8, name, "std");
    }

    fn world_method_result_type(_: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (obj.* != .name or !is_world_symbol(obj.name.ident)) return null;
        if (std.mem.eql(u8, obj.name.ident, "io")) {
            if (std.mem.eql(u8, method, "write") and args.len == 1) return .void;
        }
        return null;
    }

    /// `os.env:remove(k)` — THE ENVIRONMENT'S REMOVAL EDGE.
    ///
    /// `table_apply` converges the bare `env:remove(k)` onto this anchored
    /// subject, so exactly one shape reaches both backends and the bare face is
    /// admitted only where the program does not bind `env`.
    ///
    /// It is a distinct edge and not an assignment because `setenv(k, "", 1)`
    /// and `unsetenv(k)` have different observable results: the first leaves
    /// the variable PRESENT and empty. See `dnir_lower.lowerEnvRemove`.
    fn env_remove_method(_: *const CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) bool {
        if (!std.mem.eql(u8, method, "remove") or args.len != 1) return false;
        if (obj.* != .field) return false;
        const f = obj.field;
        return f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "os") and
            std.mem.eql(u8, f.field, "env");
    }

    /// THE ENVIRONMENT PROJECTION as a value or a place — `env(k)`, `env k`,
    /// `os.env(k)`, `os.env[k]` — returning the KEY, or null.
    ///
    /// `table_apply` has already converged all four faces onto the single
    /// `.index` node whose object is the anchored `os.env`, and it declines the
    /// conversion for any name the program binds, so this recognizer sees the
    /// world's own edge and never a user table named `env`.
    ///
    /// WHY THIS EXISTS. Without it the C backend had no environment projection
    /// at all, and failed in TWO different ways depending on whether the module
    /// happened to need the boxed runtime:
    ///
    ///   slim mode:  `static lua_Value duo_g_env;` plus `use of undeclared
    ///               identifier 'os'` — a loud C compile failure.
    ///   full mode:  `lua_table_set(lua_table_get_str_lit(os, "env", ...), ...)`
    ///               — a store into a Lua table with NO connection to the
    ///               process environment. MEASURED: `env("K") = "set"` followed
    ///               by `os.getenv("K")` compiled, ran, and answered 0. A SILENT
    ///               NO-OP, which is the failure class this tree has shipped
    ///               nine of.
    ///
    /// `getenv`/`setenv`/`unsetenv` are plain libc and `<stdlib.h>` is already
    /// unconditional in the prelude, so this needs no new include and no boxed
    /// value in either mode.
    fn env_projection_key(_: *const CodeGen, e: *const ast.Expr) ?*const ast.Expr {
        if (e.* != .index) return null;
        const o = e.index.obj;
        if (o.* != .field) return null;
        if (o.field.obj.* != .name) return null;
        if (!std.mem.eql(u8, o.field.obj.name.ident, "os")) return null;
        if (!std.mem.eql(u8, o.field.field, "env")) return null;
        return e.index.key;
    }

    /// Host egress: `stdout:write(text)` — never `io:write`. Dual of `stdin:read`.
    fn streamMethodArityOk(method: []const u8, args_len: usize) bool {
        if (std.mem.eql(u8, method, "write") or std.mem.eql(u8, method, "put")) return args_len == 1;
        if (std.mem.eql(u8, method, "close") or std.mem.eql(u8, method, "flush") or
            std.mem.eql(u8, method, "read") or std.mem.eql(u8, method, "line") or
            std.mem.eql(u8, method, "lines") or std.mem.eql(u8, method, "all"))
            return args_len == 0;
        if (std.mem.eql(u8, method, "bytes")) return args_len == 1;
        if (std.mem.eql(u8, method, "seek") or std.mem.eql(u8, method, "setvbuf")) return args_len >= 1;
        return false;
    }

    /// Stream-instance relations (`fh:write`, `fh:close`, …) on handles and
    /// other unnarrowed subjects. Standing `stdout`/`stdin` keep their own
    /// recognizers; this covers the corpus's `io.open` handle path.
    fn stream_method_result_type(_: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (!subject_home.streamRelation(method)) return null;
        if (!streamMethodArityOk(method, args.len)) return null;
        if (obj.* == .name) {
            const id = obj.name.ident;
            if (std.mem.eql(u8, id, "stdout") or std.mem.eql(u8, id, "stderr")) {
                if (std.mem.eql(u8, method, "write")) return .void;
            }
            if (std.mem.eql(u8, id, "stdin") and
                (std.mem.eql(u8, method, "read") or std.mem.eql(u8, method, "line")))
                return .any;
        }
        if (std.mem.eql(u8, method, "write") or std.mem.eql(u8, method, "close") or
            std.mem.eql(u8, method, "flush") or std.mem.eql(u8, method, "put"))
            return .void;
        return .any;
    }

    fn egress_method_result_type(_: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (obj.* != .name) return null;
        if (!std.mem.eql(u8, method, "write") or args.len != 1) return null;
        if (std.mem.eql(u8, obj.name.ident, "stdout")) return .void;
        return null;
    }

    /// The shape `try_emit_egress_protocol` claims — a VOID host write.
    fn expr_is_host_egress_write(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .method_call) return false;
        const mc = e.method_call;
        if (!std.mem.eql(u8, mc.method, "write") or mc.args.len != 1) return false;
        if (mc.obj.* != .name) return false;
        const stream = mc.obj.name.ident;
        if (!std.mem.eql(u8, stream, "stdout") and !std.mem.eql(u8, stream, "stderr")) return false;
        return self.local_type(stream) == null and self.global_type(stream) == null;
    }

    /// Host egress emit: `stdout:write(x)` / `stderr:write(x)`.
    ///
    /// This is the CANONICAL spelling since the io world law migrated 101
    /// `io.write(x)` sites onto it, and the C backend had NO emitter for it at
    /// all. The receiver fell through to the untyped `:write` face at the
    /// bottom of `.method_call`, which emitted
    /// `lua_file_write_method(stdout, x)` — passing C's `FILE* stdout` MACRO
    /// where a `lua_Value` is expected. Measured on
    /// `main: i64 = () / a = "AA\n" / stdout:write(a) / 0`:
    /// `call to undeclared function 'lua_file_write_method'`, because such a
    /// module is native-scalar and never emits the lua prelude that declares
    /// it. `io.stdout:write(x)` compiled, so the gap was EXACTLY the projected
    /// spelling — and the since-retired in-tree LSP/MCP gates then built
    /// themselves with `--backend=c`.
    ///
    /// IT IS NOT `print`. `io.write` appended no newline and neither does
    /// this; a stream write that ends a line is the caller's byte to spell.
    fn try_emit_egress_protocol(self: *CodeGen, call: anytype) E!bool {
        if (!std.mem.eql(u8, call.method, "write") or call.args.len != 1) return false;
        if (call.obj.* != .name) return false;
        const stream = call.obj.name.ident;
        if (!std.mem.eql(u8, stream, "stdout") and !std.mem.eql(u8, stream, "stderr")) return false;
        // DATA WINS THE NAME: a program that bound `stdout` itself owns it.
        if (self.local_type(stream) != null or self.global_type(stream) != null) return false;

        const arg = call.args[0];
        const t = self.expr_type(arg);

        // A boxed value: the runtime already renders every case, and
        // `lua_write_value` is the exact byte path `io.write(x)` took.
        if (self.moduleNeedsLuaRuntime() and (t == .any or self.expr_emits_lua_value(arg))) {
            self.p("lua_write_value({s}, ", .{stream});
            try self.emit_as_lua_value(arg);
            self.p(")", .{});
            return true;
        }

        if (t == .bool) {
            self.p("fprintf({s}, \"%s\", (", .{stream});
            try self.emit_expr(arg);
            self.p(") ? \"true\" : \"false\")", .{});
            return true;
        }
        if (self.enum_name_of(t)) |ename| {
            if (self.enum_is_payload_free(ename) and self.enum_has_derive(ename, "Display")) {
                self.p("fprintf({s}, \"%s\", duo_{s}_to_string(", .{ stream, ename });
                try self.emit_expr(arg);
                self.p("))", .{});
                return true;
            }
        }
        const phys = types.nominalReprOf(t) orelse t;
        const spec: []const u8 = types.cFormatSpec(phys) orelse "%s";
        self.p("fprintf({s}, \"{s}\", ", .{ stream, spec });
        if (std.mem.eql(u8, spec, "%s") and self.expr_emits_lua_value(arg)) {
            self.p("lua_to_str(", .{});
            try self.emit_expr(arg);
            self.p(")", .{});
        } else {
            try self.emit_expr(arg);
        }
        self.p(")", .{});
        return true;
    }

    /// Readable protocol: subject:read() on stdin or a path/str subject — never io:read().
    fn try_emit_readable_protocol(
        self: *CodeGen,
        call: anytype,
    ) E!bool {
        if (!std.mem.eql(u8, call.method, "read") or call.args.len != 0) return false;
        if (call.obj.* == .name and std.mem.eql(u8, call.obj.name.ident, "stdin")) {
            self.p("duo_io_read_stdin()", .{});
            return true;
        }
        const obj_ty = self.expr_type(call.obj);
        if (obj_ty == .str or call.obj.* == .quoted or call.obj.* == .name) {
            self.p("duo_io_read_path(", .{});
            try self.emit_expr(call.obj);
            self.p(")", .{});
            return true;
        }
        return false;
    }

    fn readable_method_result_type(self: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (std.mem.eql(u8, method, "line") and args.len == 0 and
            obj.* == .name and std.mem.eql(u8, obj.name.ident, "stdin")) return .str;
        if (!std.mem.eql(u8, method, "read") or args.len != 0) return null;
        if (obj.* == .name and std.mem.eql(u8, obj.name.ident, "stdin")) return .str;
        const obj_ty = self.expr_type(obj);
        if (obj_ty == .str or obj.* == .quoted or obj.* == .name) return .str;
        return null;
    }

    /// File-stream protocol: f:write(body) → fputs, f:close() → fclose.
    /// Only for bindings whose local type is .pointer(.void) — the FILE* that
    /// io.open produces in full-native mode. This is the write-side dual of
    /// try_emit_readable_protocol (duo_io_read_path), for generator code that
    /// owns a file for the duration of one spill.
    fn try_emit_file_stream_protocol(
        self: *CodeGen,
        call: anytype,
    ) E!bool {
        if (call.obj.* != .name) return false;
        const obj_ty = self.local_type(call.obj.name.ident) orelse return false;
        if (obj_ty != .pointer) return false;
        if (std.mem.eql(u8, call.method, "write") and call.args.len == 1) {
            self.p("fputs(", .{});
            try self.emit_cstr_arg(call.args[0]);
            self.p(", (FILE*)", .{});
            try self.emit_expr(call.obj);
            self.p(")", .{});
            return true;
        }
        // f:read() over a popen pipe — fgets into a per-call heap buffer,
        // NULL at EOF so `while line != nil` terminates (lib/proc.id capture,
        // lib/fs.id lines). Same fixed shape as the emit side: one line per
        // read call, caller owns the buffer lifetime.
        if (std.mem.eql(u8, call.method, "read") and call.args.len == 0) {
            self.p("duo_fstream_readline((FILE*)", .{});
            try self.emit_expr(call.obj);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, call.method, "close") and call.args.len == 0) {
            // Compile-time provenance: pclose for io.popen streams (reaps the
            // child), fclose for io.open files. The scan walks the enclosing
            // function body for the binding's initializer — no runtime flag.
            if (self.local_binds_popen(call.obj.name.ident)) {
                self.p("pclose((FILE*)", .{});
            } else {
                self.p("fclose((FILE*)", .{});
            }
            try self.emit_expr(call.obj);
            self.p(")", .{});
            return true;
        }
        return false;
    }

    fn file_stream_method_result_type(self: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (obj.* != .name) return null;
        const obj_ty = self.local_type(obj.name.ident) orelse return null;
        if (obj_ty != .pointer) return null;
        if (std.mem.eql(u8, method, "write") and args.len == 1) return .i64;
        // f:read() answers a possibly-absent line — NULL at EOF. The nilable
        // str is represented as .str with NULL sentinel here; the while-test
        // `line != nil` compares against that sentinel natively.
        if (std.mem.eql(u8, method, "read") and args.len == 0) return .str;
        if (std.mem.eql(u8, method, "close") and args.len == 0) return .i64;
        return null;
    }

    /// True when `e` is the expression `io.popen(...)`.
    fn expr_is_io_popen(e: *const ast.Expr) bool {
        if (e.* != .call) return false;
        const c = &e.call;
        if (c.func.* != .field) return false;
        const f = &c.func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "io")) return false;
        return std.mem.eql(u8, f.field, "popen");
    }

    /// Walk the current function body for a local_decl or assign that binds
    /// `name` to `io.popen(...)`. Compile-time provenance: the closer for
    /// `f:close()` must be pclose (reaps the child) when the stream came from
    /// popen, and fclose when it came from io.open. No runtime flag needed.
    fn local_binds_popen(self: *CodeGen, name: []const u8) bool {
        const fb = self.current_func_body orelse return false;
        return self.block_binds_popen(&fb.body, name);
    }
    fn block_binds_popen(self: *CodeGen, blk: *const ast.Block, name: []const u8) bool {
        for (blk.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |ld| {
                    for (ld.names, 0..) |n, i| {
                        if (std.mem.eql(u8, n.ident, name) and i < ld.inits.len and expr_is_io_popen(ld.inits[i]))
                            return true;
                    }
                },
                .assign => |as| {
                    for (as.targets, 0..) |t, i| {
                        if (t.* == .name and std.mem.eql(u8, t.name.ident, name) and i < as.values.len and expr_is_io_popen(as.values[i]))
                            return true;
                    }
                },
                .while_loop => |ws| if (self.block_binds_popen(&ws.body, name)) return true,
                .repeat_loop => |rs| if (self.block_binds_popen(&rs.body, name)) return true,
                .num_for => |nf| if (self.block_binds_popen(&nf.body, name)) return true,
                .gen_for => |gf| if (self.block_binds_popen(&gf.body, name)) return true,
                .do_block => |db| if (self.block_binds_popen(&db.body, name)) return true,
                .if_stmt => |is| {
                    if (self.block_binds_popen(&is.then, name)) return true;
                    for (is.elseifs) |ei| if (self.block_binds_popen(&ei.body, name)) return true;
                    if (is.else_body) |eb| if (self.block_binds_popen(&eb, name)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn comptime_binding_is_scalar_const(self: *CodeGen, name: []const u8) bool {
        const val = self.comptime_bindings().get(name) orelse return false;
        return switch (val) {
            .int, .float, .bool, .string => true,
            else => false,
        };
    }

    fn emit_comptime_const_var_name(self: *CodeGen, name: []const u8) void {
        if (self.current_module_cname.len > 0) {
            // Central guard: if real `duo_g_` storage was emitted for this
            // binding, the folded `<mod>__<name>` symbol does not exist. Several
            // callers reach this helper by different routes, so the check lives
            // here rather than at each one.
            var kb: [512]u8 = undefined;
            if (std.fmt.bufPrint(&kb, "{s}|{s}", .{ self.current_module_cname, name })) |k| {
                if (self.emitted_global_storage.contains(k)) {
                    self.p("duo_g_{s}_{s}", .{ self.current_module_cname, name });
                    return;
                }
            } else |_| {}
            self.p("{s}__{s}", .{ self.current_module_cname, name });
        } else {
            self.p("{s}", .{name});
        }
    }

    fn emit_var_name(self: *CodeGen, name: []const u8) void {
        self.emit_var_name_mode(name, .read);
    }

    fn emit_var_name_mode(self: *CodeGen, name: []const u8, mode: enum { read, write }) void {
        var name_buf: [256]u8 = undefined;
        if (self.function_c_names.get(name)) |cname| {
            self.p("{s}", .{cname});
        } else if (self.is_func_local_name(name)) {
            // LAW-SCOPE rung 1. This branch used to sit below the `duo_g_`
            // branches, so a function-body `local total` was DECLARED as
            // `int64_t total = 7` and then READ as `duo_g_<mod>_total` — the
            // module binding, a different value. It printed 100 where the
            // language says 7, with no diagnostic: the declaration emitter and
            // the use emitter each picked their own spelling for one binding.
            if (self.is_dense_table_name(name)) {
                self.p("__dt_{s}", .{name});
            } else {
                self.p("{s}", .{name});
            }
        } else if (self.current_module_cname.len > 0 and blk: {
            var kb: [512]u8 = undefined;
            const k = std.fmt.bufPrint(&kb, "{s}|{s}", .{ self.current_module_cname, name }) catch break :blk false;
            break :blk self.emitted_global_storage.contains(k);
        }) {
            // Real storage exists under this name — use it, whatever the binding
            // was classified as. The module export table was still spelling it
            // `<mod>__<name>` after the storage moved to `duo_g_`.
            self.p("duo_g_{s}_{s}", .{ self.current_module_cname, name });
        } else if (mode == .read and self.current_module_cname.len > 0 and
            self.const_read_only.contains(name))
        {
            // Must precede the `duo_g_` branches: sema reports these as globals,
            // but their only storage is the `static const <mod>__<name>` above.
            self.emit_comptime_const_var_name(name);
        } else if (self.current_module_cname.len > 0 and !is_runtime_global(name) and
            !self.is_param_name(name) and self.global_type(name) != null)
        {
            self.p("duo_g_{s}_{s}", .{ self.current_module_cname, name });
        } else if (!is_runtime_global(name) and !self.is_param_name(name) and
            self.global_type(name) != null)
        {
            if (self.current_module_cname.len > 0) {
                self.p("duo_g_{s}_{s}", .{ self.current_module_cname, name });
            } else {
                self.p("duo_g_{s}", .{name});
            }
        } else if (self.is_local_name(name)) {
            if (self.is_dense_table_name(name)) {
                self.p("__dt_{s}", .{name});
            } else {
                self.p("{s}", .{name});
            }
        } else if (mode == .read and self.comptime_binding_is_scalar_const(name)) {
            self.emit_comptime_const_var_name(name);
        } else if (self.comptime_bindings().get(name) != null) {
            if (self.current_module_cname.len > 0) {
                self.p("{s}__{s}", .{ self.current_module_cname, name });
            } else {
                self.p("{s}", .{name});
            }
        } else if (self.vararg_funcs.get(name)) |cname| {
            self.p("{s}__argv", .{cname});
        } else if (self.func_bodies.get(self.mangled_name(name, &name_buf)) != null) {
            if (self.current_module_cname.len > 0) {
                self.p("{s}__{s}", .{ self.current_module_cname, name });
            } else {
                self.p("{s}", .{name});
            }
        } else {
            self.p("{s}", .{name});
        }
    }

    fn root_name(expr: *const ast.Expr) ?[]const u8 {
        return switch (expr.*) {
            .name => |n| n.ident,
            .field => |f| root_name(f.obj),
            .index => |idx| root_name(idx.obj),
            else => null,
        };
    }

    fn should_bind_field_call(self: *CodeGen, func: *const ast.Expr, arg_count: usize) bool {
        // Only colon calls bind an implicit receiver; dotted field calls use
        // ordinary dispatch even in Duo mode.
        _ = self;
        _ = func;
        _ = arg_count;
        return false;
    }

    /// Internal record parameters are passed by pointer so mutation persists
    /// across application boundaries. This is one translation-unit convention:
    /// root emission, embedded emission, and descriptor spelling cannot select
    /// different ABIs for the same semantic record.
    ///
    /// Bridge deletion: once edge-local representation publishes one selected
    /// internal application ABI from place/mutation/alias/escape facts, callers
    /// and callees consume that fact and this uniform convention disappears.
    /// Header-declared foreign C ABI is separate and never consults this helper.
    /// The `.table_type` behind a record parameter, following the alias a
    /// `.@"struct"` annotation names. Same resolution `internal_record_param_by_ptr`
    /// performs, factored out so an emitter can reach the field list.
    fn resolved_record_type(self: *const CodeGen, rt: RT) ?RT {
        var resolved = rt;
        if (resolved == .@"struct") {
            if (self.record_aliases.get(resolved.@"struct".name)) |alias_rt| resolved = alias_rt;
        }
        return if (resolved == .table_type) resolved else null;
    }

    fn internal_record_param_by_ptr(self: *const CodeGen, rt: RT) bool {
        var resolved = rt;
        if (resolved == .@"struct") {
            if (self.record_aliases.get(resolved.@"struct".name)) |alias_rt| resolved = alias_rt;
        }
        return resolved == .table_type;
    }

    fn expr_is_native_record_ptr_param(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .name) return false;
        const fb = self.current_func_body orelse return false;
        for (fb.params) |par| {
            if (std.mem.eql(u8, par.name, e.name.ident)) {
                return self.internal_record_param_by_ptr(self.resolve_type(par.typ));
            }
        }
        return false;
    }

    /// A RECORD PARAMETER TAKEN BY POINTER AND RETURNED BY VALUE HAS TO BE
    /// DEREFERENCED, and nothing did it.
    ///
    /// A relation whose result is a record has a BY-VALUE C return type
    /// (`self.typ` emits `duo_rec_X`), while a record PARAMETER is passed by
    /// pointer (`internal_record_param_by_ptr`). Every other use of such a
    /// parameter already knows this — `emit_native_field_access` writes `->`,
    /// `emit_arg_for_param` passes the pointer through — but `return pack`
    /// emitted the bare name:
    ///
    ///     pack: { kinds: []i64, count: i64 }
    ///     self: pack = (pack: pack)
    ///       pack
    ///
    ///     duo_rec_X self(duo_rec_X *pack) { return pack; }
    ///     error: returning 'duo_rec_X *' from a function with incompatible
    ///            result type 'duo_rec_X'
    ///
    /// Six lines, no other module involved. It is one of the two remaining C
    /// errors in `lib/compiler/token_view.id`'s transfer artifact, which is why
    /// it is repaired here rather than recorded: without it the GAP-134
    /// prerequisite still cannot be linked, and "the calls are realized" would
    /// be a claim about the emitter rather than a program that runs.
    fn emit_returned_expr(self: *CodeGen, val: *const ast.Expr) E!void {
        if (val.* == .name and self.current_ret != .any and
            self.expr_is_native_record_ptr_param(val))
        {
            self.p("(*", .{});
            try self.emit_expr(val);
            self.p(")", .{});
            return;
        }
        try self.emit_expr(val);
    }

    fn field_base_is_native_record_ptr(self: *CodeGen, obj: *const ast.Expr) bool {
        if (self.expr_is_native_record_ptr_param(obj)) return true;
        if (obj.* == .field) return self.field_base_is_native_record_ptr(obj.field.obj);
        return false;
    }

    fn emit_native_field_access(self: *CodeGen, obj: *const ast.Expr, field: []const u8) E!void {
        if (self.expr_is_native_record_ptr_param(obj)) {
            try self.emit_expr(obj);
            self.p("->{s}", .{field});
        } else if (obj.* == .field) {
            try self.emit_native_field_access(obj.field.obj, obj.field.field);
            // A nested record field is embedded BY VALUE (`duo_rec_X inr;`), not
            // a pointer, so every hop after the root uses `.`: `o->inr.a`, never
            // `o->inr->a`. Deciding this from whether the ROOT is a pointer
            // param emitted `->` for all hops and produced "member reference
            // type ... is not a pointer" — which is what made a record holding
            // a record uncallable across a module boundary, and is why
            // std.compiler.lexer (Lexer holds Tok and Loc) could not drive
            // SH-04's token parser.
            self.p(".{s}", .{field});
        } else {
            try self.emit_expr(obj);
            self.p(".{s}", .{field});
        }
    }

    fn emit_lvalue(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (expr.* == .field and self.field_base_is_native_record_ptr(expr.field.obj)) {
            try self.emit_native_field_access(expr.field.obj, expr.field.field);
            return;
        }
        if (expr.* == .name) {
            // Inside a closure, LOCAL upvalue writes go through the closure struct.
            // Global upvalues are accessed directly via their C name.
            if (self.closure_ctx) |fb| {
                // Only redirect to closure struct if it's NOT a known global
                const is_global = (!self.is_local_name(expr.name.ident) and self.global_type(expr.name.ident) != null);
                if (!is_global) {
                    for (fb.upvalues, 0..) |uv, i| {
                        if (std.mem.eql(u8, uv.name, expr.name.ident)) {
                            if (upvalue_uses_pointer(uv)) {
                                self.p("(*cl->up{d})", .{i});
                            } else {
                                self.p("cl->up{d}", .{i});
                            }
                            return;
                        }
                    }
                }
            }
            self.emit_var_name_mode(expr.name.ident, .write);
            return;
        }
        try self.emit_expr(expr);
    }

    /// Check if a mutable upvalue should use pointer indirection.
    /// Only lua_Value (untyped) upvalues use the heap-cell pattern.
    /// Typed native upvalues are captured by value (no mutation sharing).
    /// When a captured local was emitted as a native scalar but the closure slot
    /// is a `lua_Value`, returns the scalar type so the capture can be boxed.
    /// Returns null when no coercion is needed.
    fn upvalue_scalar_coercion(self: *CodeGen, uv: ast.Upvalue) ?RT {
        if (uv.typ) |t| {
            if (t != .any) return null;
        } else return null;
        const lt = self.local_type(uv.name) orelse return null;
        return switch (lt) {
            .any, .nil, .void => null,
            else => lt,
        };
    }

    fn upvalue_uses_pointer(uv: ast.Upvalue) bool {
        if (!uv.mutable) return false;
        // Only use pointer for untyped (lua_Value) upvalues.
        //
        // An *unknown* type is not the same as `.any` and must not take the
        // pointer path. `base = 100` (no annotation) left `sym.typ` null, so a
        // read-only capture was emitted as `duo_make_closure_0(&base)` against a
        // `lua_Value*` parameter — both a type confusion (`base` is `int64_t`) and
        // a dangling pointer into the dead frame of the enclosing function. It
        // silently returned garbage: `base = 100; f(1)` gave 2 instead of 101,
        // while the annotated `base: i64 = 100` was correct. Capture by value when
        // the type is unknown; the genuinely shared-mutable case is the one that
        // needs a heap cell (see the note on `Upvalue.mutable`) and does not
        // compile today either way.
        const t = uv.typ orelse return false;
        if (t != .any) return false;
        // Even for a `.any` upvalue the pointer is `&local` — the address of a
        // stack slot in the *enclosing* frame. That frame is gone by the time the
        // closure escapes, so the pointer path is only accidentally correct when
        // the closure is invoked before its creator returns. Shared mutation needs
        // a heap cell (see `Upvalue.mutable`); until that exists, capture by value,
        // which is correct for every read-only capture and no worse for the rest.
        return false;
    }

    /// Find the index of a name as an upvalue of the current closure context.
    /// Returns null if not inside a closure or the name isn't an upvalue.
    fn find_upvalue_in_closure(self: *CodeGen, name: []const u8) ?usize {
        const fb = self.closure_ctx orelse return null;
        for (fb.upvalues, 0..) |uv, i| {
            if (std.mem.eql(u8, uv.name, name) and uv.is_local) {
                // Skip if this name is a known global (accessed directly).
                if (!self.is_local_name(name) and self.global_type(name) != null) return null;
                return i;
            }
        }
        return null;
    }

    fn expr_tree_has_float(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .float_lit => true,
            .binop => |b| self.expr_tree_has_float(b.lhs) or self.expr_tree_has_float(b.rhs),
            .unop => |u| self.expr_tree_has_float(u.operand),
            else => false,
        };
    }

    fn ind(self: *CodeGen) void {
        var i: u32 = 0;
        while (i < self.indent) : (i += 1) self.w.writeAll("    ") catch {};
    }

    pub fn p(self: *CodeGen, comptime fmt: []const u8, args: anytype) void {
        self.w.print(fmt, args) catch {};
    }

    pub fn pl(self: *CodeGen, comptime fmt: []const u8, args: anytype) void {
        self.ind();
        self.w.print(fmt ++ "\n", args) catch {};
    }

    fn nl(self: *CodeGen) void {
        self.w.writeByte('\n') catch {};
    }

    fn typ(self: *CodeGen, rt: RT) void {
        var buf: [128]u8 = undefined;
        self.p("{s}", .{self.c_type(rt, &buf)});
    }

    fn is_table_module(self: *const CodeGen, name: []const u8) bool {
        if (self.table_methods) |tm| return tm.contains(name);
        return false;
    }

    fn is_table_module_type(self: *const CodeGen, rt: RT) bool {
        return rt == .@"struct" and self.is_table_module(rt.@"struct".name);
    }

    fn normalize_table_module_type(self: *const CodeGen, rt: RT) RT {
        if (self.is_table_module_type(rt)) return .any;
        return rt;
    }

    fn c_type(self: *const CodeGen, rt: RT, buf: []u8) []const u8 {
        if (self.is_table_module_type(rt)) return "lua_Value";
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                if (alias_rt == .table_type) {
                    const hash = record_content_hash(alias_rt.table_type);
                    return std.fmt.bufPrint(buf, "duo_rec_{x}", .{hash}) catch rt.c_type(buf);
                }
            }
        }
        return rt.c_type(buf);
    }

    fn table_module_has_method(self: *const CodeGen, table_name: []const u8, method: []const u8) bool {
        const methods = if (self.table_methods) |tm| tm.get(table_name) else null;
        if (methods) |ms| {
            for (ms.items) |m| {
                if (std.mem.eql(u8, m, method)) return true;
            }
        }
        return false;
    }

    fn type_has_static_method(self: *const CodeGen, type_name: []const u8, method: []const u8) bool {
        if (self.table_module_has_method(type_name, method)) return true;
        if (self.alias_methods.get(type_name)) |ms| {
            for (ms.items) |m| {
                if (std.mem.eql(u8, m, method)) return true;
            }
        }
        if (self.alias_defs.get(type_name)) |ad| {
            if (std.mem.eql(u8, method, "hash") and alias_has_derive(ad.attributes, "Hash")) return true;
            if (std.mem.eql(u8, method, "to_string") and alias_has_derive(ad.attributes, "Display")) return true;
            if (std.mem.eql(u8, method, "eq") and alias_has_derive(ad.attributes, "Eq")) return true;
            if (std.mem.eql(u8, method, "clone") and alias_has_derive(ad.attributes, "Clone")) return true;
        }
        return false;
    }

    fn struct_type_for_mono_binding(self: *CodeGen, ident: []const u8) ?[]const u8 {
        if (self.current_mono_spec) |spec| {
            for (spec.template.params) |par| {
                if (std.mem.eql(u8, par.name, ident)) {
                    const pt = spec.resolveType(par.typ);
                    if (pt == .@"struct") return pt.@"struct".name;
                }
            }
            if (spec.value_types.get(ident)) |vt| {
                if (vt == .@"struct") return vt.@"struct".name;
            }
        }
        if (self.closure_ctx) |fb| {
            for (fb.params) |par| {
                if (std.mem.eql(u8, par.name, ident)) {
                    const pt = if (self.current_mono_spec) |spec|
                        spec.resolveType(par.typ)
                    else
                        types.resolve(par.typ, null, self.alloc) catch .any;
                    if (pt == .@"struct") return pt.@"struct".name;
                }
            }
        }
        return null;
    }

    fn static_dispatch_type_for_expr(self: *CodeGen, e: *const ast.Expr, method: []const u8) ?[]const u8 {
        if (e.* != .name) return null;
        if (self.struct_type_for_mono_binding(e.name.ident)) |tname| {
            if (self.type_has_static_method(tname, method)) return tname;
        }
        if (self.table_module_type_for_expr(e)) |tname| {
            if (self.type_has_static_method(tname, method)) return tname;
        }
        const ot = self.expr_type(e);
        if (ot == .@"struct" and self.type_has_static_method(ot.@"struct".name, method))
            return ot.@"struct".name;
        return null;
    }

    fn table_module_type_for_expr(self: *CodeGen, e: *const ast.Expr) ?[]const u8 {
        if (e.* != .name) return null;
        const ident = e.name.ident;
        if (self.current_mono_spec) |spec| {
            // Monomorphized function params (e.g. value: T with T = Good).
            for (spec.template.params) |par| {
                if (std.mem.eql(u8, par.name, ident)) {
                    const pt = spec.resolveType(par.typ);
                    if (self.is_table_module_type(pt)) return pt.@"struct".name;
                }
            }
            if (spec.value_types.get(ident)) |vt| {
                if (self.is_table_module_type(vt)) return vt.@"struct".name;
            }
        }
        if (self.closure_ctx) |fb| {
            for (fb.params) |par| {
                if (std.mem.eql(u8, par.name, ident)) {
                    const pt = if (self.current_mono_spec) |spec|
                        spec.resolveType(par.typ)
                    else
                        types.resolve(par.typ, null, self.alloc) catch .any;
                    if (self.is_table_module_type(pt)) return pt.@"struct".name;
                }
            }
        }
        const ot = self.expr_type(e);
        if (ot == .@"struct" and self.is_table_module(ot.@"struct".name))
            return ot.@"struct".name;
        return null;
    }

    fn try_emit_static_method_call(
        self: *CodeGen,
        type_name: []const u8,
        method: []const u8,
        obj: ?*const ast.Expr,
        args: []const *ast.Expr,
    ) E!bool {
        if (!self.type_has_static_method(type_name, method)) return false;
        self.p("{s}__{s}(", .{ type_name, method });
        const pass_self = obj != null and !self.is_table_module(type_name);
        if (pass_self) {
            if (self.record_aliases.get(type_name)) |rt| {
                try self.emit_arg_for_param(obj.?, rt, true);
            } else {
                try self.emit_expr(obj.?);
            }
            if (args.len > 0) self.p(", ", .{});
        }
        for (args, 0..) |arg, i| {
            if (pass_self or i > 0) self.p(", ", .{});
            try self.emit_expr(arg);
        }
        self.p(")", .{});
        return true;
    }

    fn try_emit_table_module_method_call(
        self: *CodeGen,
        table_name: []const u8,
        method: []const u8,
        args: []const *ast.Expr,
    ) E!bool {
        return self.try_emit_static_method_call(table_name, method, null, args);
    }

    /// gap[032]: `recv:sub(i, j)` where the receiver's static type is `any`.
    ///
    /// The receiver's runtime type decides. A string takes the string face; a
    /// table takes the ordinary member lookup, unchanged, so a table carrying
    /// its own `sub` still wins its own name (LAW-CALL). The receiver and every
    /// argument are bound to temporaries first, so each is evaluated exactly
    /// once no matter which arm runs.
    ///
    /// Names already claimed by the file and str-buf faces in the `any` arm
    /// (`get`, `set`, `read`, `write`, `len`, `close`, ...) are deliberately
    /// absent — this only covers faces that have no other meaning on `any`.
    ///
    /// `result_rt` is the type the USE SITE demands. Both arms of the guard
    /// answer a boxed value, so a native demand has to be coerced at the end of
    /// the statement-expression; without it `b: i64 = bytes:byte(1)` emitted
    /// `int64_t b = ({ … lua_Value … });` and clang refused the initializer.
    /// The operation-first face (`string.byte(bytes, 1)`) had the coercion all
    /// along — the same two-faces-of-one-fact divergence, one line lower down.
    fn try_emit_guarded_string_face(
        self: *CodeGen,
        method: []const u8,
        obj: *ast.Expr,
        args: []const *ast.Expr,
        result_rt: RT,
    ) E!bool {
        if (!self.moduleNeedsLuaRuntime()) return false;
        const Face = struct { name: []const u8, cfn: []const u8, arity: usize };
        const faces = [_]Face{
            .{ .name = "sub", .cfn = "lua_str_sub", .arity = 3 },
            .{ .name = "byte", .cfn = "lua_str_byte", .arity = 3 },
            .{ .name = "rep", .cfn = "lua_str_rep", .arity = 3 },
            .{ .name = "gsub", .cfn = "lua_str_gsub", .arity = 3 },
            .{ .name = "gmatch", .cfn = "lua_str_gmatch", .arity = 3 },
            .{ .name = "find", .cfn = "lua_str_find", .arity = 4 },
            .{ .name = "match", .cfn = "lua_str_match", .arity = 2 },
            .{ .name = "split", .cfn = "lua_str_split", .arity = 2 },
            .{ .name = "starts_with", .cfn = "lua_str_starts_with", .arity = 2 },
            .{ .name = "ends_with", .cfn = "lua_str_ends_with", .arity = 2 },
            .{ .name = "lower", .cfn = "lua_str_lower", .arity = 1 },
            .{ .name = "upper", .cfn = "lua_str_upper", .arity = 1 },
            .{ .name = "reverse", .cfn = "lua_str_reverse", .arity = 1 },
        };
        var face: ?Face = null;
        for (faces) |f| {
            if (std.mem.eql(u8, f.name, method)) {
                face = f;
                break;
            }
        }
        const f = face orelse return false;
        // A face taking more arguments than the string form accepts is not the
        // string form at all; leave it to the member path.
        if (args.len + 1 > f.arity) return false;

        const hash = calc_lua_hash(method);
        const coerced = self.emit_lua_result_coerce_prefix(result_rt);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __self = ", .{});
        try self.emit_as_lua_value(obj);
        self.p(";\n", .{});
        for (args, 0..) |arg, i| {
            self.ind();
            self.p("lua_Value __a{d} = ", .{i});
            try self.emit_as_lua_value(arg);
            self.p(";\n", .{});
        }
        self.ind();
        self.p("__self.type == VAL_STRING ? {s}(__self", .{f.cfn});
        var i: usize = 1;
        while (i < f.arity) : (i += 1) {
            if (i - 1 < args.len) self.p(", __a{d}", .{i - 1}) else self.p(", lua_val_nil()", .{});
        }
        self.p(") : ({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __fn = lua_table_get_str_lit(__self, \"{s}\", {d}u, {d});\n", .{ method, hash, method.len });
        self.ind();
        // `duo_args`, not `__argv`: mingw-w64's <stdlib.h> defines `__argv` as
        // `(*__p___argv())`, so every emitted call site expanded into a
        // function-call initializer and x86_64-windows died with "conflicting
        // types for '__p___argv'". A leading `__` is reserved for the
        // implementation in every C translation unit; the platform was within
        // its rights and the generator was not. (GAP-040)
        self.p("lua_Value duo_args[{d}] = {{__self", .{args.len + 1});
        for (args, 0..) |_, j| self.p(", __a{d}", .{j});
        self.p("}};\n", .{});
        self.ind();
        self.p("lua_invoke(__fn, {d}, duo_args);\n", .{args.len + 1});
        self.indent -= 1;
        self.ind();
        self.p("}});\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
        if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
        return true;
    }

    /// Emit a C parameter declaration. Function and fixed-array types need the
    /// identifier inside the declarator (`ret (*name)(args)`, `T name[N]`), so
    /// they cannot use the ordinary `type` followed by `name` emission.
    fn emit_param_decl(self: *CodeGen, rt: RT, name: ?[]const u8) void {
        switch (rt) {
            .func => |f| {
                self.typ(f.ret.*);
                self.p(" (*", .{});
                if (name) |n| self.p("{s}", .{n});
                self.p(")(", .{});
                if (f.params.len == 0) {
                    self.p("void", .{});
                } else {
                    for (f.params, 0..) |param, i| {
                        if (i > 0) self.p(", ", .{});
                        self.emit_param_decl(param, null);
                    }
                }
                self.p(")", .{});
            },
            .array => |a| {
                var inner_buf: [128]u8 = undefined;
                const inner = a.elem.c_type(&inner_buf);
                if (std.mem.eql(u8, inner, "lua_Value") and a.size == null) {
                    self.p("lua_Value", .{});
                    if (name) |n| self.p(" {s}", .{n});
                } else {
                    self.typ(a.elem.*);
                    if (name) |n| self.p(" {s}", .{n});
                    if (a.size) |size| self.p("[{d}]", .{size}) else self.p("[]", .{});
                }
            },
            else => {
                if (self.internal_record_param_by_ptr(rt)) {
                    self.typ(rt);
                    if (name) |n| self.p(" *{s}", .{n}) else self.p(" *", .{});
                } else {
                    self.typ(rt);
                    if (name) |n| self.p(" {s}", .{n});
                }
            },
        }
    }

    fn emit_func_params(self: *CodeGen, params: []const ast.FuncParam) void {
        if (params.len == 0) {
            self.p("void", .{});
            return;
        }
        for (params, 0..) |*param, i| {
            if (i > 0) self.p(", ", .{});
            self.emit_param_decl(self.resolve_type(param.typ), param.name);
        }
    }

    fn uses_multi_return(self: *CodeGen, init_expr: *const ast.Expr, name_count: usize) bool {
        if (name_count <= 1) return false;
        if (init_expr.* == .call) return true;
        return self.expr_type(init_expr) == .any;
    }

    fn comptime_value_type(self: *CodeGen, e: *const ast.Expr) ?RT {
        const value = comptime_eval.evalWithBindings(e, self.comptime_bindings(), self.comptime_eval_options()) catch return null;
        return switch (value) {
            .bool => .bool,
            .int => .i64,
            .float, .decimal => .f64,
            .string => .str,
            .nil, .table, .func, .unavailable => .any,
        };
    }

    fn expr_type(self: *CodeGen, e: *const ast.Expr) RT {
        if (e.* == .name) {
            if (self.closure_ctx) |fb| {
                for (fb.params) |par| {
                    if (std.mem.eql(u8, par.name, e.name.ident)) {
                        return types.resolve(par.typ, null, self.alloc) catch .any;
                    }
                }
                for (fb.upvalues) |uv| {
                    if (std.mem.eql(u8, uv.name, e.name.ident) and uv.is_local) {
                        if (uv.typ) |ut| return ut;
                    }
                }
            }
            if (self.local_type(e.name.ident)) |rt| return rt;
            // Check module-level globals (e.g. OP_NOP = 0x01) — these are
            // typed via the const_decl/global_decl type map and should produce
            // native comparisons instead of falling through to lua_eq.
            if (self.global_type(e.name.ident)) |rt| return rt;
        }
        if (e.* == .index) {
            // THE WORLD'S PROJECTIONS ANSWER WHAT THE ROSTER SAYS THEY ANSWER.
            //
            // The environment projection answers TEXT — `getenv` returns
            // `char*`. Without an answer here the read typed as `.any`, took
            // the boxed path, and emitted `lua_to_str` against a value nothing
            // produced. That was written for `env` ALONE, and `arg` — the same
            // shape, the same `char*`, lowered by `dnir_lower` with `.ty =
            // .str` — had no arm at all, so the two member edges of one world
            // disagreed about whether their result had a type:
            //
            //     env("HOME"):len()    ANSWERS
            //     arg(1):len()         REFUSED  DNB001 method-unresolved:len
            //
            // `subject_home.osDotMember` is now the one place a member's result
            // is declared, and `dnir_lower` reads the same row, so a member
            // added to the roster is typed at both ends with no edit here.
            if (self.osMemberOf(e.index.obj)) |m| {
                if (m.face == .projection and m.result != .any) return m.result;
            }
            const idx = e.index;
            if (idx.obj.* == .name) {
                if (self.dense_literal_table(idx.obj.name.ident)) |nd| {
                    return switch (nd.elem) {
                        .i64 => .i64,
                        .f64 => .f64,
                        .str => .str,
                    };
                }
            }
            if (self.req_module_dense_index_info(idx.obj)) |nd| {
                return switch (nd.elem) {
                    .i64 => .i64,
                    .f64 => .f64,
                    .str => .str,
                };
            }
            if (self.is_dense_table_index(idx.obj)) return .i64;
            if (self.indexed_element_type(self.expr_type(idx.obj))) |t| return t;
        }
        // A MEMBER EDGE WHOSE FACE IS A VALUE *IS* THE VALUE AT ITS OWN NODE.
        // `os.cwd` is the working directory, not a relation to apply, and
        // `table_apply` converges the bare `cwd()` onto exactly this node. The
        // declared result is the roster's, the same row `dnir_lower.lowerField`
        // realizes.
        if (e.* == .field) {
            if (self.osMemberOf(e)) |m| {
                if (m.face == .value and m.result != .any) return m.result;
            }
        }
        // `s(i)` on a `str` is a BYTE, and a byte is an integer.
        if (self.str_byte_index(e) != null) return .i64;
        if (e.* == .call) {
            const c = e.call;
            // `to(T)(v)` yields T. Without this the type is unknown and a
            // chained projection (`x:to(i64):to(str)`) cannot resolve its
            // second receiver — the edge knows its own target, so say so.
            //
            // law.host.projection { projects = to, authority = false }
            // gap[082] is the deletion gate. This literal-string comparison is
            // the HOST'S PROJECTION of a relation that now exists as data in
            // the relation store; it is not the authority on what `to` means
            // and it must not grow. It survives because the store only answers
            // for descriptor pairs somebody declared, and the primitive
            // conversions are still taught to the code generator by hand
            // rather than written as edges in `lib/std`. When they are, this
            // goes.
            if (c.func.* == .call and c.func.call.func.* == .name and
                std.mem.eql(u8, c.func.call.func.name.ident, "to") and
                c.func.call.args.len == 1 and c.func.call.args[0].* == .name)
            {
                if (self.mem_type_from_name(c.func.call.args[0].name.ident)) |t| return t;
                if (std.mem.eql(u8, c.func.call.args[0].name.ident, "str")) return .str;
            }
        }
        // `len(x)` yields what `#x` yields — one edge, one result type.
        if (e.* == .call and e.call.func.* == .name and
            std.mem.eql(u8, e.call.func.name.ident, "len") and e.call.args.len == 1 and
            !self.user_owns_name("len"))
        {
            var lu = ast.Expr{ .unop = .{ .loc = e.call.loc, .op = .len, .operand = e.call.args[0] } };
            return self.expr_type(&lu);
        }
        // Same edge, receiver-first spelling: `v:to(T)` also yields T.
        // law.host.projection { projects = to, authority = false } — gap[082].
        if (e.* == .method_call) {
            const mc = e.method_call;
            if (std.mem.eql(u8, mc.method, "to") and mc.args.len == 1 and mc.args[0].* == .name) {
                if (self.mem_type_from_name(mc.args[0].name.ident)) |t| return t;
                if (std.mem.eql(u8, mc.args[0].name.ident, "str")) return .str;
            }
        }
        if (e.* == .call) {
            const c = e.call;
            if (self.enum_eq_call_result_type(c.func, c.args)) |t| return t;
            if (self.enum_display_call_result_type(c.func, c.args)) |t| return t;
            if (self.mem_call_result_type(c.func, c.args)) |t| return t;
            if (self.atomic_call_result_type(c.func, c.args)) |t| return t;
            if (self.math_call_result_type(c.func, c.args)) |t| return t;
            if (self.table_call_result_type(c.func, c.args)) |t| return t;
            if (self.os_call_result_type(c.func, c.args)) |t| return t;
            if (self.io_call_result_type(c.func, c.args)) |t| return t;
            if (self.ffi_call_result_type(c.func, c.args)) |t| return t;
            if (self.net_call_result_type(c.func, c.args)) |t| return t;
            if (self.coroutine_call_result_type(c.func, c.args)) |t| return t;
            if (self.debug_call_result_type(c.func, c.args)) |t| return t;
            if (self.jit_call_result_type(c.func, c.args)) |t| return t;
            if (self.builtin_call_result_type(c.func, c.args)) |t| return t;
            if (self.infer_req_module_call_return_type(e)) |t| return t;
            if (c.func.* == .name) {
                if (std.mem.eql(u8, c.func.name.ident, "__constexpr") and c.args.len == 1) {
                    if (self.comptime_value_type(c.args[0])) |rt| return rt;
                    return self.expr_type(c.args[0]);
                }
                if (self.mono) |m| {
                    const env = self.current_mono_spec;
                    if (m.findSpecializationForCall(c.func.name.ident, c.args, env)) |spec| {
                        return spec.resolveType(spec.template.ret_type);
                    }
                }
            }
        }
        if (e.* == .method_call) {
            const mc = e.method_call;
            if (self.string_method_result_type(mc.method, mc.obj, mc.args)) |t| return t;
            if (self.readable_method_result_type(mc.method, mc.obj, mc.args)) |t| return t;
            if (self.file_stream_method_result_type(mc.method, mc.obj, mc.args)) |t| return t;
            if (self.world_method_result_type(mc.method, mc.obj, mc.args)) |t| return t;
            // gap[025] / FACE-CALL: a receiver face over a FREE function has the
            // callee's declared return type. Without this the method call types
            // as `.any`, the caller wraps it in `lua_to_num(...)`, and the
            // native projection cannot satisfy it — which is what layer 4 of
            // this gap was. Read from the declaration rather than a table of
            // method NAMES like the static-dispatch branch below (that list is
            // the names-carry-semantics shape LAW-ONE denies).
            if (self.func_decls.get(mc.method)) |fd| {
                return self.resolve_type(contract_ret(&fd.func));
            }
            if (self.relationEdgeFuncDecl(mc.method, mc.args.len)) |fd| {
                return self.resolve_type(contract_ret(&fd.func));
            }
            {
                var tbuf: [256]u8 = undefined;
                if (self.func_decls.get(self.mangled_name(mc.method, &tbuf))) |fd| {
                    return self.resolve_type(contract_ret(&fd.func));
                }
            }
            if (self.subjectRelation(mc.method, mc.obj)) |resolved| {
                return self.resolve_type(contract_ret(&resolved.decl.func));
            }
            if (self.probeSubjectRelationType(mc.method, mc.obj, mc.args.len)) |t| return t;
            if (self.static_dispatch_type_for_expr(mc.obj, mc.method)) |_| {
                if (std.mem.eql(u8, mc.method, "increment") or
                    std.mem.eql(u8, mc.method, "decrement") or
                    std.mem.eql(u8, mc.method, "greet"))
                    return .void;
                if (std.mem.eql(u8, mc.method, "lang")) return .str;
                if (std.mem.eql(u8, mc.method, "to_string")) return .str;
                if (std.mem.eql(u8, mc.method, "eq")) return .bool;
                return .i64;
            }
            if (std.mem.eql(u8, mc.method, "len") and self.expr_type(mc.obj) == .any) return .i64;
            if (std.mem.eql(u8, mc.method, "eq")) {
                if (self.expr_enum_name(mc.obj)) |enum_name| {
                    if (self.enum_has_derive(enum_name, "Eq") and self.enum_is_payload_free(enum_name)) return .bool;
                }
            }
            if (std.mem.eql(u8, mc.method, "to_string")) {
                if (self.expr_enum_name(mc.obj)) |enum_name| {
                    if (self.enum_has_derive(enum_name, "Display") and self.enum_is_payload_free(enum_name)) return .str;
                }
            }
        }
        if (e.* == .binop) {
            const b = e.binop;
            switch (b.op) {
                .eq, .neq, .lt, .gt, .leq, .geq, .contains => return .bool,
                else => {},
            }
            const lt = self.expr_type(b.lhs);
            const rt = self.expr_type(b.rhs);
            if (b.op == .@"or" and b.lhs.* == .binop and b.lhs.binop.op == .@"and") {
                const then_t = self.expr_type(b.lhs.binop.rhs);
                if (then_t.eql(rt) and self.lua_and_or_value_type_is_native(then_t)) return then_t;
                // A chain of comparisons joined by and/or lowers to native
                // &&/|| — the chain IS .bool. Typing it .any wraps the whole
                // condition in lua_to_bool(...), which a module that needs no
                // Lua runtime never declares (GAP-145 O3 dump-c --lib).
                if (then_t.eql(rt) and then_t == .bool) return .bool;
                return .any;
            }
            if (b.op == .@"and" or b.op == .@"or") {
                if (lt.eql(rt)) return lt;
                return .any;
            }
            if (b.op == .concat) return .str;
            if (lt.is_native() and rt.is_native()) {
                if (lt == .f64 or rt == .f64) return .f64;
                if (lt.is_integer() and rt.is_integer()) return .i64;
                return lt;
            }
            // One native numeric + one dynamic operand produces a native result when
            // the dynamic side is safe to unbox (numeric table access, numeric-marked
            // lua_Value local, or dynamic table read) and emit will use
            // try_emit_mixed_native_binop.
            if (lt.is_numeric() and rt == .any and
                (self.dynamic_binop_operand_is_safe_native_unbox(b.rhs) or
                    self.dynamic_binop_operand_is_dynamic_table_read(b.rhs) or
                    self.dynamic_binop_operand_is_numeric_access(b.lhs)))
            {
                if (lt == .f64 or b.op == .div or self.expr_tree_has_float(b.rhs)) return .f64;
                return lt;
            }
            if (rt.is_numeric() and lt == .any and
                (self.dynamic_binop_operand_is_safe_native_unbox(b.lhs) or
                    self.dynamic_binop_operand_is_dynamic_table_read(b.lhs) or
                    self.dynamic_binop_operand_is_numeric_access(b.rhs)))
            {
                if (rt == .f64 or b.op == .div or self.expr_tree_has_float(b.lhs)) return .f64;
                return rt;
            }
            // Both `.any` but each operand is safe to unbox (numeric local + field,
            // field + field, etc.) — native binop, result re-boxed on assign.
            if (lt == .any and rt == .any and
                self.dynamic_binop_operand_is_safe_native_unbox(b.lhs) and
                self.dynamic_binop_operand_is_safe_native_unbox(b.rhs))
            {
                switch (b.op) {
                    .add,
                    .sub,
                    .mul,
                    .div,
                    .idiv,
                    .mod,
                    .band,
                    .bor,
                    .bxor,
                    .lshift,
                    .rshift,
                    .eq,
                    .neq,
                    .lt,
                    .gt,
                    .leq,
                    .geq,
                    => {
                        if (b.op == .div or self.expr_tree_has_float(b.lhs) or self.expr_tree_has_float(b.rhs))
                            return .f64;
                        return .i64;
                    },
                    else => {},
                }
            }
            if (lt == .any and rt == .any) {
                const lhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(b.lhs);
                const rhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(b.rhs);
                const one_sided = (lhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(b.rhs) and !rhs_safe) or
                    (rhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(b.lhs) and !lhs_safe);
                if (one_sided) {
                    switch (b.op) {
                        .add,
                        .sub,
                        .mul,
                        .div,
                        .idiv,
                        .mod,
                        .band,
                        .bor,
                        .bxor,
                        .lshift,
                        .rshift,
                        .eq,
                        .neq,
                        .lt,
                        .gt,
                        .leq,
                        .geq,
                        => {
                            if (b.op == .eq or b.op == .neq or b.op == .lt or b.op == .gt or b.op == .leq or b.op == .geq)
                                return .bool;
                            if (b.op == .div or self.expr_tree_has_float(b.lhs) or self.expr_tree_has_float(b.rhs))
                                return .f64;
                            return .i64;
                        },
                        else => {},
                    }
                }
                if (self.dynamic_binop_operand_is_dynamic_table_read(b.lhs) and
                    self.dynamic_binop_operand_is_dynamic_table_read(b.rhs) and
                    !lhs_safe and !rhs_safe)
                {
                    switch (b.op) {
                        .add,
                        .sub,
                        .mul,
                        .div,
                        .idiv,
                        .mod,
                        .band,
                        .bor,
                        .bxor,
                        .lshift,
                        .rshift,
                        => {
                            if (b.op == .div or self.expr_tree_has_float(b.lhs) or self.expr_tree_has_float(b.rhs))
                                return .f64;
                            return .i64;
                        },
                        else => {},
                    }
                }
            }
            if (lt == .bool and rt == .bool) return .bool;
        }
        // Propagate types through wrapping/unwrapping expressions so that
        // operations on their results don't unnecessarily fall back to the
        // dynamic lua_Value path.
        if (e.* == .unwrap_expr) return self.expr_type(e.unwrap_expr.operand);
        if (e.* == .try_expr) return self.expr_type(e.try_expr.operand);
        if (e.* == .await_expr) return self.expr_type(e.await_expr.operand);
        // `x in y` is a boolean test — always produces bool.
        if (e.* == .contains_expr) return .bool;
        // Unary operators: keep results in native typed C when the operand is
        // native so downstream expressions (`arr[-i]`, `(-x)+y`, `#s == n`) stay
        // off the dynamic lua_Value path. Mirrors the native emit in emit_expr.
        if (e.* == .unop) {
            const u = e.unop;
            switch (u.op) {
                // `not` lowers to a C `!` (or `!lua_to_bool(...)`) — always bool.
                .not => return .bool,
                // `#x` lowers to `strlen`/`(int64_t)strlen` when typed → i64.
                // For untyped values (tables/strings), `lua_len` always returns
                // a number, so recover `.f64` to enable native unboxing.
                .len => {
                    const ot = self.expr_type(u.operand);
                    if (ot.is_native()) return .i64;
                    return .f64;
                },
                // `-x` is `(-x)` for a native operand, preserving its type.
                .neg => {
                    const ot = self.expr_type(u.operand);
                    if (ot.is_native()) return ot;
                    if (self.dynamic_binop_operand_is_safe_native_unbox(u.operand) or
                        self.dynamic_binop_operand_is_dynamic_table_read(u.operand))
                    {
                        if (self.expr_tree_has_float(u.operand)) return .f64;
                        return .i64;
                    }
                },
                // `~x` is `(~x)` for integer operands → integer result.
                .bnot => {
                    const ot = self.expr_type(u.operand);
                    if (ot.is_integer()) return .i64;
                    if (self.dynamic_binop_operand_is_safe_native_unbox(u.operand) or
                        self.dynamic_binop_operand_is_dynamic_table_read(u.operand))
                        return .i64;
                },
                .compile => return self.expr_type(u.operand),
            }
        }
        // Prefer a concrete sema type. When sema recorded only `.any` (or nothing),
        // fall through to the structural recovery below, which can turn that
        // dynamic fallback into a native type.
        const tm = self.type_map.get(e);
        if (tm) |t| {
            if (t != .any) return t;
        }
        // Field access on a statically-typed record: resolve the field's type
        // structurally when sema didn't record it (e.g. inside monomorphized
        // generic bodies, where type_map is keyed on the unspecialized expr).
        if (e.* == .field) {
            const ot = self.expr_type(e.field.obj);
            if (ot == .table_type) {
                for (ot.table_type.fields) |fld| {
                    if (std.mem.eql(u8, fld.name, e.field.field)) return fld.typ;
                }
            } else if (ot == .@"struct") {
                if (self.record_aliases.get(ot.@"struct".name)) |alias_rt| {
                    if (alias_rt == .table_type) {
                        for (alias_rt.table_type.fields) |fld| {
                            if (std.mem.eql(u8, fld.name, e.field.field)) return fld.typ;
                        }
                    }
                }
            } else if (e.field.obj.* == .name) {
                if (self.lookup_tracked_table_field(e.field.obj.name.ident, e.field.field)) |ft| {
                    if (ft != .any and ft != .nil) return ft;
                }
            }
        }
        // Builtin module calls can recover native result types even when sema
        // recorded `.any` or no entry for this exact expression node.
        if (e.* == .call) {
            if (self.enum_eq_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.enum_display_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.mem_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.atomic_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.math_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.string_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.utf8_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.table_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.os_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.ffi_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.net_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.coroutine_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.debug_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.jit_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (self.builtin_call_result_type(e.call.func, e.call.args)) |t| return t;
            if (e.call.func.* == .name and std.mem.eql(u8, e.call.func.name.ident, "__as") and
                e.call.args.len == 2 and e.call.args[0].* == .quoted)
            {
                if (self.type_from_c_name(e.call.args[0].quoted.val)) |target| return target;
            }
            if (e.call.func.* == .name and std.mem.eql(u8, e.call.func.name.ident, "__as_type") and
                e.call.args.len == 2 and e.call.args[1].* == .quoted)
            {
                if (self.type_from_c_name(e.call.args[1].quoted.val)) |target| return target;
            }
            const callee_type = self.expr_type(e.call.func);
            if (e.call.func.* == .name) {
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(e.call.func.name.ident, &name_buf);
                if (self.func_bodies.get(mname)) |body| {
                    const fb_type = self.func_expr_type(body);
                    if (fb_type == .func) return fb_type.func.ret.*;
                }
            }
            if (callee_type == .func) return callee_type.func.ret.*;
        }
        // Sema can leave a forward function reference without a type. Recover
        // its typed signature from the func body map so calls can be emitted as
        // direct C function calls instead of falling through to lua_invoke.
        if (e.* == .name and (tm == null or tm.? != .func)) {
            var name_buf: [256]u8 = undefined;
            if (self.func_bodies.get(self.mangled_name(e.name.ident, &name_buf))) |body| {
                const fb_type = self.func_expr_type(body);
                if (fb_type == .func) return fb_type;
            }
        }
        if (self.structural_expr_type(e)) |t| return t;
        if (e.* == .name) {
            if (self.global_type(e.name.ident)) |gt| {
                if (gt != .any) return gt;
            }
        }
        return tm orelse .any;
    }

    /// Recover types that are intrinsic to the expression node itself. This is
    /// the last line before the dynamic fallback, and covers transformed or
    /// synthetic nodes that do not have a `type_map` entry.
    fn structural_expr_type(self: *CodeGen, e: *const ast.Expr) ?RT {
        return switch (e.*) {
            .nil => .nil,
            .true_lit, .false_lit => .bool,
            .int_lit => .i64,
            .float_lit => .f64,
            .quoted => |lit| types.quotedLiteralType(lit.quote),
            .func_expr => |fb| self.func_expr_type(fb),
            .if_expr => |ie| blk: {
                const then_t = self.expr_type(ie.then_expr);
                const else_t = self.expr_type(ie.else_expr);
                break :blk if (then_t.eql(else_t)) then_t else .any;
            },
            // A bare `tonumber(...)` is deliberately NOT structurally numeric.
            // It answers nil for a string that is not a complete numeral, and
            // claiming `.f64` here made the emit declare the destination a
            // native double and wrap the call in `lua_to_num(...)` — so the nil
            // collapsed to 0 before any `!= nil` test could run (gap[031]).
            // `tonumber(s) or d` is still read as numeric, in the `or` arm
            // below, because that form consumes the nil itself.
            .binop => |b| blk: {
                if (b.op == .@"or" or b.op == .@"and") {
                    const lt = self.numeric_operand_type(b.lhs);
                    const rt = self.numeric_operand_type(b.rhs);
                    if (lt.is_numeric() and rt.is_numeric()) {
                        break :blk if (lt == .f64 or rt == .f64) .f64 else .i64;
                    }
                }
                break :blk null;
            },
            else => null,
        };
    }

    /// The type an operand of `and`/`or` contributes to the numeric-result
    /// decision. `tonumber(x)` counts as `.f64` HERE and nowhere else: the
    /// short-circuit form is the one place the nil is consumed on the spot.
    fn numeric_operand_type(self: *CodeGen, e: *const ast.Expr) RT {
        if (e.* == .call and e.call.func.* == .name and
            std.mem.eql(u8, e.call.func.name.ident, "tonumber")) return .f64;
        return self.structural_expr_type(e) orelse self.expr_type(e);
    }

    fn register_native_str_list_local(self: *CodeGen, name: []const u8) !void {
        const owned = try self.alloc.dupe(u8, name);
        try self.native_str_list_locals.put(self.alloc, owned, {});
    }

    fn is_native_str_list_local(self: *const CodeGen, name: []const u8) bool {
        return self.native_str_list_locals.contains(name);
    }

    fn register_native_split_str_list_local(self: *CodeGen, name: []const u8) !void {
        const owned = try self.alloc.dupe(u8, name);
        try self.native_split_str_list_locals.put(self.alloc, owned, {});
    }

    fn is_native_split_str_list_local(self: *const CodeGen, name: []const u8) bool {
        return self.native_split_str_list_locals.contains(name);
    }

    fn try_emit_native_split_str_list_local(self: *CodeGen, name: []const u8, init_expr: *const ast.Expr) E!bool {
        if (init_expr.* != .method_call) return false;
        const mc = init_expr.method_call;
        if (!std.mem.eql(u8, mc.method, "split") or mc.args.len != 1) return false;
        // NOT "already registered → return false". The registry is
        // function-scoped, and a second `rows = x:split(...)` in a LATER
        // function is a fresh declaration that must emit again. Registering
        // idempotently (same name, same function) is harmless; bailing here is
        // what made scripts/treesitter_emit.id:1372 refuse while :132 and :347
        // emitted fine.
        try self.note_local(name);
        try self.note_local_type(name, .any);
        try self.register_native_split_str_list_local(name);
        self.p("duo_str_split_list {s} = duo_str_split_cstr(", .{name});
        try self.emit_expr(mc.obj);
        self.p(", ", .{});
        try self.emit_cstr_arg(mc.args[0]);
        self.p(");\n", .{});
        return true;
    }

    fn is_str_list_disqualified(self: *const CodeGen, name: []const u8) bool {
        return self.str_list_disqualified.contains(name);
    }

    /// Record `name` as ineligible for the `t_items[]` + `t_len` lowering.
    fn disqualify_str_list(self: *CodeGen, name: []const u8) !void {
        if (self.str_list_disqualified.contains(name)) return;
        const owned = try self.alloc.dupe(u8, name);
        try self.str_list_disqualified.put(self.alloc, owned, {});
    }

    /// Walk a block (including nested blocks) and disqualify every `t = {}`
    /// candidate that is later used as a *keyed* table — `t.field = v` or
    /// `t["k"] = v`. The `t_items[]` lowering only models positional string
    /// appends, so without this scan a module like `M = {}; M.OP_nop = 1`
    /// silently lowers `M` to an array and emits its field writes against a
    /// table that was never declared.
    fn note_str_list_disqualifications(self: *CodeGen, blk: *const ast.Block) E!void {
        for (blk.stmts) |*stmt| try self.scan_stmt_for_keyed_table_use(stmt);
    }

    fn scan_stmt_for_keyed_table_use(self: *CodeGen, stmt: *const ast.Stmt) E!void {
        switch (stmt.*) {
            .assign => |*as| {
                for (as.targets) |t| try self.scan_expr_for_keyed_table_use(t);
            },
            .if_stmt => |*is| {
                try self.note_str_list_disqualifications(&is.then);
                for (is.elseifs) |*ei| try self.note_str_list_disqualifications(&ei.body);
                if (is.else_body) |*eb| try self.note_str_list_disqualifications(eb);
            },
            .while_loop => |*ws| try self.note_str_list_disqualifications(&ws.body),
            .repeat_loop => |*rs| try self.note_str_list_disqualifications(&rs.body),
            .num_for => |*fs| try self.note_str_list_disqualifications(&fs.body),
            .gen_for => |*fs| try self.note_str_list_disqualifications(&fs.body),
            .do_block => |*db| try self.note_str_list_disqualifications(&db.body),
            else => {},
        }
    }

    fn scan_expr_for_keyed_table_use(self: *CodeGen, expr: *const ast.Expr) E!void {
        switch (expr.*) {
            // `t.field = v` — named key, never a positional append.
            .field => |f| {
                if (f.obj.* == .name) try self.disqualify_str_list(f.obj.name.ident);
            },
            // `t["k"] = v` — string key, likewise not positional.
            .index => |ix| {
                if (ix.obj.* == .name and ix.key.* == .quoted) {
                    try self.disqualify_str_list(ix.obj.name.ident);
                }
            },
            else => {},
        }
    }

    fn func_expr_type(self: *CodeGen, fb: *const ast.FuncBody) RT {
        // Closures are always runtime `lua_Value`s, never native fn pointers.
        if (fb.closure_id != null or fb.upvalues.len > 0) return .any;
        const ret = self.alloc.create(RT) catch return .any;
        ret.* = self.resolve_type(contract_ret(fb));
        const params = self.alloc.alloc(RT, fb.params.len) catch {
            self.alloc.destroy(ret);
            return .any;
        };
        for (fb.params, 0..) |par, i| {
            params[i] = self.resolve_type(par.typ);
        }
        return .{ .func = .{
            .params = params,
            .ret = ret,
            .is_native = fb.is_typed,
            .has_vararg = fb.vararg or fb.vararg_name != null,
        } };
    }

    /// Recover the result of native C indexing from the container type. Sema
    /// intentionally leaves general indexing dynamic, but fixed arrays,
    /// pointers, and SIMD vectors have statically-known element types.
    /// `s(i)` where `s` is a `str` — the byte at `i`, ZERO-BASED, and returns
    /// the index expression when that is what this is.
    ///
    /// THE BASE IS NOT A GUESS. Three fixtures in the corpus state it and each
    /// one is checkable by hand against the bytes on disk:
    /// `examples/table/str/bytes.id` says `s = "é"` (0xC3 0xA9) answers
    /// `2 195 169` for `s:len()`, `s(0)`, `s(1)`; `str/end.id` says `"ab"`
    /// answers `97 98 0`, which also pins reading ONE PAST the end as the NUL
    /// terminator rather than a bounds fault; `str/invalid.id` holds the raw
    /// bytes 0xFF 0xFE and says `2 255 254`. A table is 1-based and a `str` is
    /// 0-based — `docs/state.md` records `xs(0)` on a table as REFUSED — so the
    /// two indexings are different relations and this one may not borrow the
    /// other's base.
    ///
    /// Before this arm the C backend emitted `void* a = NULL` for the whole
    /// binding: the index expression was DISCARDED, and the NULL then reached
    /// `duo_str_concat` -> `strlen(NULL)`. All three fixtures died with SIGSEGV
    /// 139, which is how a dropped expression presents when the value it
    /// dropped was a string.
    /// BOTH SPELLINGS ARRIVE HERE. `s(i)` parses as `.index` when the parser
    /// already knows `s` names a table and as a `.call` otherwise, and a `str`
    /// receiver takes the second road every time. Measured: `examples/table/
    /// str/end.id` produced twelve `.call` nodes on `s` and zero `.index`
    /// nodes, which is why an `.index`-only arm changed nothing.
    const StrByte = struct { obj: *const ast.Expr, key: *const ast.Expr };

    fn str_byte_index(self: *CodeGen, e: *const ast.Expr) ?StrByte {
        const pair: StrByte = switch (e.*) {
            .index => |idx| .{ .obj = idx.obj, .key = idx.key },
            .call => |c| blk: {
                if (c.args.len != 1) return null;
                // Only a plain name receiver. An arbitrary callee expression
                // typed `str` is far more likely to be a relation returning a
                // string than a string being indexed.
                if (c.func.* != .name) return null;
                // LAW-CALL: data wins the name only when the program has not
                // bound that name to a relation.
                if (self.func_decls.contains(c.func.name.ident)) return null;
                if (self.func_bodies.contains(c.func.name.ident)) return null;
                break :blk .{ .obj = c.func, .key = c.args[0] };
            },
            else => return null,
        };
        if (self.expr_type(pair.obj) != .str) return null;
        if (!self.expr_type(pair.key).is_integer()) return null;
        return pair;
    }

    fn emit_str_byte_index(self: *CodeGen, e: *const ast.Expr) E!void {
        const pair = self.str_byte_index(e).?;
        self.p("((int64_t)(unsigned char)(", .{});
        try self.emit_expr(pair.obj);
        self.p(")[", .{});
        try self.emit_expr(pair.key);
        self.p("])", .{});
    }

    fn indexed_element_type(_: *CodeGen, container: RT) ?RT {
        return switch (container) {
            .array => |a| a.elem.*,
            .pointer => |ptr| ptr.*,
            .v4f64 => .f64,
            .v4i64 => .i64,
            .v8f32 => .f32,
            .v8i32 => .i32,
            else => null,
        };
    }

    fn lua_and_or_value_type_is_native(_: *CodeGen, t: RT) bool {
        return t.is_numeric() or t == .str;
    }

    fn emit_lua_truthy_expr(self: *CodeGen, e: *const ast.Expr) E!void {
        switch (self.expr_type(e)) {
            .any => {
                self.p("lua_to_bool(", .{});
                try self.emit_as_lua_value(e);
                self.p(")", .{});
            },
            .nil => self.p("0", .{}),
            .bool => {
                if (e.* == .call and e.call.func.* == .name) {
                    var nbuf: [256]u8 = undefined;
                    const mname = self.mangled_name(e.call.func.name.ident, &nbuf);
                    if (self.func_bodies.get(mname)) |fb| {
                        if (self.should_emit_lua_thunk(fb)) {
                            try self.emit_expr(e);
                            return;
                        }
                    }
                }
                try self.emit_expr(e);
            },
            else => self.p("1", .{}),
        }
    }

    fn try_emit_lua_and_or_ternary(self: *CodeGen, b: anytype) E!bool {
        if (b.op != .@"or" or b.lhs.* != .binop or b.lhs.binop.op != .@"and") return false;

        const and_b = b.lhs.binop;
        const then_t = self.expr_type(and_b.rhs);
        const else_t = self.expr_type(b.rhs);
        if (!then_t.eql(else_t) or !self.lua_and_or_value_type_is_native(then_t)) return false;

        self.p("(", .{});
        try self.emit_lua_truthy_expr(and_b.lhs);
        self.p(" ? (", .{});
        try self.emit_expr(and_b.rhs);
        self.p(") : (", .{});
        try self.emit_expr(b.rhs);
        self.p("))", .{});
        return true;
    }

    /// gap[021]: `and`/`or` return an OPERAND (B-3), and only `false`/`nil` are
    /// falsy (B-2). C's `&&`/`||` return the boolean 0/1, so lowering a numeric
    /// `and`/`or` onto them destroyed the operand — `a or 1.5` on `a: f64 = 2.5`
    /// yielded 1.0, and `x or default` is the canon's own coalescing spelling.
    ///
    /// A native numeric has no nil and no false representation, so it is always
    /// truthy and the selection is decided statically: `a or b` IS `a` (and `b`
    /// is short-circuited away, never evaluated), `a and b` IS `b` with `a` still
    /// evaluated for its effects. Each operand is therefore written exactly once.
    fn try_emit_native_and_or_operand(self: *CodeGen, b: anytype, expr: *const ast.Expr) E!bool {
        if (b.op != .@"and" and b.op != .@"or") return false;
        if (!self.expr_type(b.lhs).is_numeric()) return false;
        if (!self.expr_type(b.rhs).is_numeric()) return false;
        // Only claim the form when the result is consumed natively; a boxed
        // result still belongs to `lua_and`/`lua_or`, which are already correct.
        if (!self.expr_type(expr).is_numeric()) return false;

        if (b.op == .@"or") {
            self.p("(", .{});
            try self.emit_expr(b.lhs);
            self.p(")", .{});
        } else {
            self.p("((void)(", .{});
            try self.emit_expr(b.lhs);
            self.p("), (", .{});
            try self.emit_expr(b.rhs);
            self.p("))", .{});
        }
        return true;
    }

    /// `a or b` / `a and b` on TEXT.
    ///
    /// Idol's `or` yields an OPERAND, not a truth value. The no-lua arm in
    /// `emit_expr` emits C's `||`, whose value is `int` 0 or 1 — so
    /// `stdout:write(env(k) or "FB")` emitted
    /// `fprintf(stdout, "%s", (getenv("K") || "FB"))` and SEGFAULTED on every
    /// run, with the variable set and with it unset. Numeric operands already
    /// have this arm (`try_emit_native_and_or_operand` above); text had none,
    /// and the tree's converged fallback idiom `env(k) or fallback` is text at
    /// every one of its sites.
    ///
    /// TRUTH IS THE POINTER, NOT THE CONTENT. An EMPTY string is truthy, which
    /// is the answer the direct backend gives and the one Lua gives: after
    /// `env(k) = ""` the fallback must NOT be taken. That distinction —
    /// present-and-empty versus absent — is the whole reason removal is a
    /// separate edge (`env:remove(k)`) and not `env(k) = nil`.
    fn try_emit_native_str_and_or(self: *CodeGen, b: anytype) E!bool {
        if (b.op != .@"and" and b.op != .@"or") return false;
        if (self.moduleNeedsLuaRuntime()) return false;
        if (!self.expr_is_native_cstr(b.lhs)) return false;
        if (!self.expr_is_native_cstr(b.rhs)) return false;
        self.p("({{ const char* __so = ", .{});
        try self.emit_expr(b.lhs);
        self.p("; ", .{});
        if (b.op == .@"or") {
            self.p("__so ? __so : ", .{});
            try self.emit_expr(b.rhs);
        } else {
            self.p("__so ? ", .{});
            try self.emit_expr(b.rhs);
            self.p(" : __so", .{});
        }
        self.p("; }})", .{});
        return true;
    }

    /// Result type of a `math.<fn>(...)` builtin call, or null if `func` is not
    /// a recognized math builtin. `max`/`min`/`abs` are integer-typed when their
    /// arguments are integers (matching the integer emit in maybe_emit_math_call);
    /// everything else lowers through double-returning libm and is f64.
    fn math_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "math")) return null;
        const fname = f.field;
        if ((std.mem.eql(u8, fname, "max") or std.mem.eql(u8, fname, "min")) and args.len == 2) {
            if (self.expr_type(args[0]).is_integer() and self.expr_type(args[1]).is_integer())
                return .i64;
            return .f64;
        }
        if (std.mem.eql(u8, fname, "abs") and args.len == 1) {
            if (self.expr_type(args[0]).is_integer()) return .i64;
            return .f64;
        }
        if (std.mem.eql(u8, fname, "random")) return .f64;
        if (std.mem.eql(u8, fname, "modf")) return .f64;
        if (std.mem.eql(u8, fname, "ult") and args.len == 2) return .bool;
        if (std.mem.eql(u8, fname, "type") and args.len == 1) {
            if (self.expr_type(args[0]).is_numeric()) return .str;
            return null;
        }
        if (std.mem.eql(u8, fname, "tointeger") and args.len == 1) {
            if (self.expr_type(args[0]).is_integer()) return .i64;
            return null;
        }
        const f64_names = [_][]const u8{
            "sqrt", "sin", "cos",   "tan",  "asin", "acos",  "atan",
            "exp",  "log", "log10", "pow",  "fmod", "floor", "ceil",
            "deg",  "rad", "sinh",  "cosh", "tanh",
        };
        for (f64_names) |n| if (std.mem.eql(u8, fname, n)) return .f64;
        return null;
    }

    /// Result type of a `string.<fn>(...)` builtin call, or null if `func` is
    /// not a recognized string builtin. This mirrors Sema's builtin typing and
    /// lets emit choose native `str`/integer paths without relying on type_map.
    fn string_builtin_result_type(self: *CodeGen, fname: []const u8, args: []const *ast.Expr) ?RT {
        if (std.mem.eql(u8, fname, "len") or
            std.mem.eql(u8, fname, "packsize"))
            return .i64;
        if (std.mem.eql(u8, fname, "char") or
            std.mem.eql(u8, fname, "format") or
            std.mem.eql(u8, fname, "rep") or
            std.mem.eql(u8, fname, "sub") or
            std.mem.eql(u8, fname, "lower") or
            std.mem.eql(u8, fname, "upper") or
            std.mem.eql(u8, fname, "reverse") or
            std.mem.eql(u8, fname, "gsub") or
            std.mem.eql(u8, fname, "pack") or
            std.mem.eql(u8, fname, "dump"))
            return .str;
        if (std.mem.eql(u8, fname, "starts_with") or
            std.mem.eql(u8, fname, "ends_with"))
            return .bool;
        if (std.mem.eql(u8, fname, "match") and args.len == 1) return .str;
        if (std.mem.eql(u8, fname, "byte")) {
            if (args.len >= 2 and args[0].* == .quoted and args[1].* == .int_lit) return .i64;
            // A `str` receiver with an integer index lowers to a raw
            // `(int64_t)(unsigned char)s[i - 1]` byte read (see the emit in
            // try_emit_native_string_call). Typing that .any made `print` wrap
            // an int64_t in lua_to_display_str, which does not compile — the
            // static shape has to name what the emitter actually produces.
            if (args.len >= 2 and self.expr_type(args[0]) == .str and
                self.expr_type(args[1]).is_integer()) return .i64;
            return null;
        }
        return null;
    }

    fn string_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "string")) return null;
        return self.string_builtin_result_type(f.field, args);
    }
    fn string_method_result_type(self: *CodeGen, method: []const u8, obj: *const ast.Expr, args: []const *ast.Expr) ?RT {
        const obj_ty = self.expr_type(obj);
        const strish = obj_ty == .str or obj.* == .quoted or obj.* == .name or
            (obj.* == .field and self.expr_type(obj) == .str);
        if (!strish) return null;
        if (std.mem.eql(u8, method, "len")) return .i64;
        if (std.mem.eql(u8, method, "trim") and args.len == 0) return .str;
        if (std.mem.eql(u8, method, "sub") and args.len >= 1 and args.len <= 2) return .str;
        // `match` AND `find` ANSWER A VALUE, NOT A YES/NO.
        //
        // Typed `.bool`, the emit wrapped the runtime call in `lua_to_bool` and
        // threw the answer away at the point of production: `"abc123":match("%d+")`
        // printed `true` instead of `123`, so no capture in the language was
        // reachable, and `s:match(p) != nil` was ALWAYS TRUE because a `bool` is
        // never nil — which turns the standard "did it match" test into a
        // constant. `"hello":find("ll", 1, true)` printed `true` where a
        // position was the whole point.
        //
        // The FUNCTION face of the same relation, in
        // `string_builtin_result_type` directly above, already answered `.str`
        // for `match`. So one relation had two types depending on which face
        // was written, and the subject-first face — the canonical one — was the
        // broken half.
        //
        // `.any` and not `.str`, because both of them answer NIL when there is
        // no match, and that nil is the observable the caller tests. `.str`
        // would send the nil through `lua_to_str` and lose the distinction a
        // second time.
        if (std.mem.eql(u8, method, "match") and args.len >= 1 and args.len <= 2) return .any;
        if (std.mem.eql(u8, method, "has") and args.len == 1) return .bool;
        if (std.mem.eql(u8, method, "find") and args.len >= 1 and args.len <= 4) return .any;
        if (std.mem.eql(u8, method, "byte") and args.len <= 1) return .i64;
        return self.string_builtin_result_type(method, args);
    }

    fn utf8_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "utf8")) return null;
        if (std.mem.eql(u8, f.field, "len")) return .i64;
        if (std.mem.eql(u8, f.field, "char")) return .str;
        return null;
    }

    fn table_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "table")) return null;
        if (std.mem.eql(u8, f.field, "concat")) return .str;
        if (std.mem.eql(u8, f.field, "isfrozen")) return .bool;
        return null;
    }

    /// The `os` world's member edge an anchored node names, or null.
    ///
    /// ONE ROSTER, ASKED. `subject_home.os_dot_members` is the one place a
    /// member's face and declared result type are written down; this file used
    /// to carry a second copy of the type half in `os_call_result_type` below
    /// and no copy at all of the face, which is why `arg` and `cwd` had no type
    /// while `clock` and `tmpname` did. Both the type side (here) and the
    /// lowering (`dnir_lower.osResult`) read the same row.
    fn osMemberOf(_: *const CodeGen, e: *const ast.Expr) ?subject_home.OsMember {
        if (e.* != .field) return null;
        const f = &e.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "os")) return null;
        return subject_home.osDotMember(f.field);
    }

    /// The result of an `os` member edge applied as a CALL.
    ///
    /// `.relation` only: a projection (`os.env(k)`) and a value (`os.cwd`) are
    /// answered at their own nodes in `expr_type`, and a program that binds `os`
    /// itself must keep an ordinary call on its own table — asking the face
    /// rather than the name is what keeps this from claiming either.
    ///
    /// `.any` is NOT DECLARED and answers null, so a member the roster has no
    /// result for falls through exactly as it did before this roster carried
    /// types at all.
    fn os_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = args;
        const m = self.osMemberOf(func) orelse return null;
        if (m.face != .relation) return null;
        if (m.result == .any) return null;
        return m.result;
    }

    fn ffi_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "ffi")) return null;
        if (std.mem.eql(u8, f.field, "sizeof") or
            std.mem.eql(u8, f.field, "alignof") or
            std.mem.eql(u8, f.field, "offsetof") or
            std.mem.eql(u8, f.field, "errno"))
            return .i64;
        if (std.mem.eql(u8, f.field, "istype")) return .bool;
        if (std.mem.eql(u8, f.field, "string")) return .str;
        return null;
    }

    /// io.open(path, mode) returns a FILE* handle in full-native mode.
    /// The native-eligibility walker already accepts io.open as native-eligible
    /// when both args are scalars; without this the binder sees .any and
    /// refuses the binding (GAP-145 O3 dump-c --lib, lib/compiler/token.id spill).
    fn io_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "io")) return null;
        if (std.mem.eql(u8, f.field, "open") and args.len >= 1) {
            if (self.moduleNeedsLuaRuntime()) return .any;
            return self.mem_pointer_to(.void);
        }
        // io.popen(cmd, mode) — the read-side dual of the open edge: a pipe
        // stream in full-native mode, same FILE* representation (lib/proc.id
        // capture, lib/fs.id lines). pclose closes it.
        if (std.mem.eql(u8, f.field, "popen") and args.len >= 1) {
            if (self.moduleNeedsLuaRuntime()) return .any;
            return self.mem_pointer_to(.void);
        }
        return null;
    }

    fn net_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "net")) return null;
        if (std.mem.eql(u8, f.field, "send") or
            std.mem.eql(u8, f.field, "udp_sendto"))
            return .i64;
        return null;
    }

    fn coroutine_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "coroutine")) return null;
        if (std.mem.eql(u8, f.field, "status")) return .str;
        if (std.mem.eql(u8, f.field, "isyieldable") or
            std.mem.eql(u8, f.field, "close"))
            return .bool;
        return null;
    }

    fn debug_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "debug")) return null;
        if (std.mem.eql(u8, f.field, "traceback")) return .str;
        return null;
    }

    fn jit_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        _ = args;
        if (func.* != .field) return null;
        const f = &func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "jit")) return null;
        if (std.mem.eql(u8, f.field, "status")) return .bool;
        if (std.mem.eql(u8, f.field, "version_num")) return .f64;
        return null;
    }

    fn builtin_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        _ = self;
        if (func.* != .name) return null;
        const name = func.name.ident;
        if (std.mem.eql(u8, name, "__metaladder") or
            std.mem.eql(u8, name, "__metacatalog") or
            std.mem.eql(u8, name, "__metaagentcatalog") or
            std.mem.eql(u8, name, "__metaagentladder") or
            std.mem.eql(u8, name, "__metaagenthooks") or
            std.mem.eql(u8, name, "__metaagentdedupe") or
            std.mem.eql(u8, name, "__metaagentgaps") or
            std.mem.eql(u8, name, "__metaagentgrammar") or
            std.mem.eql(u8, name, "__moduletypenames") or
            std.mem.eql(u8, name, "__concepttypenames") or
            std.mem.eql(u8, name, "__comptimemap") or
            std.mem.eql(u8, name, "__comptimeeach") or
            std.mem.eql(u8, name, "__comptimematch") or
            std.mem.eql(u8, name, "__comptimetabulate") or
            std.mem.eql(u8, name, "__comptimeinterpolate") or
            std.mem.eql(u8, name, "__comptimefixpoint") or
            std.mem.eql(u8, name, "__comptimezip") or
            std.mem.eql(u8, name, "__comptimeproduct") or
            std.mem.eql(u8, name, "__comptimepower") or
            std.mem.eql(u8, name, "__comptimepermute") or
            std.mem.eql(u8, name, "__comptimechoose") or
            std.mem.eql(u8, name, "__metagrammar") or
            std.mem.eql(u8, name, "__metaweave") or
            std.mem.eql(u8, name, "__metatemplate") or
            std.mem.eql(u8, name, "__metagenerate") or
            std.mem.eql(u8, name, "__metascheme") or
            std.mem.eql(u8, name, "__metaschemeclauses") or
            std.mem.eql(u8, name, "__derivechoose") or
            std.mem.eql(u8, name, "__derivepower") or
            std.mem.eql(u8, name, "__deriveproduct"))
            return .str;
        if (std.mem.eql(u8, name, "__strstartswith") or
            std.mem.eql(u8, name, "__strendswith") or
            std.mem.eql(u8, name, "__streq"))
            return .bool;
        if (std.mem.eql(u8, name, "__strcountlines") or
            std.mem.eql(u8, name, "__strsplitcount") or
            std.mem.eql(u8, name, "__strcomptelen") or
            std.mem.eql(u8, name, "__concept_count"))
            return .i64;
        if (std.mem.eql(u8, name, "__strjoin")) return .str;
        if (std.mem.eql(u8, name, "type") or
            std.mem.eql(u8, name, "tostring"))
            return .str;
        // `tonumber` is a conversion that CAN FAIL: it answers nil for a string
        // that is not a complete numeral, and for anything that is not a string
        // or a number. Typing it `.f64` made every unannotated result a native
        // double, so the emit wrapped the call in `lua_to_num(...)` and the nil
        // became 0 before any caller could test it. `.any` keeps the nil
        // reachable; an explicit `: f64` annotation still coerces, which is the
        // caller asking for a number and getting one.
        if (std.mem.eql(u8, name, "tonumber")) return .any;
        if (std.mem.eql(u8, name, "rawlen")) return .i64;
        if (std.mem.eql(u8, name, "rawequal") or
            std.mem.eql(u8, name, "pcall") or
            std.mem.eql(u8, name, "xpcall"))
            return .bool;
        if (std.mem.eql(u8, name, "select")) {
            if (args.len > 0 and args[0].* == .quoted and
                std.mem.eql(u8, args[0].quoted.val, "#"))
                return .i64;
            return null;
        }
        if (std.mem.eql(u8, name, "collectgarbage")) {
            if (args.len == 0) return .f64;
            if (args[0].* != .quoted) return null;
            const opt = args[0].quoted.val;
            if (std.mem.eql(u8, opt, "count") or
                std.mem.eql(u8, opt, "collect"))
                return .f64;
            if (std.mem.eql(u8, opt, "stop") or
                std.mem.eql(u8, opt, "restart"))
                return .bool;
            return null;
        }
        return null;
    }

    fn mem_intrinsic_name(_: *const CodeGen, func: *const ast.Expr) ?[]const u8 {
        if (func.* != .field) return null;
        const f = func.field;
        if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "mem")) return f.field;
        if (f.obj.* == .field) {
            const inner = f.obj.field;
            if (inner.obj.* == .name and
                std.mem.eql(u8, inner.obj.name.ident, "std") and
                std.mem.eql(u8, inner.field, "mem"))
                return f.field;
        }
        return null;
    }

    fn ml_intrinsic_name(_: *const CodeGen, func: *const ast.Expr) ?[]const u8 {
        if (func.* != .field) return null;
        const f = func.field;
        if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "ml")) return f.field;
        if (f.obj.* == .field) {
            const inner = f.obj.field;
            if (inner.obj.* == .name and
                std.mem.eql(u8, inner.obj.name.ident, "std") and
                std.mem.eql(u8, inner.field, "ml"))
                return f.field;
        }
        return null;
    }

    fn ensure_ml_kernels(self: *CodeGen) E!void {
        // Already emitted at file scope — this is a no-op. ML declarations are
        // unconditionally emitted in the prelude (guarded by #ifndef).
        _ = self;
    }

    fn maybe_emit_ml_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr) E!bool {
        const fname = self.ml_intrinsic_name(func) orelse return false;
        if (args.len != 0) return false;
        const expr = ml_kernels.callExpr(fname) orelse return false;
        try self.ensure_ml_kernels();
        self.ml_kernels_emitted = true;
        self.p("((double)({s}))", .{expr});
        return true;
    }

    fn mem_pointer_to(self: *CodeGen, pointee: RT) ?RT {
        const ptr = self.alloc.create(RT) catch return null;
        ptr.* = pointee;
        return RT{ .pointer = ptr };
    }

    /// The descriptor a memory-level type name projects, or the nominal
    /// descriptor of that name.
    ///
    /// The memory-level face is owned once by `types.memDescriptorNamed` — this
    /// was a roster of scalar spellings duplicated verbatim in `sema`, which
    /// decided ADMISSION from one list while this decided REALIZATION from
    /// another.
    ///
    /// The nominal tail is COMPOSED here rather than inherited, because it was
    /// never the memory level's: law.nominal (§46) makes `feet` a descriptor
    /// over a primitive, so it is a legal type NAME for a CONVERSION target and
    /// it realizes as its representation. This is what gives `d:to(inch)` a
    /// result type — without it the conversion is typed `any` and the value is
    /// boxed on the way out, which would make the whole mechanism cost exactly
    /// the box it exists to avoid. `sema` refuses `mem.store(feet)`, so no
    /// memory level ever reached this tail.
    fn mem_type_from_name(self: *CodeGen, name: []const u8) ?RT {
        const level = types.memDescriptorNamed(self.alloc, name) catch return null;
        return level orelse types.nominalNamed(name);
    }

    fn mem_type_arg(self: *CodeGen, args: []const *ast.Expr, index: usize) ?RT {
        if (index >= args.len) return null;
        // Canonical: a TYPE NAME value — `mem.store(i32)(p, v)`. Spec 2.10 G3
        // makes a type an ordinary value, so the descriptor parameter is the
        // type itself, not a string naming it. The `"i32"` string form is the
        // graveyarded spelling, still accepted so existing sources build while
        // they migrate.
        if (args[index].* == .name) return self.mem_type_from_name(args[index].name.ident);
        if (args[index].* != .quoted) return null;
        return self.mem_type_from_name(args[index].quoted.val);
    }

    fn type_from_c_name(self: *CodeGen, name: []const u8) ?RT {
        // DERIVED: the scalar arm is the inverse of `c_type`, owned once in
        // `types.descriptorByCSpelling`. This function used to restate the
        // twelve scalar identity↔C-spelling pairs by hand — a seventh copy of
        // a correspondence `c_type` already owns, running backwards. The tail
        // is the graveyarded/pointer/void spellings the memory level owns.
        if (types.descriptorByCSpelling(name)) |scalar| return scalar;
        return self.mem_type_from_name(name);
    }

    fn mem_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        // LAW-STRATA curried form: `mem.load(f64)(p)`. The descriptor group
        // carries the type, so the result type must be read from the INNER
        // group — otherwise the call infers `any` and the consuming site wraps
        // a native double in lua_to_num.
        if (func.* == .call and func.call.args.len == 1 and func.call.func.* != .call) {
            const inner = func.call;
            var buf: [8]*ast.Expr = undefined;
            if (args.len + 1 <= buf.len) {
                buf[0] = inner.args[0];
                for (args, 0..) |a, i| buf[i + 1] = a;
                return self.mem_call_result_type(inner.func, buf[0 .. args.len + 1]);
            }
        }
        const fname = self.mem_intrinsic_name(func) orelse return null;
        if (std.mem.eql(u8, fname, "alloc") or std.mem.eql(u8, fname, "calloc") or
            std.mem.eql(u8, fname, "byte_add"))
            return self.mem_pointer_to(.u8);
        if (std.mem.eql(u8, fname, "realloc") or std.mem.eql(u8, fname, "add")) {
            if (args.len > 0) {
                const t = self.expr_type(args[0]);
                if (t == .pointer) return t;
            }
            return self.mem_pointer_to(.u8);
        }
        if (std.mem.eql(u8, fname, "cast") or std.mem.eql(u8, fname, "ptr_cast") or
            std.mem.eql(u8, fname, "ptr_from_addr") or std.mem.eql(u8, fname, "ptrfromaddr"))
        {
            const pointee = self.mem_type_arg(args, 0) orelse RT.void;
            return self.mem_pointer_to(pointee);
        }
        if (std.mem.eql(u8, fname, "addr")) return .u64;
        if (std.mem.eql(u8, fname, "load") or std.mem.eql(u8, fname, "volatile_load"))
            return self.mem_type_arg(args, 0) orelse .any;
        if (std.mem.eql(u8, fname, "store") or std.mem.eql(u8, fname, "volatile_store") or
            std.mem.eql(u8, fname, "free") or std.mem.eql(u8, fname, "copy") or
            std.mem.eql(u8, fname, "move") or std.mem.eql(u8, fname, "set") or
            std.mem.eql(u8, fname, "zero") or std.mem.eql(u8, fname, "fence") or
            std.mem.eql(u8, fname, "compiler_fence") or std.mem.eql(u8, fname, "prefetch") or
            std.mem.eql(u8, fname, "assume") or std.mem.eql(u8, fname, "trap") or
            std.mem.eql(u8, fname, "unreachable"))
            return .void;
        if (std.mem.eql(u8, fname, "read_byte") or std.mem.eql(u8, fname, "read_i8") or
            std.mem.eql(u8, fname, "read_u8") or std.mem.eql(u8, fname, "read_i16") or
            std.mem.eql(u8, fname, "read_u16") or std.mem.eql(u8, fname, "read_i32") or
            std.mem.eql(u8, fname, "read_u32") or std.mem.eql(u8, fname, "read_i64") or
            std.mem.eql(u8, fname, "read_u64"))
            return .i64;
        if (std.mem.eql(u8, fname, "read_f32") or std.mem.eql(u8, fname, "read_f64") or
            std.mem.eql(u8, fname, "bytes_to_f32") or std.mem.eql(u8, fname, "bytes_to_f64"))
            return .f64;
        if (std.mem.eql(u8, fname, "write_byte") or std.mem.eql(u8, fname, "writebyte") or std.mem.eql(u8, fname, "write_i8") or
            std.mem.eql(u8, fname, "write_u8") or std.mem.eql(u8, fname, "write_i16") or
            std.mem.eql(u8, fname, "write_u16") or std.mem.eql(u8, fname, "write_i32") or
            std.mem.eql(u8, fname, "write_u32") or std.mem.eql(u8, fname, "write_i64") or std.mem.eql(u8, fname, "writei64") or
            std.mem.eql(u8, fname, "write_u64") or std.mem.eql(u8, fname, "write_f32") or
            std.mem.eql(u8, fname, "write_f64") or std.mem.eql(u8, fname, "writef64"))
            return .void;
        if (std.mem.eql(u8, fname, "dup")) return self.mem_pointer_to(.u8);
        if (std.mem.eql(u8, fname, "compare")) return .i64;
        if (std.mem.eql(u8, fname, "is_null")) return .bool;
        if (std.mem.eql(u8, fname, "sizeof") or std.mem.eql(u8, fname, "alignof")) return .u64;
        return null;
    }

    fn atomic_intrinsic_name(_: *const CodeGen, func: *const ast.Expr) ?[]const u8 {
        if (func.* != .field) return null;
        const f = func.field;
        if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "atomic")) return f.field;
        if (f.obj.* == .field) {
            const inner = f.obj.field;
            if (inner.obj.* == .name and
                std.mem.eql(u8, inner.obj.name.ident, "std") and
                std.mem.eql(u8, inner.field, "atomic"))
                return f.field;
        }
        return null;
    }

    fn atomic_fetch_intrinsic(fname: []const u8) bool {
        return std.mem.eql(u8, fname, "fetch_add") or
            std.mem.eql(u8, fname, "fetch_sub") or
            std.mem.eql(u8, fname, "fetch_and") or
            std.mem.eql(u8, fname, "fetch_or") or
            std.mem.eql(u8, fname, "fetch_xor");
    }

    fn atomic_call_result_type(self: *CodeGen, func: *const ast.Expr, args: []const *ast.Expr) ?RT {
        const fname = self.atomic_intrinsic_name(func) orelse return null;
        if (std.mem.eql(u8, fname, "load") or std.mem.eql(u8, fname, "exchange") or atomic_fetch_intrinsic(fname))
            return self.mem_type_arg(args, 0) orelse .any;
        if (std.mem.eql(u8, fname, "store") or std.mem.eql(u8, fname, "fence") or
            std.mem.eql(u8, fname, "compiler_fence"))
            return .void;
        if (std.mem.eql(u8, fname, "compare_exchange")) return .bool;
        return null;
    }

    fn atomic_order_literal(args: []const *ast.Expr, index: usize, default_order: []const u8) []const u8 {
        if (index >= args.len or args[index].* != .quoted) return default_order;
        const order = args[index].quoted.val;
        if (std.mem.eql(u8, order, "relaxed")) return "__ATOMIC_RELAXED";
        if (std.mem.eql(u8, order, "consume")) return "__ATOMIC_CONSUME";
        if (std.mem.eql(u8, order, "acquire")) return "__ATOMIC_ACQUIRE";
        if (std.mem.eql(u8, order, "release")) return "__ATOMIC_RELEASE";
        if (std.mem.eql(u8, order, "acq_rel")) return "__ATOMIC_ACQ_REL";
        if (std.mem.eql(u8, order, "seq_cst") or std.mem.eql(u8, order, "seqcst")) return "__ATOMIC_SEQ_CST";
        return default_order;
    }

    fn atomic_compare_failure_order(args: []const *ast.Expr) []const u8 {
        if (args.len > 5 and args[5].* == .quoted) return atomic_order_literal(args, 5, "__ATOMIC_SEQ_CST");
        if (args.len > 4 and args[4].* == .quoted) {
            const success = args[4].quoted.val;
            if (std.mem.eql(u8, success, "release") or std.mem.eql(u8, success, "acq_rel"))
                return "__ATOMIC_ACQUIRE";
            return atomic_order_literal(args, 4, "__ATOMIC_SEQ_CST");
        }
        return "__ATOMIC_SEQ_CST";
    }

    fn resolve_type(self: *CodeGen, te: ast.TypeExpr) RT {
        if (self.current_mono_spec) |spec| return spec.resolveType(te);
        if (te == .named) {
            if (self.record_aliases.get(te.named)) |rt| return rt;
            if (self.foreign_records) |fr| {
                if (fr.get(te.named)) |rt| return rt;
            }
        } else if (te == .generic and te.generic.base.* == .named) {
            if (self.alias_defs.get(te.generic.base.named)) |ad| {
                if (ad.type_params) |type_params| {
                    if (ad.target != null and type_params.len == te.generic.params.len) {
                        const expanded = self.substitute_alias_type(ad.target.?, type_params, te.generic.params) catch null;
                        if (expanded) |target| return self.resolve_type(target);
                    }
                }
            }
        }
        return types.resolve(te, null, self.alloc) catch .any;
    }

    fn substitute_alias_type(
        self: *CodeGen,
        type_expr: ast.TypeExpr,
        params: []const ast.TypeExpr,
        args: []const ast.TypeExpr,
    ) E!ast.TypeExpr {
        if (type_expr == .named) {
            for (params, 0..) |param, i| {
                if (param == .named and std.mem.eql(u8, param.named, type_expr.named)) return args[i];
                if (param == .constrained and std.mem.eql(u8, param.constrained.name, type_expr.named)) return args[i];
            }
            return type_expr;
        }
        return switch (type_expr) {
            .inferred => .inferred,
            .named => unreachable,
            .pointer => |inner| blk: {
                const next = try self.alloc.create(ast.TypeExpr);
                next.* = try self.substitute_alias_type(inner.*, params, args);
                break :blk .{ .pointer = next };
            },
            .optional => |inner| blk: {
                const next = try self.alloc.create(ast.TypeExpr);
                next.* = try self.substitute_alias_type(inner.*, params, args);
                break :blk .{ .optional = next };
            },
            .array => |arr| blk: {
                const elem = try self.alloc.create(ast.TypeExpr);
                elem.* = try self.substitute_alias_type(arr.elem.*, params, args);
                break :blk .{ .array = .{ .elem = elem, .size = arr.size } };
            },
            .generic => |g| blk: {
                const base = try self.alloc.create(ast.TypeExpr);
                base.* = try self.substitute_alias_type(g.base.*, params, args);
                const gargs = try self.alloc.alloc(ast.TypeExpr, g.params.len);
                for (g.params, 0..) |arg, i| {
                    gargs[i] = try self.substitute_alias_type(arg, params, args);
                }
                break :blk .{ .generic = .{ .base = base, .params = gargs } };
            },
            .func => |f| blk: {
                const fparams = try self.alloc.alloc(ast.TypeExpr, f.params.len);
                for (f.params, 0..) |param, i| {
                    fparams[i] = try self.substitute_alias_type(param, params, args);
                }
                const ret = try self.alloc.create(ast.TypeExpr);
                ret.* = try self.substitute_alias_type(f.ret.*, params, args);
                break :blk .{ .func = .{ .params = fparams, .ret = ret } };
            },
            .tuple => |items| blk: {
                const out = try self.alloc.alloc(ast.TypeExpr, items.len);
                for (items, 0..) |item, i| {
                    out[i] = try self.substitute_alias_type(item, params, args);
                }
                break :blk .{ .tuple = out };
            },
            .record => |rec| blk: {
                const fields = try self.alloc.alloc(ast.RecordField, rec.fields.len);
                for (rec.fields, 0..) |field, i| {
                    fields[i] = .{
                        .name = field.name,
                        .typ = try self.substitute_alias_type(field.typ, params, args),
                        .loc = field.loc,
                    };
                }
                const next = try self.alloc.create(ast.TypeExpr.RecordType);
                next.* = .{ .fields = fields };
                break :blk .{ .record = next };
            },
            .constrained => |cp| blk: {
                const next = try self.alloc.create(ast.TypeExpr);
                next.* = try self.substitute_alias_type(cp.constraint.*, params, args);
                const extra = try self.alloc.alloc(ast.TypeExpr, cp.extra.len);
                for (cp.extra, 0..) |e, i| extra[i] = try self.substitute_alias_type(e, params, args);
                break :blk .{ .constrained = .{ .name = cp.name, .constraint = next, .extra = extra } };
            },
        };
    }

    fn apply_binding_record_attrs(_: *CodeGen, rt: *RT, attributes: []const ast.Attribute) void {
        types.applyTableShapeAttrs(rt, attributes);
    }

    fn resolve_binding_type(self: *CodeGen, lname: *const ast.LocalName) RT {
        var rt = self.resolve_type(lname.typ);
        self.apply_binding_record_attrs(&rt, lname.attributes);
        return rt;
    }

    fn alias_record_type(self: *CodeGen, ad: *const ast.AliasDef) E!RT {
        if (ad.target) |target| {
            if (target == .record) {
                const fields = try self.merged_alias_record_fields(ad);
                var rt = RT{ .table_type = .{
                    .fields = fields,
                    .is_packed = false,
                    .align_n = null,
                    .ffi_name = null,
                } };
                // This branch builds the table type by hand instead of going
                // through `types.resolve`, so the descriptor's own refinement
                // facts have to be read here. One application, attributes
                // layered on top of refinements.
                types.applyLayout(&rt, types.layoutFromAttrs(target.record.layout, ad.attributes));
                if (rt == .table_type and rt.table_type.storage_class == .dynamic and self.record_type_lowers_native(rt)) {
                    rt.table_type.storage_class = .native;
                }
                return rt;
            }
            var rt = self.resolve_type(target);
            self.apply_binding_record_attrs(&rt, ad.attributes);
            if (rt == .table_type and rt.table_type.storage_class == .dynamic and self.record_type_lowers_native(rt)) {
                rt.table_type.storage_class = .native;
            }
            return rt;
        }
        var fields = try self.alloc.alloc(types.FieldType, ad.fields.len);
        for (ad.fields, 0..) |field, i| {
            fields[i] = .{
                .name = field.name,
                .typ = self.resolve_type(field.typ),
            };
        }
        var rt = RT{ .table_type = .{
            .fields = fields,
            .is_packed = false,
            .align_n = null,
            .ffi_name = null,
        } };
        self.apply_binding_record_attrs(&rt, ad.attributes);
        return rt;
    }

    fn merged_alias_record_fields(self: *CodeGen, ad: *const ast.AliasDef) E![]types.FieldType {
        var merged: std.ArrayList(types.FieldType) = .empty;
        errdefer merged.deinit(self.alloc);

        if (ad.parent) |parent_name| {
            if (self.alias_defs.get(parent_name)) |parent_ad| {
                const parent_fields = try self.merged_alias_record_fields(parent_ad);
                defer self.alloc.free(parent_fields);
                try merged.appendSlice(self.alloc, parent_fields);
            }
        }
        // GP-012: additional parent descriptors (multi-parent composition)
        for (ad.extra_parents) |extra_name| {
            if (self.alias_defs.get(extra_name)) |extra_ad| {
                const extra_fields = try self.merged_alias_record_fields(extra_ad);
                defer self.alloc.free(extra_fields);
                try merged.appendSlice(self.alloc, extra_fields);
            }
        }

        const append_or_override = struct {
            fn append(list: *std.ArrayList(types.FieldType), alloc: std.mem.Allocator, name: []const u8, field_typ: RT) !void {
                for (list.items) |*existing| {
                    if (std.mem.eql(u8, existing.name, name)) {
                        existing.typ = field_typ;
                        return;
                    }
                }
                try list.append(alloc, .{ .name = name, .typ = field_typ });
            }
        }.append;

        if (ad.target) |target| {
            if (target == .record) {
                for (target.record.fields) |field| {
                    try append_or_override(&merged, self.alloc, field.name, self.resolve_type(field.typ));
                }
            }
        } else {
            for (ad.fields) |field| {
                try append_or_override(&merged, self.alloc, field.name, self.resolve_type(field.typ));
            }
        }

        return try merged.toOwnedSlice(self.alloc);
    }

    // ── Module entry ──────────────────────────────────────────────────────────

    /// True when module-level code materializes a real table: some name is bound
    /// to a table literal AND receives named/string-keyed writes
    /// (`M = {}` / `M.x = 1`). Such a module emits `lua_table_set_str_lit`, so it
    /// needs the lua runtime — native-scalar mode would emit `void* M = NULL`
    /// and silently drop every field write. Deliberately NOT scoped to the tail
    /// expression: `lib/wasm/ward_mvp_opcodes.duo` has no tail at all and
    /// still exports a table.
    /// True when any function anywhere in the module lowers a table to the dense
    /// (native array) representation, so the module needs `duo_dense_runtime`.
    fn module_has_dense_table(mod: *const ast.Module) bool {
        return block_has_dense_table(&mod.body, 0);
    }

    fn block_has_dense_table(blk: *const ast.Block, depth: u8) bool {
        if (depth > 16) return true; // give up conservatively: emit the helpers
        for (blk.stmts) |*s| {
            switch (s.*) {
                .func_decl => |*fd| {
                    if (fd.func.dense_tables.len > 0) return true;
                    if (block_has_dense_table(&fd.func.body, depth + 1)) return true;
                },
                .if_stmt => |*is| {
                    if (block_has_dense_table(&is.then, depth + 1)) return true;
                    for (is.elseifs) |*ei| if (block_has_dense_table(&ei.body, depth + 1)) return true;
                    if (is.else_body) |*eb| if (block_has_dense_table(eb, depth + 1)) return true;
                },
                .while_loop => |*wl| if (block_has_dense_table(&wl.body, depth + 1)) return true,
                .repeat_loop => |*rl| if (block_has_dense_table(&rl.body, depth + 1)) return true,
                .do_block => |*db| if (block_has_dense_table(&db.body, depth + 1)) return true,
                .num_for => |*nf| if (block_has_dense_table(&nf.body, depth + 1)) return true,
                .gen_for => |*gf| if (block_has_dense_table(&gf.body, depth + 1)) return true,
                else => {},
            }
        }
        return false;
    }

    /// One `name = <table literal>` module-level binding: does it materialize a
    /// runtime table? Split out of `module_materializes_table` so the `assign`
    /// and `global_decl` spellings of the same binding cannot answer differently
    /// — which they did, and it broke every consumer of `global M = {}`.
    fn binding_materializes_table(mod: *const ast.Module, name: []const u8, value: *const ast.Expr) bool {
        if (value.* != .table) return false;
        // A non-empty literal already materializes the table; an empty
        // one only does so if fields are written to it afterwards.
        //
        // EXCEPT a positional blob of integer literals with no keyed
        // write anywhere — `wasm_header = { 0x00, 0x61, … }`. The hazard
        // this guard exists for is the KEYED producer/consumer mismatch
        // (the producer emits `void* M = NULL` and drops the field
        // writes while the consumer flattens `m.x` to an undefined
        // `mod__x`). A positional constant has no field symbols to
        // mismatch, and dnir_lower has had a memory-backed positional
        // table representation since SH-04 landed (alloc_slots + ptr).
        // So this arm was rejecting a shape both ends already handle.
        if (value.table.fields.len > 0) {
            // ADMISSION AND CAPABILITY MUST BE ONE FACT. This used to carry its
            // own rule -- a positional INT blob with no keyed write -- while
            // dnir_lower carried a different one for what it can actually
            // lower. Two rules in two passes can disagree, and the disagreement
            // is silent: a table admitted here and unlowerable there falls
            // through to a read that emits a POINTER, nondeterministically,
            // exit 0. So ask the lowering what it can do.
            if (@import("graph/lower.zig").moduleConstTableKind(mod, name, value) != null) return false;
            if (!table_is_positional_int_blob(value) or module_has_keyed_write(mod, name)) return true;
            return false;
        }
        return module_has_keyed_write(mod, name);
    }

    fn module_materializes_table(mod: *const ast.Module) bool {
        for (mod.body.stmts) |*outer| {
            switch (outer.*) {
                .assign => |as| {
                    for (as.targets, 0..) |t0, ti| {
                        if (t0.* != .name) continue;
                        if (ti >= as.values.len) continue;
                        if (binding_materializes_table(mod, t0.name.ident, as.values[ti])) return true;
                    }
                },
                // `global M = {}` + `M.x = 1` + tail `M` is the MOD-1 wrapper
                // shape, and it lives in 42 stdlib modules (std.color, std.term,
                // std.trace, std.mcp, …). This walk only ever looked at `.assign`,
                // which was harmless while `stmt_is_native_scalar` refused every
                // `global_decl` outright — the outer gate hid the hole. The moment
                // `global x = req "…"` was allowed through (it is the declared
                // spelling of an `assign` the precheck already took), the hole
                // opened: `std.color` chose native-scalar, emitted no storage for
                // `M`, and every consumer failed to compile with "use of
                // undeclared identifier `duo_g_std_color_M`" — the exact
                // producer/consumer mismatch the comment above describes.
                //
                // Caught by a hand-written probe (`req "std.color"`; read a
                // field), NOT by the 80-program corpus differential, which stayed
                // green because no example reqs a table-exporting stdlib module.
                .global_decl => |gd| {
                    for (gd.names, 0..) |gname, gi| {
                        if (gi >= gd.inits.len) continue;
                        if (binding_materializes_table(mod, gname.ident, gd.inits[gi])) return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    /// A positional aggregate whose leaves are integer literals. Nested rows
    /// are still immutable data, not keyed exports; the graph owns their exact
    /// member packs and the direct realization chooses the physical layout.
    fn table_is_positional_int_blob(expr: *const ast.Expr) bool {
        for (expr.table.fields) |fld| {
            switch (fld) {
                .positional => |pv| switch (pv.*) {
                    .int_lit => {},
                    .table => if (!table_is_positional_int_blob(pv)) return false,
                    else => return false,
                },
                else => return false,
            }
        }
        return true;
    }

    fn module_has_keyed_write(mod: *const ast.Module, name: []const u8) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .assign) continue;
            for (stmt.assign.targets) |t| {
                switch (t.*) {
                    .field => |f| {
                        if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, name)) return true;
                    },
                    .index => |ix| {
                        if (ix.obj.* == .name and ix.key.* == .quoted and
                            std.mem.eql(u8, ix.obj.name.ident, name)) return true;
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    pub fn can_emit_native_scalar_module(self: *CodeGen, mod: *const ast.Module) bool {
        self.resetNativeScalarReason();
        if (native_diag) std.debug.print("[native-diag] CALLED idol_mode={} target={s} load={} lib={} test={} bench={}\n", .{ self.idol_mode, self.target, self.load_chunk, self.lib_mode, self.test_mode, self.bench_mode });
        self.current_module = mod;
        self.collect_req_module_bindings(mod) catch {
            // gap[166]: an allocator failure while recording req bindings is not
            // a MODULE VERDICT, and naming it one put a module-shaped reason in
            // front of the graph's refusal. `nofit` records the site and nothing
            // more.
            return self.nofit(@src());
        };
        self.noteSubjectDescriptors(mod) catch {
            self.nativeDiagFail("subject-descriptors");
            return self.nofit(@src());
        };
        // WP-01: bench_mode no longer forces boxing by default.
        // Only --bench-backend=c-dynamic explicitly selects the boxed path.
        if (self.bench_mode and self.bench_backend == .c_dynamic) {
            self.nativeDiagFail("bench-c-dynamic");
            return self.nofit(@src());
        }
        if (self.bench_mode and self.bench_backend == .direct) {
            self.nativeDiagFail("bench-direct-via-codegen");
            return self.nofit(@src());
        }
        // `lib_mode` is deliberately NOT disqualifying here. It was excluded because
        // `--lib` existed for wasm WAST testing, and the target guard immediately
        // below already rejects every wasm target — so relaxing it changes behavior
        // only for native targets, where `--lib` means exactly "a natively lowered
        // object with no main", the emission mode a linkable `lexer_tokenize.c`
        // needs (SH-03 / MP4-B02).
        if (self.load_chunk or self.test_mode) {
            self.nativeDiagFail("guard-mode");
            return self.nofit(@src());
        }
        if (!std.mem.eql(u8, self.target, "native") and
            !std.mem.eql(u8, self.target, "native-object") and
            !std.mem.eql(u8, self.target, "native-mach-o") and
            !std.mem.eql(u8, self.target, "native-asm") and
            !std.mem.eql(u8, self.target, "native-exe") and
            !std.mem.eql(u8, self.target, "native-dylib"))
        {
            self.nativeDiagFail("guard-target");
            return self.nofit(@src());
        }
        // The module's own scope, live for every check below that is NOT inside
        // a function body: the tail expression here and the top-level
        // statements in the loop further down. Both used to be walked with
        // `precheck_types` empty — see `precheck_collect_module_types`.
        self.precheck_collect_module_types(mod);
        if (mod.body.tail_expr) |expr| {
            if (!self.call_stmt_is_native_scalar(expr)) {
                self.nativeDiagFail("mod-tail");
                return self.nofit(@src());
            }
        }

        // `keyed-table-export` CLOSED: a module-scope table binding's FIELDS now
        // have real storage on the direct path. `ModuleGlobals` in
        // `dnir_lower.zig` interns one `__DATA,__bss` word per written field key
        // (`Lduo_g_M.x`), the module body runs the literal and every keyed write
        // as stores into it, and `native_backend.zig`'s `globals` map answers
        // every read — so module scope and a relation body name ONE location and
        // cannot disagree. The refusal that stood here was the honest guard
        // while the write landed nowhere; the storage landed, so it is deleted.
        //
        // ONE DIAGNOSTIC STRING, SEVERAL PROBLEMS. Measured on the 941-file
        // corpus at HEAD, this line stopped 70 programs, and the shape its own
        // comment described — a table EXPORTED by keyed writes — was the
        // minority. Most were ordinary single-file programs holding a
        // module-scope record of constants (`M = { A = 3, B = 4 }`), whose reads
        // `ModuleConsts` has folded correctly for as long as it has existed. The
        // guard was refusing them for a hazard that was not theirs.
        //
        // DELETING IT ALONE WOULD MISCOMPILE, which is why the storage is the
        // deliverable and not the deletion. `M = { a = 1 }` / `M.a = 2` / a
        // relation reading `M.a` prints 1 with this line removed and nothing
        // else changed — `ModuleConsts` folds the literal while the write goes
        // somewhere else. Registering the field as storage is what removes it
        // from the constant pool. `examples/keyed_table_write_wins.id` is that
        // program.
        //
        // WHAT IS NOT CLOSED, and now refuses at LOWERING where the capability
        // lives rather than here: a LIBRARY module (no entry, so no body runs to
        // fill the words) whose table is its export — that one still needs an
        // EXTERNAL symbol and a naming law the consumer resolves through the
        // graph, and `internGlobal` emits a local symbol today; and a field
        // whose holding two writes describe differently. Both bail with a named
        // reason from `dnir_lower`/`native_backend` before any symbol is
        // emitted. The dependency-edge use of `module_materializes_table` in
        // `module_path_allows_full_native_embed` is untouched and still honest
        // for exactly that reason.

        // gap[066]/gap[108] CLOSED 2026-08-18: a file-scope binding a function
        // writes now has real storage on the direct path — `ModuleGlobals` in
        // `dnir_lower.zig` interns one `__DATA,__bss` word per name and emits
        // the initializers as entry-prologue stores, and `native_backend.zig`'s
        // `globals` map answers every read. The `mod-global-written:` refusal
        // below was the honest guard while the write landed nowhere; the storage
        // landed, so the guard is deleted and both fixtures are promoted into
        // the differential corpus proper (proof: g066 prints 6 5 / exits 6,
        // g108 prints 8 8, both agreeing with the C column).

        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl => |fd| {
                    if (fd.path.len != 1) {
                        self.nativeDiagFail("func-path");
                        return self.nofit(@src());
                    }
                    if (fd.func.vararg or fd.func.vararg_name != null) {
                        self.nativeDiagFail("func-vararg");
                        return self.nofit(@src());
                    }
                    if (fd.func.is_async) {
                        self.nativeDiagFail("func-async");
                        return self.nofit(@src());
                    }
                    // Test/bench/debug/trace directives require the full runtime.
                    if (@import("directives.zig").attrsMarkTest(fd.attributes)) {
                        self.nativeDiagFail("func-test");
                        return self.nofit(@src());
                    }
                    if (@import("directives.zig").attrsWantBench(fd.attributes)) {
                        self.nativeDiagFail("func-bench");
                        return self.nofit(@src());
                    }
                    if (@import("directives.zig").attrsHaveDebug(fd.attributes)) {
                        self.nativeDiagFail("func-debug");
                        return self.nofit(@src());
                    }
                    // Allow closures and methods — they compile to C functions.
                    if (fd.func.type_params != null) {
                        self.nativeDiagFail("func-type-params");
                        return self.nofit(@src());
                    }
                    const ret_ty = native_ret_contract(&fd.func);
                    if (ret_ty != .inferred and !self.type_expr_is_native_scalar(ret_ty) and
                        !self.type_expr_is_native_result_pack(ret_ty))
                    {
                        // The tag has to name what the PREDICATE saw, not what
                        // the source spells. `contract_ret` answers `.inferred`
                        // for a fallible contract, so `scan(b: i64): i64 | error`
                        // reported "ret-type:i64" — a type that is perfectly
                        // native — and sent a reader to the wrong line. What
                        // disqualifies it is the correlated success/error
                        // alternative, not an ordinary fixed GP result pack.
                        if (fd.func.ret_fallible) {
                            self.nativeDiagFailFmt("ret-pack:{s}|error", .{typeLabel(fd.func.ret_type)});
                        } else {
                            self.nativeDiagFailFmt("ret-type:{s}", .{typeLabel(fd.func.ret_type)});
                        }
                        return self.nofit(@src());
                    }
                    for (fd.func.params) |param| {
                        if (param.default_val != null) {
                            self.nativeDiagFail("param-default");
                            return self.nofit(@src());
                        }
                        // `param-type:any` IS THE LARGEST REFUSAL FAMILY AND
                        // CLOSING IT BUYS NOTHING. Measured on the 921-file
                        // corpus (`examples`+`lib`+`scripts`, `compile_fail`
                        // excluded): 60 programs stop here on `any` and 30 more
                        // on `inferred`. The obvious repair is CALL-SITE
                        // INFERENCE — for a whole-program compile, if every
                        // call site passes one native scalar descriptor, the
                        // parameter IS that descriptor. It was measured before
                        // it was written, and it must not be written.
                        //
                        // REACH IS ZERO, twice over. Admitting every `any`
                        // parameter unconditionally — the strict upper bound on
                        // what any inference can reach — moves all 60 programs
                        // to a DEEPER refusal and compiles none of them:
                        // `assign-target` (11), `method-unresolved:*` (16),
                        // `gen-for-dynamic-iter` (9), `expr-unhandled:func_expr`
                        // (2), `runtime-global*` (6), and one each of a dozen
                        // more. Leaving the annotation `any` is not the whole
                        // story, so the three programs whose sites do agree were
                        // also re-measured with the inferred descriptor written
                        // in BY HAND: `examples/cfloor/weak.id` with
                        // `mix(a: i64, b: i64)` still stops on `print-arg:any`
                        // (its caller's local is what is untyped, not its
                        // parameter), and both hash-agreement fixtures with
                        // `box(x: str)` still stop on `assign-target` /
                        // `block-tail-no-return`. Same 68-for-zero shape the
                        // `ret-type:any` fold hit.
                        //
                        // AND THE SOUND SET IS THREE PROGRAMS. 55 of the 60 are
                        // `lib/` modules with no entry point, so their
                        // `any`-parameter functions ARE the module's exports:
                        // of the 707 top-level functions carrying a non-native
                        // parameter, 241 have ZERO in-module call sites (no
                        // constraint exists to read) and 317 put the name in
                        // value position (higher-order, so the site is
                        // indirect). Only `examples/cfloor/weak.id` (`mix`,
                        // both parameters i64) and the two hash-agreement
                        // fixtures (`box`, str at all four sites) have every
                        // site visible, agreeing, and native.
                        //
                        // ON THOSE THREE THE INFERENCE WOULD BE A REGRESSION,
                        // not a gain. `examples/hash/agreement.id` is the
                        // `hash-agreement` build step and `docs/source-corpus-
                        // classification.md` lists it as a fixture with
                        // INTENTIONAL `any`: it proves the compile-time and
                        // runtime string hashes agree, which requires the value
                        // to stay BOXED so that `!=` is object identity. Typing
                        // `box`'s parameter `str` makes both halves take the
                        // runtime hash and the control can no longer fire — the
                        // gate would still print PASS, for no reason. `weak.id`
                        // is the weak half of the `law.perf.dominance` pair
                        // (`scripts/cfloor.id`) and its premise, written in its
                        // own header, is that an `any` parameter makes
                        // `lower.native` an invalid candidate for `mix`.
                        //
                        // THE MONO FACILITY CANNOT CARRY THIS. `mono.zig`'s
                        // `collectGenerics` keys strictly on a non-empty
                        // `type_params`, and `func-type-params` above refuses
                        // every such function before this loop runs — so no
                        // function that reaches this line is, or can become, a
                        // `findSpecializationForCall` candidate.
                        //
                        // The refusal stands because it is TRUE, not because it
                        // is unexamined: a parameter's descriptor is fixed by
                        // its call sites and this compile cannot see all of
                        // them. Reopen it only when the deeper blockers above
                        // have fallen and a program is measured to be waiting
                        // on this line alone.
                        if (!self.type_expr_is_native_scalar(param.typ)) {
                            self.nativeDiagFailFmt("param-type:{s}", .{typeLabel(param.typ)});
                            return self.nofit(@src());
                        }
                    }
                    self.precheck_collect_types(&fd.func);
                    // RESTORE, not wipe. Every statement after this one is in
                    // MODULE scope, and clearing left them with no answer at
                    // all — the same empty map the tail expression used to get.
                    defer self.precheck_collect_module_types(mod);
                    if (!self.block_is_native_scalar(fd.func.body, true)) {
                        self.nativeDiagFail("func-body");
                        return self.nofit(@src());
                    }
                },
                .const_decl => |cd| {
                    if (!self.type_expr_is_native_scalar(cd.typ) and cd.typ != .inferred) {
                        self.nativeDiagFail("const-typ-nonnative");
                        return self.nofit(@src());
                    }
                    if (!self.expr_is_native_scalar(cd.val)) {
                        self.nativeDiagFail("const-val-expr");
                        return self.nofit(@src());
                    }
                },
                .local_decl, .assign, .call_stmt, .expr_stmt, .while_loop, .num_for, .do_block, .ret, .brk, .cont => {
                    if (!self.stmt_is_native_scalar(stmt, false)) {
                        self.nativeDiagFailFmt("mod-top-stmt:{s}", .{@tagName(stmt.*)});
                        return self.nofit(@src());
                    }
                },
                // Module-top `.if_stmt` lowers into a TAIL EXPRESSION of the
                // pre-existing DISPATCH (it is the answer the direct-Native
                // run refused to admit) — every branch lowers independently
                // via `stmt_is_native_scalar`, and the gate's own `is the
                // if's tail the program tail` check falls through. A `.ret`
                // inside the body becomes the program's exit code; an
                // `.if_stmt` with no `.ret` falls through to the next
                // module-top statement, exactly as the offside tail rules.
                // Module-top early-return is the EXACT gate source shape
                // (`gate/admission.id`, `gate/host.id`) and shutting it off
                // here cost the direct backend every gate whose entrance
                // happens to look like a program with a bootstrap-waiver
                // admission — see cap-shape at `examples/demand/swap.id` for
                // a working module-tail `if`.
                .if_stmt => |is| {
                    if (!self.expr_is_native_scalar(is.cond)) {
                        self.nativeDiagFailFmt("mod-top-if-cond:{s}", .{@tagName(is.cond.*)});
                        return self.nofit(@src());
                    }
                    if (!self.block_is_native_scalar(is.then, true)) {
                        self.nativeDiagFailFmt("mod-top-if-then:{s}", .{@tagName(is.cond.*)});
                        return self.nofit(@src());
                    }
                    for (is.elseifs) |elseif| {
                        if (!self.expr_is_native_scalar(elseif.cond) or
                            !self.block_is_native_scalar(elseif.body, true))
                        {
                            self.nativeDiagFail("mod-top-if-elseif");
                            return self.nofit(@src());
                        }
                    }
                    if (is.else_body) |body| {
                        if (!self.block_is_native_scalar(body, true)) {
                            self.nativeDiagFail("mod-top-if-else");
                            return self.nofit(@src());
                        }
                    }
                },
                .repeat_loop, .gen_for, .match_stmt, .label_stmt, .goto_stmt, .global_decl => {
                    if (!self.stmt_is_native_scalar(stmt, false)) {
                        self.nativeDiagFailFmt("mod-top-stmt:{s}", .{@tagName(stmt.*)});
                        return self.nofit(@src());
                    }
                },
                .try_stmt, .defer_stmt => {
                    self.nativeDiagFail("mod-top-try-defer");
                    return self.nofit(@src());
                },
                .macro_def => {},
                .cinclude => {},
                .concept_def => {},
                .enum_def, .alias_def => {},
                .directive => {},
            }
        }
        return true;
    }

    /// gap[166]. THE MODULE QUESTION MOVED; IT DID NOT VANISH.
    ///
    /// `stmt_is_native_scalar` used to answer "does this file-scope home
    /// binding lower natively?" by probing the filesystem, and it answered it
    /// 210 lines BEFORE the graph is lifted, as a hard gate on the direct
    /// backend. That is the pre-graph module reasoning gap[166] deletes: a
    /// pre-graph gate cannot have a sound module answer, so it now admits the
    /// SHAPE and the graph answers (`unresolved-application-facts`).
    ///
    /// This generator is not a pre-graph gate. It is the retired C bootstrap's
    /// EMITTER, it runs after `collect_req_module_bindings`, and the native
    /// scalar profile it selects has no way to represent a binding that will be
    /// emitted as a runtime require. So the verdict lives HERE, once, on the
    /// consumer that needs it — not in a predicate the direct backend shares.
    ///
    /// MEASURED, `idol dump-c` over all 1005 tracked `.id`: without this,
    /// `lib/token/grammarrole.id` chose the native-scalar profile for
    /// `grammar = req("std.compiler.token")` (a home that resolves to no file)
    /// and then died on "codegen refused a binding whose value it cannot
    /// represent" — 6400 lines of C to exit 1. With it, all 1005 rows and all
    /// 815 emitted C artifacts are byte-identical to the unpatched compiler.
    fn moduleHomeBindingsAreNativeDirect(self: *CodeGen, mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| for (ld.inits) |init_expr| {
                    if (req_path_from_expr(init_expr)) |path| {
                        if (!self.req_module_is_native_direct(path)) return false;
                    }
                },
                .assign => |*as| for (as.values) |value| {
                    if (req_path_from_expr(value)) |path| {
                        if (!self.req_module_is_native_direct(path)) return false;
                    }
                },
                .global_decl => |*gd| for (gd.inits) |init_expr| {
                    if (req_path_from_expr(init_expr)) |path| {
                        if (!self.req_module_is_native_direct(path)) return false;
                    }
                },
                else => {},
            }
        }
        return true;
    }

    fn all_module_functions_native(self: *CodeGen, mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len != 1) return false;
            if (self.native_scalar_mode) continue;
            if (!self.native_scalar_funcs.contains(fd.path[0])) return false;
        }
        return true;
    }

    fn module_top_level_is_native(self: *CodeGen, mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                // gap[166]: both arms below used to answer "is this top-level
                // module binding native?" by probing the filesystem
                // (`find_module_file_for_req`) or an emission record. Same
                // deletion as the precheck gate: a home binding is admitted by
                // shape and the module question belongs to the graph.
                .local_decl => |*ld| {
                    for (ld.inits) |init_expr| {
                        if (req_path_from_expr(init_expr) != null) continue;
                        if (!self.expr_is_native_scalar(init_expr)) return false;
                    }
                },
                .assign => |*as| {
                    for (as.values) |value| {
                        if (req_path_from_expr(value) != null) continue;
                        if (!self.expr_is_native_scalar(value)) return false;
                    }
                },
                .call_stmt => |*cs| {
                    if (!self.expr_is_native_scalar(cs.expr)) return false;
                },
                .expr_stmt => |*es| {
                    if (!self.expr_is_native_scalar(es.expr)) return false;
                },
                .func_decl, .const_decl, .alias_def, .enum_def, .concept_def, .macro_def, .cinclude, .directive => {},
                else => return false,
            }
        }
        return true;
    }

    /// True when any statement in the module needs the lua runtime: a return
    /// pack (`a, b = f()`, several targets fed by one call) or a generic-for
    /// (which lowers through the dynamic `__iter` protocol). Both emit
    /// `lua_mret_*`, which the substrate-native profile never declares.
    fn blockHasReturnPack(blk: *const ast.Block) bool {
        for (blk.stmts) |*stmt| {
            switch (stmt.*) {
                .assign => |as| if (as.targets.len != as.values.len) return true,
                .local_decl => |ld| if (ld.names.len != ld.inits.len and ld.inits.len == 1) return true,
                .do_block => |db| if (blockHasReturnPack(&db.body)) return true,
                .while_loop => |ws| if (blockHasReturnPack(&ws.body)) return true,
                .repeat_loop => |rs| if (blockHasReturnPack(&rs.body)) return true,
                .num_for => |nf| if (blockHasReturnPack(&nf.body)) return true,
                .gen_for => |gf| {
                    // The loop itself needs the runtime, not just its body.
                    _ = gf;
                    return true;
                },
                .if_stmt => |is| {
                    if (blockHasReturnPack(&is.then)) return true;
                    for (is.elseifs) |ei| if (blockHasReturnPack(&ei.body)) return true;
                    if (is.else_body) |eb| if (blockHasReturnPack(&eb)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn moduleHasReturnPack(mod: *const ast.Module) bool {
        if (blockHasReturnPack(&mod.body)) return true;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl and blockHasReturnPack(&stmt.func_decl.func.body)) return true;
        }
        return false;
    }

    fn compute_substrate_native_mode(self: *CodeGen, mod: *const ast.Module) bool {
        // Source law constrains each operation below; it does not itself make
        // a checked scalar closure require the Lua runtime.
        if (self.load_chunk or self.test_mode) return false;
        if (self.bench_mode and self.bench_backend != .c_specialized) return false;
        if (self.native_scalar_mode) return true;
        if (!self.mixed_scalar_mode) return false;
        // A library has no `main` by construction; requiring one is what forced
        // `lexer.duo` to lower with the full lua runtime when compiled standalone.
        // Its exported entries carry the native-lowering requirement instead.
        if (!self.lib_mode and !self.native_scalar_funcs.contains("main")) return false;
        // Substrate-native means *no lua runtime is emitted at all*, so it is not
        // enough for `main` to be native-eligible: a module whose `main` is scalar
        // but whose helpers use return packs claimed substrate-native and then
        // emitted `lua_mret_*` against a runtime that was never declared.
        //
        // Disqualify on the construct that actually needs the runtime, not on
        // `native_scalar_funcs` membership — that predicate is much broader, and
        // requiring it of every function knocked `lexer.duo --lib` off the native
        // path entirely (1761 lines / 0 lua_Value became 8332 / 1066).
        // These four were the SILENT PATH. The instrumentation pass covered the
        // body of can_emit_native_scalar_module but not this tail, so a module
        // refused here cleared every gate that names itself and produced a
        // DNB001 with no bail site at all — the one remaining case of the
        // original undifferentiated bucket.
        if (moduleHasReturnPack(mod)) {
            self.nativeDiagFail("return-pack");
            return false;
        }
        if (self.moduleHasBoxedFuncSignature(mod)) {
            self.nativeDiagFail("boxed-func-signature");
            return false;
        }
        if (!self.req_deps_are_native_direct(mod)) {
            self.nativeDiagFail("req-dep-not-native");
            return false;
        }
        if (!self.module_top_level_is_native(mod)) {
            self.nativeDiagFail("module-top-level");
            return false;
        }
        return true;
    }

    /// Substrate-native emits no lua runtime at all, so no function SIGNATURE in
    /// the module may mention `lua_Value`. A parameter or return typed `any`
    /// lowers to exactly that, and the prototype is emitted for every top-level
    /// function whether or not it is reached — so a module with a typed native
    /// `main` beside a `g(f: any): str` helper claimed substrate-native and then
    /// emitted `static inline const char* g(lua_Value f);` against a runtime it
    /// had just decided not to declare: "unknown type name 'lua_Value'".
    ///
    /// This is deliberately a signature check and nothing more. Requiring
    /// `native_scalar_funcs` membership would also inspect bodies, which is the
    /// much broader predicate the comment above rejects.
    fn moduleHasBoxedFuncSignature(self: *CodeGen, mod: *const ast.Module) bool {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (native_ret_contract(&fd.func) != .inferred and !self.type_expr_is_native_scalar(native_ret_contract(&fd.func))) return true;
            for (fd.func.params) |param| {
                if (!self.type_expr_is_native_scalar(param.typ)) return true;
            }
        }
        return false;
    }

    /// A MODULE THIS COMPILER CANNOT FIND MUST BE REFUSED, NOT EMITTED AS A NULL.
    ///
    /// MEASURED at HEAD, and it is the worst class this tree ships — a program
    /// that type-checks clean and dies:
    ///
    ///     main: i64 = ()
    ///         print(std.nosuch.f(1))
    ///         0
    ///
    ///     idol check     ->  ✓ checked — no errors
    ///     --backend=c    ->  BUILDS, and the artifact SEGFAULTS (139, 3 of 3)
    ///
    /// `collect_require_names` registers a module for an explicit `require` or
    /// for a `std.`-dotted path that RESOLVES, and for nothing else. When
    /// neither fires nothing registers the root, sema has already recorded
    /// `std` as an ordinary dynamic global, and the emitter declares
    /// `static lua_Value duo_g_std;` — zero initialised — which the next line
    /// dereferences twice:
    ///
    ///     lua_table_get_str_lit(lua_table_get_str_lit(duo_g_std, "nosuch", …), "f", …)
    ///
    /// In a no-lua translation unit the same shape is a loud C failure instead
    /// (`unknown type name 'lua_Value'`), which is why this went unnoticed: the
    /// two lowering modes fail differently and only one of them is quiet.
    ///
    /// SCOPED TO `std`, deliberately. That is the root the resolver already
    /// special-cases above, it is the one measured, and confining the refusal
    /// to it means no user-chosen name can be captured by this check.
    ///
    /// AND IT NEVER TAKES A NAME. A program that binds `std` itself owns the
    /// word — the same invariant that governs `env` — so a module that declares
    /// `std` keeps its ordinary global and this declines.
    fn refuseUnresolvableStdModule(self: *CodeGen, mod: *const ast.Module) E!void {
        if (!self.idol_mode) return;
        if (self.src_path.len == 0) return;
        if (moduleBindsName(mod, "std")) return;

        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        self.unresolved_std_module = null;
        self.collect_require_names_block(&mod.body, &names) catch return;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                self.collect_require_names_block(&stmt.func_decl.func.body, &names) catch return;
            }
        }

        const bad = self.unresolved_std_module orelse return;
        term.locErr(bad.loc, "no module named '{s}': the compiler cannot find it, so this reference has no value", .{bad.path});
        term.locHint(bad.loc, "check the spelling, or add the module — emitting it as a null global is how this became a segfault rather than an error", .{});
        self.noalloc_violation = "codegen refused a reference to a module it cannot find";
        return error.NoAllocViolation;
    }

    /// True when the module itself binds `name` at top level — a local, a
    /// global, an assignment target or a declared relation. The world supplies
    /// reach and never takes a name, so every "is this the world's word?"
    /// question has to ask this first.
    fn moduleBindsName(mod: *const ast.Module, name: []const u8) bool {
        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*d| for (d.names) |n| {
                    if (std.mem.eql(u8, n.ident, name)) return true;
                },
                .global_decl => |*d| for (d.names) |n| {
                    if (std.mem.eql(u8, n.ident, name)) return true;
                },
                .assign => |*a| for (a.targets) |t| {
                    if (t.* == .name and std.mem.eql(u8, t.name.ident, name)) return true;
                },
                .func_decl => |*fd| {
                    if (fd.path.len > 0 and std.mem.eql(u8, fd.path[0], name)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    /// Transitive req targets are native-direct embeddable modules (lua_require not required).
    fn req_deps_are_native_direct(self: *CodeGen, mod: *const ast.Module) bool {
        if (self.src_path.len == 0) return true;
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        self.collect_require_names_block(&mod.body, &names) catch return false;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                self.collect_require_names_block(&stmt.func_decl.func.body, &names) catch return false;
            }
        }

        var seen_paths: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen_paths.deinit(self.alloc);
        var seen_names: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen_names.deinit(self.alloc);

        var i: usize = 0;
        while (i < names.items.len) : (i += 1) {
            const alias = names.items[i];
            if (seen_names.contains(alias)) continue;
            seen_names.put(self.alloc, alias, {}) catch return false;
            const mod_path = self.find_module_file_for_req(alias) orelse continue;
            if (seen_paths.contains(mod_path)) continue;
            seen_paths.put(self.alloc, mod_path, {}) catch return false;
            if (!self.req_module_is_native_direct(alias)) return false;

            const sub_src = Io.Dir.readFileAlloc(Io.Dir.cwd(), self.io, mod_path, self.alloc, .unlimited) catch return false;
            defer self.alloc.free(sub_src);
            var sub_lex = openEmbedLexer(sub_src, mod_path);
            if (!routeEmbedThroughDuoLexer(self.alloc, &sub_lex, sub_src, mod_path)) return false;
            var sub_parser = @import("parser.zig").Parser.init(&sub_lex, self.alloc);
            // The embed path must parse a `.duo` module in the same dialect the
            // standalone path uses. Without this, duo-mode-only syntax (bare
            // function declarations) parses fine when the file is compiled
            // directly but fails with "expected '<eof>', got 'end'" the moment it
            // is embedded — which is what stopped `lib/script.id` and
            // `lib/mcp.id` from embedding, and so kept the Duo MCP servers dead.
            sub_parser.idol_mode = sub_lex.family == lexer_bridge.family_canon;
            var sub_mod = sub_parser.parse_module() catch return false;
            self.collect_require_names_block(&sub_mod.body, &names) catch return false;
            for (sub_mod.body.stmts) |*sub_stmt| {
                if (sub_stmt.* == .func_decl) {
                    self.collect_require_names_block(&sub_stmt.func_decl.func.body, &names) catch return false;
                }
            }
        }
        return true;
    }

    /// Per-function native scalar check: scans the module and populates
    /// `native_scalar_funcs` with the names of functions that can be emitted
    /// as native C (scalar params, scalar body, no varargs/generics/async).
    /// Returns true if at least one function is native-eligible.
    pub fn compute_native_scalar_funcs(self: *CodeGen, mod: *const ast.Module) bool {
        self.native_scalar_funcs.clearRetainingCapacity();
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len != 1) continue;
            if (fd.func.vararg or fd.func.vararg_name != null) continue;
            if (fd.func.is_async) continue;
            if (@import("directives.zig").attrsMarkTest(fd.attributes)) continue;
            if (@import("directives.zig").attrsWantBench(fd.attributes)) continue;
            if (@import("directives.zig").attrsHaveDebug(fd.attributes)) continue;
            if (fd.func.type_params != null) continue;
            if (!self.type_expr_is_native_scalar(contract_ret(&fd.func))) continue;
            var params_ok = true;
            for (fd.func.params) |param| {
                if (param.default_val != null) {
                    params_ok = false;
                    break;
                }
                if (!self.type_expr_is_native_scalar(param.typ)) {
                    params_ok = false;
                    break;
                }
            }
            if (!params_ok) continue;
            if (!self.block_is_native_scalar(fd.func.body, true)) continue;
            self.native_scalar_funcs.put(self.alloc, fd.path[0], {}) catch {};
        }
        return self.native_scalar_funcs.count() > 0;
    }

    fn func_decl_is_native_scalar_candidate(self: *CodeGen, fd: *const ast.FuncDecl) bool {
        if (!self.func_decl_has_native_signature(fd)) return false;
        return self.block_is_native_scalar(fd.func.body, true);
    }

    fn func_decl_has_native_signature(self: *CodeGen, fd: *const ast.FuncDecl) bool {
        if (fd.path.len != 1) return false;
        if (fd.func.vararg or fd.func.vararg_name != null) return false;
        if (fd.func.is_async) return false;
        if (@import("directives.zig").attrsMarkTest(fd.attributes)) return false;
        if (@import("directives.zig").attrsWantBench(fd.attributes)) return false;
        if (@import("directives.zig").attrsHaveDebug(fd.attributes)) return false;
        if (fd.func.type_params != null) return false;
        if (native_ret_contract(&fd.func) != .inferred and !self.type_expr_is_native_scalar(native_ret_contract(&fd.func))) return false;
        for (fd.func.params) |param| {
            if (param.default_val != null) return false;
            if (!self.type_expr_is_native_scalar(param.typ)) return false;
        }
        return true;
    }

    fn collect_same_module_call_names(self: *CodeGen, expr: *const ast.Expr, out: *std.ArrayList([]const u8)) !void {
        switch (expr.*) {
            .call => |c| {
                if (c.func.* == .name and !is_runtime_global(c.func.name.ident)) {
                    try out.append(self.alloc, c.func.name.ident);
                } else if (c.func.* == .field and c.func.field.obj.* == .name) {
                    // method-style same-module: skip — use name calls only
                }
                try self.collect_same_module_call_names(c.func, out);
                for (c.args) |arg| try self.collect_same_module_call_names(arg, out);
            },
            .method_call => |mc| {
                try self.collect_same_module_call_names(mc.obj, out);
                for (mc.args) |arg| try self.collect_same_module_call_names(arg, out);
            },
            .binop => |b| {
                try self.collect_same_module_call_names(b.lhs, out);
                try self.collect_same_module_call_names(b.rhs, out);
            },
            .unop => |u| try self.collect_same_module_call_names(u.operand, out),
            .field => |f| try self.collect_same_module_call_names(f.obj, out),
            .index => |idx| {
                try self.collect_same_module_call_names(idx.obj, out);
                try self.collect_same_module_call_names(idx.key, out);
            },
            .if_expr => |ie| {
                try self.collect_same_module_call_names(ie.cond, out);
                try self.collect_same_module_call_names(ie.then_expr, out);
                try self.collect_same_module_call_names(ie.else_expr, out);
            },
            else => {},
        }
    }

    fn collect_same_module_calls_in_block(self: *CodeGen, block: *const ast.Block, out: *std.ArrayList([]const u8)) !void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |ld| {
                    for (ld.inits) |init_expr| try self.collect_same_module_call_names(init_expr, out);
                },
                .assign => |as| {
                    for (as.values) |val| try self.collect_same_module_call_names(val, out);
                },
                .if_stmt => |is| {
                    try self.collect_same_module_call_names(is.cond, out);
                    try self.collect_same_module_calls_in_block(&is.then, out);
                    for (is.elseifs) |elseif| {
                        try self.collect_same_module_call_names(elseif.cond, out);
                        try self.collect_same_module_calls_in_block(&elseif.body, out);
                    }
                    if (is.else_body) |*eb| try self.collect_same_module_calls_in_block(eb, out);
                },
                .while_loop => |wl| {
                    try self.collect_same_module_call_names(wl.cond, out);
                    try self.collect_same_module_calls_in_block(&wl.body, out);
                },
                .repeat_loop => |rl| {
                    try self.collect_same_module_call_names(rl.cond, out);
                    try self.collect_same_module_calls_in_block(&rl.body, out);
                },
                .ret => |r| {
                    for (r.vals) |val| try self.collect_same_module_call_names(val, out);
                },
                .expr_stmt => |es| try self.collect_same_module_call_names(es.expr, out),
                .call_stmt => |cs| try self.collect_same_module_call_names(cs.expr, out),
                else => {},
            }
        }
        if (block.tail_expr) |expr| try self.collect_same_module_call_names(expr, out);
    }

    fn find_embedded_top_level_func(mod: *const ast.Module, name: []const u8) ?*const ast.FuncDecl {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.path.len == 1 and std.mem.eql(u8, fd.path[0], name)) return fd;
        }
        return null;
    }

    fn expand_native_scalar_func_transitive(self: *CodeGen, mod: *const ast.Module) void {
        var work: std.ArrayList([]const u8) = .empty;
        defer work.deinit(self.alloc);
        var it = self.native_scalar_funcs.keyIterator();
        while (it.next()) |key| work.append(self.alloc, key.*) catch return;

        var i: usize = 0;
        while (i < work.items.len) : (i += 1) {
            const fd = find_embedded_top_level_func(mod, work.items[i]) orelse continue;
            var callees: std.ArrayList([]const u8) = .empty;
            self.collect_same_module_calls_in_block(&fd.func.body, &callees) catch {
                callees.deinit(self.alloc);
                continue;
            };
            for (callees.items) |callee| {
                if (self.native_scalar_funcs.contains(callee)) continue;
                const cfd = find_embedded_top_level_func(mod, callee) orelse continue;
                if (!self.func_decl_has_native_signature(cfd)) continue;
                self.native_scalar_funcs.put(self.alloc, callee, {}) catch {
                    callees.deinit(self.alloc);
                    return;
                };
                work.append(self.alloc, callee) catch {
                    callees.deinit(self.alloc);
                    return;
                };
            }
            callees.deinit(self.alloc);
        }
    }

    fn block_is_native_scalar(self: *CodeGen, block: ast.Block, allow_return: bool) bool {
        if (block.tail_expr) |expr| {
            // gap[104]: a tail expression in a non-answering block is still a
            // statement. `dnir_lower.lowerBlockTailEffect` lowers it with
            // discard/single consumption when the block is not returning, while
            // `tryEmitTailDemandReturn` consumes or returns it when the block is
            // the answer. The native precheck must therefore ask whether the
            // same expression can be LOWERED, not whether this block may return.
            //
            // gap[033]: this remains `call_stmt_is_native_scalar`, not the raw
            // expression predicate, because a void tail call such as `print` or
            // `stdout:write` is an effect in tail position. Returning it once
            // produced wrong exit codes; lowering already owns the effect/result
            // split, so the gate and lowering stay paired here.
            if (!self.call_stmt_is_native_scalar(expr)) return false;
        }
        for (block.stmts) |*stmt| {
            if (!self.stmt_is_native_scalar(stmt, allow_return)) return false;
        }
        return true;
    }

    fn stmt_is_native_scalar(self: *CodeGen, stmt: *const ast.Stmt, allow_return: bool) bool {
        // Global declarations still need their graph binding-pack consumer.
        // Local declarations and ordinary assignments are admitted here: DNIR
        // consumes the exact graph adjustment and refuses if it is missing.
        switch (stmt.*) {
            .global_decl => |gd| {
                if (gd.names.len != gd.inits.len and gd.inits.len == 1) {
                    self.nativeDiagFail("return-pack-global-decl");
                    return false;
                }
            },
            else => {},
        }
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.names) |lname| {
                    if (lname.attrib != null or lname.attributes.len != 0) {
                        self.nativeDiagFail("local-decl-attrib");
                        break :blk false;
                    }
                    if (lname.typ != .inferred and !self.type_expr_is_native_scalar(lname.typ)) {
                        self.nativeDiagFail("local-decl-typ");
                        break :blk false;
                    }
                }
                for (ld.inits, 0..) |expr, i| {
                    const hint: RT = if (i < ld.names.len) self.resolve_binding_type(&ld.names[i]) else .any;
                    // gap[094]. `a: str = "{i}"` — a number into a `str` place.
                    if (self.native_str_place_violated(hint, expr)) {
                        self.nativeDiagFail("str-place-numeric");
                        break :blk false;
                    }
                    if (!self.init_is_native_scalar(expr, hint)) {
                        self.nativeDiagFail("local-decl-init");
                        break :blk false;
                    }
                }
                break :blk true;
            },
            // `global x = req "…"` is the DECLARED spelling of `x = req "…"`,
            // which the `.assign` arm below has always accepted. The two were
            // never distinguished anywhere downstream — `req_binding_path_for_name`
            // and `stmt_declares_name` both read the arms side by side — but this
            // switch had no `.global_decl` case at all, so it fell to
            // `else => false` and disqualified the whole module. That is GAP-034
            // drift in its purest form: `lib/compiler/lexer.duo` line 7 is
            // `global strm = req "std.str"` and that one line refused native
            // lowering for every program that embeds the Duo lexer.
            //
            // `global *` (implicit global-by-default for a whole block) is NOT
            // accepted: it declares no names to check and changes name resolution
            // for statements the precheck has already walked.
            .global_decl => |gd| blk: {
                if (gd.star) {
                    self.nativeDiagFail("global-star");
                    break :blk false;
                }
                for (gd.names) |gname| {
                    if (gname.attrib != null or gname.attributes.len != 0) {
                        self.nativeDiagFail("global-decl-attrib");
                        break :blk false;
                    }
                    if (gname.typ != .inferred and !self.type_expr_is_native_scalar(gname.typ)) {
                        self.nativeDiagFail("global-decl-typ");
                        break :blk false;
                    }
                }
                for (gd.inits, 0..) |expr, i| {
                    // gap[166] MODULE-ZERO. `global x = req "a.b"` binds a HOME.
                    // Whether that home lowers natively is a graph fact, and this
                    // gate runs 210 lines BEFORE the graph is lifted, so the only
                    // thing it could consult was a filesystem probe
                    // (`req_module_is_native_direct` -> `find_module_file_for_req`)
                    // — `path == identity`, which `docs/spec/source.md` forbids by
                    // name. The probe is deleted and no verdict replaces it: this
                    // gate admits the STATEMENT SHAPE and the graph answers the
                    // module question, which it already does
                    // (`unresolved-application-facts`). A refusal minted here
                    // preempted that answer, because `main.zig` binds the graph
                    // occurrence only when the precheck has no reason of its own.
                    if (req_path_from_expr(expr) != null) continue;
                    // gap[166]. `global C = std.compiler.comptime` — a module
                    // binding written as an ambient dotted path. This arm asked
                    // the FILESYSTEM whether that path named a file and then
                    // asked an emission record whether the file had been emitted
                    // native, both before any graph existed. Deleted with the
                    // `req` verdict above: an ambient dotted path is an ordinary
                    // static path here, and `init_is_native_scalar` below folds
                    // it exactly as it folds every other one.
                    const hint: RT = if (i < gd.names.len) self.resolve_binding_type(&gd.names[i]) else .any;
                    if (!self.init_is_native_scalar(expr, hint)) {
                        self.nativeDiagFailFmt("global-decl-init:{s}", .{@tagName(expr.*)});
                        break :blk false;
                    }
                }
                break :blk true;
            },
            .const_decl => |cd| blk: {
                const typ_ok = cd.typ == .inferred or self.type_expr_is_native_scalar(cd.typ);
                if (!typ_ok) {
                    self.nativeDiagFail("const-decl-typ");
                    break :blk false;
                }
                const hint = if (cd.typ != .inferred) self.resolve_type(cd.typ) else .any;
                if (!self.init_is_native_scalar(cd.val, hint)) {
                    self.nativeDiagFail("const-decl-init");
                    break :blk false;
                }
                break :blk true;
            },
            .assign => |as| blk: {
                if (relation.declFromAssign(as) != null) break :blk true;
                // One application may feed a wider binding pack. This gate
                // admits the surface shape only; DNIR must consume the exact
                // graph PackAdjustment and refuses when that fact is absent.
                if (as.targets.len != as.values.len and as.values.len != 1) break :blk false;
                // gap[166]: the whole-statement module verdict that used to
                // stand here (`moduleBindingPath` -> `req_module_is_native_direct`)
                // is deleted. It was the only arm in this gate that ever minted a
                // module-shaped reason on the corpus, and the reason it minted
                // stood in front of the graph's own refusal for the one program
                // that reached it.
                for (as.targets) |target| {
                    if (!self.lvalue_is_native_scalar(target)) {
                        self.nativeDiagFail("assign-target");
                        break :blk false;
                    }
                }
                for (as.values, 0..) |value, i| {
                    // gap[166]: `x = req "a.b"` is a home binding; see the
                    // `.global_decl` arm above. Shape admitted, module question
                    // left to the graph. The ambient-dotted twin of this arm is
                    // deleted outright — such a path is an ordinary static path
                    // to `init_is_native_scalar` below.
                    if (req_path_from_expr(value) != null) continue;
                    const hint: RT = if (i < as.targets.len and as.targets[i].* == .name)
                        self.global_type(as.targets[i].name.ident) orelse .any
                    else
                        .any;
                    // gap[094]. The DECLARED type of the place, which is not the
                    // same question `hint` answers. `precheck_types` MERGES every
                    // binding of a name and collapses a disagreement to `.any`
                    // — `out: str = "a"` followed by `out = word` (an i64) is
                    // exactly such a disagreement, so by the time this arm runs
                    // the place reads `.any` and a check against it can never
                    // fire. Sema's type for the target expression still carries
                    // the declaration, so that is what the str-place check asks.
                    // `out: str = "a"` then `out = word`, where `word` is the
                    // bare hole `i`. This is the row that SEGFAULTED, and a
                    // check on DECLARATIONS alone would have missed it: the
                    // declaration is well typed and the later assignment is not.
                    const place: RT = if (i < as.targets.len)
                        self.expr_type(as.targets[i])
                    else
                        .any;
                    if (self.native_str_place_violated(place, value) or
                        self.native_str_place_violated(hint, value))
                    {
                        self.nativeDiagFail("str-place-numeric");
                        break :blk false;
                    }
                    if (!self.init_is_native_scalar(value, hint)) {
                        self.nativeDiagFailFmt("assign-value:{s}", .{if (value.* == .unop) @tagName(value.unop.op) else @tagName(value.*)});
                        break :blk false;
                    }
                }
                break :blk true;
            },
            .call_stmt => |cs| self.call_stmt_is_native_scalar(cs.expr),
            .expr_stmt => |es| self.expr_is_native_scalar(es.expr),
            .do_block => |db| self.block_is_native_scalar(db.body, allow_return),
            .while_loop => |wl| self.expr_is_native_scalar(wl.cond) and self.block_is_native_scalar(wl.body, allow_return),
            .repeat_loop => |rl| self.expr_is_native_scalar(rl.cond) and self.block_is_native_scalar(rl.body, allow_return),
            .if_stmt => |is| blk: {
                if (!self.expr_is_native_scalar(is.cond) or !self.block_is_native_scalar(is.then, allow_return)) break :blk false;
                for (is.elseifs) |elseif| {
                    if (!self.expr_is_native_scalar(elseif.cond) or !self.block_is_native_scalar(elseif.body, allow_return)) break :blk false;
                }
                if (is.else_body) |body| {
                    if (!self.block_is_native_scalar(body, allow_return)) break :blk false;
                }
                break :blk true;
            },
            .num_for => |nf| blk: {
                if (!self.type_expr_is_native_scalar(nf.var_typ) and nf.var_typ != .inferred) break :blk false;
                if (!self.expr_is_native_scalar(nf.start) or !self.expr_is_native_scalar(nf.stop)) break :blk false;
                if (nf.step) |step| {
                    if (!self.expr_is_native_scalar(step)) break :blk false;
                }
                break :blk self.block_is_native_scalar(nf.body, allow_return);
            },
            .ret => |r| blk: {
                if (!allow_return) break :blk false;
                for (r.vals) |value| {
                    if (!self.expr_is_native_scalar(value)) break :blk false;
                }
                break :blk true;
            },
            .brk, .cont => true,
            .gen_for => |gf| blk: {
                // §1.2 — generic-for lowers through the dynamic `__iter`
                // metafield protocol (`lua_get_metafield_lit` + `lua_mret_*`), so
                // no `for v in tbl` can be full-native today: claiming it emitted C
                // referencing undeclared `lua_mret_clear`, which meant direct
                // iteration — the *canonical* idiom that replaced pairs/ipairs —
                // could not be compiled in a typed module at all. §1.2's `@iter`
                // return-pack closure is what will make this native and delete
                // this exclusion.
                self.nativeDiagFail("gen-for-dynamic-iter");
                if (true) break :blk false;
                for (gf.iters) |iter| {
                    if (!self.expr_is_native_scalar(iter)) break :blk false;
                }
                break :blk self.block_is_native_scalar(gf.body, allow_return);
            },
            .label_stmt, .goto_stmt => true,
            .directive => true,
            .cinclude => true,
            .enum_def, .alias_def, .concept_def => true,
            .match_stmt => |m| blk: {
                if (!self.expr_is_native_scalar(m.scrutinee)) break :blk false;
                for (m.arms) |arm| {
                    if (!self.block_is_native_scalar(arm.body, allow_return)) break :blk false;
                    if (arm.guard) |g| {
                        if (!self.expr_is_native_scalar(g)) break :blk false;
                    }
                }
                break :blk true;
            },
            else => false,
        };
    }

    /// Expression/type knowledge from sema type_map (per-call lattice).
    fn exprKnowledge(self: *CodeGen, expr: *const ast.Expr) semantic_algebra.KnowledgeLevel {
        return semantic_algebra.knowledgeOfType(self.expr_type(expr));
    }

    /// True when arg can pass to a typed native param without lua_Value boxing.
    fn callArgUsesNativeLowering(self: *CodeGen, arg: *const ast.Expr, param_type: RT) bool {
        if (param_type == .any or self.is_table_module_type(param_type)) return false;
        if (!semantic_algebra.lowersToNativeC(param_type)) return false;
        const arg_rt = self.expr_type(arg);
        if (arg_rt == .any) return false;
        if (!self.exprKnowledge(arg).dominates(.stable)) return false;
        if (!semantic_algebra.knowledgeOfType(param_type).dominates(.stable)) return false;
        const fn_name = self.current_func_name orelse return false;
        return self.funcUsesNativeLowering(fn_name);
    }

    /// module-wide knowledge check (canonical replacement for `native_scalar_mode`).
    fn moduleKnowledgeAtLeast(self: *const CodeGen, min: semantic_algebra.KnowledgeLevel) bool {
        return self.module_knowledge.dominates(min);
    }

    /// Full module lowers without lua_Value (knowledge ≥ native).
    fn moduleUsesFullNativeLowering(self: *const CodeGen) bool {
        return self.native_scalar_mode or self.substrate_native_mode or
            self.moduleKnowledgeAtLeast(.native);
    }

    /// public accessor for driver/link flags (prefer over raw `native_scalar_mode`).
    pub fn usesFullNativeLowering(self: *const CodeGen) bool {
        return self.moduleUsesFullNativeLowering();
    }

    pub fn noallocViolationMessage(self: *const CodeGen) ?[]const u8 {
        return self.noalloc_violation;
    }

    /// Module includes Lua runtime (dynamic paths or mixed native/dynamic).
    fn moduleNeedsLuaRuntime(self: *const CodeGen) bool {
        return !self.moduleUsesFullNativeLowering();
    }

    /// True when `req` bindings in the current function may bypass lua_require.
    fn function_allows_native_req(self: *const CodeGen) bool {
        if (self.moduleUsesFullNativeLowering()) return true;
        return self.mixed_scalar_mode;
    }

    /// Embedded native/mixed modules: native functions only, no lua thunks.
    fn embedded_module_skips_lua_thunks(self: *const CodeGen) bool {
        // A module that exports functions through its `M` table still needs
        // thunks: the table stores lua_Values. Skipping them emitted a table
        // referencing `std_jit__alloc__lua` with no such symbol defined.
        if (self.embedded_module_exports_funcs) return false;
        return self.current_module_cname.len > 0 and self.native_scalar_mode;
    }

    fn skip_lua_thunk_emit(self: *const CodeGen) bool {
        if (!self.moduleNeedsLuaRuntime()) return true;
        if (self.moduleUsesFullNativeLowering() and self.current_module_cname.len == 0) return true;
        if (self.bench_mode and self.bench_backend == .c_specialized and self.mixed_scalar_mode and
            self.current_module_cname.len == 0)
            return true;
        if (self.embedded_module_skips_lua_thunks()) return true;
        if (self.current_module_cname.len > 0 and self.embed_parent_full_native) return true;
        return false;
    }

    /// Per-function native lowering (full-native module or mixed-mode allowlist).
    fn funcUsesNativeLowering(self: *const CodeGen, name: []const u8) bool {
        // Substrate-native / full-native entry: every function in embedded modules
        // must lower without lua_Value (no lua_invoke fallbacks).
        if (self.moduleUsesFullNativeLowering()) return true;
        if (self.embed_parent_full_native) return true;
        if (self.current_module_cname.len > 0) {
            if (self.native_scalar_mode) return true;
            return self.mixed_scalar_mode and self.native_scalar_funcs.contains(name);
        }
        if (self.mixed_scalar_mode) return self.native_scalar_funcs.contains(name);
        return false;
    }

    fn emit_fatal_error(self: *CodeGen, msg_expr: ?*const ast.Expr) E!void {
        if (!self.moduleNeedsLuaRuntime()) {
            self.p("duo_fatal(", .{});
            if (msg_expr) |e| {
                try self.emit_expr(e);
            } else {
                self.p("\"error\"", .{});
            }
            self.p(")", .{});
            return;
        }
        self.p("lua_error(", .{});
        if (msg_expr) |e| {
            try self.emit_as_lua_value(e);
        } else {
            self.p("lua_val_nil()", .{});
        }
        self.p(")", .{});
    }

    /// Expression/type knowledge: eligible for native C emission (no lua_Value).
    fn exprLowersToNativeC(_: *const CodeGen, rt: RT) bool {
        return semantic_algebra.lowersToNativeC(rt);
    }

    /// True when a table type lowers to a C struct (including nested native records).
    fn record_type_lowers_native(self: *CodeGen, rt: RT) bool {
        if (rt != .table_type) return false;
        if (rt.table_type.fields.len == 0) return false;
        for (rt.table_type.fields) |f| {
            if (self.exprLowersToNativeC(f.typ)) continue;
            if (self.record_type_lowers_native(f.typ)) continue;
            return false;
        }
        return true;
    }

    fn type_lowers_native(self: *CodeGen, rt: RT) bool {
        if (self.exprLowersToNativeC(rt)) return true;
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                return self.type_lowers_native(alias_rt);
            }
            return false;
        }
        return self.record_type_lowers_native(rt);
    }

    /// Per-call knowledge lattice: true when a .func type lowers to native C for all params and return.
    fn funcTypeLowersNative(self: *CodeGen, rt: RT) bool {
        if (rt != .func) return false;
        const f = rt.func;
        if (!self.type_lowers_native(f.ret.*)) return false;
        for (f.params) |pt| {
            if (!self.type_lowers_native(pt)) return false;
        }
        return true;
    }

    /// Legacy alias — prefer `funcTypeLowersNative`.
    fn funcTypeIsFullyNative(self: *CodeGen, rt: RT) bool {
        return self.funcTypeLowersNative(rt);
    }

    fn callSiteForShape(self: *CodeGen, shape: types.CallShape) semantic_algebra.CallSite {
        if (shape.callee_name) |name| {
            var name_buf: [256]u8 = undefined;
            if (self.func_decls.get(self.mangled_name(name, &name_buf))) |fd| {
                const effects = semantic_algebra.effectSetFromAttributes(fd.attributes);
                const hardware = semantic_algebra.hardwareLoweringsFromAttributes(fd.attributes);
                return semantic_algebra.callSiteFromShapeWithCalleeFacts(shape, effects, hardware);
            }
        }
        return semantic_algebra.callSiteFromShape(shape);
    }

    fn noteCallTransformProvenance(
        self: *CodeGen,
        shape: types.CallShape,
        site: semantic_algebra.CallSite,
        skip: ?semantic_algebra.CallTransform,
    ) void {
        const transforms = [_]semantic_algebra.CallTransform{
            .@"inline", .specialize, .memo, .devirtualize, .gpu_lower, .simd_lower,
        };
        const hash = shape.identityHash();
        for (transforms) |op| {
            if (skip) |applied| if (applied == op) continue;
            if (!semantic_algebra.callTransformEligible(op, site, shape)) continue;
            transform_engine.logProvenance(self.alloc, semantic_algebra.callTransformId(op), .emit_call, hash, hash);
        }
    }

    /// Emit a direct native C call to a module-level named function.
    fn emitDirectNamedFuncCall(self: *CodeGen, expr: *const ast.Expr) E!void {
        const c = expr.call;
        var ft = self.expr_type(c.func);
        var name_buf: [256]u8 = undefined;
        const callee_body: ?*const ast.FuncBody = if (c.func.* == .name) blk: {
            break :blk self.func_bodies.get(self.mangled_name(c.func.name.ident, &name_buf));
        } else null;
        if (callee_body) |body| {
            const fb_type = self.func_expr_type(body);
            if (fb_type == .func) ft = fb_type;
        }
        try self.emit_expr(c.func);
        self.p("(", .{});
        const callee_abi: ParamAbi = if (self.expr_names_foreign_func(c.func)) .foreign else .internal;
        var emitted_args: usize = 0;
        for (c.args, 0..) |arg, i| {
            if (i > 0) self.p(", ", .{});
            switch (ft) {
                .func => |f| {
                    if (i < f.params.len) {
                        try self.emit_arg_for_param_abi(arg, f.params[i], true, callee_abi);
                    } else {
                        try self.emit_expr(arg);
                    }
                },
                else => try self.emit_expr(arg),
            }
            emitted_args += 1;
        }
        if (ft == .func and callee_body != null) {
            const f = ft.func;
            const body = callee_body.?;
            var i = c.args.len;
            while (i < f.params.len and i < body.params.len) : (i += 1) {
                if (body.params[i].default_val == null) break;
                if (emitted_args > 0) self.p(", ", .{});
                if (try self.emit_default_for_param(&body.params[i], f.params[i])) {
                    emitted_args += 1;
                } else {
                    break;
                }
            }
            while (i < f.params.len) : (i += 1) {
                if (emitted_args > 0) self.p(", ", .{});
                self.emit_missing_arg_for_param(f.params[i]);
                emitted_args += 1;
            }
        }
        self.p(")", .{});
    }

    fn tryEmitDirectNamedCall(self: *CodeGen, expr: *const ast.Expr) E!bool {
        if (expr.* != .call) return false;
        const c = expr.call;
        if (c.func.* != .name) return false;
        if (self.vararg_funcs.get(c.func.name.ident) != null) return false;
        var name_buf: [256]u8 = undefined;
        const body = self.func_bodies.get(self.mangled_name(c.func.name.ident, &name_buf)) orelse return false;
        var ft = self.expr_type(c.func);
        const fb_type = self.func_expr_type(body);
        if (fb_type == .func) ft = fb_type;
        if (ft != .func) return false;
        if (!self.funcUsesNativeLowering(c.func.name.ident)) return false;
        if (!self.exprLowersToNativeC(ft.func.ret.*)) return false;
        try self.emitDirectNamedFuncCall(expr);
        return true;
    }

    fn tryEmitMemoCallTransform(
        self: *CodeGen,
        expr: *const ast.Expr,
        shape: types.CallShape,
        site: semantic_algebra.CallSite,
    ) E!bool {
        const value = comptime_eval.evalWithBindings(expr, self.comptime_bindings(), self.comptime_eval_options()) catch return false;
        if (value == .unavailable) return false;
        const hash = shape.identityHash();
        transform_engine.logProvenance(self.alloc, "call.memo", .emit_call, hash, hash);
        self.noteCallTransformProvenance(shape, site, .memo);
        try self.emit_comptime_value(value, self.expr_type(expr) == .any);
        return true;
    }

    /// dispatch eligible call transforms before generic call emission.
    fn tryEmitCallTransformDispatch(self: *CodeGen, expr: *const ast.Expr) E!bool {
        if (expr.* != .call) return false;
        const c = expr.call;
        const shape = types.inferCallShape(expr) orelse return false;
        const site = self.callSiteForShape(shape);
        if (c.func.* != .name) return false;
        const hash = shape.identityHash();

        if (semantic_algebra.callTransformEligible(.specialize, site, shape)) {
            if (self.mono) |m| {
                const env = self.current_mono_spec;
                if (m.findSpecializationForCall(c.func.name.ident, c.args, env)) |spec| {
                    transform_engine.logProvenance(self.alloc, "call.specialize", .emit_call, hash, hash);
                    self.noteCallTransformProvenance(shape, site, .specialize);
                    try self.emit_mono_call(spec, c.args);
                    return true;
                }
            }
        }

        if (semantic_algebra.callTransformEligible(.memo, site, shape)) {
            if (try self.tryEmitMemoCallTransform(expr, shape, site)) return true;
        }

        const direct_ops = [_]semantic_algebra.CallTransform{ .simd_lower, .gpu_lower, .@"inline" };
        for (direct_ops) |op| {
            if (!semantic_algebra.callTransformEligible(op, site, shape)) continue;
            if (!try self.tryEmitDirectNamedCall(expr)) continue;
            transform_engine.logProvenance(self.alloc, semantic_algebra.callTransformId(op), .emit_call, hash, hash);
            self.noteCallTransformProvenance(shape, site, op);
            return true;
        }
        return false;
    }

    fn try_emit_native_pipeline_projection(self: *CodeGen, lhs: *const ast.Expr, fb: *const ast.FuncBody) E!bool {
        if (fb.params.len != 1 or !std.mem.eql(u8, fb.params[0].name, "__proj_v")) return false;
        if (fb.body.stmts.len != 1 or fb.body.stmts[0] != .ret) return false;
        const vals = fb.body.stmts[0].ret.vals;
        if (vals.len != 1) return false;
        const ret = vals[0];

        transform_engine.logProvenance(
            self.alloc,
            "pipeline.map",
            .emit_call,
            std.hash.Wyhash.hash(0, "projection"),
            std.hash.Wyhash.hash(0, "native"),
        );

        if (ret.* == .field) {
            const f = ret.field;
            if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "__proj_v")) return false;
            var patched = ast.Expr{ .field = .{ .loc = f.loc, .obj = @constCast(lhs), .field = f.field } };
            try self.emit_expr(&patched);
            return true;
        }
        if (ret.* == .method_call) {
            const mc = ret.method_call;
            if (mc.obj.* != .name or !std.mem.eql(u8, mc.obj.name.ident, "__proj_v")) return false;
            var patched = ast.Expr{
                .method_call = .{
                    .loc = mc.loc,
                    .obj = @constCast(lhs),
                    .method = mc.method,
                    .args = mc.args,
                },
            };
            try self.emit_expr(&patched);
            return true;
        }
        return false;
    }

    fn pipeline_projection_field_name(fb: *const ast.FuncBody) ?[]const u8 {
        if (fb.params.len != 1 or !std.mem.eql(u8, fb.params[0].name, "__proj_v")) return null;
        if (fb.body.stmts.len != 1 or fb.body.stmts[0] != .ret) return null;
        const vals = fb.body.stmts[0].ret.vals;
        if (vals.len != 1) return null;
        const ret = vals[0];
        if (ret.* != .field) return null;
        const f = ret.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "__proj_v")) return null;
        return f.field;
    }

    fn try_emit_native_pipeline_named(self: *CodeGen, lhs: *const ast.Expr, rhs: *const ast.Expr) E!bool {
        if (rhs.* != .name) return false;
        var name_buf: [256]u8 = undefined;
        const body = self.func_bodies.get(self.mangled_name(rhs.name.ident, &name_buf)) orelse return false;
        const ft = self.func_expr_type(body);
        if (ft != .func or ft.func.params.len == 0) return false;
        if (!self.exprLowersToNativeC(ft.func.params[0])) return false;
        const lhs_rt = self.expr_type(lhs);
        if (!self.exprLowersToNativeC(lhs_rt)) return false;
        if (self.mixed_scalar_mode and !self.funcUsesNativeLowering(rhs.name.ident)) return false;
        transform_engine.logProvenance(
            self.alloc,
            "pipeline.map",
            .emit_call,
            std.hash.Wyhash.hash(0, rhs.name.ident),
            std.hash.Wyhash.hash(0, "native"),
        );
        try self.emit_expr(rhs);
        self.p("(", .{});
        try self.emit_arg_for_param(lhs, ft.func.params[0], true);
        self.p(")", .{});
        return true;
    }

    fn try_emit_native_pipeline(self: *CodeGen, lhs: *const ast.Expr, rhs: *const ast.Expr) E!bool {
        var steps: std.ArrayList(*const ast.Expr) = .empty;
        defer steps.deinit(self.alloc);
        var base = lhs;
        while (base.* == .binop and base.binop.op == .pipeline) {
            try steps.append(self.alloc, base.binop.rhs);
            base = base.binop.lhs;
        }
        try steps.append(self.alloc, rhs);

        if (steps.items.len > 1) {
            std.mem.reverse(*const ast.Expr, steps.items);
            var fields: std.ArrayList([]const u8) = .empty;
            defer fields.deinit(self.alloc);
            for (steps.items) |step| {
                if (step.* != .func_expr) break;
                const fname = pipeline_projection_field_name(step.func_expr) orelse break;
                try fields.append(self.alloc, fname);
            }
            if (fields.items.len == steps.items.len) {
                const base_rt = self.expr_type(base);
                if (self.exprLowersToNativeC(base_rt) or base_rt == .table_type) {
                    transform_engine.logProvenance(
                        self.alloc,
                        "pipeline.fuse",
                        .emit_call,
                        std.hash.Wyhash.hash(0, "projection_chain"),
                        std.hash.Wyhash.hash(0, "native"),
                    );
                    try self.emit_expr(base);
                    for (fields.items) |f| self.p(".{s}", .{f});
                    return true;
                }
            }
        }

        if (rhs.* == .func_expr) {
            return try self.try_emit_native_pipeline_projection(lhs, rhs.func_expr);
        }
        return try self.try_emit_native_pipeline_named(lhs, rhs);
    }

    /// WHAT THE MODULE'S OWN SCOPE HOLDS, from the one scanner that already
    /// answers that question for function bodies.
    ///
    /// MEASURED, and this is the whole reason the module context needs it:
    /// `can_emit_native_scalar_module` checks `mod.body.tail_expr` and the
    /// module's top-level statements with `precheck_types` EMPTY. The map was
    /// only ever filled inside the `.func_decl` arm, and cleared on the way out
    /// of it, so a program with no functions at all had no answer for any name.
    /// `x = 10  print(x)` — a whole program — was refused `print-arg:any`,
    /// which is verbatim the sentence the `precheck_types` doc comment already
    /// writes about function locals. Same hole, the other scope.
    ///
    /// NOT `module_globals`. That map is the checked sema's answer for a
    /// different question — bindings that are GLOBAL — and under
    /// local-by-default a module-top `x = 10` in a `.id` file is not one, so it
    /// is absent from it by construction (`sema.zig` `note_global`). Reading it
    /// harder would not have found `x`; nothing had computed `x`'s type at all.
    fn precheck_collect_module_types(self: *CodeGen, mod: *const ast.Module) void {
        self.precheck_types.clearRetainingCapacity();
        self.precheck_scan_block(&mod.body);
    }

    /// What the PRECHECK can prove about one function's local bindings.
    ///
    /// Deliberately not a type inferencer. It proves exactly two facts —
    /// "this name always holds an integer" and "this name always holds text" —
    /// because those are the two the direct backend's `print` lowering
    /// (`dnir_lower.lowerPrint`) can already render, and it renders anything
    /// else it does not recognize as `%lld`. A third answer here would be a
    /// wrong NUMBER, not a bail: `print(ok)` on a bool must read `true`, and
    /// the same register printed as an integer reads `1`. So bool, f64,
    /// records, tables and everything unproven stay `.any` and stay refused.
    ///
    /// Order-INSENSITIVE on purpose. Every assignment to a name anywhere in the
    /// body must agree, so a name rebound to a different kind later in the
    /// function is unproven at EVERY use, including the ones textually before
    /// the rebinding. A per-point analysis would be sharper and would have to be
    /// right about control flow; this one only has to be right about a set.
    fn precheck_collect_types(self: *CodeGen, f: *const ast.FuncBody) void {
        // The enclosing module's bindings first: a function body reads them,
        // and before this they answered `.any` inside a function for exactly
        // the same reason they did at module top — nobody had collected them.
        if (self.current_module) |mod| {
            self.precheck_collect_module_types(mod);
        } else {
            self.precheck_types.clearRetainingCapacity();
        }
        // A PARAMETER SHADOWS THE MODULE BINDING OF THE SAME NAME, so it
        // OVERWRITES. `precheck_note_type` widens two disagreeing answers to
        // `.any` — right for two bindings in one scope, wrong across a shadow,
        // where the inner binding simply IS the answer.
        for (f.params) |param| {
            const rt = types.resolve(param.typ, null, self.alloc) catch continue;
            self.precheck_set_type(param.name, rt);
        }
        self.precheck_scan_block(&f.body);
    }

    /// A binding that SHADOWS whatever the enclosing scope said. Never widens.
    fn precheck_set_type(self: *CodeGen, name: []const u8, rt: RT) void {
        self.precheck_types.put(self.alloc, name, rt) catch return;
    }

    fn precheck_note_type(self: *CodeGen, name: []const u8, rt: RT) void {
        const gop = self.precheck_types.getOrPut(self.alloc, name) catch return;
        if (!gop.found_existing) {
            gop.value_ptr.* = rt;
            return;
        }
        // Two bindings, two answers: the name proves nothing.
        if (!std.meta.eql(gop.value_ptr.*, rt)) gop.value_ptr.* = .any;
    }

    fn precheck_scan_block(self: *CodeGen, block: *const ast.Block) void {
        for (block.stmts) |*stmt| self.precheck_scan_stmt(stmt);
    }

    fn precheck_scan_stmt(self: *CodeGen, stmt: *const ast.Stmt) void {
        switch (stmt.*) {
            .local_decl => |ld| {
                if (ld.names.len != ld.inits.len) {
                    for (ld.names) |n| self.precheck_note_type(n.ident, .any);
                    return;
                }
                for (ld.names, ld.inits) |n, init_expr| {
                    if (n.typ != .inferred) {
                        self.precheck_note_type(n.ident, types.resolve(n.typ, null, self.alloc) catch .any);
                    } else {
                        self.precheck_note_type(n.ident, self.precheck_value_type(init_expr));
                    }
                }
            },
            .global_decl => |gd| {
                if (gd.names.len != gd.inits.len) {
                    for (gd.names) |n| self.precheck_note_type(n.ident, .any);
                    return;
                }
                for (gd.names, gd.inits) |n, init_expr| {
                    if (n.typ != .inferred) {
                        self.precheck_note_type(n.ident, types.resolve(n.typ, null, self.alloc) catch .any);
                    } else {
                        self.precheck_note_type(n.ident, self.precheck_value_type(init_expr));
                    }
                }
            },
            .assign => |as| {
                if (as.targets.len != as.values.len) {
                    for (as.targets) |t| {
                        if (t.* == .name) self.precheck_note_type(t.name.ident, .any);
                    }
                    return;
                }
                for (as.targets, as.values) |t, v| {
                    if (t.* != .name) continue;
                    self.precheck_note_type(t.name.ident, self.precheck_value_type(v));
                }
            },
            .const_decl => |cd| self.precheck_note_type(cd.ident, self.precheck_value_type(cd.val)),
            .do_block => |db| self.precheck_scan_block(&db.body),
            .while_loop => |ws| self.precheck_scan_block(&ws.body),
            .repeat_loop => |rs| self.precheck_scan_block(&rs.body),
            .if_stmt => |is| {
                if (is.binding) |b| self.precheck_note_type(b.name, .any);
                self.precheck_scan_block(&is.then);
                for (is.elseifs) |ei| self.precheck_scan_block(&ei.body);
                if (is.else_body) |eb| self.precheck_scan_block(&eb);
            },
            .num_for => |nf| {
                const rt: RT = if (nf.var_typ != .inferred)
                    types.resolve(nf.var_typ, null, self.alloc) catch .any
                else
                    self.precheck_value_type(nf.start);
                self.precheck_note_type(nf.var_name, rt);
                self.precheck_scan_block(&nf.body);
            },
            .gen_for => |gf| {
                for (gf.vars) |v| self.precheck_note_type(v, .any);
                self.precheck_scan_block(&gf.body);
            },
            else => {},
        }
    }

    /// gap[094], the paired requirement. TRUE when a `str` PLACE is being fed a
    /// value this predicate can prove is a number.
    ///
    /// `"{i}"` with no surrounding literal text desugars to the bare hole — the
    /// concat fold that would have converted it never runs on a one-part list —
    /// so `a: str = "{i}"` puts an i64 into a `const char*` place. C's type
    /// system catches it and refuses the program. The native-scalar precheck had
    /// no such check, admitted the module, and emitted a LOAD THROUGH 7: the
    /// direct backend reported `ok compile` and the binary took SIGSEGV, while
    /// the C backend correctly refused the identical source.
    ///
    /// A backend accepting what the oracle rejects is the §3 failure mode, and a
    /// segfault is the worst way to express it. Refusing here turns it into a
    /// DNB, which routes the program to C and gets the honest diagnostic. This
    /// does NOT repair the desugar — that lives in the parser and is still owed;
    /// it stops the native path from making the parser's defect lethal.
    ///
    /// Only PROVEN numbers refuse. `.any` is unproven and stays admitted, so a
    /// value the predicate cannot type is not punished for it.
    fn native_str_place_violated(self: *CodeGen, hint: RT, value: *const ast.Expr) bool {
        if (hint != .str) return false;
        const vt = self.precheck_value_type(value);
        return vt.is_numeric() or vt == .bool;
    }

    /// The two facts, and nothing else. `.any` means "unproven", never "dynamic".
    fn precheck_value_type(self: *CodeGen, e: *const ast.Expr) RT {
        // Sema first, when sema was sure. It knows shapes this predicate
        // deliberately does not reconstruct — `to(i64)("…")` is a call whose
        // CALLEE is a call, and the relation surface already declares its own
        // result type. Restricted to the two kinds below for the same reason
        // everything else here is: a third answer is a wrong number.
        if (e.* != .name) {
            const t = self.expr_type(e);
            if (t == .i64 or t == .str) return t;
        }
        return switch (e.*) {
            .int_lit => .i64,
            .quoted => |lit| types.quotedLiteralType(lit.quote),
            // A name already proven in THIS body. One pass, no fixpoint: a name
            // read before it is written answers `.any`, and `.any` is the
            // refusing answer, so the order can only cost coverage.
            .name => |n| self.precheck_types.get(n.ident) orelse .any,
            .unop => |u| switch (u.op) {
                // `#x` is a count and `-n` keeps its operand's kind.
                .len => .i64,
                .neg => self.precheck_value_type(u.operand),
                else => .any,
            },
            .binop => |b| switch (b.op) {
                // A comparison is a BOOL, and a bool rendered as an integer is
                // the wrong answer this whole predicate exists to avoid.
                .eq, .neq, .lt, .gt, .leq, .geq, .@"and", .@"or" => .any,
                .concat => .any,
                else => blk: {
                    const lt = self.precheck_value_type(b.lhs);
                    if (lt != .i64) break :blk .any;
                    break :blk if (self.precheck_value_type(b.rhs) == .i64) .i64 else .any;
                },
            },
            // A call answers what its callee DECLARED, and only when that
            // declaration is one of the two proven kinds. An inferred or
            // fallible return proves nothing.
            .call => |c| blk: {
                if (c.func.* != .name) break :blk .any;
                // APPLY-ONE (gap[092]): a DESCRIPTOR subject constructs, so
                // there is no callee to read a return type off — the answer is
                // the descriptor itself. Without this the precheck said `.any`
                // and refused the whole module: `q = point{ … }` and
                // `q: point = { … }` are one value by two spellings and they
                // landed on OPPOSITE sides of the native gate. Measured
                // 2026-08-09, the applied face emitted 6053 lines of boxed
                // runtime where the typed binding emitted 128, while the
                // construction site itself was already a compound literal in
                // both — it was this predicate, not the emitter, that made the
                // difference. Answered as `.@"struct"` rather than the record's
                // `.table_type` because that is literally what `types.resolve`
                // hands the typed binding, and the two spellings have to be
                // indistinguishable from here on.
                if (self.descriptor_application_type(c) != null) {
                    break :blk RT{ .@"struct" = .{ .name = c.func.name.ident } };
                }
                var buf: [256]u8 = undefined;
                const fd = self.func_decls.get(c.func.name.ident) orelse
                    self.func_decls.get(self.mangled_name(c.func.name.ident, &buf)) orelse
                    break :blk .any;
                if (fd.func.ret_fallible) break :blk .any;
                const rt = self.resolve_type(contract_ret(&fd.func));
                break :blk if (rt == .i64 or rt == .str) rt else .any;
            },
            else => .any,
        };
    }

    /// The precheck's own answer for a bare name, used only where `expr_type`
    /// gave up. Never widens a type sema was sure about.
    fn precheck_name_type(self: *CodeGen, e: *const ast.Expr) RT {
        // A FIELD read off a name the precheck has proven. gap[092]: this is
        // the second half of teaching the precheck about descriptor
        // application, and without it the first half buys nothing — the
        // refusal is raised on `q.x`, not on `q`, so knowing `q` is a `point`
        // while still answering `.any` for `q.x` refuses exactly as before.
        //
        // Deliberately one level and names only. This predicate's whole
        // discipline is that a third answer is a wrong number, and the record's
        // own field list is the one place a field's type is already stated —
        // nothing is reconstructed here.
        if (e.* == .field and e.field.obj.* == .name) {
            const obj = self.precheck_types.get(e.field.obj.name.ident) orelse return .any;
            var rec = obj;
            if (rec == .@"struct") {
                rec = self.record_aliases.get(rec.@"struct".name) orelse return .any;
            }
            if (rec != .table_type) return .any;
            for (rec.table_type.fields) |f| {
                if (std.mem.eql(u8, f.name, e.field.field)) return f.typ;
            }
            return .any;
        }
        if (e.* != .name) return .any;
        return self.precheck_types.get(e.name.ident) orelse .any;
    }

    fn call_stmt_is_native_scalar(self: *CodeGen, expr: *const ast.Expr) bool {
        if (expr.* != .call) return self.expr_is_native_scalar(expr);
        const call = expr.call;
        if (call.func.* == .name and std.mem.eql(u8, call.func.name.ident, "print")) {
            for (call.args) |arg| {
                var rt = self.expr_type(arg);
                // `expr_type` reads `local_scopes`, which the precheck never
                // fills — it runs before any emit. So a function-local answered
                // `.any` and `n = 1  print("{n}")` was refused. Only consulted
                // where sema had nothing, and only for the two kinds
                // `dnir_lower.lowerPrint` renders (gap[034]: the precheck and
                // the lowering must claim the same set).
                if (rt == .any) rt = self.precheck_name_type(arg);
                if (self.enum_name_of(rt)) |ename| {
                    if (self.enum_is_payload_free(ename) and self.expr_is_native_scalar(arg)) continue;
                    return false;
                }
                if (!(rt.is_numeric() or rt == .bool or rt == .str)) {
                    // Was a bare `return false`, so the reason never reached the
                    // recorder and every one of these surfaced as the outer
                    // "func-body" — a tag that names the whole body and points
                    // at nothing.
                    self.nativeDiagFailFmt("print-arg:{s}", .{@tagName(rt)});
                    return false;
                }
                if (!self.expr_is_native_scalar(arg)) return false;
            }
            return true;
        }
        return self.expr_is_native_scalar(expr);
    }

    const FixedArrayIndex = struct {
        obj: *const ast.Expr,
        key: *const ast.Expr,
    };

    /// Fixed-array computed projection uses `[]` only. `()` remains application.
    fn fixed_array_index(self: *CodeGen, e: *const ast.Expr) ?FixedArrayIndex {
        const pair: FixedArrayIndex = switch (e.*) {
            .index => |idx| .{ .obj = idx.obj, .key = idx.key },
            else => return null,
        };
        const container = self.expr_type(pair.obj);
        if (container != .array) return null;
        if (container.array.size == null) return null;
        const elem = self.indexed_element_type(container) orelse return null;
        if (!elem.is_numeric() and elem != .bool) return null;
        if (!self.expr_is_native_scalar(pair.key)) return null;
        return pair;
    }

    fn native_index_access(self: *CodeGen, expr: *const ast.Expr, require_lvalue_obj: bool) bool {
        const pair: struct { obj: *const ast.Expr, key: *const ast.Expr } = switch (expr.*) {
            .index => |idx| .{ .obj = idx.obj, .key = idx.key },
            else => return false,
        };
        if (self.fixed_array_index(expr)) |_| return true;
        if (pair.obj.* != .name) return false;
        if (require_lvalue_obj and !self.precheck_name_is_bound(pair.obj.name.ident)) return false;
        if (!require_lvalue_obj and !self.expr_is_native_scalar(pair.obj)) return false;
        return self.expr_is_native_scalar(pair.key);
    }

    fn lvalue_is_native_scalar(self: *CodeGen, expr: *const ast.Expr) bool {
        if (self.native_index_access(expr, true)) return true;
        return switch (expr.*) {
            .name => true,
            .index => |idx| self.expr_is_native_scalar(idx.obj) and self.expr_is_native_scalar(idx.key),
            .field => |field| self.expr_is_native_scalar(field.obj),
            else => false,
        };
    }

    fn expr_is_native_scalar(self: *CodeGen, expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .true_lit, .false_lit, .int_lit, .float_lit => true,
            .quoted => true,
            .nil => true,
            // A name the program BOUND is an ordinary local — asked first, so
            // neither world test below can take it away from the author.
            .name => |name| if (self.precheck_name_is_bound(name.ident))
                true
            else if (is_world_symbol(name.ident))
                true
            else if (is_runtime_global(name.ident)) blk: {
                self.nativeDiagFailFmt("runtime-global:{s}", .{name.ident});
                break :blk false;
            } else true,
            .binop => |bin| self.expr_is_native_scalar(bin.lhs) and self.expr_is_native_scalar(bin.rhs),
            // §6 — `k = if n > 3 10 else 20`, the expression-if that IS the
            // ternary. Paired with `dnir_lower.lowerIfExpr`, which lowers it to
            // the same single-slot branch shape `and`/`or` already used; before
            // that arm existed this had to refuse, and the refusal outlived it
            // (gap[034], the precheck/lowering drift).
            .if_expr => |ie| self.expr_is_native_scalar(ie.cond) and
                self.expr_is_native_scalar(ie.then_expr) and
                self.expr_is_native_scalar(ie.else_expr),
            .unop => |un| blk: {
                // `kind = { eof = 0, ident = 1 }` — a literal enum descriptor.
                // (The canonical spelling of a keywordless enum is the case-set
                // copula `kind: { eof, ident }`, which lifts a real
                // `enum_shape`; this bind form stays readable because the
                // corpus still holds constant tables written that way.)
                // dnir_lower.collectModuleConsts already folds this
                // exact shape into module constants (its doc names it), but the
                // gate in front rejected every `.compile` unop outright, so the
                // canonical spelling disqualified its module. Same drift as
                // string.byte: the lowering had grown past the precheck.
                //
                // Narrow on purpose — only a table of named integer literals,
                // which is what the folder consumes. Any other compile-time
                // construct still needs the boxed path.
                if (un.op == .compile) {
                    if (un.operand.* != .table) {
                        // THE COMPILE-STAGE WORLD ANSWERS FIRST, and the rule
                        // lives once. `@(1 + 2)` is a value that world holds,
                        // so the program contains the value and there is
                        // nothing left to realize — but this precheck rejected
                        // every non-table `.compile` outright while
                        // `dnir_lower` was already able to fold it, so the
                        // whole scalar face of `@( … )` refused on the default
                        // backend. Same precheck/lowering drift as string.byte
                        // and the expression-if; `compileStageValue` is the one
                        // rule both sides now call.
                        if (@import("graph/lower.zig").compileStageValue(un.operand) != null) break :blk true;
                        self.nativeDiagFail("compile-stage-absent");
                        break :blk false;
                    }
                    for (un.operand.table.fields) |fld| {
                        const nf = switch (fld) {
                            .named => |x| x,
                            else => {
                                self.nativeDiagFail("descriptor-field-unnamed");
                                break :blk false;
                            },
                        };
                        if (nf.val.* != .int_lit) {
                            self.nativeDiagFail("descriptor-field-nonint");
                            break :blk false;
                        }
                    }
                    break :blk true;
                }
                break :blk self.expr_is_native_scalar(un.operand);
            },
            .field => |field| blk: {
                if (self.expr_is_req_module_const_field(expr)) break :blk true;
                break :blk self.expr_is_native_scalar(field.obj);
            },
            .index => |idx| self.expr_is_native_scalar(idx.obj) and self.expr_is_native_scalar(idx.key),
            .table => |t| blk: {
                // A table literal is native scalar only when it is a typed record
                // (anonymous struct) — emitted as a C struct compound literal via
                // emit_record_initializer at binding/call/return sites. Untyped
                // dynamic tables require the lua_Value runtime.
                const rt = self.expr_type(expr);
                if (rt == .table_type and self.type_lowers_native(rt)) {
                    for (t.fields) |fld| switch (fld) {
                        .named => |nmd| if (!self.expr_is_native_scalar(nmd.val)) break :blk false,
                        .positional => |pos| if (!self.expr_is_native_scalar(pos)) break :blk false,
                        .indexed => |idx| if (!self.expr_is_native_scalar(idx.key) or
                            !self.expr_is_native_scalar(idx.val)) break :blk false,
                        .spread => break :blk false,
                        .semantic => break :blk false,
                    };
                    break :blk true;
                }
                if (rt == .any or rt == .@"struct") {
                    for (t.fields) |fld| switch (fld) {
                        .named => |nmd| if (!self.expr_is_native_scalar(nmd.val)) break :blk false,
                        .positional => |pos| if (!self.expr_is_native_scalar(pos)) break :blk false,
                        .indexed => |idx| if (!self.expr_is_native_scalar(idx.key) or
                            !self.expr_is_native_scalar(idx.val)) break :blk false,
                        .spread => break :blk false,
                        // G1/G8 recorded, not implemented (Phase 0): a semantic entry is never a native scalar.
                        .semantic => break :blk false,
                    };
                    break :blk true;
                }
                self.nativeDiagFail("dynamic-table");
                break :blk false;
            },
            .call => |call| blk: {
                if (self.native_index_access(expr, false)) break :blk true;
                if (self.req_call_expr_is_native_direct(expr)) break :blk true;
                if (call.func.* == .field) {
                    const f = call.func.field;
                    // The precheck is a conservative approximation of what the
                    // backend can lower, and it had drifted: dnir_lower gained a
                    // `string.byte(s, i)` arm (an indexed load, no runtime call,
                    // added so a tokenizer's inner loop stays native) and this
                    // gate in front of it still admitted only `string.len`. So
                    // every module using the byte read was disqualified before
                    // reaching the lowering that supports it — 12 programs in
                    // examples/ alone. Both spellings are listed together here
                    // so the pair cannot drift apart again.
                    // Paired with the dnir_lower arm: `os.exit(n)` lowers to
                    // libc `exit`, so the gate must stop calling it a runtime
                    // global. Kept adjacent to the string rows so the whole set
                    // of "runtime-global name, native lowering" pairs is in one
                    // place and drifts together or not at all (gap[034]).
                    // Paired with the dnir_lower arm: the three mem primitives
                    // that are plain libc rather than typed-pointer surface.
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "math") and
                        call.args.len == 1)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]);
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "mem")) {
                        const nargs = call.args.len;
                        // `ptr_from_addr(T, a)` is listed apart because its
                        // FIRST operand is a DESCRIPTOR, not a value. Running
                        // `expr_is_native_scalar` over it asks a type name for
                        // its register and is answered no, which would
                        // disqualify the module in front of a lowering that
                        // never touches that operand.
                        if (std.mem.eql(u8, f.field, "ptr_from_addr") and nargs == 2) {
                            break :blk self.expr_is_native_scalar(call.args[1]);
                        }
                        const ok_mem = (std.mem.eql(u8, f.field, "alloc") and nargs == 1) or
                            (std.mem.eql(u8, f.field, "free") and nargs == 1) or
                            (std.mem.eql(u8, f.field, "read_byte") and nargs == 2) or
                            (std.mem.eql(u8, f.field, "read_i64") and nargs == 2) or
                            (std.mem.eql(u8, f.field, "write_byte") and nargs == 3) or
                            (std.mem.eql(u8, f.field, "write_i64") and nargs == 3) or
                            (std.mem.eql(u8, f.field, "zero") and nargs == 2) or
                            (std.mem.eql(u8, f.field, "addr") and nargs == 1) or
                            (std.mem.eql(u8, f.field, "load") and nargs == 2) or
                            (std.mem.eql(u8, f.field, "store") and nargs == 3);
                        if (ok_mem) {
                            for (call.args) |a| {
                                if (!self.expr_is_native_scalar(a)) break :blk false;
                            }
                            break :blk true;
                        }
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "os") and
                        std.mem.eql(u8, f.field, "exit") and call.args.len == 1)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]);
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "os") and
                        std.mem.eql(u8, f.field, "execute") and call.args.len == 1)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]);
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "os") and
                        std.mem.eql(u8, f.field, "remove") and call.args.len == 1)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]);
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "io") and
                        std.mem.eql(u8, f.field, "open") and call.args.len == 2)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]) and
                            self.expr_is_native_scalar(call.args[1]);
                    }
                    // io.popen(cmd, mode): same FILE* stream shape as io.open,
                    // native-eligible when the operands are scalar (lib/proc.id
                    // capture). The binder types it via io_call_result_type.
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "io") and
                        std.mem.eql(u8, f.field, "popen") and call.args.len == 2)
                    {
                        break :blk self.expr_is_native_scalar(call.args[0]) and
                            self.expr_is_native_scalar(call.args[1]);
                    }
                    if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "string")) {
                        if (std.mem.eql(u8, f.field, "len") and call.args.len == 1) {
                            break :blk self.expr_is_native_scalar(call.args[0]);
                        }
                        if (std.mem.eql(u8, f.field, "char") and call.args.len == 1) {
                            break :blk self.expr_is_native_scalar(call.args[0]);
                        }
                        if (std.mem.eql(u8, f.field, "byte") and call.args.len == 2) {
                            break :blk self.expr_is_native_scalar(call.args[0]) and
                                self.expr_is_native_scalar(call.args[1]);
                        }
                    }
                    if (f.obj.* == .name) {
                        if (self.req_module_bindings.get(f.obj.name.ident)) |mod_cname| {
                            if (self.lookup_req_module_func_type(mod_cname, f.field)) |ft| {
                                if (self.funcTypeLowersNative(ft)) break :blk true;
                            }
                        }
                    }
                }
                if (call.func.* == .name) {
                    // @c.emit / __emit / __asm: raw C injection — always native scalar.
                    if (std.mem.eql(u8, call.func.name.ident, "__emit") or
                        std.mem.eql(u8, call.func.name.ident, "__asm")) break :blk true;
                    // Same order as the `.name` arm: a bound name is the
                    // author's, and applying it is an ordinary application.
                    if (!self.precheck_name_is_bound(call.func.name.ident) and
                        is_runtime_global(call.func.name.ident))
                    {
                        self.nativeDiagFailFmt("runtime-global-call:{s}", .{call.func.name.ident});
                        break :blk false;
                    }
                }
                if (!self.expr_is_native_scalar(call.func)) break :blk false;
                const param_hints = self.call_param_types(call.func);
                for (call.args, 0..) |arg, i| {
                    const hint: RT = if (param_hints) |hints| (if (i < hints.len) hints[i] else .any) else .any;
                    if (!self.init_is_native_scalar(arg, hint)) break :blk false;
                }
                const rt = self.expr_type(expr);
                break :blk rt.is_numeric() or rt == .bool or rt == .str or rt == .void or rt == .any or
                    self.type_lowers_native(rt);
            },
            // gap[025] / FACE-CALL: the canonical `subject:member(args)`.
            //
            // The precheck had no `.method_call` arm at all, so every receiver
            // face fell into `else` and disqualified its whole module. The
            // spelling rule 6 mandates everywhere was the one shape the native
            // path could not see: `s:byte(1)` reported expr-unhandled:method_call
            // while the vestige `string.byte(s, 1)` reported runtime-global:string
            // — writing canonical Duo bought no native coverage over the form the
            // deny list forbids.
            //
            // Admit exactly the three shapes `expr_type` (above) can already
            // resolve, so the precheck never promises the emitter more than it
            // can lower: a string primitive, a receiver face over a free
            // function, and the `to(T)` conversion edge.
            .method_call => |mc| blk: {
                // COLLECTION-RELATION-ONE, asked FIRST because the generic arm
                // below would walk the body relation as an ordinary operand and
                // refuse it `expr-unhandled:func_expr` — the relation-as-value
                // wall, hit by a face that never becomes a value. What the
                // precheck must approve is the SUBJECT and the FUSED BODY, and
                // the result descriptor is the question's, not the body's.
                if (collection_relation.shapeOf(expr)) |shape| {
                    if (!self.expr_is_native_scalar(shape.subject)) break :blk false;
                    if (!self.expr_is_native_scalar(shape.body)) break :blk false;
                    break :blk true;
                }
                if (!self.expr_is_native_scalar(mc.obj)) break :blk false;
                for (mc.args) |arg| {
                    if (!self.expr_is_native_scalar(arg)) break :blk false;
                }
                const resolvable = self.string_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.readable_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.file_stream_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.egress_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.stream_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.world_method_result_type(mc.method, mc.obj, mc.args) != null or
                    self.func_decls.get(mc.method) != null or
                    self.relationEdgeFuncDecl(mc.method, mc.args.len) != null or
                    fd: {
                        var tbuf: [256]u8 = undefined;
                        break :fd self.func_decls.get(self.mangled_name(mc.method, &tbuf)) != null;
                    } or self.subjectRelation(mc.method, mc.obj) != null or
                    self.probeSubjectRelationType(mc.method, mc.obj, mc.args.len) != null or
                    // law.host.projection { projects = to, authority = false }
                    // gap[082] is the deletion gate.
                    (std.mem.eql(u8, mc.method, "to") and mc.args.len == 1) or
                    // The test world's relations lower to a trap, not a call,
                    // so there is no declaration for this precheck to find.
                    (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "test")) or
                    // The environment projection's removal edge lowers to
                    // `unsetenv`, not to a call into a declared relation, so
                    // there is no declaration for this precheck to find —
                    // exactly the test world's case above.
                    self.env_remove_method(mc.method, mc.obj, mc.args);
                if (!resolvable) {
                    self.nativeDiagFailFmt("method-unresolved:{s}", .{mc.method});
                    break :blk false;
                }
                if (self.relationEdgeFuncDecl(mc.method, mc.args.len) != null) break :blk true;
                const rt = self.expr_type(expr);
                if (rt.is_numeric() or rt == .bool or rt == .str or rt == .void or rt == .any or
                    self.type_lowers_native(rt)) break :blk true;
                self.nativeDiagFailFmt("method-ret:{s}", .{mc.method});
                break :blk false;
            },
            else => {
                self.nativeDiagFailFmt("expr-unhandled:{s}", .{@tagName(expr.*)});
                return false;
            },
        };
    }

    /// Like `expr_is_native_scalar` but admits a table literal when the
    /// surrounding context expects a typed record (`table_type`). This lets
    /// `local p: Point = {x=1, y=2}` and `f({x=1})` (with `f(p: Point)`)
    /// stay native without falling back to the lua_Value runtime.
    fn call_param_types(self: *CodeGen, func: *const ast.Expr) ?[]const RT {
        if (func.* != .name) return null;
        var name_buf: [256]u8 = undefined;
        const body = self.func_bodies.get(self.mangled_name(func.name.ident, &name_buf)) orelse return null;
        const fb_type = self.func_expr_type(body);
        if (fb_type != .func) return null;
        return fb_type.func.params;
    }

    fn init_is_native_scalar(self: *CodeGen, expr: *const ast.Expr, hint: RT) bool {
        if (expr.* == .nil and hint == .any) return false;
        if (req_path_from_expr(expr)) |path| {
            if (self.req_module_skips_lua_binding(path)) return true;
        }
        if (expr.* == .table and hint == .table_type) {
            const t = expr.table;
            var found: std.StringHashMapUnmanaged(*const ast.Expr) = .empty;
            defer found.deinit(self.alloc);
            var positionals: std.ArrayList(*const ast.Expr) = .empty;
            defer positionals.deinit(self.alloc);
            for (t.fields) |fld| switch (fld) {
                .named => |nmd| found.put(self.alloc, nmd.key, nmd.val) catch {},
                .positional => |pf| positionals.append(self.alloc, pf) catch {},
                .indexed => |idx| {
                    if (!self.expr_is_native_scalar(idx.key)) return false;
                    if (!self.init_is_native_scalar(idx.val, .any)) return false;
                },
                .spread => return false,
                .semantic => return false,
            };
            for (hint.table_type.fields, 0..) |rf, i| {
                const v = if (found.get(rf.name)) |val| val else if (i < positionals.items.len) positionals.items[i] else continue;
                if (!self.init_is_native_scalar(v, rf.typ)) return false;
            }
            return true;
        }
        return self.expr_is_native_scalar(expr);
    }

    fn type_expr_is_native_scalar(self: *CodeGen, type_expr: ast.TypeExpr) bool {
        const rt = self.resolve_type(type_expr);
        // .any requires lua_Value boxing — NOT native scalar.
        // .func as a value type also requires boxing (closure/function pointer).
        // A `.dynamic` table is a BOXED lua table. Answering "native scalar"
        // for it put a value on the opposite side of the native gate from what
        // `types.ResolvedType.is_native` and `semantic_algebra.lowersToNativeC`
        // both say — the gap[092] shape, where two spellings of one value land
        // on opposite sides. Storage class is the discriminator all three
        // owners already agree on; see gaps/GAP-108.md §2.1 for the probe.
        return rt.is_numeric() or rt == .bool or rt == .str or rt == .void or
            rt == .array or rt == .@"struct" or rt == .enum_type or
            (rt == .table_type and rt.table_type.storage_class != .dynamic) or rt == .pointer;
    }

    fn type_expr_is_native_result_pack(self: *CodeGen, type_expr: ast.TypeExpr) bool {
        if (type_expr != .tuple or type_expr.tuple.len == 0 or type_expr.tuple.len > 8) return false;
        for (type_expr.tuple) |item| {
            const rt = self.resolve_type(item);
            switch (rt) {
                .i8,
                .i16,
                .i32,
                .i64,
                .u8,
                .u16,
                .u32,
                .u64,
                .bool,
                .str,
                .pointer,
                => {},
                else => return false,
            }
        }
        return true;
    }

    fn module_has_cinclude(self: *CodeGen, mod: *const ast.Module) bool {
        _ = self;
        for (mod.body.stmts) |stmt| {
            if (stmt == .cinclude) return true;
        }
        return false;
    }

    fn module_has_concept_def(self: *CodeGen, mod: *const ast.Module) bool {
        _ = self;
        for (mod.body.stmts) |stmt| {
            if (stmt == .concept_def) return true;
        }
        return false;
    }

    const NativeHelper = enum { split, fstream };

    /// Physical prelude demand. These helpers used to be emitted into every C
    /// translation unit, so a self-contained lexer acquired split-list storage,
    /// an 8 KiB line reader and popen declarations it could never reach. Scan
    /// the resolved AST before the prelude and materialize only a helper family
    /// the module can actually select.
    fn module_needs_native_helper(self: *CodeGen, mod: *const ast.Module, helper: NativeHelper) bool {
        if (!self.moduleUsesFullNativeLowering()) return false;
        return self.block_needs_native_helper(mod.body, helper);
    }

    fn block_needs_native_helper(self: *CodeGen, block: ast.Block, helper: NativeHelper) bool {
        if (block.tail_expr) |expr| if (self.expr_needs_native_helper(expr, helper)) return true;
        for (block.stmts) |*stmt| if (self.stmt_needs_native_helper(stmt, helper)) return true;
        return false;
    }

    fn stmt_needs_native_helper(self: *CodeGen, stmt: *const ast.Stmt, helper: NativeHelper) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.inits) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                break :blk false;
            },
            .global_decl => |gd| blk: {
                for (gd.inits) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                break :blk false;
            },
            .const_decl => |cd| self.expr_needs_native_helper(cd.val, helper),
            .assign => |as| blk: {
                for (as.targets) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                for (as.values) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_native_helper(cs.expr, helper),
            .expr_stmt => |es| self.expr_needs_native_helper(es.expr, helper),
            .do_block => |db| self.block_needs_native_helper(db.body, helper),
            .while_loop => |wl| self.expr_needs_native_helper(wl.cond, helper) or self.block_needs_native_helper(wl.body, helper),
            .repeat_loop => |rl| self.expr_needs_native_helper(rl.cond, helper) or self.block_needs_native_helper(rl.body, helper),
            .if_stmt => |is| blk: {
                if (is.binding) |binding| if (self.expr_needs_native_helper(binding.expr, helper)) break :blk true;
                if (self.expr_needs_native_helper(is.cond, helper) or self.block_needs_native_helper(is.then, helper)) break :blk true;
                for (is.elseifs) |elseif| if (self.expr_needs_native_helper(elseif.cond, helper) or self.block_needs_native_helper(elseif.body, helper)) break :blk true;
                if (is.else_body) |body| if (self.block_needs_native_helper(body, helper)) break :blk true;
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_native_helper(nf.start, helper) or
                self.expr_needs_native_helper(nf.stop, helper) or
                (nf.step != null and self.expr_needs_native_helper(nf.step.?, helper)) or
                self.block_needs_native_helper(nf.body, helper),
            .gen_for => |gf| blk: {
                for (gf.iters) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                break :blk self.block_needs_native_helper(gf.body, helper);
            },
            .func_decl => |fd| self.func_needs_native_helper(&fd.func, helper),
            .match_stmt => |m| self.match_needs_native_helper(&m, helper),
            .try_stmt => |ts| blk: {
                if (self.block_needs_native_helper(ts.body, helper)) break :blk true;
                for (ts.catches) |catch_clause| if (self.block_needs_native_helper(catch_clause.body, helper)) break :blk true;
                for (ts.defers) |defer_stmt| if (self.block_needs_native_helper(defer_stmt.body, helper)) break :blk true;
                break :blk false;
            },
            .defer_stmt => |ds| self.block_needs_native_helper(ds.body, helper),
            .alias_def => |alias| blk: {
                for (alias.fields) |field| if (field.default_val) |value| {
                    if (self.expr_needs_native_helper(value, helper)) break :blk true;
                };
                for (alias.methods) |method| if (self.func_needs_native_helper(&method.func, helper)) break :blk true;
                break :blk false;
            },
            .macro_def => |macro| switch (macro.body) {
                .expr => |expr| self.expr_needs_native_helper(expr, helper),
                .block => |block| self.block_needs_native_helper(block, helper),
            },
            .ret => |r| blk: {
                for (r.vals) |expr| if (self.expr_needs_native_helper(expr, helper)) break :blk true;
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_native_helper(self: *CodeGen, expr: *const ast.Expr, helper: NativeHelper) bool {
        if (helper == .fstream and expr_is_io_popen(expr)) return true;
        return switch (expr.*) {
            .binop => |b| self.expr_needs_native_helper(b.lhs, helper) or self.expr_needs_native_helper(b.rhs, helper),
            .unop => |un| self.expr_needs_native_helper(un.operand, helper),
            .call => |call| blk: {
                if (helper == .fstream and call.func.* == .field and call.func.field.obj.* == .name and
                    std.mem.eql(u8, call.func.field.obj.name.ident, "io") and std.mem.eql(u8, call.func.field.field, "open")) break :blk true;
                if (self.expr_needs_native_helper(call.func, helper)) break :blk true;
                for (call.args) |arg| if (self.expr_needs_native_helper(arg, helper)) break :blk true;
                break :blk false;
            },
            .method_call => |call| blk: {
                if (helper == .split and std.mem.eql(u8, call.method, "split") and call.args.len == 1) break :blk true;
                if (self.expr_needs_native_helper(call.obj, helper)) break :blk true;
                for (call.args) |arg| if (self.expr_needs_native_helper(arg, helper)) break :blk true;
                break :blk false;
            },
            .index => |idx| self.expr_needs_native_helper(idx.obj, helper) or self.expr_needs_native_helper(idx.key, helper),
            .field => |field| self.expr_needs_native_helper(field.obj, helper),
            .func_expr => |func| self.func_needs_native_helper(func, helper),
            .table => |table| blk: {
                for (table.fields) |field| switch (field) {
                    .indexed => |entry| if (self.expr_needs_native_helper(entry.key, helper) or self.expr_needs_native_helper(entry.val, helper)) break :blk true,
                    .named => |entry| if (self.expr_needs_native_helper(entry.val, helper)) break :blk true,
                    .positional, .spread => |value| if (self.expr_needs_native_helper(value, helper)) break :blk true,
                    .semantic => |entry| if (self.expr_needs_native_helper(entry.val, helper)) break :blk true,
                };
                break :blk false;
            },
            .list_comp => |list| self.expr_needs_native_helper(list.value, helper) or
                self.expr_needs_native_helper(list.iter, helper) or
                (list.filter != null and self.expr_needs_native_helper(list.filter.?, helper)),
            .try_expr => |wrapped| self.expr_needs_native_helper(wrapped.operand, helper),
            .unwrap_expr => |wrapped| self.expr_needs_native_helper(wrapped.operand, helper),
            .await_expr => |wrapped| self.expr_needs_native_helper(wrapped.operand, helper),
            .if_expr => |if_expr| self.expr_needs_native_helper(if_expr.cond, helper) or
                self.expr_needs_native_helper(if_expr.then_expr, helper) or
                self.expr_needs_native_helper(if_expr.else_expr, helper),
            .match_expr => |match_expr| self.match_needs_native_helper(match_expr, helper),
            .contains_expr => |contains| self.expr_needs_native_helper(contains.lhs, helper) or self.expr_needs_native_helper(contains.rhs, helper),
            .quote => |quoted| self.expr_needs_native_helper(quoted.expr, helper),
            .unquote => |quoted| self.expr_needs_native_helper(quoted.expr, helper),
            .macro_call => |macro| blk: {
                for (macro.args) |arg| if (self.expr_needs_native_helper(arg, helper)) break :blk true;
                break :blk false;
            },
            .sequence => |sequence| blk: {
                for (sequence.exprs) |item| if (self.expr_needs_native_helper(item, helper)) break :blk true;
                break :blk false;
            },
            .range => |range| self.expr_needs_native_helper(range.start, helper) or
                self.expr_needs_native_helper(range.end, helper) or
                (range.step != null and self.expr_needs_native_helper(range.step.?, helper)),
            else => false,
        };
    }

    fn match_needs_native_helper(self: *CodeGen, match_expr: *const ast.MatchExpr, helper: NativeHelper) bool {
        if (self.expr_needs_native_helper(match_expr.scrutinee, helper)) return true;
        for (match_expr.arms) |arm| {
            if (arm.guard) |guard| if (self.expr_needs_native_helper(guard, helper)) return true;
            if (self.block_needs_native_helper(arm.body, helper)) return true;
        }
        return false;
    }

    fn func_needs_native_helper(self: *CodeGen, func: *const ast.FuncBody, helper: NativeHelper) bool {
        for (func.params) |param| if (param.default_val) |value| {
            if (self.expr_needs_native_helper(value, helper)) return true;
        };
        return self.block_needs_native_helper(func.body, helper);
    }

    fn native_scalar_needs_string_h(self: *CodeGen, mod: *const ast.Module) bool {
        if (!self.moduleKnowledgeAtLeast(.native)) return true;
        if (mod.body.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_string_h(expr)) return true;
        }
        for (mod.body.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_string_h(stmt)) return true;
        }
        return false;
    }

    fn block_needs_native_scalar_string_h(self: *CodeGen, block: ast.Block) bool {
        if (block.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_string_h(expr)) return true;
        }
        for (block.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_string_h(stmt)) return true;
        }
        return false;
    }

    fn stmt_needs_native_scalar_string_h(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.inits) |expr| {
                    if (self.expr_needs_native_scalar_string_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| self.expr_needs_native_scalar_string_h(cd.val),
            .assign => |as| blk: {
                for (as.targets) |expr| {
                    if (self.expr_needs_native_scalar_string_h(expr)) break :blk true;
                }
                for (as.values) |expr| {
                    if (self.expr_needs_native_scalar_string_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_native_scalar_string_h(cs.expr),
            .expr_stmt => |es| self.expr_needs_native_scalar_string_h(es.expr),
            .do_block => |db| self.block_needs_native_scalar_string_h(db.body),
            .while_loop => |wl| self.expr_needs_native_scalar_string_h(wl.cond) or self.block_needs_native_scalar_string_h(wl.body),
            .repeat_loop => |rl| self.expr_needs_native_scalar_string_h(rl.cond) or self.block_needs_native_scalar_string_h(rl.body),
            .if_stmt => |is| blk: {
                if (self.expr_needs_native_scalar_string_h(is.cond) or self.block_needs_native_scalar_string_h(is.then)) break :blk true;
                for (is.elseifs) |elseif| {
                    if (self.expr_needs_native_scalar_string_h(elseif.cond) or self.block_needs_native_scalar_string_h(elseif.body)) break :blk true;
                }
                if (is.else_body) |body| {
                    if (self.block_needs_native_scalar_string_h(body)) break :blk true;
                }
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_native_scalar_string_h(nf.start) or
                self.expr_needs_native_scalar_string_h(nf.stop) or
                (nf.step != null and self.expr_needs_native_scalar_string_h(nf.step.?)) or
                self.block_needs_native_scalar_string_h(nf.body),
            .func_decl => |fd| self.block_needs_native_scalar_string_h(fd.func.body),
            .ret => |r| blk: {
                for (r.vals) |expr| {
                    if (self.expr_needs_native_scalar_string_h(expr)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_native_scalar_string_h(self: *CodeGen, expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .binop => |b| (b.op == .concat and (self.expr_type(b.lhs) == .str or self.expr_type(b.rhs) == .str)) or self.expr_needs_native_scalar_string_h(b.lhs) or self.expr_needs_native_scalar_string_h(b.rhs),
            .unop => |un| (un.op == .len and self.expr_type(un.operand) == .str) or self.expr_needs_native_scalar_string_h(un.operand),
            .call => |call| blk: {
                if (self.expr_needs_native_scalar_string_h(call.func)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_string_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |call| blk: {
                if (self.expr_needs_native_scalar_string_h(call.obj)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_string_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .index => |idx| self.expr_needs_native_scalar_string_h(idx.obj) or self.expr_needs_native_scalar_string_h(idx.key),
            .field => |field| self.expr_needs_native_scalar_string_h(field.obj),
            else => false,
        };
    }

    fn native_scalar_needs_stdlib_h(self: *CodeGen, mod: *const ast.Module) bool {
        if (!self.moduleKnowledgeAtLeast(.native)) return true;
        if (mod.body.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdlib_h(expr)) return true;
        }
        for (mod.body.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdlib_h(stmt)) return true;
        }
        return false;
    }

    fn block_needs_native_scalar_stdlib_h(self: *CodeGen, block: ast.Block) bool {
        if (block.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdlib_h(expr)) return true;
        }
        for (block.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdlib_h(stmt)) return true;
        }
        return false;
    }

    fn stmt_needs_native_scalar_stdlib_h(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.inits) |expr| {
                    if (self.expr_needs_native_scalar_stdlib_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| self.expr_needs_native_scalar_stdlib_h(cd.val),
            .assign => |as| blk: {
                for (as.targets) |expr| {
                    if (self.expr_needs_native_scalar_stdlib_h(expr)) break :blk true;
                }
                for (as.values) |expr| {
                    if (self.expr_needs_native_scalar_stdlib_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_native_scalar_stdlib_h(cs.expr),
            .expr_stmt => |es| self.expr_needs_native_scalar_stdlib_h(es.expr),
            .do_block => |db| self.block_needs_native_scalar_stdlib_h(db.body),
            .while_loop => |wl| self.expr_needs_native_scalar_stdlib_h(wl.cond) or self.block_needs_native_scalar_stdlib_h(wl.body),
            .repeat_loop => |rl| self.expr_needs_native_scalar_stdlib_h(rl.cond) or self.block_needs_native_scalar_stdlib_h(rl.body),
            .if_stmt => |is| blk: {
                if (self.expr_needs_native_scalar_stdlib_h(is.cond) or self.block_needs_native_scalar_stdlib_h(is.then)) break :blk true;
                for (is.elseifs) |elseif| {
                    if (self.expr_needs_native_scalar_stdlib_h(elseif.cond) or self.block_needs_native_scalar_stdlib_h(elseif.body)) break :blk true;
                }
                if (is.else_body) |body| {
                    if (self.block_needs_native_scalar_stdlib_h(body)) break :blk true;
                }
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_native_scalar_stdlib_h(nf.start) or
                self.expr_needs_native_scalar_stdlib_h(nf.stop) or
                (nf.step != null and self.expr_needs_native_scalar_stdlib_h(nf.step.?)) or
                self.block_needs_native_scalar_stdlib_h(nf.body),
            .func_decl => |fd| self.block_needs_native_scalar_stdlib_h(fd.func.body),
            .ret => |r| blk: {
                for (r.vals) |expr| {
                    if (self.expr_needs_native_scalar_stdlib_h(expr)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_native_scalar_stdlib_h(self: *CodeGen, expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .binop => |b| (b.op == .concat and (self.expr_type(b.lhs) == .str or self.expr_type(b.rhs) == .str)) or self.expr_needs_native_scalar_stdlib_h(b.lhs) or self.expr_needs_native_scalar_stdlib_h(b.rhs),
            .unop => |un| self.expr_needs_native_scalar_stdlib_h(un.operand),
            .call => |call| blk: {
                if (call.func.* == .name and std.mem.eql(u8, call.func.name.ident, "__emit")) break :blk true;
                if (self.expr_needs_native_scalar_stdlib_h(call.func)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdlib_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |call| blk: {
                if (self.expr_needs_native_scalar_stdlib_h(call.obj)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdlib_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .index => |idx| self.expr_needs_native_scalar_stdlib_h(idx.obj) or self.expr_needs_native_scalar_stdlib_h(idx.key),
            .field => |field| self.expr_needs_native_scalar_stdlib_h(field.obj),
            else => false,
        };
    }

    fn native_scalar_needs_stdio_h(self: *CodeGen, mod: *const ast.Module) bool {
        if (!self.moduleKnowledgeAtLeast(.native)) return true;
        if (mod.body.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdio_h(expr)) return true;
        }
        for (mod.body.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdio_h(stmt)) return true;
        }
        return false;
    }

    fn block_needs_native_scalar_stdio_h(self: *CodeGen, block: ast.Block) bool {
        if (block.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdio_h(expr)) return true;
        }
        for (block.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdio_h(stmt)) return true;
        }
        return false;
    }

    fn stmt_needs_native_scalar_stdio_h(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.inits) |expr| {
                    if (self.expr_needs_native_scalar_stdio_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| self.expr_needs_native_scalar_stdio_h(cd.val),
            .assign => |as| blk: {
                for (as.targets) |expr| {
                    if (self.expr_needs_native_scalar_stdio_h(expr)) break :blk true;
                }
                for (as.values) |expr| {
                    if (self.expr_needs_native_scalar_stdio_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_native_scalar_stdio_h(cs.expr),
            .expr_stmt => |es| self.expr_needs_native_scalar_stdio_h(es.expr),
            .do_block => |db| self.block_needs_native_scalar_stdio_h(db.body),
            .while_loop => |wl| self.expr_needs_native_scalar_stdio_h(wl.cond) or self.block_needs_native_scalar_stdio_h(wl.body),
            .repeat_loop => |rl| self.expr_needs_native_scalar_stdio_h(rl.cond) or self.block_needs_native_scalar_stdio_h(rl.body),
            .if_stmt => |is| blk: {
                if (self.expr_needs_native_scalar_stdio_h(is.cond) or self.block_needs_native_scalar_stdio_h(is.then)) break :blk true;
                for (is.elseifs) |elseif| {
                    if (self.expr_needs_native_scalar_stdio_h(elseif.cond) or self.block_needs_native_scalar_stdio_h(elseif.body)) break :blk true;
                }
                if (is.else_body) |body| {
                    if (self.block_needs_native_scalar_stdio_h(body)) break :blk true;
                }
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_native_scalar_stdio_h(nf.start) or
                self.expr_needs_native_scalar_stdio_h(nf.stop) or
                (nf.step != null and self.expr_needs_native_scalar_stdio_h(nf.step.?)) or
                self.block_needs_native_scalar_stdio_h(nf.body),
            .func_decl => |fd| self.block_needs_native_scalar_stdio_h(fd.func.body),
            .ret => |r| blk: {
                for (r.vals) |expr| {
                    if (self.expr_needs_native_scalar_stdio_h(expr)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_native_scalar_stdio_h(self: *CodeGen, expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .binop => |b| self.expr_needs_native_scalar_stdio_h(b.lhs) or self.expr_needs_native_scalar_stdio_h(b.rhs),
            .unop => |un| self.expr_needs_native_scalar_stdio_h(un.operand),
            .call => |call| blk: {
                if (call.func.* == .name) {
                    const name = call.func.name.ident;
                    if (std.mem.eql(u8, name, "print") or std.mem.eql(u8, name, "__emit")) break :blk true;
                }
                if (self.expr_needs_native_scalar_stdio_h(call.func)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdio_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |call| blk: {
                if (self.expr_needs_native_scalar_stdio_h(call.obj)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdio_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .index => |idx| self.expr_needs_native_scalar_stdio_h(idx.obj) or self.expr_needs_native_scalar_stdio_h(idx.key),
            .field => |field| self.expr_needs_native_scalar_stdio_h(field.obj),
            else => false,
        };
    }

    fn native_scalar_needs_stdbool_h(self: *CodeGen, mod: *const ast.Module) bool {
        if (!self.moduleKnowledgeAtLeast(.native)) return true;
        if (mod.body.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdbool_h(expr)) return true;
        }
        for (mod.body.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdbool_h(stmt)) return true;
        }
        return false;
    }

    fn block_needs_native_scalar_stdbool_h(self: *CodeGen, block: ast.Block) bool {
        if (block.tail_expr) |expr| {
            if (self.expr_needs_native_scalar_stdbool_h(expr)) return true;
        }
        for (block.stmts) |*stmt| {
            if (self.stmt_needs_native_scalar_stdbool_h(stmt)) return true;
        }
        return false;
    }

    fn stmt_needs_native_scalar_stdbool_h(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.names, 0..) |lname, i| {
                    if (self.resolve_type(lname.typ) == .bool) break :blk true;
                    if (lname.typ == .inferred and i < ld.inits.len and self.expr_type(ld.inits[i]) == .bool) break :blk true;
                }
                for (ld.inits) |expr| {
                    if (self.expr_needs_native_scalar_stdbool_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| self.resolve_type(cd.typ) == .bool or self.expr_needs_native_scalar_stdbool_h(cd.val),
            .assign => |as| blk: {
                for (as.values) |expr| {
                    if (self.expr_needs_native_scalar_stdbool_h(expr)) break :blk true;
                }
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_native_scalar_stdbool_h(cs.expr),
            .expr_stmt => |es| self.expr_needs_native_scalar_stdbool_h(es.expr),
            .do_block => |db| self.block_needs_native_scalar_stdbool_h(db.body),
            .while_loop => |wl| self.expr_needs_native_scalar_stdbool_h(wl.cond) or self.block_needs_native_scalar_stdbool_h(wl.body),
            .repeat_loop => |rl| self.expr_needs_native_scalar_stdbool_h(rl.cond) or self.block_needs_native_scalar_stdbool_h(rl.body),
            .if_stmt => |is| blk: {
                if (self.expr_needs_native_scalar_stdbool_h(is.cond) or self.block_needs_native_scalar_stdbool_h(is.then)) break :blk true;
                for (is.elseifs) |elseif| {
                    if (self.expr_needs_native_scalar_stdbool_h(elseif.cond) or self.block_needs_native_scalar_stdbool_h(elseif.body)) break :blk true;
                }
                if (is.else_body) |body| {
                    if (self.block_needs_native_scalar_stdbool_h(body)) break :blk true;
                }
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_native_scalar_stdbool_h(nf.start) or
                self.expr_needs_native_scalar_stdbool_h(nf.stop) or
                (nf.step != null and self.expr_needs_native_scalar_stdbool_h(nf.step.?)) or
                self.block_needs_native_scalar_stdbool_h(nf.body),
            .func_decl => |fd| blk: {
                if (self.resolve_type(contract_ret(&fd.func)) == .bool) break :blk true;
                for (fd.func.params) |param| {
                    if (self.resolve_type(param.typ) == .bool) break :blk true;
                    if (param.default_val) |expr| {
                        if (self.expr_needs_native_scalar_stdbool_h(expr)) break :blk true;
                    }
                }
                break :blk self.block_needs_native_scalar_stdbool_h(fd.func.body);
            },
            .ret => |r| blk: {
                for (r.vals) |expr| {
                    if (self.expr_needs_native_scalar_stdbool_h(expr)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_native_scalar_stdbool_h(self: *CodeGen, expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .true_lit, .false_lit => true,
            .binop => |b| self.expr_needs_native_scalar_stdbool_h(b.lhs) or
                self.expr_needs_native_scalar_stdbool_h(b.rhs),
            .unop => |un| self.expr_needs_native_scalar_stdbool_h(un.operand),
            .call => |call| blk: {
                if (self.expr_needs_native_scalar_stdbool_h(call.func)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdbool_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |call| blk: {
                if (self.expr_needs_native_scalar_stdbool_h(call.obj)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_native_scalar_stdbool_h(arg)) break :blk true;
                }
                break :blk false;
            },
            .index => |idx| self.expr_needs_native_scalar_stdbool_h(idx.obj) or
                self.expr_needs_native_scalar_stdbool_h(idx.key),
            .field => |field| self.expr_needs_native_scalar_stdbool_h(field.obj),
            else => false,
        };
    }

    fn native_scalar_needs_int_floor_helpers(self: *CodeGen, mod: *const ast.Module) bool {
        if (!self.moduleKnowledgeAtLeast(.native)) return true;
        if (mod.body.tail_expr) |expr| {
            if (self.expr_needs_int_floor_helpers(expr, true)) return true;
        }
        for (mod.body.stmts) |*stmt| {
            if (self.stmt_needs_int_floor_helpers(stmt, true)) return true;
        }
        // The top-level walker never reaches into embedded modules whose bodies
        // use `//` or `%` on integer operands. Walk the sema application table
        // for every reached home, resolve each to its source path, and re-parse
        // the module to find floor relations inside its own function bodies.
        // Cost is one parse per reached home and runs only at codegen time.
        //
        // STRICT-TYPES IS OFF in the embedded walker. The walker has no sema
        // context (it re-parses a fresh ast.Module from disk), so expr_type()
        // returns .any for every name reference and the integer check at
        // expr_needs_int_floor_helpers would say "no" to every site. The
        // operator spelling is the only thing the walker has, and `//` / `%`
        // are integer-floor relations in both admitted source laws. The
        // top-level walk keeps strict-types=true because it has the sema
        // context to distinguish integer operands from string/float ones.
        if (self.checked_sema) |checked| {
            var seen = std.StringHashMap(void).init(self.alloc);
            defer seen.deinit();
            var applied = checked.appliedHomes();
            while (applied.next()) |home| {
                if (seen.contains(home)) continue;
                seen.put(home, {}) catch continue;
                const fh = checked.resolvedHome(home) orelse continue;
                const submod = self.readModuleForEmbeddedFloorWalk(fh.path) orelse continue;
                if (submod.body.tail_expr) |sexpr| {
                    if (self.expr_needs_int_floor_helpers(sexpr, false)) return true;
                }
                for (submod.body.stmts) |*sub_stmt| {
                    if (self.stmt_needs_int_floor_helpers(sub_stmt, false)) return true;
                }
            }
        }
        return false;
    }

    /// Read + parse an embedded module file for the floor-helper walker.
    /// The result is a snapshot — the real codegen owns its own parse.
    fn readModuleForEmbeddedFloorWalk(self: *CodeGen, path: []const u8) ?ast.Module {
        const Lexer = @import("lexer.zig").Lexer;
        const Parser = @import("parser.zig").Parser;
        const lexer_dispatch = @import("lexer_dispatch.zig");
        const allocator = self.alloc;
        const source = Io.Dir.readFileAlloc(Io.Dir.cwd(), self.io, path, allocator, .unlimited) catch return null;
        defer allocator.free(source);
        var lex = Lexer.initFacts(source, path, lexer_bridge.sourceFacts(path));
        var parser = Parser.init(&lex, allocator);
        parser.pack_tokens = lexer_dispatch.route(allocator, &lex, source, path) catch return null;
        parser.pack_index = 0;
        parser.idol_mode = lex.family == lexer_bridge.family_canon;
        const result = parser.parse_module() catch |e| {
            std.debug.print("[floor-walk] parse_module failed for {s}: {s}\n", .{ path, @errorName(e) });
            return null;
        };
        std.debug.print("[floor-walk] parsed {s} stmts={d}\n", .{ path, result.body.stmts.len });
        return result;
    }

    fn block_needs_int_floor_helpers(self: *CodeGen, block: ast.Block, strict_types: bool) bool {
        if (block.tail_expr) |expr| {
            if (self.expr_needs_int_floor_helpers(expr, strict_types)) return true;
        }
        for (block.stmts) |*stmt| {
            if (self.stmt_needs_int_floor_helpers(stmt, strict_types)) return true;
        }
        return false;
    }

    fn stmt_needs_int_floor_helpers(self: *CodeGen, stmt: *const ast.Stmt, strict_types: bool) bool {
        return switch (stmt.*) {
            .local_decl => |ld| blk: {
                for (ld.inits) |expr| {
                    if (self.expr_needs_int_floor_helpers(expr, strict_types)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| self.expr_needs_int_floor_helpers(cd.val, strict_types),
            .assign => |as| blk: {
                for (as.targets) |expr| {
                    if (self.expr_needs_int_floor_helpers(expr, strict_types)) break :blk true;
                }
                for (as.values) |expr| {
                    if (self.expr_needs_int_floor_helpers(expr, strict_types)) break :blk true;
                }
                break :blk false;
            },
            .call_stmt => |cs| self.expr_needs_int_floor_helpers(cs.expr, strict_types),
            .expr_stmt => |es| self.expr_needs_int_floor_helpers(es.expr, strict_types),
            .do_block => |db| self.block_needs_int_floor_helpers(db.body, strict_types),
            .while_loop => |wl| self.expr_needs_int_floor_helpers(wl.cond, strict_types) or self.block_needs_int_floor_helpers(wl.body, strict_types),
            .repeat_loop => |rl| self.expr_needs_int_floor_helpers(rl.cond, strict_types) or self.block_needs_int_floor_helpers(rl.body, strict_types),
            .if_stmt => |is| blk: {
                if (self.expr_needs_int_floor_helpers(is.cond, strict_types) or self.block_needs_int_floor_helpers(is.then, strict_types)) break :blk true;
                for (is.elseifs) |elseif| {
                    if (self.expr_needs_int_floor_helpers(elseif.cond, strict_types) or self.block_needs_int_floor_helpers(elseif.body, strict_types)) break :blk true;
                }
                if (is.else_body) |body| {
                    if (self.block_needs_int_floor_helpers(body, strict_types)) break :blk true;
                }
                break :blk false;
            },
            .num_for => |nf| self.expr_needs_int_floor_helpers(nf.start, strict_types) or
                self.expr_needs_int_floor_helpers(nf.stop, strict_types) or
                (nf.step != null and self.expr_needs_int_floor_helpers(nf.step.?, strict_types)) or
                self.block_needs_int_floor_helpers(nf.body, strict_types),
            .func_decl => |fd| self.block_needs_int_floor_helpers(fd.func.body, strict_types),
            .ret => |r| blk: {
                for (r.vals) |expr| {
                    if (self.expr_needs_int_floor_helpers(expr, strict_types)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn expr_needs_int_floor_helpers(self: *CodeGen, expr: *const ast.Expr, strict_types: bool) bool {
        return switch (expr.*) {
            .binop => |b| blk: {
                if (self.expr_needs_int_floor_helpers(b.lhs, strict_types) or self.expr_needs_int_floor_helpers(b.rhs, strict_types)) break :blk true;
                if (b.op != .idiv and b.op != .mod) break :blk false;
                // `//` and `%` are INTEGER-FLOOR relations in both admitted source
                // laws. The operator spelling alone decides that; the type system
                // rejects non-integer operands elsewhere. The strict-types branch
                // kept here to filter out `//` on strings/floats, but the check
                // falls through to .any too often for inferred locals (lo, hi, m
                // in classify.id / rewrite.id are not declared i64, so expr_type
                // returns .any and the integer guard wrongly says "no"). Trusting
                // the operator spelling is the same answer the codegen emitter
                // gives — it lowers `//` and `%` to lua_idiv_i64/lua_imod_i64
                // whenever the operator fires, regardless of the source's
                // declared operand types.
                if (!strict_types) break :blk true;
                const lt = self.expr_type(b.lhs);
                const rt = self.expr_type(b.rhs);
                if (lt == .any or rt == .any) break :blk true;
                if (!lt.is_integer() or !rt.is_integer()) break :blk false;
                break :blk true;
            },
            .unop => |un| self.expr_needs_int_floor_helpers(un.operand, strict_types),
            .call => |call| blk: {
                if (self.expr_needs_int_floor_helpers(call.func, strict_types)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_int_floor_helpers(arg, strict_types)) break :blk true;
                }
                break :blk false;
            },
            .method_call => |call| blk: {
                if (self.expr_needs_int_floor_helpers(call.obj, strict_types)) break :blk true;
                for (call.args) |arg| {
                    if (self.expr_needs_int_floor_helpers(arg, strict_types)) break :blk true;
                }
                break :blk false;
            },
            .index => |idx| self.expr_needs_int_floor_helpers(idx.obj, strict_types) or self.expr_needs_int_floor_helpers(idx.key, strict_types),
            .field => |field| self.expr_needs_int_floor_helpers(field.obj, strict_types),
            else => false,
        };
    }

    pub fn emit_module(self: *CodeGen, mod: *ast.Module) E!void {
        const old_module_cname = self.current_module_cname;
        const old_module = self.current_module;
        self.current_module_cname = "";
        self.current_module = mod;
        // Collect `req` bindings so qualified calls can resolve to module
        // symbols. Failure is non-fatal: the boxed path still applies.
        defer {
            self.current_module_cname = old_module_cname;
            self.current_module = old_module;
            // gap[082]: a refused composition has already reported itself at
            // the site. Stopping here is what makes the class lattice a rule —
            // if the build continued, the site would fall through to the
            // builtin projection and the program would quietly stop meaning
            // what its edges say.
            if (refused_conversions > 0) {
                term.err("{d} conversion(s) refused: silent composition stops at lossless", .{refused_conversions});
                std.process.exit(1);
            }
        }
        if (self.src_path.len > 0) {
            debug_trace.event(.codegen, .module, "emit {s}", .{self.src_path});
        } else {
            debug_trace.event(.codegen, .module, "emit module", .{});
        }
        try self.refuseUnresolvableStdModule(mod);
        try self.populate_relation_edges(mod);
        try self.populate_alias_defs(mod);
        try self.collect_comptime_only_funcs(mod);
        try self.populate_record_aliases(mod);
        try self.noteSubjectDescriptors(mod);
        try self.populate_foreign_aliases();
        try self.populate_enum_defs(mod);
        try self.populate_func_bodies(mod);
        // Promote main-module module-scope bindings referenced by module
        // functions to module globals (mirrors embedded-module promotion), so
        // generated module functions can read their `duo_g_*` storage. The
        // driver then assigns the globals instead of driver-local copies.
        if (self.module_globals) |mg| {
            try self.promote_module_captured_locals(mod, @constCast(mg), self.type_map);
        }
        meta_directives.registerModuleDirectives(self.alloc, mod) catch {};

        self.collect_req_module_bindings(mod) catch {};
        self.native_scalar_mode = self.can_emit_native_scalar_module(mod);
        // gap[166]: see `moduleHomeBindingsAreNativeDirect`. The pre-graph gate
        // no longer answers this; the emitter that needs the answer asks it.
        if (self.native_scalar_mode and !self.moduleHomeBindingsAreNativeDirect(mod)) {
            self.native_scalar_mode = false;
        }
        if (self.native_scalar_mode and !self.req_deps_allow_full_native(mod)) {
            self.native_scalar_mode = false;
        }
        // Candidate discovery consumes checked descriptors/module facts. A
        // foreign source law is not a physical runtime obligation.
        if (!self.native_scalar_mode and (self.target.len == 0 or std.mem.eql(u8, self.target, "native"))) {
            if (self.compute_native_scalar_funcs(mod)) {
                self.mixed_scalar_mode = true;
            }
        }
        // P0: bench profiles must diverge in generated C, not just manifest metadata.
        if (self.bench_mode and self.bench_backend == .c_dynamic) {
            self.mixed_scalar_mode = false;
            self.native_scalar_funcs.clearRetainingCapacity();
        }
        self.substrate_native_mode = self.compute_substrate_native_mode(mod);
        // Same dependency check `native_scalar_mode` gets above: both feed
        // `moduleUsesFullNativeLowering`, which drops the Lua runtime from the
        // whole TU. Guarding only one of them let a small typed `main` that reqs
        // `std.io`/`std.json` choose substrate-native, then embed those modules'
        // `lua_Value` signatures with no runtime declared — "unknown type name
        // 'lua_Value'". A req dependency that needs the runtime disqualifies
        // full-native lowering regardless of which mode selected it.
        if (self.substrate_native_mode and !self.req_deps_allow_full_native(mod)) {
            self.substrate_native_mode = false;
        }
        self.module_knowledge = if (self.native_scalar_mode or self.substrate_native_mode)
            .native
        else if (self.mixed_scalar_mode)
            .guarded
        else
            .observed;
        if (native_diag) std.debug.print("[native-diag] emit_module native_scalar_mode={} mixed={} knowledge={s} src={s}\n", .{
            self.native_scalar_mode,
            self.mixed_scalar_mode,
            semantic_algebra.KnowledgeLevel.name(self.module_knowledge),
            self.src_path,
        });
        self.current_module = mod;
        try self.collect_native_dense_module_tables(mod);
        try self.collect_native_const_descriptors(mod);
        const native_scalar_plain = self.moduleUsesFullNativeLowering() and
            !self.module_has_cinclude(mod) and
            !self.module_has_concept_def(mod);

        // File header
        self.p("/* Generated by duo compiler — do not edit */\n", .{});
        if (!std.mem.eql(u8, self.target, "wasm32-wasi") and !native_scalar_plain) {
            self.p("#define _XOPEN_SOURCE 600\n", .{});
            // _DEFAULT_SOURCE is not decoration next to the Darwin macro; it is
            // the glibc/musl half of the same request. `_XOPEN_SOURCE 600`
            // ALONE hides `mkdtemp` (POSIX 2008, so it needs 700 or the default
            // set) and `mkstemps` (BSD, so it needs the default set at any
            // level), and the private-run-dir and suffixed-temp helpers below
            // call both. The tracked artifact was frozen with only the Darwin
            // macro, so `src/lexer_tokenize.c` compiled on macOS and failed on
            // every glibc host with two implicit-declaration errors — the
            // GAP-040 shape again, one layer down from the preprocessor guards
            // that were supposed to have retired it.
            self.p("#define _DEFAULT_SOURCE\n", .{});
            self.p("#define _DARWIN_C_SOURCE\n", .{});
        }
        // Emit user @cinclude directives before standard headers so FFI
        // declarations can use library types.
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .cinclude) continue;
            const header = stmt.cinclude.header;
            if (std.mem.indexOf(u8, header, "/") != null) {
                self.p("#include \"{s}\"\n", .{header});
            } else {
                self.p("#include <{s}>\n", .{header});
            }
        }
        try self.emit_foreign_func_decls();
        if (!native_scalar_plain) {
            self.p("#include <stddef.h>\n", .{});
        }
        self.p("#include <stdint.h>\n", .{});
        if (!native_scalar_plain or self.native_scalar_needs_stdbool_h(mod) or self.moduleUsesFullNativeLowering()) {
            self.p("#include <stdbool.h>\n", .{});
        }
