        self.pl("{s} full = {s} / 10;", .{ ct, n });
        self.pl("{s} rem = {s} % 10;", .{ ct, n });
        self.pl("total += full * 55;", .{});
        self.pl("total += rem > 0 ? (rem * (rem + 3)) / 2 : 0;", .{});
        self.pl("return total;", .{});
    }

