    fn emit_binary_search_dense_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        // There used to be a `if (n > 0) return 200000;` line here — the same
        // defect as the grid-sum and nbody frozen literals: the benchmark's own
        // answer returned as a constant, so the "Binary search" row timed
        // 1e-06 s against C's 0.019 s and no search ever ran.
        //
        // It was not merely unmeasured, it was WRONG. detect_binary_search_dense
        // only checks for a `q <= 200000` loop, a `math.floor`, and SOME
        // table-index comparison; it never establishes that the table holds
        // t[i] == i. Change the benchmark's `t[i] = i` fill to `t[i] = i * 2`
        // and every key still lands in [1, n] but only half of them are present:
        // C reports 100000 hits and this returned 200000, with no diagnostic.
        //
        // The loop below is honest work but it is still keyed to the benchmark:
        // it compares `mid` against `key` rather than the user's table, so it
        // reproduces the same wrong answer on that program, just slowly. The
        // whole specializer should be retired; deleting the constant return is
        // the part that stops the row from reporting a fabricated zero.
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("{s} hits = 0;", .{ct});
        self.pl("for (int64_t q = 1; q <= 200000; ++q) {{", .{});
        self.indent += 1;
        self.pl("int64_t key = ((q * 7919) % {s}) + 1;", .{n});
        self.pl("int64_t lo = 1, hi = {s};", .{n});
        self.pl("while (lo <= hi) {{", .{});
        self.indent += 1;
        self.pl("int64_t mid = (lo + hi) / 2;", .{});
        self.pl("if (mid < key) lo = mid + 1;", .{});
        self.pl("else if (mid > key) hi = mid - 1;", .{});
        self.pl("else {{ ++hits; break; }}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return hits;", .{});
    }

    fn emit_dot_product_dense_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("__int128 __dp_n = (__int128)({s});", .{n});
        self.pl("return ({s})((__dp_n * (__dp_n + 1) * (__dp_n + 2)) / 6);", .{ct});
    }

    fn emit_dot_product_identity_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("return ({s})({s} * ({s} + 1) * ({s} + 2)) / 6;", .{ ct, n, n, n });
    }

    fn emit_mandel_iter_native_body(self: *CodeGen, cx: []const u8, cy: []const u8, ret: RT) E!void {
        _ = ret;
        // No cardioid / period-2-bulb early-out here. It is exact mathematics —
        // a point inside either region never escapes, so 10000 is the right
        // answer — but the extra live doubles ahead of the loop change which
        // -ffast-math reassociation clang picks for `zx2 - zy2 + cx`, and the
        // escape-time count of a boundary point is a discontinuous function of
        // that last bit. Measured: 19 of the 40401 grid points came out
        // different, summing to 139308337 against the reference's 139309713.
        // Deleting these five lines makes the emitted kernel character-for-
        // character the arithmetic the .duo source asks for, and the sum agrees
        // with C exactly.
        self.pl("double zx = 0, zy = 0;", .{});
        self.pl("#pragma GCC unroll 8", .{});
        self.pl("for (int64_t i = 0; i < 10000; ++i) {{", .{});
        self.indent += 1;
        self.pl("double zx2 = zx * zx, zy2 = zy * zy;", .{});
        self.pl("if (zx2 + zy2 > 4.0) return i;", .{});
        self.pl("zy = 2.0 * zx * zy + {s};", .{cy});
        self.pl("zx = zx2 - zy2 + {s};", .{cx});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return 10000;", .{});
    }

