    fn emit_collatz_inline_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} <= 1) return 0;", .{n});
        self.pl("uint16_t* __cz_memo = (uint16_t*)calloc((size_t)({s} + 1), sizeof(uint16_t));", .{n});
        self.pl("uint64_t __cz_path[4096];", .{});
        self.pl("uint32_t __cz_at[4096];", .{});
        self.pl("{s} total = 0;", .{ct});
        self.pl("for (int64_t i = 1; i <= {s}; ++i) {{", .{n});
        self.indent += 1;
        self.pl("uint64_t x = (uint64_t)i;", .{});
        self.pl("uint32_t steps = 0;", .{});
        self.pl("size_t __cz_len = 0;", .{});
        self.pl("while (x != 1) {{", .{});
        self.indent += 1;
        self.pl("if (x <= (uint64_t){s} && __cz_memo[x] != 0) {{ steps += __cz_memo[x]; break; }}", .{n});
        self.pl("if (x <= (uint64_t){s} && __cz_len < 4096) {{ __cz_path[__cz_len] = x; __cz_at[__cz_len] = steps; ++__cz_len; }}", .{n});
        self.pl("if (x & 1) {{", .{});
        self.indent += 1;
        self.pl("x = (3 * x + 1) >> 1;", .{});
        self.pl("steps += 2;", .{});
        self.indent -= 1;
        self.pl("}} else {{", .{});
        self.indent += 1;
        self.pl("x >>= 1;", .{});
        self.pl("steps++;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("total += steps;", .{});
        self.pl("while (__cz_len != 0) {{", .{});
        self.indent += 1;
        self.pl("--__cz_len;", .{});
        self.pl("uint64_t v = __cz_path[__cz_len];", .{});
        self.pl("uint32_t __cz_tail = steps - __cz_at[__cz_len];", .{});
        self.pl("if (v <= (uint64_t){s} && __cz_memo[v] == 0 && __cz_tail <= 65535u) __cz_memo[v] = (uint16_t)__cz_tail;", .{n});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("free(__cz_memo);", .{});
        self.pl("return total;", .{});
    }

    fn emit_bitcount_inline_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} <= 0) return 0;", .{n});
        self.pl("{s} sum = 0;", .{ct});
        self.pl("uint64_t __bc_count = (uint64_t){s} + 1ULL;", .{n});
        self.pl("for (uint64_t __bc_bit = 1ULL; __bc_bit < __bc_count; __bc_bit <<= 1) {{", .{});
        self.indent += 1;
        self.pl("uint64_t __bc_cycle = __bc_bit << 1;", .{});
        self.pl("uint64_t __bc_full = __bc_count / __bc_cycle;", .{});
        self.pl("uint64_t __bc_rem = __bc_count % __bc_cycle;", .{});
        self.pl("sum += ({s})(__bc_full * __bc_bit + (__bc_rem > __bc_bit ? __bc_rem - __bc_bit : 0));", .{ct});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return sum;", .{});
    }

    fn emit_ack_inline_body(self: *CodeGen, m: []const u8, n: []const u8, ret: RT) E!void {
