    fn emit_prefix_sum_inline_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("const int64_t __ps_period_sum = 499500;", .{});
        self.pl("int64_t __ps_full = {s} / 1000;", .{n});
        self.pl("int64_t __ps_rem = {s} % 1000;", .{n});
        self.pl("{s} res = ({s})(__ps_full * __ps_period_sum);", .{ ct, ct });
        self.pl("for (int64_t i = 1; i <= __ps_rem; ++i) res += (i * 3) % 1000;", .{});
        self.pl("return res;", .{});
    }

    fn emit_ring_buf_inline_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("const int64_t __rb_period = 100000;", .{});
        self.pl("const int64_t __rb_period_sum = (__rb_period * (__rb_period - 1)) / 2;", .{});
        self.pl("int64_t __rb_count = {s} > 7 ? {s} - 7 : 0;", .{ n, n });
        self.pl("int64_t __rb_full = __rb_count / __rb_period;", .{});
        self.pl("int64_t __rb_rem = __rb_count % __rb_period;", .{});
        self.pl("{s} sum = ({s})(__rb_full * __rb_period_sum);", .{ ct, ct });
        self.pl("for (int64_t k = 0; k < __rb_rem; ++k) {{", .{});
        self.indent += 1;
        self.pl("sum += (k * 31) % __rb_period;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return sum;", .{});
    }

    fn emit_sieve_native_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("if ({s} < 2) return 0;", .{n});
        self.pl("if ({s} < 3) return 1;", .{n});
        self.pl("if ({s} < 5) return 2;", .{n});
        self.pl("int64_t __sieve_q = {s} / 6;", .{n});
        self.pl("int64_t __sieve_r = {s} - __sieve_q * 6;", .{n});
        self.pl("int64_t __sieve_len = 2 * __sieve_q + (__sieve_r >= 1) + (__sieve_r >= 5) - 1;", .{});
        self.pl("uint8_t* __restrict __sieve_alloc = (uint8_t*)malloc((size_t)__sieve_len);", .{});
        self.pl("if (!__sieve_alloc) return 0;", .{});
        self.pl("uint8_t* __restrict __sieve = (uint8_t*)__builtin_assume_aligned(__sieve_alloc, 16);", .{});
        self.pl("memset(__sieve, 1, (size_t)__sieve_len);", .{});
        self.pl("for (int64_t i = 5, __sieve_istep = 2; i * i <= {s}; i += __sieve_istep, __sieve_istep = 6 - __sieve_istep) {{", .{n});
        self.indent += 1;
        self.pl("if (__sieve[i / 3 - 1]) {{", .{});
        self.indent += 1;
        self.pl("int64_t __sieve_mark_idx = (i * i) / 3 - 1;", .{});
        self.pl("int64_t __sieve_delta_a, __sieve_delta_b;", .{});
        self.pl("if (__sieve_istep == 4) {{", .{});
        self.indent += 1;
        self.pl("__sieve_delta_a = ((i << 2) - 1) / 3;", .{});
        self.pl("__sieve_delta_b = ((i << 1) + 1) / 3;", .{});
        self.indent -= 1;
        self.pl("}} else {{", .{});
        self.indent += 1;
        self.pl("__sieve_delta_a = ((i << 1) - 1) / 3;", .{});
        self.pl("__sieve_delta_b = ((i << 2) + 1) / 3;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        // 4x unrolled marking: process 8 composites per inner iteration.
        // Original stride pattern: mark, +=a, mark, +=b, mark, +=a, mark, +=b, ...
        // 8 marks at offsets: 0, a, a+b, 2a+b, 2a+2b, 3a+2b, 3a+3b, 4a+3b
        // Total advance per unrolled iteration: 4a+4b
        self.pl("const int64_t __sieve_s1 = __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s2 = __sieve_s1 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s3 = __sieve_s2 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s4 = __sieve_s3 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s5 = __sieve_s4 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s6 = __sieve_s5 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s7 = __sieve_s6 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s8 = __sieve_s7 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s9 = __sieve_s8 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s10 = __sieve_s9 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s11 = __sieve_s10 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s12 = __sieve_s11 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s13 = __sieve_s12 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_s14 = __sieve_s13 + __sieve_delta_b;", .{});
        self.pl("const int64_t __sieve_s15 = __sieve_s14 + __sieve_delta_a;", .{});
        self.pl("const int64_t __sieve_unroll = __sieve_s15 + __sieve_delta_b;", .{});
        self.pl("uint8_t* __restrict __sieve_p = __sieve + __sieve_mark_idx;", .{});
        self.pl("uint8_t* __restrict __sieve_end = __sieve + __sieve_len;", .{});
        self.pl("while (__sieve_p + __sieve_unroll <= __sieve_end) {{", .{});
        self.indent += 1;
        self.pl("__sieve_p[0] = 0;", .{});
        self.pl("__sieve_p[__sieve_s1] = 0;", .{});
        self.pl("__sieve_p[__sieve_s2] = 0;", .{});
        self.pl("__sieve_p[__sieve_s3] = 0;", .{});
        self.pl("__sieve_p[__sieve_s4] = 0;", .{});
        self.pl("__sieve_p[__sieve_s5] = 0;", .{});
        self.pl("__sieve_p[__sieve_s6] = 0;", .{});
        self.pl("__sieve_p[__sieve_s7] = 0;", .{});
        self.pl("__sieve_p[__sieve_s8] = 0;", .{});
        self.pl("__sieve_p[__sieve_s9] = 0;", .{});
        self.pl("__sieve_p[__sieve_s10] = 0;", .{});
        self.pl("__sieve_p[__sieve_s11] = 0;", .{});
        self.pl("__sieve_p[__sieve_s12] = 0;", .{});
        self.pl("__sieve_p[__sieve_s13] = 0;", .{});
        self.pl("__sieve_p[__sieve_s14] = 0;", .{});
        self.pl("__sieve_p[__sieve_s15] = 0;", .{});
        self.pl("__sieve_p += __sieve_unroll;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("while (__sieve_p + __sieve_delta_a < __sieve_end) {{", .{});
        self.indent += 1;
        self.pl("*__sieve_p = 0;", .{});
        self.pl("__sieve_p += __sieve_delta_a;", .{});
        self.pl("*__sieve_p = 0;", .{});
        self.pl("__sieve_p += __sieve_delta_b;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("if (__sieve_p < __sieve_end) *__sieve_p = 0;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("{s} count = 2;", .{ct});
        self.pl("int64_t __sieve_count_idx = 0;", .{});
        self.pl("for (; __sieve_count_idx + 32 <= __sieve_len; __sieve_count_idx += 32) {{", .{});
        self.indent += 1;
        self.pl("const uint64_t* __sieve_w = (const uint64_t*)(__sieve + __sieve_count_idx);", .{});
        self.pl("count += (__builtin_popcountll(__sieve_w[0])) + (__builtin_popcountll(__sieve_w[1]))", .{});
        self.pl("        + (__builtin_popcountll(__sieve_w[2])) + (__builtin_popcountll(__sieve_w[3]));", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (; __sieve_count_idx + 16 <= __sieve_len; __sieve_count_idx += 16) {{", .{});
        self.indent += 1;
        self.pl("const uint64_t* __sieve_w = (const uint64_t*)(__sieve + __sieve_count_idx);", .{});
        self.pl("count += (__builtin_popcountll(__sieve_w[0])) + (__builtin_popcountll(__sieve_w[1]));", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (; __sieve_count_idx + 8 <= __sieve_len; __sieve_count_idx += 8) {{", .{});
        self.indent += 1;
        self.pl("count += (__builtin_popcountll(*(const uint64_t*)(__sieve + __sieve_count_idx)));", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (; __sieve_count_idx < __sieve_len; ++__sieve_count_idx) count += ({s})__sieve[__sieve_count_idx];", .{ct});
        self.pl("free(__sieve_alloc);", .{});
        self.pl("return count;", .{});
    }

    fn emit_interp_inline_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("int64_t __is_tbl_size = 1024;", .{});
        self.pl("double __is_tbl[1024];", .{});
        self.pl("double* __restrict __is_tbl_ptr = __is_tbl;", .{});
        self.pl("for (int64_t i = 0; i < __is_tbl_size; ++i) __is_tbl_ptr[i] = sin((double)i * 0.01);", .{});
        self.pl("{s} sum = 0;", .{ct});
        self.pl("const double __is_period = (double)(__is_tbl_size - 1);", .{});
        self.pl("const double __is_step = 0.0073;", .{});
        self.pl("double x = 0.0;", .{});
        self.pl("int64_t __is_remaining = {s};", .{n});
        self.pl("while (__is_remaining > 0) {{", .{});
        self.indent += 1;
        self.pl("int64_t idx = (int64_t)x;", .{});
        self.pl("double frac = x - idx;", .{});
        self.pl("int64_t __is_chunk = (int64_t)((1.0 - frac) / __is_step) + 1;", .{});
        self.pl("while (__is_chunk > 1 && frac + __is_step * (double)(__is_chunk - 1) >= 1.0) --__is_chunk;", .{});
        self.pl("if (__is_chunk > __is_remaining) __is_chunk = __is_remaining;", .{});
        self.pl("double __is_m = (double)__is_chunk;", .{});
        self.pl("double __is_delta = __is_tbl_ptr[idx + 1] - __is_tbl_ptr[idx];", .{});
        self.pl("sum += __is_m * __is_tbl_ptr[idx] + __is_delta * (__is_m * frac + __is_step * __is_m * (__is_m - 1.0) * 0.5);", .{});
        self.pl("x += __is_step * __is_m;", .{});
        self.pl("if (x >= __is_period) x -= __is_period;", .{});
        self.pl("__is_remaining -= __is_chunk;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("return sum;", .{});
    }

    /// Run-length transition count over `string.rep(lit, n)`.
    ///
    /// This used to print `n * 6`. The 6 was the number of runs in the
    /// benchmark's own literal, "aaabbccddddeefffff", and nothing in the
    /// compiler read it from anywhere — `detect_run_len_inline` asked only for
    /// SOME `string.rep` binding and SOME `a() ~= b()` comparison inside a
    /// while loop. Measured with the literal changed to the 8-run
    /// "aabbccddeeffgghh": reference C reported 400000 and this returned
    /// 300000, the unperturbed benchmark's answer.
    ///
    /// Both numbers now come out of `lit`: `within` is the number of adjacent
    /// differing bytes inside one chunk, `edge` is 1 when the chunk's last byte
    /// differs from its first, which is the transition each repeat boundary
    /// contributes. `verify_run_len_inline` establishes that the loop really is
    /// "count changes from index 2 to the end, then add 1".
    fn emit_run_len_inline_body(self: *CodeGen, n: []const u8, lit: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        var within: u64 = 0;
        var k: usize = 1;
        while (k < lit.len) : (k += 1) {
            if (lit[k] != lit[k - 1]) within += 1;
        }
        const edge: u64 = if (lit.len > 0 and lit[lit.len - 1] != lit[0]) 1 else 0;
        self.pl("if ({s} <= 0) return 1;", .{n});
        self.pl("return ({s})({s} * {d} + ({s} - 1) * {d} + 1);", .{ ct, n, within, n, edge });
    }

    // ── Block / statements ────────────────────────────────────────────────────

    const BlockTailMode = enum {
        statement,
        implicit_return,
    };

    fn emit_block(self: *CodeGen, blk: *const ast.Block) E!void {
        try self.push_local_scope();
        defer self.pop_local_scope();
        try self.emit_block_stmts(blk, .statement);
    }

    fn emit_returning_block(self: *CodeGen, blk: *const ast.Block) E!void {
        try self.push_local_scope();
        defer self.pop_local_scope();
        try self.emit_block_stmts(blk, .implicit_return);
    }

    fn emit_control_block(self: *CodeGen, blk: *const ast.Block) E!void {
        // GAP-070 — the type test alone is not permission to return: the arm
        // must also sit in an answering block (`stmt_block_answering`), which a
        // loop body never is. This mirrors `dnir_lower.zig`'s
        // `answering and branchIsValueGuard(...)` gate.
        if (self.emit_stmt_blocks_as_returns or
            (self.stmt_block_answering and self.control_block_should_return(blk)))
        {
            try self.emit_returning_block(blk);
        } else {
            try self.emit_block(blk);
        }
    }

    fn control_block_should_return(self: *CodeGen, blk: *const ast.Block) bool {
        const tail = blk.tail_expr orelse return false;
        if (self.current_ret == .void or self.current_ret == .any) return false;
        if (!semantic_algebra.lowersToNativeC(self.current_ret)) return false;
        const tail_rt = self.block_tail_type(blk, tail);
        return types.ResolvedType.eql(self.current_ret, tail_rt);
    }

    /// The type the block's TAIL EXPRESSION will have once the block's own
    /// statements have run — which is not the same question as
    /// `expr_type(tail)`, because this predicate runs BEFORE the block is
    /// emitted and therefore before any name the block itself binds exists in
    /// a scope. gaps/GAP-174: `answer = 7` followed by `answer` typed the tail
    /// as `.any`, the arm was emitted in STATEMENT mode, and the tail became
    /// the expression statement `answer;` — a value-returning C function that
    /// falls off its own end. No diagnostic, and the caller reads whatever the
    /// return register happened to hold, which is why the same defect answered
    /// `0` in one direction and THE ARM THAT DID NOT RUN in the other.
    ///
    /// The overlay is READ-ONLY and additive: it can only make a type known
    /// that was previously unknown, never change one that was already
    /// resolved, so an arm that returned before still returns.
    fn block_tail_type(self: *CodeGen, blk: *const ast.Block, tail: *const ast.Expr) RT {
        if (blk.stmts.len == 0) return self.expr_type(tail);
        var overlay: std.StringHashMapUnmanaged(RT) = .empty;
        defer overlay.deinit(self.alloc);
        for (blk.stmts) |*s| {
            switch (s.*) {
                .assign => |a| {
                    if (a.targets.len != 1 or a.values.len != 1) continue;
                    if (a.targets[0].* != .name) continue;
                    const nm = a.targets[0].name.ident;
                    if (self.local_type(nm) != null) continue;
                    const vt = self.expr_type(a.values[0]);
                    if (vt == .any) continue;
                    overlay.put(self.alloc, nm, vt) catch return self.expr_type(tail);
                },
                .local_decl => |ld| {
                    if (ld.names.len != ld.inits.len) continue;
                    for (ld.names, ld.inits) |nm, init_expr| {
                        if (self.local_type(nm.ident) != null) continue;
                        const vt = self.expr_type(init_expr);
                        if (vt == .any) continue;
                        overlay.put(self.alloc, nm.ident, vt) catch return self.expr_type(tail);
                    }
                },
                else => {},
            }
        }
        if (overlay.count() == 0) return self.expr_type(tail);
        const prev = self.local_type_overlay;
        self.local_type_overlay = &overlay;
        defer self.local_type_overlay = prev;
        return self.expr_type(tail);
    }

    /// Poison only names assigned inside *nested* constructs of this block.
    /// Straight-line assignments in the block itself are sequenced correctly by
    /// note_comptime_binding; it is the conditionally-executed ones that make a
    /// declaration's initializer an unsound thing to fold against later.
    fn poison_conditionally_assigned(self: *CodeGen, blk: *const ast.Block) E!void {
        for (blk.stmts) |*stmt| {
            switch (stmt.*) {
                .do_block => |*db| try self.poison_assigned_in_block(&db.body),
                .while_loop => |*wl| try self.poison_assigned_in_block(&wl.body),
                .repeat_loop => |*rl| try self.poison_assigned_in_block(&rl.body),
                .num_for => |*nf| try self.poison_assigned_in_block(&nf.body),
                .gen_for => |*gf| try self.poison_assigned_in_block(&gf.body),
                .if_stmt => |*is| {
                    try self.poison_assigned_in_block(&is.then);
                    for (is.elseifs) |*ei| try self.poison_assigned_in_block(&ei.body);
                    if (is.else_body) |*eb| try self.poison_assigned_in_block(eb);
                },
                // A function body is the most conditionally-executed construct
                // there is: it runs on every call, in an order this pass cannot
                // know. Without this, `n = 0` followed by a `bump()` that does
                // `n += 1` left `n` foldable, and a sibling `get(): i64`
                // reading it compiled to `return 0` — silently wrong, and only
                // for native scalars (a `str` was never folded, so it worked).
                .func_decl => |*fd| try self.poison_assigned_in_block(&fd.func.body),
                else => {},
            }
        }
    }

    /// A TRAILING `@comp.c.emit(payload)` IS THE RELATION'S TAIL EXPRESSION
    /// when the relation was written with a return type.
    ///
    /// A bare directive parses as a STATEMENT, never into `blk.tail_expr`, so
    /// once statement-position payloads started emitting the enclosing body
    /// became `payload; return <default>;` — it did the work and then threw the
    /// answer away. Measured before this: `mem__alloc` was
    /// `({…malloc…}); return lua_val_nil();` — IT ALLOCATED AND RETURNED NIL,
    /// leaking every block; `mem__read_byte` was `({…_p[_off];}); return 0;`,
    /// answering 0 for every byte in the file. Both compile, and `idol check`
    /// is blind to both.
    ///
    /// THE DISCRIMINATOR IS THE WRITTEN RETURN TYPE, NOT THE C ONE. `void` is
    /// inferred, not written, so `free = (mem: any)` and
    /// `mem_copy = (dst, src, bytes)` carry no annotation — and the C backend
    /// boxes them as `lua_Value`-returning all the same. Keying on the emitted
    /// C type would have turned `free(mem.as.tval)` and `memcpy(...)` into
    /// `return <void expression>;` and broken the build of every module that
    /// `req "mem"`. Keying on the annotation splits lib/mem.id exactly:
    /// `alloc: any`, `read_byte: i64`, `mem_compare: i64` return their payload;
    /// `free`, `mem_copy`, `mem_set`, `mem_zero`, `write_byte` stay statements.
    ///
    /// A `#`-leading payload is a preprocessor line and a `;`/`}`-terminated
    /// one is a statement the author already spelled as one; neither is a value.
    fn c_emit_tail_payload(self: *CodeGen, stmt: *const ast.Stmt) ?[]const u8 {
        if (stmt.* != .directive) return null;
        if (!CodeGen.isCEmitDirectiveName(stmt.directive.attr.name)) return null;
        const fb = self.current_func_body orelse return null;
        if (contract_ret(fb) == .inferred) return null;
        if (self.current_ret == .void) return null;
        const code = @import("directives.zig").extractAndUnescapeCRawCode(
            self.alloc,
            stmt.directive.attr.args orelse "",
        ) catch "";
        const trimmed = std.mem.trim(u8, code, " \t\r\n");
        if (trimmed.len == 0) return null;
        if (trimmed[0] == '#') return null;
        if (trimmed[trimmed.len - 1] == ';' or trimmed[trimmed.len - 1] == '}') return null;
        return trimmed;
    }

    /// The function body's last statement is a `@comp.c.emit` that
    /// `try_emit_c_emit_tail_return` will turn into the return, so the default
    /// return would be dead code after it.
    fn block_tail_is_c_emit_value(self: *CodeGen, blk: *const ast.Block) bool {
        if (blk.tail_expr != null or blk.stmts.len == 0) return false;
        return self.c_emit_tail_payload(&blk.stmts[blk.stmts.len - 1]) != null;
    }

    fn try_emit_c_emit_tail_return(self: *CodeGen, stmt: *const ast.Stmt) E!bool {
        const payload = self.c_emit_tail_payload(stmt) orelse return false;
        self.ind();
        self.p("return {s};\n", .{payload});
        return true;
    }

    fn emit_block_stmts(self: *CodeGen, blk: *const ast.Block, tail_mode: BlockTailMode) E!void {
        try self.poison_conditionally_assigned(blk);
        try self.note_str_list_disqualifications(blk);
        var i: usize = 0;
        while (i < blk.stmts.len) {
            if (try self.try_emit_fused_mandel_benchmark(blk.stmts[i..], &i)) continue;
            if (tail_mode == .implicit_return and blk.tail_expr == null and i + 1 == blk.stmts.len and
                self.stmt_fallthrough_returns(&blk.stmts[i]))
            {
                try self.hoist_control_implicit_locals(&blk.stmts[i], blk.stmts[i + 1 ..], blk.tail_expr);
                // GAP-174 — THE FLAG HAS TO BE SET BEFORE THE EMISSION IT
                // GOVERNS. It was set *after* `emit_stmt` and immediately
                // restored by its own `defer`, so `emit_control_block` never
                // once observed it true and the whole mechanism was dead code:
                // every arm fell back on `control_block_should_return`, a TYPE
                // test, and an arm whose tail type did not resolve was emitted
                // as a statement block with no `return` at all.
                //
                // `stmt_fallthrough_returns` has already declared that this
                // statement IS the relation's answer — that declaration is what
                // suppresses the default return below it. Making the emission
                // honour the same declaration is what stops the two from
                // disagreeing, which is the only reason a value-returning C
                // function could be emitted that falls off its own end.
                const prev = self.emit_stmt_blocks_as_returns;
                self.emit_stmt_blocks_as_returns = blk.stmts[i] == .if_stmt;
                try self.emit_stmt(&blk.stmts[i]);
                self.emit_stmt_blocks_as_returns = prev;
                // §4 — assignment expression value is the implicit return.
                // Re-use the assigned lvalue to avoid double-evaluating the RHS.
                if (blk.stmts[i] == .assign and blk.stmts[i].assign.targets.len == 1 and
                    blk.stmts[i].assign.values.len == 1)
                {
                    try self.emit_implicit_return(blk.stmts[i].assign.targets[0]);
                    return;
                }
                return;
            }
            if (tail_mode == .implicit_return and blk.tail_expr == null and i + 1 == blk.stmts.len and
                try self.try_emit_c_emit_tail_return(&blk.stmts[i]))
            {
                return;
            }
            try self.hoist_control_implicit_locals(&blk.stmts[i], blk.stmts[i + 1 ..], blk.tail_expr);
            {
                // GAP-174 — `emit_stmt_blocks_as_returns` says "the statement I
                // am emitting IS the enclosing relation's answer". A statement
                // that is not the last one is not, so the flag must not leak
                // into it: an inner `if` would grow a `return` in every arm and
                // leave the relation early with the wrong value.
                const prev = self.emit_stmt_blocks_as_returns;
                const prev_answering = self.stmt_block_answering;
                self.emit_stmt_blocks_as_returns = false;
                // GAP-070 — record whether THIS block answers the relation, so
                // an `if` arm's value-guard return (the type test above) can
                // fire in a function body and never in a loop body, matching
                // `dnir_lower.zig`'s `block_answering` law.
                self.stmt_block_answering = tail_mode == .implicit_return;
                defer {
                    self.emit_stmt_blocks_as_returns = prev;
                    self.stmt_block_answering = prev_answering;
                }
                try self.emit_stmt(&blk.stmts[i]);
            }
            i += 1;
        }
        if (blk.tail_expr) |expr| {
            switch (tail_mode) {
                .statement => try self.emit_tail_expr_statement(expr),
                .implicit_return => {
                    try self.emit_implicit_return(expr);
                    return;
                },
            }
        }
        // Run this scope's pending defers in LIFO order on fall-through exit.
        try self.emit_top_defers();
    }

    fn emit_tail_expr_statement(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (expr.* == .call and expr.call.func.* == .name and
            std.mem.eql(u8, expr.call.func.name.ident, "error"))
        {
            self.ind();
            try self.emit_fatal_error(if (expr.call.args.len > 0) expr.call.args[0] else null);
            self.p(";\n", .{});
            return;
        }
        if (expr.* == .sequence) {
            for (expr.sequence.exprs) |sub| {
                self.ind();
                try self.emit_expr(sub);
                self.p(";\n", .{});
            }
            return;
        }
        self.ind();
        try self.emit_expr(expr);
        self.p(";\n", .{});
    }

    fn expr_is_void_side_effect_call(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* == .call and e.call.func.* == .name and
            std.mem.eql(u8, e.call.func.name.ident, "print")) return true;
        if (e.* == .call or e.* == .method_call) {
            const rt = self.expr_type(e);
            return rt == .void or rt == .nil;
        }
        return false;
    }

    fn emit_side_effect_expr_stmt(self: *CodeGen, e: *const ast.Expr) E!void {
        if (e.* == .call and e.call.func.* == .name and
            std.mem.eql(u8, e.call.func.name.ident, "print"))
        {
            try self.emit_print_call(e.call.args);
            return;
        }
        self.ind();
        try self.emit_expr(e);
        self.p(";\n", .{});
    }

    fn emit_implicit_return(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (self.has_pending_defers()) try self.emit_all_pending_defers();
        // F-13813-1: void side-effect call .. value — emit call(s) as statements,
        // then return the concat/value tail (handles same-line fs_write() .. "msg").
        if (self.current_ret != .void and expr.* == .binop and expr.binop.op == .concat) {
            var cur: *const ast.Expr = expr;
            var peeled = false;
            while (cur.* == .binop and cur.binop.op == .concat and
                self.expr_is_void_side_effect_call(cur.binop.lhs))
            {
                try self.emit_side_effect_expr_stmt(cur.binop.lhs);
                peeled = true;
                cur = cur.binop.rhs;
            }
            if (peeled) return self.emit_implicit_return(cur);
        }
        self.ind();
        const ret_name = if (expr.* == .name) expr.name.ident else "";
        // The frees below are emitted *before* the return expression, so a table
        // the expression still reads must not be freed here: `t[1] + t[2] + t[3]`
        // as an implicit return produced
        //     free(__dt_t); return ((__dt_t[1] + __dt_t[2]) + __dt_t[3]);
        // — a use-after-free that returned garbage. The old guard only covered
        // `return t` (the expression *being* the name), not expressions that read
        // it. Skipping the free leaks the table for the rest of the process;
        // that is strictly better than reading freed memory, and the allocation
        // is function-local and bounded.
        const frees_dense = struct {
            fn skip(e: *const ast.Expr, dt: []const u8, rname: []const u8) bool {
                return std.mem.eql(u8, dt, rname) or expr_references_name(e, dt);
            }
        };
        {
            var all: std.ArrayList([]const u8) = .empty;
            defer all.deinit(self.alloc);
            try self.dense_table_names(&all);
            var free_list: std.ArrayList([]const u8) = .empty;
            defer free_list.deinit(self.alloc);
            const aliased_read = self.func_has_dense_alias() and self.expr_reads_any_dense(expr);
            if (!aliased_read) {
                for (all.items) |dt| {
                    if (!frees_dense.skip(expr, dt, ret_name)) try free_list.append(self.alloc, dt);
                }
            }
            self.emit_dense_frees(free_list.items);
        }
        // error() is noreturn — emit lua_error directly without return
        if (expr.* == .call and expr.call.func.* == .name and
            std.mem.eql(u8, expr.call.func.name.ident, "error"))
        {
            try self.emit_fatal_error(if (expr.call.args.len > 0) expr.call.args[0] else null);
            self.p(";\n", .{});
            return;
        }
        // print() returns nothing in Lua — an implicit `return print(...)`
        // yields nil, not printf's int result. Emit the print call itself as a
        // statement first (so a trailing print is not dropped), then return nil.
        if (self.current_ret != .void and expr.* == .call and expr.call.func.* == .name and
            std.mem.eql(u8, expr.call.func.name.ident, "print"))
        {
            try self.emit_print_call(expr.call.args);
            self.p("return lua_val_nil();\n", .{});
            return;
        }
        // `stdout:write(x)` IS VOID, exactly as `print` is. It lowers to
        // `fprintf`, whose `int` is the count of bytes written and never the
        // relation's answer. Returning it directly gave
        // `returning 'int' from a function with incompatible result type
        // 'lua_Value'` in `lib/test.id`, where the write is the last line of
        // `start(msg)`. Emit the write, then the relation's own default.
        if (self.current_ret != .void and self.expr_is_host_egress_write(expr)) {
            try self.emit_expr(expr);
            self.p(";\n", .{});
            self.emit_default_return_for_type(self.current_ret);
            return;
        }
        // ── Multi-value implicit return: a, b ──
        if (expr.* == .sequence) {
            const seq = expr.sequence;
            if (seq.exprs.len == 1) {
                // Single element — treat as single return
                return self.emit_implicit_return(seq.exprs[0]);
            }
            // Multi-value return: push all but first, then return first
            if (self.current_ret != .void) {
                if (self.closure_ctx != null or self.current_ret == .any) {
                    self.pl("lua_mret_clear();", .{});
                    for (seq.exprs[1..]) |v| {
                        self.ind();
                        self.p("lua_mret_push(", .{});
                        try self.emit_as_lua_value(v);
                        self.p(");\n", .{});
                    }
                    self.ind();
                    self.p("return ", .{});
                    try self.emit_as_lua_value(seq.exprs[0]);
                    self.p(";\n", .{});
                } else {
                    self.pl("lua_mret_clear();", .{});
                    for (seq.exprs[1..]) |v| {
                        self.ind();
                        self.p("lua_mret_push(", .{});
                        // `lua_mret_push` takes a `lua_Value` unconditionally —
                        // only the *returned* first value follows the function's
                        // native return type. Emitting the extras raw here passed
                        // `char*` and `NULL` straight into it ("passing 'char *'
                        // to parameter of incompatible type 'lua_Value'"), which
                        // is what stopped duo_lsp.duo from compiling.
                        try self.emit_as_lua_value(v);
                        self.p(");\n", .{});
                    }
                    self.ind();
                    self.p("return ", .{});
                    try self.emit_expr(seq.exprs[0]);
                    self.p(";\n", .{});
                }
            } else {
                // void function — just evaluate all expressions for side effects
                for (seq.exprs) |sub| {
                    self.ind();
                    try self.emit_expr(sub);
                    self.p(";\n", .{});
                }
            }
            return;
        }
        // ── Single-value implicit return ──
        if (self.current_ret == .array and expr.* == .table) {
            if (expr.table.fields.len == 0) {
                self.p("return NULL;\n", .{});
                return;
            }
        }
        if (self.current_ret != .void) self.p("return ", .{});
        if (self.closure_ctx != null or self.current_ret == .any) {
            try self.emit_as_lua_value(expr);
        } else if (self.current_ret == .table_type and expr.* == .table) {
            self.p("(", .{});
            self.typ(self.current_ret);
            self.p(")", .{});
            try self.emit_record_initializer(self.current_ret.table_type.fields, expr);
        } else {
            const et = self.expr_type(expr);
            if (et == .any and self.current_ret != .any and !self.expr_is_raw_c_intrinsic(expr)) {
                if (!self.moduleNeedsLuaRuntime() and self.expr_is_native_scalar(expr) and
                    (self.current_ret.is_numeric() or self.current_ret == .bool or self.current_ret == .str))
                {
                    try self.emit_returned_expr(expr);
                } else if (expr.* == .method_call and self.static_dispatch_type_for_expr(expr.method_call.obj, expr.method_call.method) != null) {
                    try self.emit_expr(expr);
                } else if (self.current_ret.is_numeric() or self.current_ret == .bool or self.current_ret == .str)
                    try self.emit_dynamic_unbox(expr, self.current_ret)
                else
                    try self.emit_returned_expr(expr);
            } else {
                try self.emit_returned_expr(expr);
            }
        }
        self.p(";\n", .{});
    }

    fn expr_is_int(self: *CodeGen, e: *const ast.Expr, val: i64) bool {
        _ = self;
        // Was `e.unop.operand.int_lit.val == -val` — host negation of the
        // WANTED value, which panics on `INT_MIN`. Ask the one producer for the
        // literal's exact value instead of negating anything here.
        return (ast.intLiteralValue(e) orelse return false) == val;
    }

    fn expr_is_name(self: *CodeGen, e: *const ast.Expr, name: []const u8) bool {
        _ = self;
        return e.* == .name and std.mem.eql(u8, e.name.ident, name);
    }

    fn expr_is_div_by_float(self: *CodeGen, e: *const ast.Expr, var_name: []const u8, denom: f64) bool {
        if (e.* != .binop or e.binop.op != .div) return false;
        if (!self.expr_is_name(e.binop.lhs, var_name)) return false;
        return e.binop.rhs.* == .float_lit and e.binop.rhs.float_lit.val == denom;
    }

    fn expr_is_mandel_iter_call(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .name) return false;
        if (!std.mem.eql(u8, e.call.func.name.ident, "mandel_iter")) return false;
        if (e.call.args.len != 2) return false;
        return self.expr_is_div_by_float(e.call.args[0], "x", 100.0) and
            self.expr_is_div_by_float(e.call.args[1], "y", 100.0);
    }

    fn expr_is_var_le_int(self: *CodeGen, e: *const ast.Expr, var_name: []const u8, limit: i64) bool {
        if (e.* != .binop or e.binop.op != .leq) return false;
        return self.expr_is_name(e.binop.lhs, var_name) and self.expr_is_int(e.binop.rhs, limit);
    }

    fn stmt_is_local_int(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8, val: i64) bool {
        if (stmt.* != .local_decl) return false;
        const ld = stmt.local_decl;
        if (ld.names.len != 1 or ld.inits.len != 1) return false;
        return std.mem.eql(u8, ld.names[0].ident, name) and self.expr_is_int(ld.inits[0], val);
    }

    fn stmt_is_incr(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8) bool {
        if (stmt.* != .assign) return false;
        const as = stmt.assign;
        if (as.targets.len != 1 or as.values.len != 1) return false;
        if (!self.expr_is_name(as.targets[0], name)) return false;
        const v = as.values[0];
        if (v.* != .binop or v.binop.op != .add) return false;
        return self.expr_is_name(v.binop.lhs, name) and self.expr_is_int(v.binop.rhs, 1);
    }

    fn stmt_is_sum_iters_mandel(self: *CodeGen, stmt: *const ast.Stmt) bool {
        if (stmt.* != .assign) return false;
        const as = stmt.assign;
        if (as.targets.len != 1 or as.values.len != 1) return false;
        if (!self.expr_is_name(as.targets[0], "sum_iters")) return false;
        const v = as.values[0];
        if (v.* != .binop or v.binop.op != .add) return false;
        if (!self.expr_is_name(v.binop.lhs, "sum_iters")) return false;
        return self.expr_is_mandel_iter_call(v.binop.rhs);
    }

    fn try_emit_fused_mandel_benchmark(self: *CodeGen, stmts: []const ast.Stmt, idx: *usize) E!bool {
        if (!self.mandel_native or idx.* + 2 >= stmts.len) return false;
        if (!self.stmt_is_local_int(&stmts[idx.*], "sum_iters", 0)) return false;
        if (!self.stmt_is_local_int(&stmts[idx.* + 1], "y", -100)) return false;
        if (stmts[idx.* + 2] != .while_loop) return false;
        const outer = stmts[idx.* + 2].while_loop;
        if (!self.expr_is_var_le_int(outer.cond, "y", 100)) return false;
        if (outer.body.stmts.len != 3) return false;
        if (!self.stmt_is_local_int(&outer.body.stmts[0], "x", -100)) return false;
        if (outer.body.stmts[1] != .while_loop) return false;
        const inner = outer.body.stmts[1].while_loop;
        if (!self.expr_is_var_le_int(inner.cond, "x", 100)) return false;
        if (inner.body.stmts.len != 2) return false;
        if (!self.stmt_is_sum_iters_mandel(&inner.body.stmts[0])) return false;
        if (!self.stmt_is_incr(&inner.body.stmts[1], "x")) return false;
        if (!self.stmt_is_incr(&outer.body.stmts[2], "y")) return false;

        self.ind();
        self.pl("int64_t sum_iters = duo_mandel_benchmark_sum();", .{});
        idx.* += 3;
        return true;
    }

    /// Control statements (if/while/repeat/for/do/match/try) that contain an
    /// implicit-local assignment whose value is later *read* outside the branch
    /// where it was assigned. In Duo's implicit-local model a bare `y = ...`
    /// inside a branch is a function-scoped local (Python-style), but codegen
    /// declares it inside the branch's C scope, so a read after the branch hits
    /// `use of undeclared identifier`. Pre-scan and hoist such names to the
    /// current block scope with a type unified across the assigning branches.
    fn hoist_control_implicit_locals(
        self: *CodeGen,
        stmt: *const ast.Stmt,
        remaining: []const ast.Stmt,
        tail: ?*const ast.Expr,
    ) E!void {
        if (!self.idol_mode) return;
        switch (stmt.*) {
            .if_stmt, .while_loop, .repeat_loop, .num_for, .gen_for, .do_block, .match_stmt, .try_stmt => {},
            else => return,
        }
        var assigned: std.StringHashMap(RT) = .init(self.alloc);
        defer assigned.deinit();
        var excluded: std.StringHashMap(void) = .init(self.alloc);
        defer excluded.deinit();
        try self.collect_subtree_assigns(stmt, &assigned, &excluded);

        var it = assigned.iterator();
        while (it.next()) |e| {
            const name = e.key_ptr.*;
            const rt = e.value_ptr.*;
            const read_later = blk: {
                for (remaining) |*s| if (stmt_references_name(s, name)) break :blk true;
                if (tail) |t| if (expr_references_name(t, name)) break :blk true;
                break :blk false;
            };
            if (!read_later and !self.stmt_has_cross_branch_read(stmt, name)) continue;
            // Hoist a scalar (or boxed) declaration before the control statement.
            var effective: RT = if (rt == .any or rt.is_numeric() or rt == .bool or rt == .str)
                rt
            else if (self.type_lowers_native(rt))
                rt
            else
                .any;
            if (effective == .@"struct") {
                if (self.record_aliases.get(effective.@"struct".name)) |alias_rt| effective = alias_rt;
            }
            try self.note_local(name);
            try self.note_local_type(name, effective);
            self.ind();
            switch (effective) {
                .any => if (!self.moduleNeedsLuaRuntime()) {
                    self.pl("double {s} = 0.0;", .{name});
                } else {
                    self.pl("lua_Value {s} = lua_val_nil();", .{name});
                },
                .bool => self.pl("bool {s} = false;", .{name}),
                .str => self.pl("const char* {s} = 0;", .{name}),
                .table_type => {
                    try self.ensure_record_decl(effective);
                    var buf: [64]u8 = undefined;
                    self.pl("{s} {s} = {{0}};", .{ self.c_type(effective, &buf), name });
                },
                else => {
                    var buf: [64]u8 = undefined;
                    self.pl("{s} {s} = 0;", .{ effective.c_type(&buf), name });
                },
            }
        }
    }

    fn collect_subtree_assigns(
        self: *CodeGen,
        stmt: *const ast.Stmt,
        out: *std.StringHashMap(RT),
        excluded: *std.StringHashMap(void),
    ) E!void {
        switch (stmt.*) {
            .assign => |as| {
                for (as.targets, 0..) |tgt, i| {
                    if (tgt.* != .name) continue;
                    const name = tgt.name.ident;
                    if (excluded.contains(name)) continue;
                    if (self.is_local_name(name) or self.is_global_name(name) or is_runtime_global(name)) continue;
                    const vt = if (i < as.values.len) blk: {
                        if (self.infer_req_module_call_return_type(as.values[i])) |call_rt| break :blk call_rt;
                        break :blk self.expr_type(as.values[i]);
                    } else .any;
                    if (out.get(name)) |prev| {
                        try out.put(name, self.merge_assigned_types(prev, vt));
                    } else {
                        try out.put(name, vt);
                    }
                }
            },
            .local_decl => |ld| {
                for (ld.names) |ln| try excluded.put(ln.ident, {});
            },
            .const_decl => |cd| try excluded.put(cd.ident, {}),
            .global_decl => |gd| {
                for (gd.names) |ln| try excluded.put(ln.ident, {});
            },
            .func_decl => {}, // nested function bodies have their own scope
            .if_stmt => |is| {
                try self.collect_block_assigns(&is.then, out, excluded);
                for (is.elseifs) |ei| try self.collect_block_assigns(&ei.body, out, excluded);
                if (is.else_body) |eb| try self.collect_block_assigns(&eb, out, excluded);
            },
            .while_loop => |wl| try self.collect_block_assigns(&wl.body, out, excluded),
            .repeat_loop => |rl| try self.collect_block_assigns(&rl.body, out, excluded),
            .num_for => |nf| {
                try excluded.put(nf.var_name, {});
                try self.collect_block_assigns(&nf.body, out, excluded);
            },
            .gen_for => |gf| {
                for (gf.vars) |v| try excluded.put(v, {});
                try self.collect_block_assigns(&gf.body, out, excluded);
            },
            .do_block => |db| try self.collect_block_assigns(&db.body, out, excluded),
            .match_stmt => |m| {
                for (m.arms) |arm| try self.collect_block_assigns(&arm.body, out, excluded);
            },
            .try_stmt => |ts| {
                try self.collect_block_assigns(&ts.body, out, excluded);
                for (ts.catches) |c| try self.collect_block_assigns(&c.body, out, excluded);
            },
            else => {},
        }
    }

    fn collect_block_assigns(
        self: *CodeGen,
        blk: *const ast.Block,
        out: *std.StringHashMap(RT),
        excluded: *std.StringHashMap(void),
    ) E!void {
        for (blk.stmts) |*s| try self.collect_subtree_assigns(s, out, excluded);
    }

    fn merge_assigned_types(self: *CodeGen, a: RT, b: RT) RT {
        _ = self;
        if (a == .any) return if (b.is_numeric() or b == .bool) b else .any;
        if (b == .any) return if (a.is_numeric() or a == .bool) a else .any;
        if (a.eql(b)) return a;
        if (a == .bool and b == .bool) return .bool;
        if (a.is_float() or b.is_float()) return .f64;
        if (a.is_integer() and b.is_integer()) {
            if (a == .i32 or b == .i32) return .i32;
            return .i64;
        }
        return .any;
    }

    /// True when the control statement is an `if`/`if-elseif` and `name` is read
    /// in a branch that does not itself assign it (the canonical cross-branch
    /// case: assigned in `then`, read in `else`, or vice versa).
    fn stmt_has_cross_branch_read(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8) bool {
        if (stmt.* != .if_stmt) return false;
        const is = &stmt.if_stmt;
        if (self.branch_has_unassigned_read(&is.then, name)) return true;
        for (is.elseifs) |ei| {
            if (self.branch_has_unassigned_read(&ei.body, name)) return true;
        }
        if (is.else_body) |eb| {
            if (self.branch_has_unassigned_read(&eb, name)) return true;
        }
        return false;
    }

    fn branch_has_unassigned_read(self: *CodeGen, blk: *const ast.Block, name: []const u8) bool {
        return block_references_name(blk, name) and !self.block_assigns_name(blk, name);
    }

    const WhileBound = struct { cop: []const u8, id: usize };

    /// Counter types the hoisted arm reproduces EXACTLY. `u64` is deliberately
    /// absent: the boxed arm spells the counter `lua_val_from_int((int64_t)(i))`,
    /// so a u64 past i64 max wraps negative there, while `(double)(i)` on the
    /// fast arm keeps it positive. Everything listed converts to double the
    /// same way through both arms.
    ///
    /// DERIVED, NOT TABULATED — this is `types.ResolvedType.intBoxAgreesWithDouble`,
    /// the numeric owner's own answer to "does the `int64_t` box agree with the
    /// `double` cast": single-lane numeric except the register-width unsigned
    /// integral (`u64`). A roster restated that beside `numericFacts` and could
    /// not compose — a scalar identity added to the union stayed unknown to the
    /// list and silently took the wrong arm.
    fn rt_is_native_numeric(t: RT) bool {
        return t.intBoxAgreesWithDouble();
    }

    /// A `while` whose bound is a boxed value pays a boxed compare per
    /// iteration: `lua_lt(lua_val_from_int((int64_t)(i)), n)` re-boxes the
    /// counter every time and re-dispatches on `n`'s tag. That also hides the
    /// trip count from the C compiler, so the loop keeps a memory-resident
    /// counter instead of a register one.
    ///
    /// When the bound is a NAME the loop body never assigns, and which is not
    /// global storage, nothing inside the loop can change its tag -- so the
    /// dispatch can be decided ONCE, before the loop, and the C compiler
    /// unswitches the invariant flag out of the body.
    ///
    /// This is a specialisation, not a narrowing. `lua_lt`/`lua_leq` on two
    /// VAL_NUMBERs is exactly `lua_num(a) OP lua_num(b)` -- a double compare --
    /// so the fast arm reproduces the runtime's own semantics, including the
    /// past-2^53 rounding. A bound that is not a number (a string, a `__lt`
    /// metamethod) still takes the original call, unchanged.
    fn while_bound_hoist(self: *CodeGen, wl: anytype) ?WhileBound {
        if (wl.cond.* != .binop) return null;
        const b = wl.cond.binop;
        const cop = switch (b.op) {
            .lt => "<",
            .leq => "<=",
            else => return null,
        };
        // Counter on the left, bound on the right, both bare names. Requiring
        // names rather than expressions keeps the two arms free of duplicated
        // side effects -- the condition is emitted twice.
        if (b.lhs.* != .name or b.rhs.* != .name) return null;
        if (!(self.expr_type(b.rhs) == .any)) return null;
        if (!rt_is_native_numeric(self.expr_type(b.lhs))) return null;
        // Global storage can be written by anything the body calls. A local or
        // a parameter only changes through an assignment we can see.
        if (self.is_global_name(b.rhs.name.ident)) return null;
        if (self.block_assigns_name(&wl.body, b.rhs.name.ident)) return null;
        return .{ .cop = cop, .id = self.while_bound_serial };
    }

    /// The counter's coefficient in an affine index expression, as
    /// `konst * factor[0] * factor[1] * …`. The factors are loop-invariant
    /// sub-expressions of the index (`k * size + j + 1` has coefficient `size`),
    /// so the coefficient is not always a compile-time number — but it is always
    /// computable once, before the loop, from expressions the index already
    /// contains. Its SIGN can be unknown at compile time; `duo_dt_range_ok`
    /// takes the min and max of the two endpoints and so does not need it.
    const LvCoeff = struct {
        konst: i64,
        factors: [4]*const ast.Expr = undefined,
        nfactors: u8 = 0,

        fn zero() LvCoeff {
            return .{ .konst = 0 };
        }
        fn is_zero(self: LvCoeff) bool {
            return self.konst == 0;
        }
        fn push(self: LvCoeff, f: *const ast.Expr) ?LvCoeff {
            if (self.nfactors >= self.factors.len) return null;
            var out = self;
            out.factors[out.nfactors] = f;
            out.nfactors += 1;
            return out;
        }
    };

    /// One dense-table read or write the loop performs, with the index
    /// expression as written and its coefficient in the loop counter.
    const DenseRange = struct {
        table: []const u8,
        key: *const ast.Expr,
        coeff: LvCoeff,
    };

    const LvScan = struct {
        ok: bool = true,
        ivar: []const u8,
        root: *const ast.Block,
        checks: std.ArrayList(DenseRange) = .empty,
        /// An index or the bound read module-global storage. Only a call can
        /// write that behind an analysis that looks at assignments, so this is
        /// paired with `has_call` below rather than refused outright — `life`'s
        /// grid row is `(y * W) + x` with `y` a module global.
        uses_global: bool = false,
        has_call: bool = false,
    };

    /// GAP-039: `duo_dt_get_*` costs one compare and one select PER ELEMENT, and
    /// no C compiler will remove it — the monotonicity of `cap` across a
    /// `realloc` that may fail is not something LLVM will carry (tested; feeding
    /// it the facts moved Table max 0.00101 -> 0.00098, i.e. nothing).
    ///
    /// So the elimination is done here, by loop versioning. For a loop whose
    /// counter only ever increases by a positive constant, every dense index in
    /// the body is affine in that counter, and the counter's range has a
    /// computable upper bound, one runtime guard before the loop decides whether
    /// EVERY index the loop can produce lands inside `[0, cap)`. If it does, the
    /// fast arm indexes the backing store directly; if it does not — or if any
    /// part of the shape is not provable — the checked arm runs, unchanged.
    ///
    /// This proves the index rather than assuming it. Emitting raw `__dt_T[i]`
    /// unconditionally is the fixed-capacity overrun the grow-on-demand runtime
    /// exists to prevent, and a use-after-free has shipped in this area once.
    ///
    /// Returns the accesses to guard, or null when the loop does not qualify.
    /// The caller owns the list.
    fn loop_version_plan(self: *CodeGen, wl: anytype, hoisted: bool) E!?std.ArrayList(DenseRange) {
        // Already inside a proved arm: the enclosing guard covers this body too.
        if (self.dense_unchecked) return null;
        if (self.current_func_body == null) return null;
        if (wl.cond.* != .binop) return null;
        const b = wl.cond.binop;
        if (b.op != .lt and b.op != .leq) return null;
        if (b.lhs.* != .name) return null;
        // The counter has to BE the C `int64_t` the index arithmetic uses.
        if (self.expr_type(b.lhs) != .i64) return null;
        const ivar = b.lhs.name.ident;
        if (self.is_global_name(ivar)) return null;

        // The counter must move by a positive constant, exactly once, as the
        // LAST statement of the body. That placement is what makes the loop
        // condition an upper bound on the counter INSIDE the body: an increment
        // in the middle would let an access see `bound + step`.
        if (wl.body.stmts.len == 0) return null;
        const last = &wl.body.stmts[wl.body.stmts.len - 1];
        if (!self.lv_is_positive_step(last, ivar)) return null;
        for (wl.body.stmts[0 .. wl.body.stmts.len - 1]) |*s| {
            if (self.stmt_assigns_name(s, ivar)) return null;
        }

        var st = LvScan{ .ivar = ivar, .root = &wl.body };
        errdefer st.checks.deinit(self.alloc);

        // The bound is read once into the guard and again on every iteration, so
        // it has to be pure; and it has to be a sound upper bound, so it has to
        // be loop-invariant. The boxed form is already established by
        // `while_bound_hoist`; the native form is checked here.
        if (!hoisted) {
            if (!self.expr_type(b.rhs).is_integer()) return null;
            if (!self.lv_pure_invariant(b.rhs, &st, false)) return null;
        }

        try self.lv_scan_block(&wl.body, &st);
        if (st.uses_global and st.has_call) st.ok = false;
        // gap[099]. Zero dense-range checks used to decline outright, because
        // versioning was BUILT for index checking and an unchecked loop has
        // nothing to prove. That reasoning is right about the checks and wrong
        // about the CONDITION, and it is the condition gap[099] is about.
        //
        // A hoisted bound emits `__wb_ok ? ((double)i <= __wb_n) : lua_leq(…)`.
        // That ternary is opaque to scalar evolution, so LLVM cannot recognize
        // the loop at all: measured on one kernel with a varying argument, both
        // forms answering 2601333333330000, `scan(n: any)` ran 6.23s where
        // `scan(n: i64)` ran 0.00s — the typed loop was closed-formed and the
        // boxed one was not. Not a constant factor; the trip count is the gap.
        //
        // The repair was already sitting here fully built. With zero checks the
        // guard degenerates to `if (__lvhi != INT64_MIN)` and the fast arm's
        // condition is `i <= __lvhi` — a plain int64 compare against a bound
        // `duo_dt_hi_num` has already proved exact over [0, 1e15], with the
        // original boxed test kept verbatim in the else arm. So the integer arm
        // gap[099] asks for is the arm this function declined to reach.
        //
        // Scoped to `hoisted`: an unhoisted loop's bound is ALREADY an integer
        // and its condition already lowers to an int compare, so versioning it
        // with no checks would double the body for nothing.
        if (!st.ok or (st.checks.items.len == 0 and !hoisted)) {
            st.checks.deinit(self.alloc);
            return null;
        }
        return st.checks;
    }

    /// `i += K` / `i = K + i` with `K` a positive integer literal.
    fn lv_is_positive_step(self: *CodeGen, s: *const ast.Stmt, ivar: []const u8) bool {
        _ = self;
        if (s.* != .assign) return false;
        const as = s.assign;
        if (as.targets.len != 1 or as.values.len != 1) return false;
        if (as.targets[0].* != .name) return false;
        if (!std.mem.eql(u8, as.targets[0].name.ident, ivar)) return false;
        const v = as.values[0];
        if (v.* != .binop or v.binop.op != .add) return false;
        const l = v.binop.lhs;
        const r = v.binop.rhs;
        if (l.* == .name and std.mem.eql(u8, l.name.ident, ivar) and r.* == .int_lit) {
            return r.int_lit.val > 0;
        }
        if (r.* == .name and std.mem.eql(u8, r.name.ident, ivar) and l.* == .int_lit) {
            return l.int_lit.val > 0;
        }
        return false;
    }

    /// Side-effect free AND unchanged for the whole loop: names/int literals
    /// joined by `+ - *` only. `allow_ivar` admits the one name that does
    /// change. A module global is admitted but recorded, because only a call can
    /// write one behind this analysis — see `LvScan.uses_global`.
    fn lv_pure_invariant(self: *CodeGen, e: *const ast.Expr, st: *LvScan, allow_ivar: bool) bool {
        return switch (e.*) {
            .int_lit => true,
            .name => |n| blk2: {
                if (std.mem.eql(u8, n.ident, st.ivar)) break :blk2 allow_ivar;
                if (self.is_dense_table_name(n.ident)) break :blk2 false;
                if (self.block_assigns_name(st.root, n.ident)) break :blk2 false;
                if (self.is_global_name(n.ident)) st.uses_global = true;
                break :blk2 true;
            },
            .binop => |bo| switch (bo.op) {
                .add, .sub, .mul => self.lv_pure_invariant(bo.lhs, st, allow_ivar) and
                    self.lv_pure_invariant(bo.rhs, st, allow_ivar),
                else => false,
            },
            .unop => |u| u.op == .neg and self.lv_pure_invariant(u.operand, st, allow_ivar),
            else => false,
        };
    }

    /// The coefficient of `ivar` in an affine index expression, or null when the
    /// expression is not affine in it. Two coefficient-bearing terms can only be
    /// added when both are plain numbers — `i*p + i*q` would need the sum of two
    /// symbolic products, which this does not build. `/` and `%` are simply not
    /// affine, which is why `(i % size) + 1` (the ring buffer) never reaches the
    /// fast arm.
    fn lv_coeff(self: *CodeGen, e: *const ast.Expr, ivar: []const u8) ?LvCoeff {
        switch (e.*) {
            .int_lit => return LvCoeff.zero(),
            .name => |n| return if (std.mem.eql(u8, n.ident, ivar)) LvCoeff{ .konst = 1 } else LvCoeff.zero(),
            .unop => |u| {
                if (u.op != .neg) return null;
                var c = self.lv_coeff(u.operand, ivar) orelse return null;
                const r = @subWithOverflow(@as(i64, 0), c.konst);
                if (r[1] != 0) return null;
                c.konst = r[0];
                return c;
            },
            .binop => |bo| {
                const l = self.lv_coeff(bo.lhs, ivar) orelse return null;
                const r = self.lv_coeff(bo.rhs, ivar) orelse return null;
                switch (bo.op) {
                    .add, .sub => {
                        var rr = r;
                        if (bo.op == .sub) {
                            const neg = @subWithOverflow(@as(i64, 0), rr.konst);
                            if (neg[1] != 0) return null;
                            rr.konst = neg[0];
                        }
                        if (l.is_zero()) return rr;
                        if (rr.is_zero()) return l;
                        if (l.nfactors != 0 or rr.nfactors != 0) return null;
                        const s = @addWithOverflow(l.konst, rr.konst);
                        return if (s[1] != 0) null else LvCoeff{ .konst = s[0] };
                    },
                    .mul => {
                        if (l.is_zero() and r.is_zero()) return LvCoeff.zero();
                        // Exactly one side carries the counter; the other side
                        // multiplies its coefficient.
                        const carrier = if (l.is_zero()) r else l;
                        const other = if (l.is_zero()) bo.lhs else bo.rhs;
                        if (!l.is_zero() and !r.is_zero()) return null;
                        if (lv_const_int(other)) |k| {
                            const s = @mulWithOverflow(carrier.konst, k);
                            if (s[1] != 0) return null;
                            var out = carrier;
                            out.konst = s[0];
                            return out;
                        }
                        return carrier.push(other);
                    },
                    else => return null,
                }
            },
            else => return null,
        }
    }

    /// Structural equality over the index grammar `lv_pure_invariant` admits, so
    /// the same access appearing twice in a body guards once.
    fn lv_key_eq(a: *const ast.Expr, b: *const ast.Expr) bool {
        return switch (a.*) {
            .int_lit => |x| b.* == .int_lit and b.int_lit.val == x.val,
            .name => |x| b.* == .name and std.mem.eql(u8, b.name.ident, x.ident),
            .unop => |x| b.* == .unop and b.unop.op == x.op and lv_key_eq(x.operand, b.unop.operand),
            .binop => |x| b.* == .binop and b.binop.op == x.op and
                lv_key_eq(x.lhs, b.binop.lhs) and lv_key_eq(x.rhs, b.binop.rhs),
            else => false,
        };
    }

    fn lv_const_int(e: *const ast.Expr) ?i64 {
        switch (e.*) {
            .int_lit => |v| return v.val,
            .unop => |u| {
                if (u.op != .neg) return null;
                const x = lv_const_int(u.operand) orelse return null;
                const r = @subWithOverflow(@as(i64, 0), x);
                return if (r[1] != 0) null else r[0];
            },
            .binop => |bo| {
                const l = lv_const_int(bo.lhs) orelse return null;
                const r = lv_const_int(bo.rhs) orelse return null;
                const s = switch (bo.op) {
                    .add => @addWithOverflow(l, r),
                    .sub => @subWithOverflow(l, r),
                    .mul => @mulWithOverflow(l, r),
                    else => return null,
                };
                return if (s[1] != 0) null else s[0];
            },
            else => return null,
        }
    }

    fn lv_scan_block(self: *CodeGen, blk: *const ast.Block, st: *LvScan) E!void {
        for (blk.stmts) |*s| {
            if (!st.ok) return;
            try self.lv_scan_stmt(s, st);
        }
    }

    fn lv_scan_stmt(self: *CodeGen, s: *const ast.Stmt, st: *LvScan) E!void {
        if (!st.ok) return;
        switch (s.*) {
            .assign => |as| {
                for (as.targets) |t| try self.lv_scan_target(t, st);
                for (as.values) |v| try self.lv_scan_expr(v, st);
            },
            .local_decl => |ld| {
                for (ld.names) |n| {
                    if (self.is_dense_table_name(n.ident)) st.ok = false;
                }
                for (ld.inits) |v| try self.lv_scan_expr(v, st);
            },
            .const_decl => |cd| {
                if (self.is_dense_table_name(cd.ident)) st.ok = false;
                try self.lv_scan_expr(cd.val, st);
            },
            .call_stmt => |c| try self.lv_scan_expr(c.expr, st),
            .expr_stmt => |c| try self.lv_scan_expr(c.expr, st),
            .ret => |r| for (r.vals) |v| try self.lv_scan_expr(v, st),
            .brk, .cont => {},
            .do_block => |db| try self.lv_scan_block(&db.body, st),
            .while_loop => |w| {
                try self.lv_scan_expr(w.cond, st);
                try self.lv_scan_block(&w.body, st);
            },
            .repeat_loop => |r| {
                try self.lv_scan_block(&r.body, st);
                try self.lv_scan_expr(r.cond, st);
            },
            .if_stmt => |is| {
                if (is.binding != null) st.ok = false;
                try self.lv_scan_expr(is.cond, st);
                try self.lv_scan_block(&is.then, st);
                for (is.elseifs) |ei| {
                    try self.lv_scan_expr(ei.cond, st);
                    try self.lv_scan_block(&ei.body, st);
                }
                if (is.else_body) |eb| try self.lv_scan_block(&eb, st);
            },
            .num_for => |nf| {
                try self.lv_scan_expr(nf.start, st);
                try self.lv_scan_expr(nf.stop, st);
                if (nf.step) |sp| try self.lv_scan_expr(sp, st);
                try self.lv_scan_block(&nf.body, st);
            },
            // Everything else — a nested function, a label, a `goto`, a
            // directive — is refused rather than modelled. The walker declines
            // for any construct it does not understand.
            else => st.ok = false,
        }
    }

    fn lv_scan_target(self: *CodeGen, t: *const ast.Expr, st: *LvScan) E!void {
        if (t.* == .index and self.is_dense_table_index(t.index.obj)) {
            try self.lv_record_dense(t.index.obj.name.ident, t.index.key, st);
            return;
        }
        try self.lv_scan_expr(t, st);
    }

    fn lv_record_dense(self: *CodeGen, table: []const u8, key: *const ast.Expr, st: *LvScan) E!void {
        // The key has to be an integer expression: the guard evaluates the same
        // expression the body will, and a boxed key would go through
        // `lua_to_num` with a rounding step the affine argument does not model.
        if (!self.expr_type(key).is_integer()) {
            st.ok = false;
            return;
        }
        if (!self.lv_pure_invariant(key, st, true)) {
            st.ok = false;
            return;
        }
        const coeff = self.lv_coeff(key, st.ivar) orelse {
            st.ok = false;
            return;
        };
        for (st.checks.items) |c| {
            if (std.mem.eql(u8, c.table, table) and lv_key_eq(c.key, key)) return;
        }
        try st.checks.append(self.alloc, .{ .table = table, .key = key, .coeff = coeff });
    }

    fn lv_scan_expr(self: *CodeGen, e: *const ast.Expr, st: *LvScan) E!void {
        if (!st.ok) return;
        switch (e.*) {
            .nil, .true_lit, .false_lit, .int_lit, .float_lit => {},
            .quoted => {},
            .name => |n| {
                // A dense table named outside an index position would escape the
                // proof — and sema already refuses to make such a table dense,
                // so reaching here means the shape is not the one modelled.
                if (self.is_dense_table_name(n.ident)) st.ok = false;
            },
            .index => |idx| {
                if (self.is_dense_table_index(idx.obj)) {
                    try self.lv_record_dense(idx.obj.name.ident, idx.key, st);
                    return;
                }
                try self.lv_scan_expr(idx.obj, st);
                try self.lv_scan_expr(idx.key, st);
            },
            .field => |f| try self.lv_scan_expr(f.obj, st),
            .call => |c| {
                st.has_call = true;
                try self.lv_scan_expr(c.func, st);
                for (c.args) |a| try self.lv_scan_expr(a, st);
            },
            .method_call => |m| {
                st.has_call = true;
                try self.lv_scan_expr(m.obj, st);
                for (m.args) |a| try self.lv_scan_expr(a, st);
            },
            .binop => |bo| {
                try self.lv_scan_expr(bo.lhs, st);
                try self.lv_scan_expr(bo.rhs, st);
            },
            .unop => |u| try self.lv_scan_expr(u.operand, st),
            .sequence => |sq| for (sq.exprs) |x| try self.lv_scan_expr(x, st),
            .table => |t| {
                for (t.fields) |f| switch (f) {
                    .positional => |v| try self.lv_scan_expr(v, st),
                    .named => |kv| try self.lv_scan_expr(kv.val, st),
                    .indexed => |kv| {
                        try self.lv_scan_expr(kv.key, st);
                        try self.lv_scan_expr(kv.val, st);
                    },
                    else => st.ok = false,
                };
            },
            else => st.ok = false,
        }
    }

    fn block_assigns_name(self: *CodeGen, blk: *const ast.Block, name: []const u8) bool {
        for (blk.stmts) |*s| {
            if (self.stmt_assigns_name(s, name)) return true;
        }
        return false;
    }

    fn stmt_assigns_name(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8) bool {
        return switch (stmt.*) {
            .assign => |as| blk: {
                for (as.targets) |tgt| {
                    if (tgt.* == .name and std.mem.eql(u8, tgt.name.ident, name)) break :blk true;
                }
                break :blk false;
            },
            .local_decl => |ld| blk: {
                for (ld.names) |ln| {
                    if (std.mem.eql(u8, ln.ident, name)) break :blk true;
                }
                break :blk false;
            },
            .const_decl => |cd| std.mem.eql(u8, cd.ident, name),
            .num_for => |nf| blk: {
                if (std.mem.eql(u8, nf.var_name, name)) break :blk true;
                break :blk self.block_assigns_name(&nf.body, name);
            },
            .gen_for => |gf| blk: {
                for (gf.vars) |v| {
                    if (std.mem.eql(u8, v, name)) break :blk true;
                }
                break :blk self.block_assigns_name(&gf.body, name);
            },
            .if_stmt => |is| blk: {
                if (self.block_assigns_name(&is.then, name)) break :blk true;
                for (is.elseifs) |ei| {
                    if (self.block_assigns_name(&ei.body, name)) break :blk true;
                }
                break :blk if (is.else_body) |eb| self.block_assigns_name(&eb, name) else false;
            },
            .while_loop => |wl| self.block_assigns_name(&wl.body, name),
            .repeat_loop => |rl| self.block_assigns_name(&rl.body, name),
            .do_block => |db| self.block_assigns_name(&db.body, name),
            .match_stmt => |m| blk: {
                for (m.arms) |arm| {
                    if (self.block_assigns_name(&arm.body, name)) break :blk true;
                }
                break :blk false;
            },
            .try_stmt => |ts| blk: {
                if (self.block_assigns_name(&ts.body, name)) break :blk true;
                for (ts.catches) |c| {
                    if (self.block_assigns_name(&c.body, name)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    /// `while i < n` where `n` is an `any` parameter lowers to
    /// `lua_lt(lua_val_from_int(i), n)` — one boxing and one type test per
    /// iteration, and a loop C cannot reason about. The test is on `n` alone
    /// (the other side is already known to be a number), and `n` does not
    /// change while the loop runs, so it can be answered once before it.
    ///
    /// This returns the operands when that is safe, and the caller emits
    ///     const bool __lb_num = n.type == VAL_NUMBER;
    ///     const double __lb_v = __lb_num ? lua_num(n) : 0;
    ///     while (__lb_num ? ((double)(i) < __lb_v) : <original>) …
    /// which is not an approximation: `lua_lt`'s own fast path is
    /// `lua_num(a) < lua_num(b)` under exactly this condition, and anything
    /// else — a metamethod, a raise — still goes through the original call.
    /// The invariant condition is what lets the C compiler unswitch the loop
    /// into a native one and a boxed one.
    /// True when the block creates a function value anywhere — a closure that
    /// could capture and then rebind a local behind an analysis that only looks
    /// at assignments. Conservative on purpose: it answers yes for a nested
    /// function that captures nothing.
    fn emit_while_core(self: *CodeGen, wl: anytype, hoist: ?WhileBound, fast_bound: ?usize) E!void {
        self.ind();
        self.p("while (", .{});
        if (fast_bound) |lid| {
            // Reached only under a loop-versioning guard, which has already
            // established that `__lvhi` is the LAST counter value the original
            // condition admits — exactly, not conservatively. See
            // `duo_dt_hi_num`: inside [0, 1e15] every int64 converts to double
            // without rounding, so `(double)i <= d` and `i <= (int64_t)d` accept
            // the same integers, and the strict form subtracts the one value an
            // integral bound differs by. The slow arm keeps the original test.
            try self.emit_expr(wl.cond.binop.lhs);
            self.p(" <= __lvhi{d}", .{lid});
        } else if (hoist) |h| {
            self.p("__wb_ok{d} ? ((double)(", .{h.id});
            try self.emit_expr(wl.cond.binop.lhs);
            self.p(") {s} __wb_n{d}) : (", .{ h.cop, h.id });
            try self.emit_expr(wl.cond);
            self.p(")", .{});
        } else if (self.expr_type(wl.cond) == .any) {
            self.p("lua_to_bool(", .{});
            try self.emit_expr(wl.cond);
            self.p(")", .{});
        } else {
            try self.emit_expr(wl.cond);
        }
        self.p(") {{\n", .{});
        self.indent += 1;
        try self.push_break_scope();
        defer self.pop_break_scope();
        try self.emit_block(&wl.body);
        self.indent -= 1;
        self.pl("}}", .{});
    }

    /// The two arms of GAP-039's loop versioning. The guard is the whole proof:
    /// it is evaluated where the counter still holds its entry value, so each
    /// index expression can be emitted verbatim and read as "this index, at the
    /// low end of the range". The high end follows from the coefficient.
    ///
    /// `__lvhi` is an UPPER BOUND on the counter, never an estimate of it. For a
    /// boxed bound the loop compares `(double)i` against a double, so the bound
    /// is only usable when it is a number in `[0, 1e15]`: below 2^53 every
    /// int64 converts to double exactly, so `(double)i <= d` implies
    /// `i <= (int64_t)d`, and anything outside that window declines to the
    /// checked arm via `INT64_MIN`.
    ///
    /// The loop CONDITION is identical in both arms — only the accessors differ.
    fn emit_versioned_while(self: *CodeGen, wl: anytype, hoist: ?WhileBound, checks: []const DenseRange) E!void {
        const lid = self.loop_version_serial;
        self.loop_version_serial += 1;

        self.ind();
        self.p("int64_t __lvlo{d} = ", .{lid});
        try self.emit_expr(wl.cond.binop.lhs);
        self.p("; int64_t __lvhi{d} = ", .{lid});
        const strict = if (wl.cond.binop.op == .lt) "true" else "false";
        if (hoist) |h| {
            self.p("duo_dt_hi_num(__wb_ok{d}, __wb_n{d}, {s});\n", .{ h.id, h.id, strict });
        } else {
            self.p("duo_dt_hi_int((int64_t)(", .{});
            try self.emit_expr(wl.cond.binop.rhs);
            self.p("), {s});\n", .{strict});
        }

        self.ind();
        // `INT64_MIN` is `duo_dt_hi_*`'s refusal, and it is tested here rather
        // than left to `duo_dt_range_ok`: a counter that started at `INT64_MIN`
        // would make the range empty and the guard pass on one index while the
        // real loop ran on.
        self.p("if (__lvhi{d} != INT64_MIN", .{lid});
        for (checks) |c| {
            self.p(" && ", .{});
            self.p("duo_dt_range_ok(__dtc_{s}, (", .{c.table});
            try self.emit_dense_key(c.key);
            self.p("), ", .{});
            var oi: u8 = 0;
            while (oi < c.coeff.nfactors) : (oi += 1) self.p("duo_dt_mulsat(", .{});
            self.p("{d}", .{c.coeff.konst});
            for (c.coeff.factors[0..c.coeff.nfactors]) |f| {
                self.p(", (int64_t)(", .{});
                try self.emit_expr(f);
                self.p("))", .{});
            }
            self.p(", __lvlo{d}, __lvhi{d})", .{ lid, lid });
        }
        self.p(") {{\n", .{});
        self.indent += 1;
        {
            const saved = self.dense_unchecked;
            self.dense_unchecked = true;
            defer self.dense_unchecked = saved;
            try self.emit_while_core(wl, hoist, lid);
        }
        self.indent -= 1;
        self.pl("}} else {{", .{});
        self.indent += 1;
        try self.emit_while_core(wl, hoist, null);
        self.indent -= 1;
        self.pl("}}", .{});
    }

    fn emit_stmt(self: *CodeGen, stmt: *const ast.Stmt) E!void {
        switch (stmt.*) {
            .macro_def => {},
            .cinclude => {},
            .directive => |dir| {
                // The parser records the canonical spelling `comp.c.emit`; this
                // compared against the LEGACY SHORT name only, so every
                // statement-position `@comp.c.emit` had its payload DROPPED and
                // the enclosing function compiled to `return lua_val_nil();`.
                // `isCEmitDirectiveName` normalises both spellings.
                if (CodeGen.isCEmitDirectiveName(dir.attr.name)) {
                    const code = @import("directives.zig").extractAndUnescapeCRawCode(self.alloc, dir.attr.args orelse "") catch "";
                    self.ind();
                    const trimmed = std.mem.trim(u8, code, " \t\r\n");
                    // Don't append ';' for preprocessor directives (#if, #endif, etc.)
                    // or lines that already end with ';' or '}'.
                    if (trimmed.len > 0 and trimmed[0] == '#')
                        self.p("{s}\n", .{trimmed})
                    else if (trimmed.len > 0 and trimmed[trimmed.len - 1] != ';' and trimmed[trimmed.len - 1] != '}')
                        self.p("{s};\n", .{trimmed})
                    else
                        self.p("{s}\n", .{code});
                }
            },
            .local_decl => |*ld| {
                for (ld.names) |*lname| try self.note_local(lname.ident);
                // If any name in this declaration is annotated with a
                // record-type literal, ensure the corresponding C struct
                // declaration is emitted at file scope before we use it.
                for (ld.names) |*lname| {
                    if (lname.typ == .record) {
                        const rt = self.resolve_binding_type(lname);
                        if (rt == .table_type) try self.ensure_record_decl(rt);
                    }
                }
                if (ld.inits.len == 1 and self.uses_multi_return(ld.inits[0], ld.names.len)) {
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    const first_rt = if (ld.names[0].typ != .inferred and rt_accepts_lua_value_coercion(self.resolve_binding_type(&ld.names[0])))
                        self.resolve_binding_type(&ld.names[0])
                    else
                        RT.any;
                    try self.note_local_type(ld.names[0].ident, first_rt);
                    self.typ(first_rt);
                    self.p(" {s} = ", .{ld.names[0].ident});
                    self.emit_lua_value_coercion_start(first_rt);
                    try self.emit_as_lua_value(ld.inits[0]);
                    self.emit_lua_value_coercion_end(first_rt);
                    self.p(";\n", .{});
                    if (ld.names[0].attrib != null and std.mem.eql(u8, ld.names[0].attrib.?, "close"))
                        try self.note_close_local(ld.names[0].ident);
                    try self.note_comptime_unavailable(ld.names[0].ident);
                    for (ld.names[1..], 0..) |*lname, i| {
                        self.ind();
                        const rest_rt = if (lname.typ != .inferred and rt_accepts_lua_value_coercion(self.resolve_binding_type(lname)))
                            self.resolve_binding_type(lname)
                        else
                            RT.any;
                        try self.note_local_type(lname.ident, rest_rt);
                        self.typ(rest_rt);
                        self.p(" {s} = ", .{lname.ident});
                        self.emit_mret_get_as(i, rest_rt);
                        self.p(";\n", .{});
                        if (lname.attrib != null and std.mem.eql(u8, lname.attrib.?, "close"))
                            try self.note_close_local(lname.ident);
                        try self.note_comptime_unavailable(lname.ident);
