                    // Literal-init table with all-int/float positional fields:
                    // emit a native static array instead of lua_table_new.
                    if (i < ld.inits.len and ld.inits[i].* == .table and ld.inits[i].table.fields.len > 0) {
                        const fields = ld.inits[i].table.fields;
                        var all_literal = true;
                        var is_float = false;
                        for (fields) |f| {
                            const v = switch (f) {
                                .positional => |val| val,
                                else => {
                                    all_literal = false;
                                    break;
                                },
                            };
                            if (v.* == .float_lit) {
                                is_float = true;
                            } else if (v.* != .int_lit) {
                                all_literal = false;
                                break;
                            }
                        }
                        if (all_literal) {
                            const elem_type: []const u8 = if (is_float) "double" else "int64_t";
                            // Emit static array + populate.
                            self.ind();
                            self.p("{s} {s}[{d}] = {{", .{ elem_type, lname.ident, fields.len + 1 });
                            // Element 0 is unused (Lua 1-based indexing).
                            self.p("0", .{});
                            for (fields) |f| {
                                const v = switch (f) {
                                    .positional => |val| val,
                                    else => unreachable,
                                };
                                self.p(", ", .{});
                                switch (v.*) {
                                    .int_lit => |il| self.emit_c_int_literal(il.val),
                                    .float_lit => |fl| self.p("{e}", .{fl.val}),
                                    else => self.p("0", .{}),
                                }
                            }
                            self.p("}};\n", .{});
                            try self.note_local_type(lname.ident, if (is_float) .f64 else .i64);
                            try self.note_comptime_unavailable(lname.ident);
                            continue;
                        }
                    }
                    if (i < ld.inits.len) {
                        if (req_path_from_expr(ld.inits[i])) |path| {
                            try self.try_register_req_binding(lname.ident, path);
                            if (self.idol_mode and self.req_module_skips_lua_binding(path)) {
                                try self.mark_req_native_direct(lname.ident);
                                try self.note_comptime_unavailable(lname.ident);
                                const promoted_module_local = (self.current_module_cname.len > 0 or self.at_module_top_level) and
                                    !is_runtime_global(lname.ident) and
                                    self.global_type(lname.ident) != null;
                                if (!promoted_module_local) continue;
                            }
                        }
                    }
                    self.ind();
                    // Determine type
                    const rt: RT = blk: {
                        if (lname.typ != .inferred) {
                            break :blk self.resolve_binding_type(lname);
                        }
                        if (i < ld.inits.len) {
                            const init_rt = self.expr_type(ld.inits[i]);
                            if (init_rt != .any and init_rt != .nil) break :blk init_rt;
                            if (self.infer_req_module_call_return_type(ld.inits[i])) |call_rt| break :blk call_rt;
                            break :blk init_rt;
                        }
                        break :blk .any;
                    };
                    const promoted_module_local = (self.current_module_cname.len > 0 or self.at_module_top_level) and
                        !is_runtime_global(lname.ident) and
                        self.global_type(lname.ident) != null;
                    if (!promoted_module_local) try self.note_local_type(lname.ident, if (rt == .nil) .any else rt);
                    if (rt == .any or rt == .option or rt == .result or rt == .nil) {
                        if (promoted_module_local) {
                            self.p_global_c_symbol(lname.ident);
                        } else {
                            self.p("lua_Value {s}", .{lname.ident});
                        }
                        if (i < ld.inits.len) {
                            self.p(" = ", .{});
                            try self.emit_as_lua_value(ld.inits[i]);
                        }
                    } else if (rt == .table_type and i < ld.inits.len and ld.inits[i].* == .table) {
                        // Record-typed binding initialized from a table
                        // literal: emit as a C struct initializer. Field
                        // order in the struct typedef matches the order
                        // declared in the record-type annotation, so we
                        // iterate the table's named fields and emit them
                        // in that order. Missing fields default-init
                        // (zero) — emitted as `{0}` so any plain-`int`
                        // field still gets a valid C value.
                        if (promoted_module_local) {
                            self.p_global_c_symbol(lname.ident);
                            self.p(" = ", .{});
                        } else {
                            self.typ(rt);
                            self.p(" {s} = ", .{lname.ident});
                        }
                        try self.emit_record_initializer(rt.table_type.fields, ld.inits[i]);
                    } else if (rt == .func) {
                        // Function-valued binding: a Duo function value is a
                        // boxed lua_Value, not a raw C function pointer. Declare
                        // it as lua_Value and box the callee so reads/tables get
                        // a valid value instead of a `/* func */` placeholder.
                        if (promoted_module_local) {
                            self.p_global_c_symbol(lname.ident);
                        } else {
                            self.p("lua_Value {s}", .{lname.ident});
                        }
                        if (i < ld.inits.len) {
                            self.p(" = ", .{});
                            try self.emit_as_lua_value(ld.inits[i]);
                        } else {
                            self.p(" = lua_val_nil()", .{});
                        }
                    } else {
                        if (promoted_module_local) {
                            self.p_global_c_symbol(lname.ident);
                        } else {
                            self.typ(rt);
                            self.p(" {s}", .{lname.ident});
                        }
                        if (i < ld.inits.len) {
                            self.p(" = ", .{});
                            const init_rt = self.expr_type(ld.inits[i]);
                            if (!self.expr_is_raw_c_intrinsic(ld.inits[i]) and
                                (rt.is_numeric() or rt == .bool or rt == .str) and
                                (init_rt == .any or init_rt.is_numeric() or init_rt == .bool or init_rt == .str))
                            {
                                try self.emit_arg_for_param(ld.inits[i], rt, false);
                            } else {
                                try self.emit_expr(ld.inits[i]);
                            }
                        }
                    }
                    self.p(";\n", .{});
                    if (!promoted_module_local) {
                        self.emit_arc_retain(lname.ident, rt);
                        try self.note_arc_local(lname.ident, rt, attr_is_close(lname.attrib));
                        if (lname.attrib != null and std.mem.eql(u8, lname.attrib.?, "close"))
                            try self.note_close_local(lname.ident);
                    }
                    if (i < ld.inits.len) {
                        if (rt == .str) {
                            if (self.fold_meta_string_expr(ld.inits[i])) |s| {
                                try self.note_comptime_string(lname.ident, s);
                            } else {
                                try self.note_comptime_binding(lname.ident, ld.inits[i]);
                            }
                        } else {
                            try self.note_comptime_binding(lname.ident, ld.inits[i]);
                        }
                        if (rt == .any) try self.update_numeric_lua_local(lname.ident, ld.inits[i]);
                    } else {
                        try self.note_comptime_unavailable(lname.ident);
                    }
                }
            },
            .global_decl => |*gd| {
                if (gd.star) return;
                if (gd.inits.len == 1 and self.uses_multi_return(gd.inits[0], gd.names.len)) {
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    if (self.current_module_cname.len > 0) {
                        self.p("duo_g_{s}_{s} = ", .{ self.current_module_cname, gd.names[0].ident });
                    } else {
                        self.p("duo_g_{s} = ", .{gd.names[0].ident});
                    }
                    try self.emit_as_lua_value(gd.inits[0]);
                    self.p(";\n", .{});
                    for (gd.names[1..], 0..) |*lname, i| {
                        self.ind();
                        if (self.current_module_cname.len > 0) {
                            self.p("duo_g_{s}_{s} = lua_mret_get({d});\n", .{ self.current_module_cname, lname.ident, i });
                        } else {
                            self.p("duo_g_{s} = lua_mret_get({d});\n", .{ lname.ident, i });
                        }
                    }
                } else for (gd.names, 0..) |*lname, i| {
                    if (self.is_native_dense_module_table(lname.ident)) {
                        if (i < gd.inits.len) try self.note_comptime_binding(lname.ident, gd.inits[i]);
                        continue;
                    }
                    self.ind();
                    const rt: RT = blk: {
                        if (lname.typ != .inferred) {
                            break :blk self.resolve_binding_type(lname);
                        }
                        if (i < gd.inits.len) {
                            break :blk self.expr_type(gd.inits[i]);
                        }
                        break :blk self.global_type(lname.ident) orelse .any;
                    };
                    if (self.current_module_cname.len > 0) {
                        self.p("duo_g_{s}_{s}", .{ self.current_module_cname, lname.ident });
                    } else {
                        self.p("duo_g_{s}", .{lname.ident});
                    }
                    if (i < gd.inits.len) {
                        self.p(" = ", .{});
                        if (rt == .any) {
                            try self.emit_as_lua_value(gd.inits[i]);
                        } else if (rt == .table_type and gd.inits[i].* == .table) {
                            self.p("(", .{});
                            self.typ(rt);
                            self.p(")", .{});
                            try self.emit_record_initializer(rt.table_type.fields, gd.inits[i]);
                        } else {
                            try self.emit_expr(gd.inits[i]);
                        }
                    }
                    self.p(";\n", .{});
                    self.emit_arc_retain(lname.ident, rt);
                }
            },
            .const_decl => |*cd| {
                self.ind();
                const rt = if (cd.typ != .inferred)
                    self.resolve_type(cd.typ)
                else
                    self.expr_type(cd.val);
                self.p("const ", .{});
                self.typ(rt);
                self.p(" {s} = ", .{cd.ident});
                try self.emit_arg_for_param(cd.val, rt, false);
                self.p(";\n", .{});
                try self.note_comptime_binding(cd.ident, cd.val);
