                                continue;
                            }
                            // A table of same-kind literals bound inside a
                            // full-native function. This runs BEFORE the
                            // `void* {s} = NULL` fallback below, which is where
                            // such a table used to land — initializer discarded,
                            // every read NULL, `roman.id` dying in strlen.
                            if (!self.moduleNeedsLuaRuntime() and effective_tt == .any and i < as.values.len and
                                try self.try_emit_dense_local_table(name, as.values[i]))
                            {
                                continue;
                            }
                            try self.note_local(name);
                            if (effective_tt == .any) {
                                if (i < as.values.len) {
                                    if (self.fold_meta_string_expr(as.values[i])) |folded| {
                                        try self.note_local_type(name, .str);
                                        self.p("const char* {s} = ", .{name});
                                        try self.emit_c_string_literal(folded);
                                    } else if (!self.moduleNeedsLuaRuntime()) {
                                        const nt = self.structural_expr_type(as.values[i]) orelse self.expr_type(as.values[i]);
                                        if (nt != .any and nt != .nil and self.exprLowersToNativeC(nt)) {
                                            try self.note_local_type(name, nt);
                                            self.typ(nt);
                                            self.p(" {s} = ", .{name});
                                            try self.emit_expr(as.values[i]);
                                        } else {
                                            // A BINDING CODEGEN CANNOT REPRESENT
                                            // IS REFUSED, NOT ZEROED.
                                            //
                                            // This arm used to emit
                                            // `void* NAME = NULL` and DISCARD
                                            // the initializer outright — no
                                            // diagnostic, exit 0, `idol check`
                                            // silent — so every later read of
                                            // the name answered NULL. It is the
                                            // single largest wrong-answer source
                                            // found in this backend: it is why
                                            // `examples/boring/roman.id` died in
                                            // `strlen(NULL)` with SIGSEGV 139
                                            // (and printed a DIFFERENT line on
                                            // each run before that, which is
                                            // uninitialised memory presenting as
                                            // a formatting bug), why
                                            // `examples/table/str/bytes.id`,
                                            // `str/end.id` and `str/invalid.id`
                                            // all exited 139, and why
                                            // `examples/boring/jsonparse.id`
                                            // reached clang with a call to an
                                            // undeclared `lua_eq`.
                                            //
                                            // The representable cases above this
                                            // line are the fix for most of those.
                                            // What is left is genuinely outside
                                            // what a full-native translation unit
                                            // can hold, and the honest answer to
                                            // that is a located refusal naming
                                            // the binding — never a value that
                                            // silently means nothing.
                                            term.locErr(as.values[i].loc(), "'{s}' has no native representation in this module: the C backend would have to discard its value", .{name});
                                            term.locHint(as.values[i].loc(), "give '{s}' a declared type the native path can hold, or keep the module on the dynamic path", .{name});
                                            self.noalloc_violation = "codegen refused a binding whose value it cannot represent";
                                            return error.NoAllocViolation;
                                        }
                                    } else {
                                        try self.note_local_type(name, .any);
                                        self.p("lua_Value {s} = ", .{name});
                                        try self.emit_as_lua_value(as.values[i]);
                                    }
                                } else if (!self.moduleNeedsLuaRuntime()) {
                                    try self.note_local_type(name, .any);
                                    self.p("void* {s} = NULL", .{name});
                                } else {
                                    try self.note_local_type(name, .any);
                                    self.p("lua_Value {s} = lua_val_nil()", .{name});
                                }
                            } else if (effective_tt.is_numeric()) {
                                try self.note_local_type(name, effective_tt);
                                self.typ(effective_tt);
                                self.p(" {s} = ", .{name});
                                if (i < as.values.len) {
                                    try self.emit_dynamic_unbox(as.values[i], effective_tt);
                                } else if (!self.moduleNeedsLuaRuntime()) {
                                    self.p("0", .{});
                                } else {
                                    var buf: [64]u8 = undefined;
                                    self.p("(({s})lua_to_num(lua_val_nil()))", .{effective_tt.c_type(&buf)});
                                }
                            } else if (effective_tt == .bool) {
                                try self.note_local_type(name, .bool);
                                self.p("bool {s} = ", .{name});
                                if (i < as.values.len) try self.emit_dynamic_unbox(as.values[i], .bool) else if (!self.moduleNeedsLuaRuntime()) self.p("false", .{}) else self.p("lua_to_bool(lua_val_nil())", .{});
                            } else if (effective_tt == .str) {
                                try self.note_local_type(name, .str);
                                self.p("const char* {s} = ", .{name});
                                if (i < as.values.len) try self.emit_dynamic_unbox(as.values[i], .str) else if (!self.moduleNeedsLuaRuntime()) self.p("\"\"", .{}) else self.p("lua_to_str(lua_val_nil())", .{});
                            } else if (self.type_lowers_native(effective_tt)) {
                                try self.note_local_type(name, effective_tt);
                                if (effective_tt == .table_type) try self.ensure_record_decl(effective_tt);
                                self.typ(effective_tt);
                                self.p(" {s} = ", .{name});
                                if (i < as.values.len) try self.emit_expr(as.values[i]);
                            } else if (effective_tt == .func) {
                                try self.note_local_type(name, effective_tt);
                                self.p("lua_Value {s} = ", .{name});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                            } else {
                                try self.note_local_type(name, effective_tt);
                                self.typ(effective_tt);
                                self.p(" {s} = ", .{name});
                                if (i < as.values.len) try self.emit_expr(as.values[i]) else self.p("lua_val_nil()", .{});
                            }
                            self.p(";\n", .{});
                            if (i < as.values.len) {
                                if (effective_tt == .str) {
                                    if (self.fold_meta_string_expr(as.values[i])) |s| {
                                        try self.note_comptime_string(name, s);
                                    } else {
                                        try self.note_comptime_binding(name, as.values[i]);
                                    }
                                } else {
                                    try self.note_comptime_binding(name, as.values[i]);
                                }
                            } else {
                                try self.note_comptime_unavailable(name);
                            }
                            continue;
                        }
                    }

                    // `t = {}` on a hoisted dense table: the buffer was declared
                    // in the prologue, so this rebinding is a reset of it, not
                    // a second declaration.
                    if (tgt.* == .name and i < as.values.len and as.values[i].* == .table and
                        self.is_dense_table_name(tgt.name.ident) and
                        self.dense_table_is_hoisted(tgt.name.ident))
                    {
                        const dt = tgt.name.ident;
                        const info = self.dense_table_info(dt);
                        const fields = as.values[i].table.fields;
                        self.emit_dense_table_reset(dt, info, fields.len);
                        for (fields, 0..) |f, f_idx| {
                            const val = switch (f) {
                                .positional => |v| v,
                                else => break,
                            };
                            self.ind();
                            self.p("duo_dt_set_{s}(&__dt_{s}, &__dtc_{s}, {d}, ", .{ info.sfx(), dt, dt, f_idx + 1 });
                            try self.emit_dense_value(val, info);
                            self.p(");\n", .{});
                        }
                        continue;
                    }

                    // `grid = next_grid` on two already-declared dense tables:
                    // the capacity travels with the pointer, so the default
                    // single-name assignment (which would move only `__dt_`)
                    // would leave the two out of step.
                    if (tgt.* == .name and i < as.values.len and as.values[i].* == .name and
                        self.is_dense_table_name(tgt.name.ident) and
                        self.is_dense_table_name(as.values[i].name.ident))
                    {
                        const dst = tgt.name.ident;
                        const src = as.values[i].name.ident;
                        self.pl("__dt_{s} = __dt_{s}; __dtc_{s} = __dtc_{s};", .{ dst, src, dst, src });
                        continue;
                    }

                    // `env(k) = v` — the world projection, WRITTEN. POSIX
                    // `setenv(k, v, 1)`: the overwrite flag is 1 so a store
                    // always takes effect, and the empty string is NOT special
                    // — `env(k) = ""` sets the variable to the EMPTY value and
                    // keeps it PRESENT. Removal is `env:remove(k)`, a different
                    // edge, and `env(k) = nil` is refused in sema.
                    if (self.env_projection_key(tgt)) |key| {
                        self.ind();
                        self.p("setenv(", .{});
                        try self.emit_cstr_arg(key);
                        self.p(", ", .{});
                        if (i < as.values.len) try self.emit_cstr_arg(as.values[i]) else self.p("\"\"", .{});
                        self.p(", 1);\n", .{});
                        continue;
                    }

                    var is_table_assign = false;
                    if (try self.try_emit_call_form_index_assign(
                        tgt,
                        if (i < as.values.len) as.values[i] else null,
                    )) {
                        continue;
                    }
                    if (tgt.* == .field) {
                        const f = &tgt.field;
                        if (self.expr_type(f.obj) == .any) {
                            const hash = calc_lua_hash(f.field);
                            is_table_assign = true;
                            self.p("lua_table_set_str_lit(", .{});
                            try self.emit_expr(f.obj);
                            self.p(", \"{s}\", {d}u, {d}, ", .{ f.field, hash, f.field.len });
                            if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                            self.p(");\n", .{});
                        }
                    } else if (tgt.* == .index) {
                        const idx = &tgt.index;
                        if (idx.obj.* == .name and self.is_native_str_list_local(idx.obj.name.ident)) {
                            is_table_assign = true;
                            const str_list = idx.obj.name.ident;
                            self.p("{s}_items[{s}_len++] = ", .{ str_list, str_list });
                            if (i < as.values.len) try self.emit_expr(as.values[i]) else self.p("NULL", .{});
                            self.p(";\n", .{});
                        } else if (self.is_dense_table_index(idx.obj)) {
                            is_table_assign = true;
                            if (idx.obj.* == .name) {
                                const dt = idx.obj.name.ident;
                                const info = self.dense_table_info(dt);
                                // Under a loop-versioning guard the index is
                                // proved inside [0, cap), so the store can
                                // neither grow the buffer nor move it.
                                if (self.dense_unchecked) {
                                    self.p("__dt_{s}[", .{dt});
                                    try self.emit_dense_key(idx.key);
                                    self.p("] = ", .{});
                                    if (i < as.values.len) try self.emit_dense_value(as.values[i], info) else self.p("0", .{});
                                    self.p(";\n", .{});
                                } else {
                                    self.p("duo_dt_set_{s}(&__dt_{s}, &__dtc_{s}, ", .{ info.sfx(), dt, dt });
                                    try self.emit_dense_key(idx.key);
                                    self.p(", ", .{});
                                    if (i < as.values.len) try self.emit_dense_value(as.values[i], info) else self.p("0", .{});
                                    self.p(");\n", .{});
                                }
                            }
                        } else if (self.expr_is_dynamic_table(idx.obj)) {
                            is_table_assign = true;
                            if (positive_int_key(idx.key)) |key| {
                                self.p("lua_table_set_i64(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", {d}, ", .{key});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            } else if (self.is_integer_key(idx.key)) {
                                self.p("lua_table_set_i64(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", ", .{});
                                try self.emit_i64_index_key(idx.key);
                                self.p(", ", .{});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            } else {
                                self.p("lua_table_set(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", ", .{});
                                try self.emit_as_lua_value(idx.key);
                                self.p(", ", .{});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            }
                        }
                    }

                    if (!is_table_assign) {
                        if (tgt.* == .name) {
                            const tt_for_drop = self.expr_type(tgt);
                            self.emit_arc_drop(tgt.name.ident, tt_for_drop, false);
                            self.ind();
                        }
                        try self.emit_lvalue(tgt);
                        self.p(" = ", .{});
                        if (i < as.values.len) {
                            const vt = self.expr_type(as.values[i]);
                            if (tt == .any) {
                                if (!self.moduleNeedsLuaRuntime()) {
                                    try self.emit_expr(as.values[i]);
                                } else {
                                    try self.emit_as_lua_value(as.values[i]);
                                }
                            } else if (!self.expr_is_raw_c_intrinsic(as.values[i]) and
                                (tt.is_numeric() or tt == .bool or tt == .str) and
                                (vt == .any or vt.is_numeric() or vt == .bool or vt == .str))
                            {
                                try self.emit_arg_for_param(as.values[i], tt, false);
                            } else {
                                try self.emit_expr(as.values[i]);
                            }
                        } else {
                            self.p("0", .{});
                        }
                        self.p(";\n", .{});
                        if (tgt.* == .name) {
                            const tt_for_retain = self.expr_type(tgt);
                            self.emit_arc_retain(tgt.name.ident, tt_for_retain);
                            if (i < as.values.len) {
                                if (tt == .str) {
                                    if (self.fold_meta_string_expr(as.values[i])) |s| {
                                        try self.note_comptime_string(tgt.name.ident, s);
                                    } else {
                                        try self.note_comptime_binding(tgt.name.ident, as.values[i]);
                                    }
                                } else {
                                    try self.note_comptime_binding(tgt.name.ident, as.values[i]);
                                }
                                try self.update_numeric_lua_local(tgt.name.ident, as.values[i]);
                            } else {
                                try self.note_comptime_unavailable(tgt.name.ident);
                            }
                        }
                    } else if (tgt.* == .name) {
                        try self.note_comptime_unavailable(tgt.name.ident);
                    }
                }
            },
            .call_stmt => |*cs| {
                self.ind();
                // Special-case print(...)
                if (cs.expr.* == .call) {
                    const c = &cs.expr.call;
                    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "print")) {
                        try self.emit_print_call(c.args);
                        return;
                    }
                }
                try self.emit_expr(cs.expr);
                self.p(";\n", .{});
            },
            .expr_stmt => |*es| {
                // Handle sequence expressions (a, b) — evaluate all, discard results.
                if (es.expr.* == .sequence) {
                    for (es.expr.sequence.exprs) |sub| {
                        self.ind();
                        try self.emit_expr(sub);
                        self.p(";\n", .{});
                    }
                } else {
                    self.ind();
                    try self.emit_expr(es.expr);
                    self.p(";\n", .{});
                }
            },
            .ret => |*r| {
                // Run all enclosing defers (LIFO, innermost scope first)
                // before unwinding. Cheap no-op when none are pending.
                if (self.has_pending_defers()) try self.emit_all_pending_defers();
                self.ind();
                var returned_dts = std.StringHashMap(void).init(self.alloc);
                defer returned_dts.deinit();
                for (r.vals) |val| {
                    if (val.* == .name) {
                        try returned_dts.put(val.name.ident, {});
                    }
                }
                {
                    var all: std.ArrayList([]const u8) = .empty;
                    defer all.deinit(self.alloc);
                    try self.dense_table_names(&all);
                    var free_list: std.ArrayList([]const u8) = .empty;
                    defer free_list.deinit(self.alloc);
                    var reads_dense = false;
                    for (r.vals) |val| {
                        if (self.expr_reads_any_dense(val)) reads_dense = true;
                    }
                    if (!(self.func_has_dense_alias() and reads_dense)) {
                        for (all.items) |dt| {
                            if (returned_dts.contains(dt)) continue;
                            // `return t[1] + t[2]` reads the buffer after this
                            // point; the bare-name test alone does not see that.
                            var referenced = false;
                            for (r.vals) |val| {
                                if (expr_references_name(val, dt)) referenced = true;
                            }
                            if (referenced) continue;
                            try free_list.append(self.alloc, dt);
                        }
                    }
                    self.emit_dense_frees(free_list.items);
                }
                if (r.vals.len == 0) {
                    if (self.emitting_main_driver) {
                        self.p("return 0;\n", .{});
                    } else if (self.current_ret == .any and self.moduleNeedsLuaRuntime()) {
                        self.p("return lua_val_nil();\n", .{});
                    } else {
                        self.p("return;\n", .{});
                    }
                } else if (r.vals.len == 1 and r.vals[0].* == .call and
                    r.vals[0].call.func.* == .name and
                    std.mem.eql(u8, r.vals[0].call.func.name.ident, "error"))
                {
                    // error() is noreturn — emit fatal directly without return
                    try self.emit_fatal_error(if (r.vals[0].call.args.len > 0) r.vals[0].call.args[0] else null);
                    self.p(";\n", .{});
                } else if (self.closure_ctx != null or self.current_ret == .any) {
                    if (r.vals.len == 1) {
                        self.p("return ", .{});
                        try self.emit_as_lua_value(r.vals[0]);
                        self.p(";\n", .{});
                    } else {
                        self.pl("lua_mret_clear();", .{});
                        for (r.vals[1..]) |v| {
                            self.ind();
                            self.p("lua_mret_push(", .{});
                            try self.emit_as_lua_value(v);
                            self.p(");\n", .{});
                        }
                        self.ind();
                        self.p("return ", .{});
                        try self.emit_as_lua_value(r.vals[0]);
                        self.p(";\n", .{});
                    }
                } else if (self.current_ret == .table_type and r.vals[0].* == .table) {
                    // Record-typed return initialized from a table
                    // literal: emit as a C struct initializer, matching
                    // emit_arg_for_param and local_decl.
                    self.p("return (", .{});
                    self.typ(self.current_ret);
                    self.p(")", .{});
                    try self.emit_record_initializer(self.current_ret.table_type.fields, r.vals[0]);
                    self.p(";\n", .{});
                } else if (r.vals.len == 1) {
                    const et = self.expr_type(r.vals[0]);
                    if (et == .any and self.current_ret != .any and !self.expr_is_raw_c_intrinsic(r.vals[0])) {
                        self.p("return ", .{});
                        if (!self.moduleNeedsLuaRuntime() and self.expr_is_native_scalar(r.vals[0]) and
                            (self.current_ret.is_numeric() or self.current_ret == .bool or self.current_ret == .str))
                        {
                            try self.emit_returned_expr(r.vals[0]);
                        } else if (self.current_ret.is_numeric() or self.current_ret == .bool or self.current_ret == .str)
                            try self.emit_dynamic_unbox(r.vals[0], self.current_ret)
                        else
                            try self.emit_returned_expr(r.vals[0]);
                        self.p(";\n", .{});
                    } else {
                        self.p("return ", .{});
                        try self.emit_returned_expr(r.vals[0]);
                        self.p(";\n", .{});
                    }
                } else {
                    self.pl("lua_mret_clear();", .{});
                    for (r.vals[1..]) |v| {
                        self.ind();
                        self.p("lua_mret_push(", .{});
                        // Same as the `.seq` path above: pushed extras are always
                        // boxed; only the returned value is native.
                        try self.emit_as_lua_value(v);
                        self.p(");\n", .{});
                    }
                    self.ind();
                    self.p("return ", .{});
                    try self.emit_expr(r.vals[0]);
                    self.p(";\n", .{});
                }
            },
            .if_stmt => |*is| {
                if (is.binding) |b| {
                    try self.note_local(b.name);
                    const bind_rt = self.expr_type(b.expr);
                    if (self.funcUsesNativeLowering(self.current_func_name orelse "") and
                        bind_rt != .any and semantic_algebra.lowersToNativeC(bind_rt))
                    {
                        self.ind();
                        var buf: [64]u8 = undefined;
                        self.p("{s} {s} = ", .{ bind_rt.c_type(&buf), b.name });
                        try self.emit_expr(b.expr);
                        self.p(";\n", .{});
                    } else {
                        self.ind();
                        self.p("lua_Value {s} = ", .{b.name});
                        try self.emit_as_lua_value(b.expr);
                        self.p(";\n", .{});
                    }
                }
                // Dead-branch elimination: if condition is compile-time known,
                // emit only the taken branch (no if/else wrapper).
                if (self.try_eval_const_condition(is.cond)) |known| {
                    if (known) {
                        // Condition always true — emit then-block directly
                        try self.emit_control_block(&is.then);
                    } else {
                        // Condition always false — check elseifs then else
                        var found_taken = false;
                        for (is.elseifs) |*ei| {
                            if (self.try_eval_const_condition(ei.cond)) |ei_known| {
                                if (ei_known) {
                                    try self.emit_control_block(&ei.body);
                                    found_taken = true;
                                    break;
                                }
                                // This elseif is also false, skip it
                            } else {
                                // Unknown elseif — must emit rest dynamically
                                self.ind();
                                self.p("if (", .{});
                                if (self.expr_type(ei.cond) == .any) {
                                    self.p("lua_to_bool(", .{});
                                    try self.emit_expr(ei.cond);
                                    self.p(")", .{});
                                } else {
                                    try self.emit_expr(ei.cond);
                                }
                                self.p(") {{\n", .{});
                                self.indent += 1;
                                try self.emit_control_block(&ei.body);
                                self.indent -= 1;
                                if (is.else_body) |*eb| {
                                    self.ind();
                                    self.p("}} else {{\n", .{});
                                    self.indent += 1;
                                    try self.emit_control_block(eb);
                                    self.indent -= 1;
                                }
                                self.pl("}}", .{});
                                found_taken = true;
                                break;
                            }
                        }
                        if (!found_taken) {
                            if (is.else_body) |*eb| {
                                try self.emit_control_block(eb);
                            }
                        }
                    }
                } else {
                    // Normal runtime if/else emission
                    self.ind();
                    self.p("if (", .{});
                    if (self.expr_type(is.cond) == .any) {
                        self.p("lua_to_bool(", .{});
                        try self.emit_expr(is.cond);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(is.cond);
                    }
                    self.p(") {{\n", .{});
                    self.indent += 1;
                    try self.emit_control_block(&is.then);
                    self.indent -= 1;
                    for (is.elseifs) |*ei| {
                        self.ind();
                        self.p("}} else if (", .{});
                        if (self.expr_type(ei.cond) == .any) {
                            self.p("lua_to_bool(", .{});
                            try self.emit_expr(ei.cond);
                            self.p(")", .{});
                        } else {
                            try self.emit_expr(ei.cond);
                        }
                        self.p(") {{\n", .{});
                        self.indent += 1;
                        try self.emit_control_block(&ei.body);
                        self.indent -= 1;
