                    if (is.else_body) |*eb| {
                        self.ind();
                        self.p("}} else {{\n", .{});
                        self.indent += 1;
                        try self.emit_control_block(eb);
                        self.indent -= 1;
                    }
                    self.pl("}}", .{});
