                    } else {
                        // while true → emit infinite loop (let C handle it)
                        self.pl("while (1) {{", .{});
                        self.indent += 1;
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&wl.body);
                        self.indent -= 1;
                        self.pl("}}", .{});
