            .num_for => |*nf| {
                self.ind();
                // Resolve the loop variable's type BEFORE registering it so
                // that inner expressions (e.g. `arr[i]`, `i * 2`) see the
                // concrete type (i64/f64) rather than `.any`.
                const vt: RT = if (nf.var_typ != .inferred)
                    types.resolve(nf.var_typ, null, self.alloc) catch .i64
                else
                    self.expr_type(nf.start);
                const vt2 = if (vt == .any) RT.i64 else vt;
                // THE LOOP VARIABLE IS SCOPED TO THE LOOP, and the C output has
                // always said so — `for (int64_t i = 1; …)` ends `i` at the
                // closing brace. Codegen's own scope model did not: the name was
                // written into the ENCLOSING scope and left there, so a later
                // `i = 0` was treated as an assignment to something already
                // declared and emitted `i = 0;` with no declaration in reach.
                // `examples/boring/anagram.id` does exactly that — a `for i = 1,
                // 256` fill loop and then `i = 0` to walk the string — and died
                // with "use of undeclared identifier 'i'". Restoring whatever
                // the name meant before the loop is what makes the model agree
                // with the C it emits; a program that already bound `i` outside
                // keeps its binding, and one that did not gets a fresh
                // declaration at the next assignment.
                const outer_var_binding: ?RT = if (self.local_scopes.items.len > 0)
                    self.local_scopes.items[self.local_scopes.items.len - 1].get(nf.var_name)
                else
                    null;
                defer if (self.local_scopes.items.len > 0) {
                    const scope = &self.local_scopes.items[self.local_scopes.items.len - 1];
                    if (outer_var_binding) |prev| {
                        scope.put(self.alloc, nf.var_name, prev) catch {};
                    } else {
                        _ = scope.remove(nf.var_name);
                    }
                };
                try self.note_local_type(nf.var_name, vt2);
                // The continuation test MUST follow the step's sign. This was an
                // unconditional `<=`, so `for i = 4, 1, -1` emitted
                // `for (int64_t i = 4; i <= 1; i += (-1))` and ran ZERO times —
                // every descending loop silently did nothing. It went unnoticed
                // because the DIRECT ARM64 backend lowers the same loop
                // correctly, so examples/native_for_smoke.duo (which compiles
                // native) passed while the C backend was wrong. That is exactly
                // the backend divergence scripts/semantic_harness.duo exists to
                // catch, and it took the harness to surface it.
                const step_negative: ?bool = if (nf.step) |s| num_for_step_negative(s) else false;
                var closed_scope = false;
                if (step_negative == null) {
                    // Sign unknown until run time. Lua evaluates `stop` and
                    // `step` exactly ONCE, so they are hoisted into temps rather
                    // than re-evaluated in the condition — an expression with a
                    // side effect must not fire per iteration. The temps live in
                    // their own C block, so a nested loop reusing the same loop
                    // variable name simply shadows, which is well defined. The
                    // block opens BEFORE the vectorization pragma below: a
                    // `#pragma clang loop` must be immediately followed by the
                    // loop itself, and an intervening `{` is a hard error.
                    closed_scope = true;
                    self.p("{{\n", .{});
                    self.indent += 1;
                    self.ind();
                    self.typ(vt2);
                    self.p(" __dfor_stop_{s} = ", .{nf.var_name});
                    try self.emit_num_for_bound(nf.stop, vt2);
                    self.p(";\n", .{});
                    self.ind();
                    self.typ(vt2);
                    self.p(" __dfor_step_{s} = ", .{nf.var_name});
                    try self.emit_num_for_bound(nf.step.?, vt2);
                    self.p(";\n", .{});
                    self.ind();
                }
                // Emit vectorization hint for simple counted loops in typed code.
                // Stronger pragma when sema detects reduction/accumulation loops.
                if (self.current_ret.is_native()) {
                    const simd_reduction = if (self.current_func_body) |body| body.use_simd_reduction else false;
                    const unroll = nf.unroll orelse if (self.current_func_body) |body| body.unroll_count else null;
                    if (simd_reduction) {
                        if (unroll) |n| {
                            self.p("#pragma clang loop vectorize(enable) interleave(enable) unroll_count({d})\n", .{n});
                        } else {
                            self.p("#pragma clang loop vectorize(enable) interleave(enable) unroll_count(8)\n", .{});
                        }
                    } else if (unroll) |n| {
                        self.p("#pragma GCC unroll {d}\n", .{n});
                        self.p("#pragma clang loop vectorize(enable) interleave(enable)\n", .{});
                    } else {
                        self.p("#pragma clang loop vectorize(enable) interleave(enable)\n", .{});
                    }
                    self.ind();
                }
                self.p("for (", .{});
                self.typ(vt2);
                self.p(" {s} = ", .{nf.var_name});
                try self.emit_num_for_bound(nf.start, vt2);
                self.p("; ", .{});
                if (step_negative) |neg| {
                    self.p("{s} {s} ", .{ nf.var_name, if (neg) ">=" else "<=" });
                    try self.emit_num_for_bound(nf.stop, vt2);
                    self.p("; {s} += ", .{nf.var_name});
                    if (nf.step) |s| try self.emit_num_for_bound(s, vt2) else self.p("1", .{});
                } else {
                    self.p("__dfor_step_{s} > 0 ? {s} <= __dfor_stop_{s} : {s} >= __dfor_stop_{s}", .{
                        nf.var_name, nf.var_name, nf.var_name, nf.var_name, nf.var_name,
                    });
                    self.p("; {s} += __dfor_step_{s}", .{ nf.var_name, nf.var_name });
                }
                self.p(") {{\n", .{});
                self.indent += 1;
                try self.push_break_scope();
                defer self.pop_break_scope();
                try self.emit_block(&nf.body);
                self.indent -= 1;
                self.pl("}}", .{});
                if (closed_scope) {
                    self.indent -= 1;
                    self.pl("}}", .{});
                }
            },
