                    for (gf.vars, 0..) |vname, vi| {
                        self.ind();
                        if (vi == 0) {
                            self.pl("lua_Value {s} = _gf_r0;", .{vname});
                        } else {
                            self.pl("lua_Value {s} = lua_mret_get({d});", .{ vname, vi - 1 });
                        }
                    }
                    {
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&gf.body);
                    }
                    self.indent -= 1;
                    self.ind();
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                } else {
                    for (gf.vars) |vname| try self.note_local(vname);
                    self.pl("{{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    self.p("lua_Value _gf_tmp = ", .{});
                    if (gf.iters.len > 0) {
                        try self.emit_expr(gf.iters[0]);
                    } else {
                        self.p("lua_val_nil()", .{});
                    }
                    self.p(";\n", .{});
                    self.ind();
                    self.p("if (_gf_tmp.type == VAL_TABLE && ", .{});
                    self.emit_metafield_literal("_gf_tmp", "__iter");
                    self.pl(".type != VAL_NIL) _gf_tmp = lua_iter(_gf_tmp);", .{});
                    self.ind();
                    self.pl("lua_Value _gf_f, _gf_s, _gf_var;", .{});
                    self.ind();
                    self.w.writeAll("if (lua_mret_n >= 3) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_mret_get(2);", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else if (lua_mret_n >= 1) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = _gf_tmp;", .{});
                    self.pl("_gf_s = lua_val_nil();", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("}\n") catch {};
                    self.ind();
                    self.pl("while (1) {{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_Value _gf_argv[2] = {{ _gf_s, _gf_var }};", .{});
                    self.ind();
                    self.pl("lua_Value _gf_r0 = lua_invoke(_gf_f, 2, _gf_argv);", .{});
                    self.ind();
                    self.pl("_gf_var = _gf_r0;", .{});
                    self.ind();
                    self.pl("if (_gf_r0.type == VAL_NIL) break;", .{});
                    for (gf.vars, 0..) |vname, vi| {
                        self.ind();
                        if (vi == 0) {
                            self.pl("lua_Value {s} = _gf_r0;", .{vname});
                        } else {
                            self.pl("lua_Value {s} = lua_mret_get({d});", .{ vname, vi - 1 });
                        }
                    }
                    {
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&gf.body);
                    }
                    self.indent -= 1;
                    self.ind();
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                }
            },
            .do_block => |*db| {
                self.pl("{{", .{});
                self.indent += 1;
                try self.emit_block(&db.body);
                self.indent -= 1;
                self.pl("}}", .{});
            },
            .func_decl => |*fd| {
                if (fd.path.len == 1 and !fd.method) {
                    try self.note_comptime_func(fd.path[0], &fd.func);
                }
                if (fd.is_local) {
                    // Hoisted to file scope in emit_module.
                }
                try self.emit_table_field_func_install(fd);
            },
            // NOTE: there is no `.struct_def` case. Anonymous record
            // bindings don't need a top-level emission — they are handled
            // inline at the binding site.
            .match_stmt => |match_stmt| {
                self.ind();
                try self.emit_match_expr(match_stmt);
                self.p(";\n", .{});
            },
            .try_stmt => |try_stmt| {
                try self.emit_try_stmt(try_stmt);
            },
            .defer_stmt => |*defer_stmt| {
                // Register the body to run on scope exit (LIFO). The actual
                // emission happens at block end (`emit_top_defers`) and before
                // early returns (`emit_all_pending_defers`). `&defer_stmt.body`
                // points into the stable AST, so it stays valid.
                try self.note_defer(&defer_stmt.body);
            },
            .enum_def => |*ed| try self.emit_enum_descriptor(ed),
            .concept_def => |*cd| {
                if (self.moduleNeedsLuaRuntime()) try self.emit_concept_descriptor(cd);
            },
            .alias_def => {},
            .brk => {
                if (self.has_pending_defers()) {
                    try self.emit_pending_defers_from(self.current_break_scope_base());
                }
                self.pl("break;", .{});
            },
            .cont => {
                if (self.has_pending_defers()) {
                    try self.emit_pending_defers_from(self.current_break_scope_base());
                }
                self.pl("continue;", .{});
            },
            .goto_stmt => |g| self.pl("goto {s};", .{g.label}),
            .label_stmt => |l| self.pl("{s}:;", .{l.label}),
        }
    }

    /// `t.f = (a) …` where `t` is a runtime table: bind the emitted function
    /// INTO the table at the point the declaration is written.
    ///
    /// A path-qualified declaration produces a C function (`t__f`, plus its
    /// `t__f__lua` thunk) and, before this, nothing else at all — the statement
    /// emitted zero bytes. So the table stayed empty and `t.f(5)` looked the
    /// field up, missed, and `lua_invoke` on nil answers nil rather than
    /// failing. Measured: `t = {}; t.f = (a: i64) a + 1; t.f(5)` printed `nil`.
    /// A silent wrong answer, not a diagnostic — the function was compiled,
    /// correct, and unreachable.
    ///
    /// SCOPE, deliberately narrow. Only `receiver.field`, only when the module
    /// has a Lua runtime (without one there is no table to set), and only when
    /// the receiver is an ordinary value binding. A stdlib global (`string.x`),
    /// a `req` module binding and an embedded-module path all already have
    /// their own emission and must keep it; installing over them would be a
    /// second answer for a name that already has one.
    fn emit_table_field_func_install(self: *CodeGen, fd: *const ast.FuncDecl) E!void {
        if (fd.path.len != 2 or fd.method) return;
        if (!self.moduleNeedsLuaRuntime()) return;
        if (self.skip_lua_thunk_emit()) return;
        if (func_ffi_name(fd.attributes) != null) return;

        const recv = fd.path[0];
        const field = fd.path[1];
        if (is_runtime_global(recv)) return;
        if (self.req_module_bindings.get(recv) != null) return;
        if (self.embedded_module_paths.contains(recv)) return;
        if (self.function_c_names.get(recv) != null) return;

        // The receiver must actually be a table-shaped binding that exists at
        // this point. `.any` is what a `{}` literal binding carries; anything
        // narrower is a native scalar and cannot take a field.
        var recv_expr = ast.Expr{ .name = .{ .loc = fd.func.body.loc, .ident = recv } };
        if (self.expr_type(&recv_expr) != .any) return;

        const ft = self.func_expr_type(&fd.func);
        if (ft != .func) return;

        var name_buf: [256]u8 = undefined;
        const cname = self.emit_func_c_name(fd, &name_buf);
        const hash = calc_lua_hash(field);

        self.ind();
        self.p("lua_table_set_str_lit(", .{});
        self.emit_var_name(recv);
        self.p(", \"", .{});
        try self.emit_string_escaped(field);
        self.p("\", {d}u, {d}, ", .{ hash, field.len });
        try self.emit_native_func_cname_as_lua_value(cname, ft.func.params, ft.func.is_compile_only);
        self.p(");\n", .{});
    }

    fn derive_arg_count(args: ?[]const u8) usize {
        const raw = args orelse return 0;
        var count: usize = 0;
        var it = std.mem.splitScalar(u8, raw, ',');
        while (it.next()) |part| {
            if (std.mem.trim(u8, part, " \t\r\n").len != 0) count += 1;
        }
        return count;
    }

    fn enum_derive_count(attrs: []const ast.Attribute) usize {
        var count: usize = 0;
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            count += derive_arg_count(attr.args);
        }
        return count;
    }

    fn strip_attribute_string(raw: []const u8) []const u8 {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
            return trimmed[1 .. trimmed.len - 1];
        }
        return trimmed;
    }

    fn attrs_have_derive(attrs: []const ast.Attribute, derive_name: []const u8) bool {
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                if (std.mem.eql(u8, strip_attribute_string(part), derive_name)) return true;
            }
        }
        return false;
    }

    fn enum_has_derive_descriptor(self: *const CodeGen, enum_name: []const u8) bool {
        const ed = self.enum_defs.get(enum_name) orelse return false;
        return enum_derive_count(ed.attributes) > 0;
    }

    fn emit_enum_descriptor(self: *CodeGen, ed: *const ast.EnumDef) E!void {
        const derive_count = enum_derive_count(ed.attributes);
        if (derive_count == 0) return;

        try self.note_local(ed.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{ed.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"enum\"));", .{ ed.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, calc_lua_hash("name") });
        try self.emit_string_escaped(ed.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_variants = lua_table_new_with_capacity({d}, 0);", .{ ed.name, ed.variants.len });
        for (ed.variants, 0..) |variant, i| {
            const has_payload = variant.payload != null and variant.payload.?.len > 0;
            self.ind();
            self.pl("lua_Value {s}_variant_{d} = lua_table_new_with_capacity(0, 3);", .{ ed.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_variant_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(variant.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"tag\", {d}, 3, lua_val_from_int({d}));", .{ ed.name, i, calc_lua_hash("tag"), i });
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"has_payload\", {d}, 11, lua_val_from_bool({s}));", .{ ed.name, i, calc_lua_hash("has_payload"), if (has_payload) "true" else "false" });
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_variants, {d}, {s}_variant_{d});", .{ ed.name, i + 1, ed.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"variants\", {d}, 8, {s}_variants);", .{ ed.name, calc_lua_hash("variants"), ed.name });

        self.ind();
        self.pl("lua_Value {s}_derives = lua_table_new_with_capacity({d}, 0);", .{ ed.name, derive_count });
        var derive_index: usize = 1;
        for (ed.attributes) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                const derive_name = strip_attribute_string(part);
                if (derive_name.len == 0) continue;
                self.ind();
                self.p("lua_table_set_raw_i64({s}_derives, {d}, lua_val_lit(\"", .{ ed.name, derive_index });
                try self.emit_string_escaped(derive_name);
                self.p("\"));\n", .{});
                derive_index += 1;
            }
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"derives\", {d}, 7, {s}_derives);", .{ ed.name, calc_lua_hash("derives"), ed.name });
    }

    fn emit_concept_descriptor(self: *CodeGen, cd: *const ast.ConceptDef) E!void {
        try self.note_local(cd.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{cd.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"concept\"));", .{ cd.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, calc_lua_hash("name") });
        try self.emit_string_escaped(cd.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_fields = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_fields.len });
        for (cd.required_fields, 0..) |field, i| {
            self.ind();
            self.pl("lua_Value {s}_field_{d} = lua_table_new_with_capacity(0, 2);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(field.name);
            self.p("\"));\n", .{});
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"type\", {d}, 4, ", .{ cd.name, i, calc_lua_hash("type") });
            try self.emit_type_expr_metadata(field.typ);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_fields, {d}, {s}_field_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_fields\", {d}, 15, {s}_fields);", .{ cd.name, calc_lua_hash("required_fields"), cd.name });

        self.ind();
        self.pl("lua_Value {s}_methods = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_methods.len });
        for (cd.required_methods, 0..) |method, i| {
            self.ind();
            self.pl("lua_Value {s}_method_{d} = lua_table_new_with_capacity(0, 3);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(method.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_method_{d}, \"param_count\", {d}, 11, lua_val_from_num({d}));", .{ cd.name, i, calc_lua_hash("param_count"), method.params.len });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"return\", {d}, 6, ", .{ cd.name, i, calc_lua_hash("return") });
            try self.emit_type_expr_metadata(method.ret_type);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_methods, {d}, {s}_method_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_methods\", {d}, 16, {s}_methods);", .{ cd.name, calc_lua_hash("required_methods"), cd.name });
    }

    fn emit_type_expr_metadata(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        self.p("lua_val_from_str(\"", .{});
        try self.emit_type_expr_metadata_inner(type_expr);
        self.p("\")", .{});
    }

    fn emit_type_expr_metadata_inner(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        switch (type_expr) {
            .inferred => try self.emit_string_escaped("any"),
            .named => |name| try self.emit_string_escaped(name),
            .pointer => |child| {
                try self.emit_string_escaped("*");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .optional => |child| {
                try self.emit_string_escaped("?");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .array => |arr| {
                if (arr.size) |size| {
                    self.p("[{d}]", .{size});
                } else {
                    try self.emit_string_escaped("[]");
                }
                try self.emit_type_expr_metadata_inner(arr.elem.*);
            },
            .func => try self.emit_string_escaped("function"),
            .record => try self.emit_string_escaped("table"),
            .tuple => try self.emit_string_escaped("tuple"),
            .generic => |g| {
                try self.emit_type_expr_metadata_inner(g.base.*);
                try self.emit_string_escaped("[");
                for (g.params, 0..) |param, i| {
                    if (i > 0) try self.emit_string_escaped(",");
                    try self.emit_type_expr_metadata_inner(param);
                }
                try self.emit_string_escaped("]");
            },
            .constrained => |cp| {
                try self.emit_string_escaped(cp.name);
                try self.emit_string_escaped(":");
                try self.emit_type_expr_metadata_inner(cp.constraint.*);
                for (cp.extra) |extra| {
                    try self.emit_string_escaped("+");
                    try self.emit_type_expr_metadata_inner(extra);
                }
            },
        }
    }

    // ── print() special case ──────────────────────────────────────────────────

    fn emit_print_call(self: *CodeGen, args: []*ast.Expr) E!void {
        if (args.len == 0) {
            self.p("puts(\"\");\n", .{});
            return;
        }
        // Build format string based on arg types
        var fmt_buf: std.ArrayList(u8) = .empty;
        defer fmt_buf.deinit(self.alloc);
        var has_sep = false;
        for (args) |arg| {
            if (has_sep) try fmt_buf.appendSlice(self.alloc, "\\t");
            has_sep = true;
            const t = self.expr_type(arg);
            const spec: []const u8 = blk: {
                if (self.enum_name_of(t)) |ename| {
                    if (self.enum_is_payload_free(ename) and self.enum_has_derive(ename, "Display"))
                        break :blk "%s";
                    if (self.enum_is_payload_free(ename)) break :blk "%d";
                }
                // law.nominal (§46): RENDERING IS A PHYSICAL QUESTION. A
                // nominal descriptor is printed as the thing it IS, and the
                // fallback below is not a safe default for it — `feet` took
                // the `else` arm and emitted `printf("%s", d)` on a `double`,
                // which SEGFAULTED at runtime with `ok compile` reported. This
                // is the exact class gap[097] hole 2 names: a switch whose
                // descriptor arm assumes boxed. gap[093] measured the same
                // site as silent no-output before the descriptor reached the
                // emitter at all.
                const phys = types.nominalReprOf(t) orelse t;
                break :blk types.cFormatSpec(phys) orelse "%s";
            };
            try fmt_buf.appendSlice(self.alloc, spec);
        }
        try fmt_buf.appendSlice(self.alloc, "\\n");
        self.p("printf(\"{s}\"", .{fmt_buf.items});
        for (args) |arg| {
            self.p(", ", .{});
            const t = self.expr_type(arg);
            if (t == .bool) {
                self.p("(", .{});
                try self.emit_expr(arg);
                self.p(") ? \"true\" : \"false\"", .{});
            } else if (t == .any) {
                // Display context: honour __tostring so `print(v)` matches
                // `print(tostring(v))` without the caller writing it out.
                self.p("lua_to_display_str(", .{});
                try self.emit_expr(arg);
                self.p(")", .{});
            } else if (t == .str or arg.* == .quoted) {
                if (self.expr_emits_lua_value(arg)) {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(arg);
                }
            } else if (self.enum_name_of(t)) |ename| {
                if (self.enum_is_payload_free(ename) and self.enum_has_derive(ename, "Display")) {
                    self.p("duo_{s}_to_string(", .{ename});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else if (self.enum_is_payload_free(ename)) {
                    self.p("(int)(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                }
            } else {
                try self.emit_expr(arg);
            }
        }
        self.p(");\n", .{});
    }

    fn emit_dynamic_unbox(self: *CodeGen, e: *const ast.Expr, want: RT) E!void {
        const et = self.expr_type(e);
        if (!self.moduleNeedsLuaRuntime()) {
            if (e.* == .name) {
                if (self.local_type(e.name.ident)) |lt| {
                    if (lt.is_numeric() and want.is_numeric()) {
                        if (lt.eql(want)) {
                            try self.emit_expr(e);
                        } else {
                            var buf: [64]u8 = undefined;
                            self.p("(({s})(", .{want.c_type(&buf)});
                            try self.emit_expr(e);
                            self.p("))", .{});
                        }
                        return;
                    }
                    if (lt.eql(want)) {
                        try self.emit_expr(e);
                        return;
                    }
                }
            }
            if (et != .any) {
                if (want.is_numeric() and et.is_numeric()) {
                    if (want.eql(et)) {
                        try self.emit_expr(e);
                    } else {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})(", .{want.c_type(&buf)});
                        try self.emit_expr(e);
                        self.p("))", .{});
                    }
                    return;
                }
                if (want.eql(et)) {
                    try self.emit_expr(e);
                    return;
                }
            }
        }
        if (e.* == .index) {
            if (self.req_module_dense_index_info(e.index.obj)) |nd| {
                const matches = switch (nd.elem) {
                    .str => want == .str,
                    .i64, .f64 => want.is_numeric(),
                };
                if (matches) {
                    try self.emit_expr(e);
                    return;
                }
            }
        }
        if (e.* == .index and self.is_native_dense_module_index(e.index.obj)) {
            // Sema types this as `.any` (it doesn't know about the codegen-only
            // dense-table classification), but the value codegens to a raw C
            // array element, not a lua_Value. Emit it directly when the
            // requested type matches the element's natural representation.
            const nd = self.dense_literal_table(e.index.obj.name.ident).?;
            const matches = switch (nd.elem) {
                .str => want == .str,
                .i64, .f64 => want.is_numeric(),
            };
            if (matches) {
                try self.emit_expr(e);
                return;
            }
        }
        // A `str` byte is already a native integer; unboxing it would ask for a
        // `lua_Value` that no full-native module has.
        if (want.is_numeric() and self.str_byte_index(e) != null) {
            try self.emit_expr(e);
            return;
        }
        if (try self.try_emit_table_projection_unbox(e, want)) return;
        // A call into a req-module lowers to a direct C call returning a native
        // value. If sema typed the call `.any` we would wrap it in lua_to_num(),
        // which does not accept an int64_t — so consult the callee's real return
        // type here rather than trusting expr_type alone.
        if (want.is_numeric() and !et.is_numeric()) {
            if (self.infer_req_module_call_return_type(e)) |crt| {
                if (crt.is_numeric()) {
                    var cbuf: [64]u8 = undefined;
                    self.p("(({s})(", .{want.c_type(&cbuf)});
                    try self.emit_expr(e);
                    self.p("))", .{});
                    return;
                }
            }
        }
        if (want.is_numeric() and et.is_numeric()) {
            if (want.eql(et)) {
                // A bare C integer literal has type `int` (32-bit) even where a
                // 64-bit value is wanted. That silently breaks shifts by >= 32
                // (the count wraps mod 32) and any literal that does not fit in
                // 32 bits, so give integer literals explicit 64-bit width.
                if (want == .i64 and e.* == .int_lit) {
                    if (e.int_lit.val == std.math.minInt(i64))
                        self.emit_c_int_literal(e.int_lit.val)
                    else
                        self.p("INT64_C({d})", .{e.int_lit.val});
                    return;
                }
                try self.emit_expr(e);
            } else {
                var buf: [64]u8 = undefined;
                self.p("(({s})(", .{want.c_type(&buf)});
                try self.emit_expr(e);
                self.p("))", .{});
            }
            return;
        }
        // `tonumber(s) or fallback` already lowers to a native double under full
        // native lowering, so coercing it must be a plain cast — `lua_to_num` does
        // not exist in that profile.
        if (want.is_numeric() and self.expr_is_native_tonumber_or(e)) {
            var cbuf: [64]u8 = undefined;
            self.p("(({s})(", .{want.c_type(&cbuf)});
            try self.emit_expr(e);
            self.p("))", .{});
            return;
        }
        switch (want) {
            .str => {
                if (et == .str) {
                    try self.emit_expr(e);
                } else {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(e);
                    self.p(")", .{});
                }
            },
            .bool => {
                if (et == .bool) {
                    try self.emit_expr(e);
                } else {
                    self.p("lua_to_bool(", .{});
                    try self.emit_expr(e);
                    self.p(")", .{});
                }
            },
            .f64 => {
                self.p("(double)lua_to_num(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
            else => {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_to_num(", .{want.c_type(&buf)});
                try self.emit_expr(e);
                self.p("))", .{});
            },
        }
    }

    /// Emit a folded descriptor field. The value is a scalar literal, so the
    /// only work is the cast the surrounding expression expects.
    fn emit_const_descriptor_literal(self: *CodeGen, lit: *const ast.Expr, want: RT) E!void {
        if (want.is_integer() or want.is_float()) {
            var buf: [64]u8 = undefined;
            self.p("(({s})", .{want.c_type(&buf)});
            try self.emit_expr(lit);
            self.p(")", .{});
            return;
        }
        try self.emit_expr(lit);
    }

    fn emit_mret_get_as(self: *CodeGen, idx: usize, want: RT) void {
        if (want.is_numeric()) {
            var buf: [64]u8 = undefined;
            self.p("(({s})lua_mret_get_num({d}))", .{ want.c_type(&buf), idx });
        } else if (want == .bool) {
            self.p("lua_mret_get_bool({d})", .{idx});
        } else if (want == .str) {
            self.p("lua_mret_get_cstr({d})", .{idx});
        } else {
            self.p("lua_mret_get({d})", .{idx});
        }
    }

    fn try_emit_table_projection_unbox(self: *CodeGen, e: *const ast.Expr, want: RT) E!bool {
        if (!want.is_numeric() and want != .bool and want != .str) return false;
        switch (e.*) {
            .field => |f| {
                if (self.const_descriptor_field(f.obj, f.field)) |lit| {
                    try self.emit_const_descriptor_literal(lit, want);
                    return true;
                }
                if (f.obj.* == .name) {
                    if (self.req_module_bindings.get(f.obj.name.ident)) |mod_cname| {
                        if (try self.try_emit_req_module_const_field(mod_cname, f.field, want)) return true;
                    }
                }
                // §2.7 ambient namespace: `std.a.b.C` is a static path and folds.
                if (f.obj.* == .field) {
                    if (try self.try_emit_ambient_module_const_field(f.obj, f.field, want)) return true;
                }
                const obj_rt = self.expr_type(f.obj);
                if (self.type_lowers_native(obj_rt)) {
                    try self.emit_native_field_access(f.obj, f.field);
                    return true;
                }
                if (obj_rt != .any and self.expr_type(e) != .any) return false;
                const hash = calc_lua_hash(f.field);
                // L2 — interned field IDs: every fallback `.field` access on the
                // dynamic path is emitted through a duo_fallback_get_* marker carrying a
                // stable per-compilation field ID. The marker expands to the standard
                // string-keyed lookup (zero runtime cost), and the generated C records
                // fallback field access + interned field-ID counts for the L6 manifest.
                const fid = self.interned_fallback_field_id(f.field);
                if (want.is_numeric()) {
                    var buf: [64]u8 = undefined;
                    self.p("(({s})duo_fallback_get_num({d}, ", .{ want.c_type(&buf), fid });
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d}))", .{ f.field, hash, f.field.len });
                } else if (want == .bool) {
                    self.p("duo_fallback_get_bool({d}, ", .{fid});
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                } else {
                    self.p("duo_fallback_get_cstr({d}, ", .{fid});
                    try self.emit_expr(f.obj);
                    self.p(", \"{s}\", {d}u, {d})", .{ f.field, hash, f.field.len });
                }
                return true;
            },
            .index => |idx| {
                // THE ENVIRONMENT PROJECTION IS NOT A TABLE LOOKUP, and this
                // emitter is the one that did not know it. Asked ONCE, at the
                // single entry of the arm rather than in each `want` branch
                // below: the three branches differ only in which unboxer they
                // name, so a per-`want` check would be reintroduced as a hole
                // by the next specialization added.
                //
                // Without it a typed consumer of `env(k)` emitted
                // `lua_table_get_key_cstr(lua_table_get_str_lit(os, "env", …), …)`
                // — a lookup in an unpopulated Lua table, which answers NIL for
                // a variable that is genuinely set. `emit_expr`'s own `.index`
                // arm has carried the recognizer since the projection landed,
                // but THIS function is consulted first by `emit_dynamic_unbox`,
                // so it wins before that guard is ever reached.
                if (self.env_projection_key(e) != null) {
                    if (want == .str) {
                        try self.emit_expr(e);
                        return true;
                    }
                    return false;
                }
                if (self.req_module_dense_index_info(idx.obj)) |nd| {
                    self.p("{s}[", .{nd.c_symbol});
                    try self.emit_expr(idx.key);
                    self.p("]", .{});
                    return true;
                }
                // A dense table is a native array, not a `lua_Value` — this arm
                // would otherwise hand `__dt_t` to `lua_table_get_i64_num`.
                if (self.is_dense_table_index(idx.obj)) {
                    const dt = idx.obj.name.ident;
                    const info = self.dense_table_info(dt);
                    if (want.is_numeric()) {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})", .{want.c_type(&buf)});
                    } else {
                        self.p("(", .{});
                    }
                    if (self.dense_unchecked) {
                        self.p("__dt_{s}[", .{dt});
                        try self.emit_dense_key(idx.key);
                        self.p("])", .{});
                        return true;
                    }
                    self.p("duo_dt_get_{s}(__dt_{s}, __dtc_{s}, ", .{ info.sfx(), dt, dt });
                    try self.emit_dense_key(idx.key);
                    self.p("))", .{});
                    return true;
                }
                if (self.is_native_dense_module_index(idx.obj)) return false;
                if (self.is_integer_key(idx.key) or positive_int_key(idx.key) != null) {
                    if (want.is_numeric()) {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})lua_table_get_i64_num(", .{want.c_type(&buf)});
                    } else if (want == .bool) {
                        self.p("lua_table_get_i64_bool(", .{});
                    } else {
                        self.p("lua_table_get_i64_cstr(", .{});
                    }
                    try self.emit_expr(idx.obj);
                    self.p(", ", .{});
                    if (positive_int_key(idx.key)) |key| {
                        self.p("{d}", .{key});
                    } else {
                        try self.emit_i64_index_key(idx.key);
                    }
                } else {
                    if (want.is_numeric()) {
                        var buf: [64]u8 = undefined;
                        self.p("(({s})lua_table_get_key_num(", .{want.c_type(&buf)});
                    } else if (want == .bool) {
                        self.p("lua_table_get_key_bool(", .{});
                    } else {
                        self.p("lua_table_get_key_cstr(", .{});
                    }
                    try self.emit_expr(idx.obj);
                    self.p(", ", .{});
                    try self.emit_as_lua_value(idx.key);
                }
                if (want.is_numeric())
                    self.p("))", .{})
                else
                    self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// True when a `.any` binop operand is a table field/index (or numeric call)
    /// whose value is known to be numeric — safe to unbox without skipping metamethods
    /// on arbitrary userdata/table objects.
    fn dynamic_binop_operand_is_numeric_access(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            // Table field reads on dynamic objects; emit unboxes when the value is numeric.
            .field => true,
            .index => |idx| self.expr_type(e).is_numeric() or
                (self.expr_is_dynamic_table(idx.obj) and self.is_integer_key(idx.key)),
            .call => self.expr_type(e).is_numeric(),
            .unop => |u| u.op == .neg and self.dynamic_binop_operand_is_numeric_access(u.operand),
            else => false,
        };
    }

    /// Dynamic table field/index read on a `.any` object — still runs full `lua_table_get`
    /// (including `__index`), but pairs with a numeric-marked local in one-sided binops.
    fn dynamic_binop_operand_is_dynamic_table_read(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .field => |f| blk: {
                if (self.expr_is_req_module_const_field(e)) break :blk false;
                const obj_rt = self.expr_type(f.obj);
                if (obj_rt == .table_type and obj_rt.table_type.storage_class == .native) break :blk false;
                break :blk self.expr_is_dynamic_table(f.obj);
            },
            .index => self.expr_is_dynamic_table(e.index.obj),
            else => false,
        };
    }

    /// Operand safe to treat as a number in a native binop when the other side
    /// is also safe. Bare `.name` locals only qualify after numeric assignment.
    fn dynamic_binop_operand_is_safe_native_unbox(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .int_lit, .float_lit => true,
            .name => |n| self.is_numeric_lua_local(n.ident),
            else => blk: {
                if (self.expr_is_req_module_const_field(e)) break :blk true;
                if (self.expr_is_native_record_field(e)) break :blk true;
                break :blk self.dynamic_binop_operand_is_numeric_access(e);
            },
        };
    }

    /// Both operands are `.any` but each can be unboxed without metamethod dispatch.
    fn try_emit_both_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(lhs)) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(rhs)) return false;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(lhs) or self.expr_tree_has_float(rhs);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// One operand is a numeric-marked `lua_Value` local (or literal); the other is a
    /// dynamic table read with a non-numeric key/param. Unbox the local side only.
    fn try_emit_one_sided_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        const lhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(lhs);
        const rhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(rhs);
        if (lhs_safe and rhs_safe) return false;

        const pair: struct { safe: *const ast.Expr, read: *const ast.Expr } = if (lhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(rhs) and !rhs_safe)
            .{ .safe = lhs, .read = rhs }
        else if (rhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(lhs) and !lhs_safe)
            .{ .safe = rhs, .read = lhs }
        else
            return false;
        const safe_expr = pair.safe;
        const read_expr = pair.read;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(safe_expr) or self.expr_tree_has_float(read_expr);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// Both operands are dynamic table reads with non-safe keys (e.g. untyped index
    /// params). Still runs full `lua_table_get` per operand; skips `lua_add` etc. on
    /// numeric table values. Not used when either side is a bare `.name` or already
    /// handled by both-any / one-sided paths.
    fn try_emit_both_dynamic_table_read_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        if (!self.dynamic_binop_operand_is_dynamic_table_read(lhs)) return false;
        if (!self.dynamic_binop_operand_is_dynamic_table_read(rhs)) return false;
        if (self.dynamic_binop_operand_is_safe_native_unbox(lhs)) return false;
        if (self.dynamic_binop_operand_is_safe_native_unbox(rhs)) return false;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(lhs) or self.expr_tree_has_float(rhs);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// When exactly one binop operand is a native scalar and the other is `.any`,
    /// emit a direct C operator with a single unbox on the dynamic side.
    fn try_emit_mixed_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        const native_t: RT = if (lt.is_native() and lt != .any and rt == .any)
            lt
        else if (rt.is_native() and rt != .any and lt == .any)
            rt
        else
            return false;
        const native_is_lhs = lt.eql(native_t);
        const any_expr = if (native_is_lhs) rhs else lhs;
        const native_expr = if (native_is_lhs) lhs else rhs;
        const via_any_unbox = self.dynamic_binop_operand_is_safe_native_unbox(any_expr);
        const via_dynamic_read = self.dynamic_binop_operand_is_dynamic_table_read(any_expr);
        const via_native_access = self.dynamic_binop_operand_is_numeric_access(native_expr);
        if (!via_any_unbox and !via_native_access and !via_dynamic_read) return false;
        // Unbox the `.any` side; the native side is either a typed local or a
        // numeric table access that already lowers to a native scalar.
        const dynamic = any_expr;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        if (op == .@"and" or op == .@"or") {
            if (native_t != .bool) return false;
            if (op == .@"or") {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") : (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p("))", .{});
            } else {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p(") : (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p("))", .{});
            }
            return true;
        }

        if ((op == .eq or op == .neq) and native_t == .str) {
            if (!self.expr_is_native_cstr(if (native_is_lhs) lhs else rhs)) return false;
            self.p("(strcmp(", .{});
            if (native_is_lhs) {
                try self.emit_expr(lhs);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .str);
            } else {
                try self.emit_dynamic_unbox(lhs, .str);
                self.p(", ", .{});
                try self.emit_expr(rhs);
            }
            self.p(") {s} 0)", .{if (op == .eq) "==" else "!="});
            return true;
        }

        if (native_t == .bool) return false;

        const use_float = native_t == .f64 or op == .div or self.expr_tree_has_float(dynamic);
        const unbox_t: RT = if (use_float) .f64 else if (native_t.is_integer()) .i64 else native_t;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, unbox_t);
                } else {
                    try self.emit_dynamic_unbox(lhs, unbox_t);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            .idiv => {
                if (native_is_lhs) {
                    self.p("lua_idiv_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_idiv_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .mod => {
                if (native_is_lhs) {
                    self.p("lua_imod_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_imod_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                if (!native_t.is_integer()) return false;
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, .i64);
                } else {
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    fn collect_concat_operands(self: *CodeGen, expr: *const ast.Expr, parts: *std.ArrayList(*const ast.Expr)) E!void {
        if (expr.* == .binop and expr.binop.op == .concat) {
            try self.collect_concat_operands(expr.binop.lhs, parts);
            try self.collect_concat_operands(expr.binop.rhs, parts);
            return;
        }
        try parts.append(self.alloc, expr);
    }

    /// The exact condition `try_emit_native_str_concat` tests, as a predicate:
    /// every collected part of the concat tree is a native cstr. Mirrors
    /// `concat_operand_is_native_cstr` over the whole tree so consumers like
    /// `expr_is_native_cstr` can ask the emitter's own question without
    /// emitting.
    fn concat_tree_is_native_cstr(self: *CodeGen, expr: *const ast.Expr) bool {
        var parts: std.ArrayList(*const ast.Expr) = .empty;
        defer parts.deinit(self.alloc);
        self.collect_concat_operands(expr, &parts) catch return false;
        if (parts.items.len == 0) return false;
        for (parts.items) |part| {
            if (!self.concat_operand_is_native_cstr(part)) return false;
        }
        return true;
    }

    fn concat_operand_is_native_cstr(self: *CodeGen, expr: *const ast.Expr) bool {
        return self.expr_type(expr) == .str and !self.expr_emits_lua_value(expr);
    }

    /// gap[094]. TRUE for a compile-time EMPTY text literal operand of `..`.
    ///
    /// The parser seeds single-hole interpolation with an empty literal so that
    /// `"{i}"` and `"x{i}"` are one desugar shape (`"" .. i` beside `"x" .. i`).
    /// That seed is a SOURCE-shaped realization, not a semantic demand: the
    /// only observation the program makes is the text VALUE, and concatenating
    /// the empty text is the identity on that observation
    /// (`law.observation.minimum`). So the native C projection consumes the
    /// exact graph fact — an operand that is a text literal of length zero —
    /// and elides the concat instead of materializing an empty segment plus a
    /// second allocation, `strlen`, and `memcpy`.
    ///
    /// The witness is structural and complete: an empty literal has no effect,
    /// so dropping it changes no evaluation order; the surviving operand is
    /// emitted through the same display conversion (`emit_native_display_cstr`)
    /// the concat arm would have fed it through, so the produced bytes are
    /// byte-identical; and the concat's fresh allocation is not a semantic
    /// observation — text is immutable in this projection. The BYTE face is
    /// excluded: `''` is a byte-sequence value under `law.literal.bytes`, and
    /// this witness speaks only for text. The boxed `lua_concat` path is also
    /// excluded: under Lua law `"" .. x` errors on nil/table and STRINGIFIES a
    /// number, so eliding there would change observable law — the equivalence
    /// is witnessed only where the operand's display conversion is already the
    /// exact realization, which is the full-native arm below.
    fn concat_operand_is_empty_text(expr: *const ast.Expr) bool {
        return switch (expr.*) {
            .quoted => |lit| lit.val.len == 0 and !ast.quotedLiteralIsByteSequence(lit.quote),
            else => false,
        };
    }

    /// Render a native scalar as a C string, for the contexts where the boxed
    /// backend would have called `lua_to_str`.
    ///
    /// A full-native module has no `lua_Value` and no `lua_*` runtime, so the
    /// display conversion has to be spelled in plain C. Emitting the boxed call
    /// anyway is the declaration/use asymmetry that produced
    /// "call to undeclared function 'lua_to_str'" and then, because C treats an
    /// implicit declaration as returning `int`, a second `-Wint-conversion`
    /// error when the result was handed to `duo_str_concat`. The formats below
    /// mirror `lua_to_str` exactly so both backends print the same text.
    fn emit_native_display_cstr(self: *CodeGen, expr: *const ast.Expr) E!void {
        const t = self.expr_type(expr);
        if (t == .str) {
            try self.emit_expr(expr);
        } else if (t == .bool) {
            self.p("duo_str_from_bool(", .{});
            try self.emit_expr(expr);
            self.p(")", .{});
        } else if (t.is_float()) {
            self.p("duo_str_from_f64((double)(", .{});
            try self.emit_expr(expr);
            self.p("))", .{});
        } else if (t.is_integer()) {
            self.p("duo_str_from_i64((int64_t)(", .{});
            try self.emit_expr(expr);
            self.p("))", .{});
        } else {
            try self.emit_expr(expr);
        }
    }

    fn emit_native_str_concat_left_fold(self: *CodeGen, parts: []const *const ast.Expr, count: usize) E!void {
        if (count == 1) {
            try self.emit_expr(parts[0]);
            return;
        }
        self.p("duo_str_concat(", .{});
        try self.emit_native_str_concat_left_fold(parts, count - 1);
        self.p(", ", .{});
        try self.emit_expr(parts[count - 1]);
        self.p(")", .{});
    }

    fn try_emit_native_str_concat(self: *CodeGen, expr: *const ast.Expr) E!bool {
        var parts: std.ArrayList(*const ast.Expr) = .empty;
        defer parts.deinit(self.alloc);
        try self.collect_concat_operands(expr, &parts);
        if (parts.items.len == 0) return false;
        for (parts.items) |part| {
            if (!self.concat_operand_is_native_cstr(part)) return false;
        }
        // gap[094]. Empty text segments are identity operands of `..`; see
        // `concat_operand_is_empty_text`. Dropping them here means an all-str
        // chain that only ever had one real segment folds to that segment with
        // no `duo_str_concat` call at all (`count == 1` emits the part bare).
        var kept: usize = 0;
        for (parts.items) |part| {
            if (concat_operand_is_empty_text(part)) continue;
            parts.items[kept] = part;
            kept += 1;
        }
        if (kept == 0) {
            // Every segment was empty, so the value IS the empty text.
            self.p("\"\"", .{});
            return true;
        }
        try self.emit_native_str_concat_left_fold(parts.items, kept);
        return true;
    }

    fn expr_is_string_char_call(_: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .field) return false;
        const f = e.call.func.field;
        return f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "string") and
            std.mem.eql(u8, f.field, "char");
    }

    fn emit_string_char_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        const c = expr.call;
        self.p("lua_str_char(", .{});
        for (0..4) |i| {
            if (i > 0) self.p(", ", .{});
            if (i < c.args.len) {
                try self.emit_as_lua_value(c.args[i]);
            } else {
                self.p("lua_val_nil()", .{});
            }
        }
        self.p(")", .{});
    }

    fn emit_as_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        // Full-native programs never box — emit direct C values only.
        if (!self.moduleNeedsLuaRuntime()) {
            try self.emit_expr(expr);
            return;
        }
        // THE BOXED PROJECTION MUST NOT BOX A NULL. `getenv` answers NULL for an
        // absent variable, and the generic `.str` boxing wrapper is
        // `lua_val_from_str`, which dereferences it. MEASURED:
        //
        //     sh(env("IDOLPROBE"))   ->  lua_Value duo_args[1] =
        //                                    {lua_val_from_str(getenv("IDOLPROBE"))};
        //     IDOLPROBE=z ./a.out    ->  z, rc 0
        //     env -u IDOLPROBE ./a.out -> SIGSEGV, rc 139
        //
        // ABSENCE IS A NORMAL ANSWER on this projection — it is the answer live
        // corpus sites branch on — so the boxed face has to be able to carry it.
        // `lua_os_getenv` is already unconditional in the boxed prelude and is
        // exactly this function: it null-checks and answers `lua_val_nil()`.
        // Calling it beats hand-rolling the box, which is how the null got in.
        //
        // The UNBOXED face keeps emitting a bare `getenv` — a `const char*`
        // consumer wants the pointer, and NULL is what absence is there. The
        // read face's own ruling (docs/env-identity.md: absence TRAPS, and
        // `env(k, absent)` is the total form) is what finally removes that
        // asymmetry; this stops the boxed half from being undefined behaviour in
        // the meantime.
        if (self.env_projection_key(expr)) |key| {
            self.p("lua_os_getenv(", .{});
            try self.emit_as_lua_value(key);
            self.p(")", .{});
            return;
        }
        if (expr.* == .name) {
            if (self.is_native_dense_module_table(expr.name.ident)) {
                try self.emit_native_dense_module_table_as_lua_value(expr.name.ident);
                return;
            }
            if (self.vararg_funcs.get(expr.name.ident)) |argv_cname| {
                self.p("lua_val_from_func((void*){s}__argv)", .{argv_cname});
                return;
            }
            // A module file-scope constant is emitted as a *native* C const
            // (`static const int64_t std_hash_crc64__poly_lo`), but `expr_type`
            // reports it as a plain comptime binding, so no boxing wrapper was
            // added and it reached `lua_bxor` raw: "passing 'const int64_t' to
            // parameter of incompatible type 'lua_Value'". Box it here, where we
            // know a lua_Value is required.
            if (self.current_module_cname.len > 0 and
                self.global_type(expr.name.ident) == null and
                !self.is_local_name(expr.name.ident) and
                self.function_c_names.get(expr.name.ident) == null)
            {
                if (self.comptime_bindings().get(expr.name.ident)) |cv| {
                    const wrap: ?[]const u8 = switch (cv) {
                        .int => "lua_val_from_int",
                        .float, .decimal => "lua_val_from_num",
                        .bool => "lua_val_from_bool",
                        else => null,
                    };
                    if (wrap) |w| {
                        self.p("{s}(", .{w});
                        self.emit_var_name(expr.name.ident);
                        self.p(")", .{});
                        return;
                    }
                }
            }
        }
        if (expr.* == .quoted) {
            const hash = calc_lua_hash(expr.quoted.val);
            self.p("lua_val_from_literal(\"", .{});
            try self.emit_string_escaped(expr.quoted.val);
            self.p("\", {d}, {d})", .{ hash, expr.quoted.val.len });
            return;
        }
        const t = self.expr_type(expr);
        const skip_numeric_unbox = blk: {
            const fn_name = self.current_func_name orelse break :blk false;
            if (!self.funcUsesNativeLowering(fn_name)) break :blk false;
            if (!self.exprKnowledge(expr).dominates(.stable)) break :blk false;
            break :blk self.exprLowersToNativeC(t);
        };
        switch (t) {
            .str => {
                if (self.expr_is_string_char_call(expr)) {
                    try self.emit_string_char_lua_value(expr);
                } else if (self.expr_emits_lua_value(expr)) {
                    try self.emit_expr(expr);
                } else {
                    self.p("lua_val_from_str(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                }
            },
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                self.p("lua_val_from_int((int64_t)(", .{});
                if (self.expr_emits_lua_value(expr) and !skip_numeric_unbox) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .f32, .f64 => {
                self.p("lua_val_from_num((double)(", .{});
                if (self.expr_emits_lua_value(expr) and !skip_numeric_unbox) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .bool => {
                self.p("lua_val_from_bool(", .{});
                try self.emit_expr(expr);
                self.p(")", .{});
            },
            .func => {
                if (expr.* == .func_expr) {
                    try self.emit_expr(expr);
                } else {
                    try self.emit_native_func_as_lua_value(expr);
                }
            },
            .any => {
                try self.emit_expr(expr);
            },
            else => {
                self.p("lua_val_nil()", .{});
            },
        }
    }

    fn emit_bound_field_call(self: *CodeGen, c: anytype) E!void {
        const f = c.func.field;
        const hash = calc_lua_hash(f.field);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __self = ", .{});
        try self.emit_as_lua_value(f.obj);
        self.p(";\n", .{});
        self.ind();
        self.p("lua_Value __fn = lua_table_get_str_lit(__self, \"{s}\", {d}u, {d});\n", .{ f.field, hash, f.field.len });
        self.ind();
        self.p("lua_Value duo_args[{d}] = {{__self", .{c.args.len + 1});
        for (c.args) |arg| {
            self.p(", ", .{});
            try self.emit_as_lua_value(arg);
        }
        self.p("}};\n", .{});
        self.ind();
        self.p("lua_invoke(__fn, {d}, duo_args);\n", .{c.args.len + 1});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    // ── Expressions ───────────────────────────────────────────────────────────

    fn emit_num_for_bound(self: *CodeGen, expr: *const ast.Expr, vt: RT) E!void {
        if (self.expr_type(expr) == .any and !self.expr_is_raw_c_intrinsic(expr)) {
            self.p("(", .{});
            self.typ(vt);
            self.p(")lua_to_num(", .{});
            try self.emit_as_lua_value(expr);
            self.p(")", .{});
        } else {
            try self.emit_expr(expr);
        }
    }

    /// True when the expression is the nil literal.
    fn expr_is_nil_lit(self: *CodeGen, e: *const ast.Expr) bool {
        _ = self;
        return e.* == .nil;
    }

    /// True when a native (non-any, non-pointer) typed value can never hold nil.
    fn expr_is_typed_non_nil(self: *CodeGen, e: *const ast.Expr) bool {
        const t = self.expr_type(e);
        return t != .any and t != .nil and t != .str and t != .func and t != .pointer;
    }

    fn emit_list_comprehension(self: *CodeGen, lc: ast.ListComprehension) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        try self.push_local_scope();
        defer self.pop_local_scope();

        self.ind();
        self.p("lua_Value tmp = lua_table_new();\n", .{});
        self.ind();
        self.p("lua_Value tbl = ", .{});
        try self.emit_as_lua_value(lc.iter);
        self.p(";\n", .{});
        self.ind();
        self.p("int out_idx = 1;\n", .{});
        self.ind();
        self.p("if (tbl.type == VAL_TABLE) {{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Table* t_ptr = (lua_Table*)tbl.as.tval;\n", .{});

        if (lc.key_name) |key_name| {
            try self.note_local(key_name);
            try self.note_local(lc.value_name);

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->array[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = lua_val_from_num((double)(_gf_idx + 1));\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->capacity; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->hash_keys[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_keys[_gf_idx];\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_vals[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        } else {
            try self.note_local(lc.value_name);
            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            self.ind();
            self.p("if ({s}.type == VAL_NIL) break;\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }

        self.indent -= 1;
        self.ind();
        self.p("}}\n", .{});
        self.ind();
        self.p("tmp;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_list_comprehension_append(self: *CodeGen, lc: ast.ListComprehension) E!void {
        if (lc.filter) |filter| {
            self.ind();
            self.p("if (", .{});
            try self.emit_lua_truthy_expr(filter);
            self.p(") {{\n", .{});
            self.indent += 1;
        }
        self.ind();
        self.p("lua_table_set_raw_i64(tmp, out_idx++, ", .{});
        try self.emit_as_lua_value(lc.value);
        self.p(");\n", .{});
        if (lc.filter != null) {
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
    }

    /// `#x` where the operand's type is `.any` (untyped / boxed).
    ///
    /// With the Lua runtime present this is `lua_len_num`, which dispatches on
    /// the boxed tag: table length, string length, 0 for nil. Both `.any` arms
    /// of the `.len` unop used to emit that call unconditionally, but the
    /// runtime preamble that DEFINES `lua_len_num` is emitted only when
    /// `moduleNeedsLuaRuntime()` holds. A full-native module therefore got the
    /// call with no declaration, and clang rejected the whole file with "call
    /// to undeclared function 'lua_len_num'" — examples/nil_init_smoke.duo,
    /// hence `zig build agent-smoke`, died there. Same declaration/use
    /// asymmetry as the `duo_test_jmp` one fixed above.
    ///
    /// There the fix was to declare the symbol on every target. Here it cannot
    /// be: `lua_len_num` takes a `lua_Value`, and a full-native module has no
    /// `lua_Value` type, so declaring it would drag the entire boxed runtime
    /// back in to serve one length. The call goes instead.
    ///
    /// The `.any` bindings full-native mode actually emits are the `void*` a
    /// nil-initialised local starts as — `x = nil` then `x = "hi"`, which is
    /// exactly the smoke test — and what later lands in one is a C string.
    /// Native-list and dense-module shapes are recognised by their own arms
    /// before reaching here. `strlen` is the native reading of the same edge,
    /// and the NULL guard reproduces `lua_len_num`'s own answer for an operand
    /// that is still nil: 0.
    fn emit_any_len(self: *CodeGen, operand: *const ast.Expr) E!void {
        if (self.moduleNeedsLuaRuntime()) {
            self.p("lua_len_num(", .{});
            try self.emit_expr(operand);
            self.p(")", .{});
            return;
        }
        self.p("({{ const char* _duo_lenv = (const char*)(", .{});
        try self.emit_expr(operand);
        self.p("); _duo_lenv ? (int64_t)strlen(_duo_lenv) : (int64_t)0; }})", .{});
    }

    fn emit_expr(self: *CodeGen, expr: *const ast.Expr) E!void {
        switch (expr.*) {
            .quote, .unquote, .macro_call => self.p("/* unexpanded macro expression */ lua_val_nil()", .{}),
            // G1/G2 (`@name`, `@`) are canon but Phase 0 ships no parser
            // production for them, so nothing reaches here. Refuse rather than
            // invent a lowering before the resolution ladder exists.
            .semantic, .semantic_scope => self.p("/* Pass 36 semantic access: not yet lowered */ lua_val_nil()", .{}),
            .sequence => |seq| {
                // In single-value context, emit first expression; rest are side effects.
                if (seq.exprs.len > 0) {
                    try self.emit_expr(seq.exprs[0]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
            },
            .nil => self.p("NULL", .{}),
            .true_lit => self.p("true", .{}),
            .false_lit => self.p("false", .{}),
            .int_lit => |v| self.emit_c_int_literal(v.val),
            .float_lit => |v| self.p("{e}", .{v.val}),
            // Producer quote owns the face (GAP-145 O5): this generic emitter
            // has no byte-sequence realization, so a byte-face quote is
            // refused as a commented placeholder — never silently emitted as
            // a text literal. Same total-but-honest route this switch already
            // uses for unrealizable constructs.
            .quoted => |v| if (ast.quotedLiteralIsByteSequence(v.quote))
                self.p("/* byte-sequence face has no realization in this emitter */ lua_val_nil()", .{})
            else {
                self.p("\"", .{});
                try self.emit_string_escaped(v.val);
