                    };
                    if (invoke_argc == 0) {
                        self.pl("lua_invoke(__fn, 0, NULL);", .{});
                    } else {
                        self.p("lua_Value duo_args[{d}] = {{", .{invoke_argc});
                        for (0..invoke_argc) |i| {
                            if (i > 0) self.p(", ", .{});
                            if (i < c.args.len) {
                                try self.emit_as_lua_value(c.args[i]);
                            } else {
                                self.p("lua_val_nil()", .{});
                            }
                        }
                        self.p("}};\n", .{});
                        self.ind();
                        self.p("lua_invoke(__fn, {d}, duo_args);\n", .{invoke_argc});
                    }
                    self.indent -= 1;
                    self.ind();
                    self.p("}})", .{});
                    if (rt_accepts_lua_value_coercion(invoke_result_rt)) {
                        self.emit_lua_value_coercion_end(invoke_result_rt);
                    }
                    return;
                }
                // Field access on a dynamic (any-typed) table returns a lua_Value,
                // not a C function pointer. Route through lua_invoke even when
                // expr_type resolved the field to .func via table_field_types.
                if (c.func.* == .field and self.expr_type(c.func.field.obj) == .any) {
                    const invoke_result_rt = self.expr_type(expr);
                    if (rt_accepts_lua_value_coercion(invoke_result_rt)) {
                        self.emit_lua_value_coercion_start(invoke_result_rt);
                    }
                    self.p("({{\n", .{});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __fn = ", .{});
                    try self.emit_expr(c.func);
                    self.p(";\n", .{});
                    self.ind();
                    if (c.args.len == 0) {
                        self.pl("lua_invoke(__fn, 0, NULL);", .{});
                    } else {
                        self.p("lua_Value duo_args[{d}] = {{", .{c.args.len});
                        for (c.args, 0..) |arg, i| {
                            if (i > 0) self.p(", ", .{});
                            try self.emit_as_lua_value(arg);
                        }
                        self.p("}};\n", .{});
                        self.ind();
                        self.p("lua_invoke(__fn, {d}, duo_args);\n", .{c.args.len});
                    }
                    self.indent -= 1;
                    self.ind();
                    self.p("}})", .{});
                    if (rt_accepts_lua_value_coercion(invoke_result_rt)) {
                        self.emit_lua_value_coercion_end(invoke_result_rt);
                    }
                    return;
                }
                try self.emit_expr(c.func);
                self.p("(", .{});
                const callee_body: ?*const ast.FuncBody = if (c.func.* == .name) blk: {
                    var name_buf: [256]u8 = undefined;
                    break :blk self.func_bodies.get(self.mangled_name(c.func.name.ident, &name_buf));
                } else null;
                const callee_abi: ParamAbi = if (self.expr_names_foreign_func(c.func)) .foreign else .internal;
                var emitted_args: usize = 0;
                for (c.args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    switch (ft) {
                        .func => |f| {
                            if (i < f.params.len) {
                                try self.emit_arg_for_param_abi(arg, f.params[i], true, callee_abi);
                            } else {
                                try self.emit_expr(arg);
                            }
                        },
                        else => {
                            try self.emit_as_lua_value(arg);
                        },
