                    }
                }
                self.p(")", .{});
            },
            .method_call => |mc| {
                const ot = self.expr_type(mc.obj);

                // LAW-CALL generalized (spec 4.2, S13): a `:` invocation
                // resolves ordinary members FIRST — data always wins the name —
                // then a relation family with a receiver-bindable role,
                // normalizing to the SAME edge: `p:to(str)` === `to(str)(p)`.
                // Restricted to scalar receivers, where no user member can
                // exist, so the data-wins rule is preserved by construction.
                // Retrieval stays anchored (`p@to` is the value; `p:to(str)`
                // is the act).
                // law.host.projection { projects = to, authority = false }
                // gap[082] is the deletion gate.
                if (mc.args.len == 1 and std.mem.eql(u8, mc.method, "to") and
                    (ot.is_numeric() or ot == .str or ot == .bool or
                        self.untyped_receiver_takes_convert_edge(ot, mc)))
                {
                    var fam = ast.Expr{ .name = .{ .loc = mc.loc, .ident = "to" } };
                    var inner_args = [_]*ast.Expr{mc.args[0]};
                    var inner = ast.Expr{ .call = .{ .loc = mc.loc, .func = &fam, .args = inner_args[0..] } };
                    var outer_args = [_]*ast.Expr{mc.obj};
                    if (try self.maybe_emit_stdlib_call(&inner, outer_args[0..], self.expr_type(expr))) return;
                    if (mc.args[0].* == .name) {
                        const dest = mc.args[0].name.ident;
                        if (try self.emit_relation_convert_exhaustive(dest, mc.loc, mc.obj, self.expr_type(expr))) return;
                    }
                }

                // `env:remove(k)` — the REMOVAL edge, POSIX `unsetenv(k)`.
                // Asked before every other receiver face for the same reason
                // `stdout:write` is: the subject is a WORLD, not a value with a
                // metatable, and the fallback path emits
                // `lua_table_get_str_lit(os, "env", ...)` against an identifier
                // nothing declares.
                if (self.env_remove_method(mc.method, mc.obj, mc.args)) {
                    self.p("unsetenv(", .{});
                    try self.emit_cstr_arg(mc.args[0]);
                    self.p(")", .{});
                    return;
                }
                if (try self.tryEmitSubjectRelation(mc)) return;
                if (try self.try_emit_file_stream_protocol(mc)) return;
                if (try self.try_emit_readable_protocol(mc)) return;
                if (try self.try_emit_egress_protocol(mc)) return;

                // ═══════════════════════════════════════════════════════════
                // Zero-cost metatable dispatch: if we know the object's type
                // has a method defined in its alias_defs, emit a direct call
                // instead of going through lua_table_get + lua_invoke.
                // ═══════════════════════════════════════════════════════════
                if (ot == .any and mc.obj.* == .name) {
                    const obj_name = mc.obj.name.ident;
                    // Check if this variable has a known type alias with methods
                    if (self.record_aliases.get(obj_name)) |alias_rt| {
                        if (alias_rt == .@"struct") {
                            if (self.alias_defs.get(alias_rt.@"struct".name)) |alias_def| {
                                for (alias_def.methods) |method| {
                                    const mname = if (method.path.len > 0) method.path[method.path.len - 1] else "";
                                    if (std.mem.eql(u8, mname, mc.method)) {
