                    if (self.enum_name_of(ot)) |enum_name| {
                        if (self.enum_has_derive(enum_name, "Eq") and self.enum_is_payload_free(enum_name) and mc.args.len >= 1) {
                            self.p("duo_{s}_eq(", .{enum_name});
                            try self.emit_expr(mc.obj);
                            self.p(", ", .{});
                            try self.emit_expr(mc.args[0]);
                            self.p(")", .{});
                            return;
                        }
                    }
                }
                if (std.mem.eql(u8, mc.method, "to_string")) {
                    if (self.enum_name_of(ot)) |enum_name| {
                        if (self.enum_has_derive(enum_name, "Display") and self.enum_is_payload_free(enum_name)) {
                            self.p("duo_{s}_to_string(", .{enum_name});
                            try self.emit_expr(mc.obj);
                            self.p(")", .{});
                            return;
                        }
                    }
                }
                if (ot == .any) {
                    if (self.static_dispatch_type_for_expr(mc.obj, mc.method)) |tname| {
                        if (try self.try_emit_static_method_call(tname, mc.method, mc.obj, mc.args)) return;
                    }
                    // gap[032]: a receiver face on an `any` receiver returned
                    // nil, silently. The receiver fell straight through to the
                    // table-member dispatch at the bottom of this branch, and a
                    // string has no members — so `cur.s:byte(i)` looked "byte"
                    // up on a string, found nil, invoked nil, and produced nil
                    // with no diagnostic. A table FIELD is `any`, so every site
                    // the corpus-wide string.byte (299) and string.sub (369)
                    // sweeps converted whose receiver was a field went
                    // quiet-wrong: std.json.decode returned the number 0 and
                    // std.wasm.decode read every opcode as 0.
                    //
                    // The repair is the runtime-guarded dispatch gap[014] named
                    // as the only correct shape: if the receiver IS a string at
                    // run time take the string face, otherwise take the member
                    // path unchanged. Data still wins the name by construction,
                    // because a string cannot carry a member — a table with its
                    // own `sub` is never hijacked, which is what sank the
                    // unconditional projection tried for gap[014].
                    if (try self.try_emit_guarded_string_face(mc.method, mc.obj, mc.args, self.expr_type(expr))) return;
                    if (std.mem.eql(u8, mc.method, "put") or std.mem.eql(u8, mc.method, "write")) {
                        self.p("lua_file_write_method(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) {
                            try self.emit_as_lua_value(mc.args[0]);
                        } else {
                            self.p("lua_val_nil()", .{});
                        }
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "get") or std.mem.eql(u8, mc.method, "tostring") or std.mem.eql(u8, mc.method, "read")) {
                        self.p("lua_file_read_method(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) {
                            try self.emit_as_lua_value(mc.args[0]);
                        } else {
                            self.p("lua_val_nil()", .{});
                        }
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "reset")) {
                        self.p("lua_str_buf_reset(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "set")) {
                        self.p("lua_str_buf_set(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) try self.emit_as_lua_value(mc.args[0]) else self.p("lua_val_nil()", .{});
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "free")) {
                        self.p("lua_str_buf_free(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "len")) {
                        // The receiver's RUNTIME type decides, because `any`
                        // covers string, table and str-buf and the str-buf
                        // face answers 0 for the other two. Measured: a file
                        // read into an untyped local reported `bytes:len()`
                        // == 0 where `string.len(bytes)` reported 27791, and
                        // the wasm engine's `bytes:len() < 8` magic guard
                        // therefore rejected every module it was given.
                        if (mc.obj.* == .name and self.is_native_split_str_list_local(mc.obj.name.ident)) {
                            self.p("{s}.len", .{mc.obj.name.ident});
                            return;
                        }
                        const result_rt = self.expr_type(expr);
                        self.p("{s}(", .{if (result_rt.is_integer()) "lua_any_len_i64" else "lua_any_len"});
                        try self.emit_expr(mc.obj);
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "putf")) {
                        self.p("lua_str_buf_putf(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) try self.emit_as_lua_value(mc.args[0]) else self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        if (mc.args.len > 1) try self.emit_as_lua_value(mc.args[1]) else self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        if (mc.args.len > 2) try self.emit_as_lua_value(mc.args[2]) else self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        if (mc.args.len > 3) try self.emit_as_lua_value(mc.args[3]) else self.p("lua_val_nil()", .{});
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "close")) {
                        self.p("lua_io_close(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "flush")) {
                        self.p("lua_file_flush_method(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "seek")) {
                        self.p("lua_file_seek_method(", .{});
                        try self.emit_expr(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) try self.emit_as_lua_value(mc.args[0]) else self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        if (mc.args.len > 1) try self.emit_as_lua_value(mc.args[1]) else self.p("lua_val_nil()", .{});
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "setvbuf")) {
