                        // buffering is fine, so this is a no-op that returns the file
                        // handle (matches Lua's file:setvbuf contract). Previously fell
                        // through to the generic method lookup, found nil, and crashed.
                        try self.emit_expr(mc.obj);
                    } else if (std.mem.eql(u8, mc.method, "contains")) {
                        self.p("lua_val_from_bool(duo_contains(", .{});
                        try self.emit_as_lua_value(mc.obj);
                        self.p(", ", .{});
                        if (mc.args.len > 0) try self.emit_as_lua_value(mc.args[0]) else self.p("lua_val_nil()", .{});
                        self.p("))", .{});
                    } else if (std.mem.eql(u8, mc.method, "push") and mc.args.len == 1) {
                        // gap[068]. `t:push(v)` is THE canonical append (§0.9 —
                        // `table.` DOES NOT EXIST, so there is no other
                        // spelling). It had no arm here, so it fell through to
                        // the generic lookup, read the field `push` off the
                        // table, got NIL, and `lua_invoke(nil, …)` did nothing
                        // at all. `t = { }` / `t:push(10)` / `t:push(29)` then
                        // printed `0 nil nil` — exit 0, `ok compile`, no
                        // diagnostic. Both appends vanished, and the wrong
                        // answer was EMPTY, which reads as "no results" rather
                        // than "the append did not happen".
                        //
                        // `lua_tbl_insert(t, v, nil)` is the append arm of the
                        // same helper `table.insert` already used, so this adds
                        // no new runtime surface — it routes the canonical
                        // spelling to the code that was always there. Alias and
                        // record methods are resolved ABOVE this chain, so a
                        // user-defined `push` still wins.
                        self.p("lua_tbl_insert(", .{});
                        try self.emit_as_lua_value(mc.obj);
                        self.p(", ", .{});
                        try self.emit_as_lua_value(mc.args[0]);
                        self.p(", lua_val_nil())", .{});
                    } else if (std.mem.eql(u8, mc.method, "insert") and mc.args.len >= 1 and mc.args.len <= 2) {
                        // THE THIRD INSTANCE OF THE SAME HOLE. `push` and `pop`
                        // above each fell through to the generic method lookup,
                        // read the field off the TABLE ITSELF, found nil, and
                        // `lua_invoke(nil, …)` did nothing; `insert` did too and
                        // was left. Measured: `u = {}` / `u:insert("q")` /
                        // `u:len()` answers 0, exit 0, `idol check` silent — and
                        // a library relation built this way returned `{}` for
                        // every input it was ever given.
                        //
                        // `table.insert` is not the escape hatch, because §0.9
                        // says `table.` does not exist; the subject-first
                        // spelling is the only one a program can write, so it
                        // has to be the one that is wired. Both arities go to
                        // the same helper the `push` arm already uses: one
                        // argument appends, two insert at a position, which is
                        // exactly `lua_tbl_insert`'s own two arms.
                        self.p("lua_tbl_insert(", .{});
                        try self.emit_as_lua_value(mc.obj);
                        self.p(", ", .{});
                        try self.emit_as_lua_value(mc.args[0]);
                        self.p(", ", .{});
                        if (mc.args.len > 1) try self.emit_as_lua_value(mc.args[1]) else self.p("lua_val_nil()", .{});
                        self.p(")", .{});
                    } else if (std.mem.eql(u8, mc.method, "pop") and mc.args.len == 0) {
                        // gap[068], the sibling the gap told us to look for:
                        // "One no-op found by hand usually means an untested
                        // receiver state, not a unique defect." `t:pop()` had
                        // the identical hole from the other side — it read the
                        // field `pop`, got nil, and answered NIL for every pop.
                        // `examples/boring/stackqueue.duo` failed as
                        // `want '3 1' got 'nil 1'`, and `nil` reads as "the
                        // stack was empty" rather than "pop is not wired".
                        //
                        // `lua_tbl_remove(t, nil)` is the remove-the-last arm
                        // of the helper `table.remove` already uses, so LIFO
                        // comes from the code that was always there.
                        self.p("lua_tbl_remove(", .{});
                        try self.emit_as_lua_value(mc.obj);
                        self.p(", lua_val_nil())", .{});
                    } else {
                        const hash = calc_lua_hash(mc.method);
                        self.p("({{\n", .{});
                        self.indent += 1;
                        self.ind();
                        self.p("lua_Value __self = ", .{});
                        try self.emit_as_lua_value(mc.obj);
                        self.p(";\n", .{});
                        self.ind();
                        self.p("lua_Value __fn = lua_table_get_str_lit(__self, \"{s}\", {d}u, {d});\n", .{ mc.method, hash, mc.method.len });
                        self.ind();
                        self.p("lua_Value duo_args[{d}] = {{__self", .{mc.args.len + 1});
                        for (mc.args, 0..) |arg, i| {
                            _ = i;
                            self.p(", ", .{});
                            try self.emit_as_lua_value(arg);
                        }
                        self.p("}};\n", .{});
                        self.ind();
                        self.p("lua_invoke(__fn, {d}, duo_args);\n", .{mc.args.len + 1});
                        self.indent -= 1;
                        self.ind();
                        self.p("}})", .{});
