                                    self.ind();
                                    self.pl("lua_table_set_raw_i64(tmp, {d} + _vi, lua_table_get_raw({s}, lua_val_from_int(_vi + 1)));", .{ @as(i64, @intFromFloat(pos_idx)), vn });
                                    self.pl("}}", .{});
                                    continue;
                                }
                            }
                            self.p("lua_table_set_raw_i64(tmp, {d}, ", .{@as(i64, @intFromFloat(pos_idx))});
                            try self.emit_as_lua_value(pos_expr);
                            self.p(");\n", .{});
                            pos_idx += 1.0;
                        },
                        .spread => |src| {
                            self.ind();
                            self.p("{{ lua_Value _spr = ", .{});
                            try self.emit_as_lua_value(src);
                            self.p(";\n", .{});
                            self.ind();
                            self.pl("if (_spr.type == VAL_TABLE) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("lua_Table* _st = (lua_Table*)_spr.as.tval;", .{});
                            self.ind();
                            self.pl("for (int _si = 0; _si < _st->array_size; _si++) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("if (_st->array[_si].type != VAL_NIL) lua_table_set_raw_i64(tmp, _si + 1, _st->array[_si]);", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.ind();
                            self.pl("for (int _si = 0; _si < _st->capacity; _si++) {{", .{});
                            self.indent += 1;
                            self.ind();
                            self.pl("if (_st->hash_keys[_si].type != VAL_NIL) lua_table_set_raw(tmp, _st->hash_keys[_si], _st->hash_vals[_si]);", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.indent -= 1;
                            self.ind();
                            self.pl("}}", .{});
                            self.ind();
                            self.pl("}}", .{});
                        },
                        // G8 (`{ @eq = impl }`): a semantic entry installs into
                        // the semantic namespace, not the ordinary table, so it emits
                        // no raw set here. Refuse rather than invent an installation
                        // path before the resolution ladder exists.
                        .semantic => self.p("/* Pass 36 semantic table entry: not yet lowered */\n", .{}),
                    }
                }
                self.ind();
                self.p("tmp;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .list_comp => |lc| try self.emit_list_comprehension(lc),
            .try_expr => |te| {
                // expr? — propagate error; in this runtime errors are already thrown
                // via lua_error/longjmp, so the operand either returns normally or jumps.
                try self.emit_expr(te.operand);
            },
            .unwrap_expr => |ue| {
                // expr! — unwrap result, panicking on nil (unreachable in @nopanic fns).
                self.p("({{lua_Value _uw = (", .{});
                try self.emit_expr(ue.operand);
                self.p("); if (LUA_UNLIKELY(_uw.type == VAL_NIL)) lua_error(lua_val_from_str(\"unwrap of nil\")); _uw; }})", .{});
            },
            .if_expr => |ie| {
                self.p("((", .{});
                try self.emit_expr(ie.cond);
                self.p(") ? (", .{});
                try self.emit_expr(ie.then_expr);
                self.p(") : (", .{});
                try self.emit_expr(ie.else_expr);
                self.p("))", .{});
            },
            .match_expr => |match_expr| {
                try self.emit_match_expr(match_expr);
            },
            .await_expr => |ae| {
                // await expr — synchronous evaluation; the async state-machine lowering
                // handles the full cooperative scheduling model for async functions.
                try self.emit_expr(ae.operand);
            },
            .contains_expr => |ce| {
                // x in y — membership test via duo_contains(container, item).
                const as_lua = self.expr_type(expr) == .any;
                if (as_lua) self.p("lua_val_from_bool(", .{});
                self.p("duo_contains(", .{});
                try self.emit_expr(ce.rhs);
                self.p(", ", .{});
                try self.emit_expr(ce.lhs);
                self.p(")", .{});
                if (as_lua) self.p(")", .{});
            },
            .range => |r| {
                // TODO: proper range codegen — for now emit as runtime trio
                self.p("duo_range(", .{});
                try self.emit_expr(r.start);
                self.p(", ", .{});
                try self.emit_expr(r.end);
                if (r.step) |s| {
                    self.p(", ", .{});
                    try self.emit_expr(s);
                }
                self.p(")", .{});
            },
        }
    }

    fn isHexDigitByte(c: u8) bool {
        return (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f') or (c >= 'A' and c <= 'F');
    }

    fn emit_string_escaped(self: *CodeGen, s: []const u8) E!void {
        for (s, 0..) |c, i| {
            switch (c) {
                '"' => self.p("\\\"", .{}),
                '\\' => self.p("\\\\", .{}),
                '\n' => self.p("\\n", .{}),
                '\r' => self.p("\\r", .{}),
                '\t' => self.p("\\t", .{}),
                else => {
                    if (c < 32 or c == 127) {
                        self.p("\\x{x:0>2}", .{c});
                        // See jit.zig emitCStringLiteral: \x escapes greedily
                        // consume following hex digits in C, so split the
                        // literal if the next raw byte is one.
                        if (i + 1 < s.len and isHexDigitByte(s[i + 1])) self.p("\"\"", .{});
                    } else self.p("{c}", .{c});
                },
            }
        }
    }

    /// AN i64 AS A C INTEGER CONSTANT — exact at `INT_MIN`.
    ///
    /// C has no negative integer constants. `-9223372036854775808` is unary
    /// minus over the magnitude `9223372036854775808`, which exceeds
    /// `LLONG_MAX`, so the standard gives that token an unsigned type and the
    /// conversion back to `int64_t` is implementation-defined (clang says
    /// `-Wimplicitly-unsigned-literal`). Write it the way `<stdint.h>` writes
    /// `INT64_MIN` — one below the largest representable value — so the emitted
    /// constant is exactly `INT_MIN` under every C implementation, with no
    /// silent wrap through an unsigned intermediate. The form is already
    /// `long long`, so it needs no `INT64_C` wrapper.
    fn emit_c_int_literal(self: *CodeGen, v: i64) void {
        if (v == std.math.minInt(i64)) {
            self.p("(-9223372036854775807LL - 1)", .{});
            return;
        }
        self.p("{d}", .{v});
    }

    fn emit_c_string_literal(self: *CodeGen, s: []const u8) E!void {
        self.p("\"", .{});
        try self.emit_string_escaped(s);
        self.p("\"", .{});
    }

    fn fold_meta_string_expr(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        return switch (expr.*) {
            // Producer quote owns the face (GAP-145 O5): a byte-sequence
            // literal is not a compile-time string, so this arm refuses rather
            // than folds it into the string kingdom. Same fail-closed route as
            // `src/comptime.zig` — callers treat null as "leave it lowered".
            .quoted => |s| if (ast.quotedLiteralIsByteSequence(s.quote)) null else s.val,
            .name => |n| blk: {
                const value = self.comptime_bindings().get(n.ident) orelse break :blk null;
                break :blk if (value == .string) value.string else null;
            },
            .call => |c| blk: {
                if (c.func.* != .name) break :blk null;
                const name = c.func.name.ident;
                if (transform_engine.publicNameForInternal(name) != null and
                    !transform_engine.requireMetaDispatchBeforeHook(name))
                    break :blk null;
                if (self.meta_combinator_fold_depth == 0 and meta_dispatch.canDispatch(name)) {
                    self.meta_combinator_fold_depth += 1;
                    defer self.meta_combinator_fold_depth -= 1;
                    var storage: [8]comptime_eval.Value = undefined;
                    const n = self.buildMetaCombinatorValues(name, c.args, &storage) orelse break :blk null;
                    break :blk self.runMetaCombinatorString(name, storage[0..n], .top_level_assign);
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn isCEmitDirectiveName(name: []const u8) bool {
        return @import("meta_module.zig").isCEmitDirective(name);
    }

    /// Fold `@c.emit(@comp.*(...))` / `__emit(combinator(...))` payload to a C string.
    fn fold_c_emit_payload(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (expr.* != .call) return null;
        const c = expr.call;
        if (c.func.* != .name or c.args.len == 0) return null;
        if (!std.mem.eql(u8, c.func.name.ident, "__emit")) return null;
        if (c.args[0].* == .quoted) return c.args[0].quoted.val;
        return self.fold_meta_string_expr(c.args[0]);
    }

    fn emit_file_scope_c_payload(self: *CodeGen, code: []const u8) void {
        const trimmed = std.mem.trim(u8, code, " \t\r\n");
        if (trimmed.len == 0) return;
        if (trimmed[trimmed.len - 1] != ';' and trimmed[trimmed.len - 1] != '}')
            self.p("{s};\n", .{code})
        else
            self.p("{s}\n", .{code});
    }

    fn stmt_is_file_scope_c_emit(self: *CodeGen, stmt: *const ast.Stmt) bool {
        return switch (stmt.*) {
            .directive => |d| blk: {
                if (!CodeGen.isCEmitDirectiveName(d.attr.name)) break :blk false;
                if (d.attr.args) |raw| {
                    break :blk @import("directives.zig").isRawCEmitLiteral(raw);
                }
                break :blk true;
            },
            .expr_stmt => |es| self.fold_c_emit_payload(es.expr) != null,
            else => false,
        };
    }

    fn count_lines(s: []const u8) i64 {
        if (s.len == 0) return 0;
        var count: i64 = 0;
        var saw_non_ws = false;
        for (s) |c| {
            if (c == '\n') count += 1;
            if (c != '\n' and c != '\r' and c != '\t' and c != ' ') saw_non_ws = true;
        }
        if (s[s.len - 1] != '\n' and saw_non_ws) count += 1;
        return count;
    }

    fn split_count(source: []const u8, sep: []const u8) i64 {
        if (source.len == 0) return 0;
        if (sep.len == 0) return @intCast(source.len);
        var count: i64 = 1;
        var rest = source;
        while (std.mem.indexOf(u8, rest, sep)) |idx| {
            count += 1;
            rest = rest[idx + sep.len ..];
        }
        return count;
    }

    fn maybe_emit_meta_int_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (std.mem.eql(u8, name, "__strcountlines") and args.len == 1) {
            const source = self.fold_meta_string_expr(args[0]) orelse return false;
            self.p("{d}", .{count_lines(source)});
            return true;
        }
        if (std.mem.eql(u8, name, "__strsplitcount") and args.len == 2) {
            const source = self.fold_meta_string_expr(args[0]) orelse return false;
            const sep = self.fold_meta_string_expr(args[1]) orelse return false;
            self.p("{d}", .{split_count(source, sep)});
            return true;
        }
        if (std.mem.eql(u8, name, "__strcomptelen") and args.len == 1) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                self.p("{d}", .{@as(i64, @intCast(source.len))});
                return true;
            }
            if (self.expr_type(args[0]) == .str) {
                self.p("({{ const unsigned char* _duo_s = (const unsigned char*)(", .{});
                try self.emit_expr(args[0]);
                self.p("); int64_t _duo_len = 0; while (*_duo_s) {{ if ((*_duo_s & 0xC0) != 0x80) _duo_len++; _duo_s++; }} _duo_len; }})", .{});
                return true;
            }
        }
        if (std.mem.eql(u8, name, "__concept_count") and args.len == 1 and args[0].* == .quoted) {
            const concepts = self.concepts orelse return false;
            const concept = concepts.get(args[0].quoted.val) orelse return false;
            self.p("{d}", .{@as(i64, @intCast(concept.required_methods.len + concept.required_fields.len))});
            return true;
        }
        return false;
    }

    fn maybe_emit_meta_bool_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (std.mem.eql(u8, name, "__strstartswith") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                const prefix = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.startsWith(u8, source, prefix)) "true" else "false"});
                return true;
            }
            if (try self.try_emit_native_string_affix("starts_with", args[0], args[1])) return true;
        }
        if (std.mem.eql(u8, name, "__strendswith") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |source| {
                const suffix = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.endsWith(u8, source, suffix)) "true" else "false"});
                return true;
            }
            if (try self.try_emit_native_string_affix("ends_with", args[0], args[1])) return true;
        }
        if (std.mem.eql(u8, name, "__streq") and args.len == 2) {
            if (self.fold_meta_string_expr(args[0])) |lhs| {
                const rhs = self.fold_meta_string_expr(args[1]) orelse return false;
                self.p("{s}", .{if (std.mem.eql(u8, lhs, rhs)) "true" else "false"});
                return true;
            }
            if (self.expr_is_native_cstr(args[0]) and self.expr_is_native_cstr(args[1])) {
                self.p("({{ const char* _duo_a = ", .{});
                try self.emit_expr(args[0]);
                self.p("; const char* _duo_b = ", .{});
                try self.emit_expr(args[1]);
                self.p("; strcmp(_duo_a, _duo_b) == 0; }})", .{});
                return true;
            }
        }
        return false;
    }

    fn comptimeJoinTableStrings(self: *CodeGen, parts: comptime_eval.Value, sep: []const u8) E!?[]const u8 {
        if (parts != .table) return null;
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(self.alloc);
        for (parts.table, 0..) |entry, i| {
            if (i > 0 and sep.len > 0) try out.appendSlice(self.alloc, sep);
            switch (entry.val) {
                .string => |v| try out.appendSlice(self.alloc, v),
                .int => |v| {
                    var buf: [32]u8 = undefined;
                    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return null;
                    try out.appendSlice(self.alloc, written);
                },
                .float => |v| {
                    var buf: [32]u8 = undefined;
                    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return null;
                    try out.appendSlice(self.alloc, written);
                },
                .decimal => |v| {
                    var buf: [32]u8 = undefined;
                    const written = std.fmt.bufPrint(&buf, "{d}", .{v.toFloat()}) catch return null;
                    try out.appendSlice(self.alloc, written);
                },
                .bool => |v| try out.appendSlice(self.alloc, if (v) "true" else "false"),
                .nil => try out.appendSlice(self.alloc, "nil"),
                else => return null,
            }
        }
        return try out.toOwnedSlice(self.alloc);
    }

    fn maybe_emit_meta_string_call(self: *CodeGen, name: []const u8, args: []const *ast.Expr) E!bool {
        if (transform_engine.publicNameForInternal(name) != null and
            !transform_engine.requireMetaDispatchBeforeHook(name))
            return false;
        if (meta_dispatch.canDispatch(name)) {
            return try self.tryEmitMetaCombinatorString(name, args);
        }
        if (std.mem.eql(u8, name, "__metaladder") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.scalingLadderText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagenthooks") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentHooksText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentdedupe") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentDedupeText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentgaps") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentGapsText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentgrammar") and args.len == 0) {
            try self.emit_c_string_literal(meta_module.agentGrammarText());
            return true;
        }
        if (std.mem.eql(u8, name, "__metacatalog") or std.mem.eql(u8, name, "__metaagentcatalog")) {
            if (args.len > 1) return false;
            const filter = if (args.len == 1 and args[0].* == .quoted) args[0].quoted.val else null;
            const catalog = if (std.mem.eql(u8, name, "__metaagentcatalog") and filter == null)
                try meta_module.formatAgentCatalog(self.alloc)
            else
                try meta_module.formatCatalogFiltered(self.alloc, filter);
            defer self.alloc.free(catalog);
            try self.emit_c_string_literal(catalog);
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentladder") and args.len == 0) {
            const ladder = try meta_module.formatAgentLadder(self.alloc);
            defer self.alloc.free(ladder);
            try self.emit_c_string_literal(ladder);
            return true;
        }
        if (std.mem.eql(u8, name, "__metaagentmultiplier")) {
            if (args.len == 0) {
                try self.emit_c_string_literal(meta_module.agentMultiplierText());
                return true;
            }
            if (args.len == 1 and args[0].* == .quoted) {
                const hint = meta_module.agentMultiplierFor(args[0].quoted.val);
                try self.emit_c_string_literal(hint);
                return true;
            }
            return false;
        }
        if (std.mem.eql(u8, name, "__strjoin") and args.len == 2) {
            const parts = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch return false;
            const sep_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch return false;
            const sep: []const u8 = switch (sep_val) {
                .string => sep_val.string,
                else => return false,
            };
            const joined = try self.comptimeJoinTableStrings(parts, sep) orelse return false;
            defer self.alloc.free(joined);
            try self.emit_c_string_literal(joined);
            return true;
        }
        if (std.mem.eql(u8, name, "__moduletypenames") and args.len == 0) {
            const value = meta_codegen.moduleTypeNamesHook(self.meta_host(), self.alloc) orelse return false;
            if (value != .string) return false;
            try self.emit_c_string_literal(value.string);
            return true;
        }
        if (std.mem.eql(u8, name, "__concepttypenames") and args.len == 1 and args[0].* == .quoted) {
            const value = meta_codegen.conceptTypeNamesHook(self.meta_host(), args[0].quoted.val, self.alloc) orelse return false;
            if (value != .string) return false;
            try self.emit_c_string_literal(value.string);
            return true;
        }
        return false;
    }

    fn emit_comptime_value(self: *CodeGen, value: comptime_eval.Value, as_lua_value: bool) E!void {
        switch (value) {
            .unavailable => unreachable,
            .nil => if (as_lua_value) self.p("lua_val_nil()", .{}) else self.p("0", .{}),
            .bool => |v| if (as_lua_value) self.p("lua_val_from_bool({s})", .{if (v) "true" else "false"}) else self.p("{s}", .{if (v) "true" else "false"}),
            .int => |v| if (as_lua_value) self.p("lua_val_from_int({d})", .{v}) else self.p("{d}", .{v}),
            .float => |v| if (as_lua_value) self.p("lua_val_from_num({d})", .{v}) else self.p("{d}", .{v}),
            .decimal => |v| if (as_lua_value) self.p("lua_val_from_num({d})", .{v.toFloat()}) else self.p("{d}", .{v.toFloat()}),
            .string => |v| {
                if (as_lua_value) {
                    const hash = calc_lua_hash(v);
                    self.p("lua_val_from_literal(\"", .{});
                    try self.emit_string_escaped(v);
                    self.p("\", {d}, {d})", .{ hash, v.len });
                } else {
                    self.p("\"", .{});
                    try self.emit_string_escaped(v);
                    self.p("\"", .{});
                }
            },
            .table => |entries| {
                // TODO: emit native C struct when as_lua_value == false for typed tables
                // Currently always uses Lua API for table construction
                var array_count: usize = 0;
                var hash_count: usize = 0;
                for (entries) |entry| {
                    if (entry.name != null) {
                        hash_count += 1;
                    } else if (entry.key) |key| {
                        if (key == .int and key.int >= 1) {
                            array_count += 1;
                        } else {
                            hash_count += 1;
                        }
                    }
                }
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value tmp = lua_table_new_with_capacity({d}, {d});\n", .{ array_count, hash_count });
                for (entries) |entry| {
                    self.ind();
                    if (entry.name) |name| {
                        const hash = calc_lua_hash(name);
                        self.p("lua_table_set_raw_lit(tmp, \"{s}\", {d}, {d}, ", .{ name, hash, name.len });
                        try self.emit_comptime_value(entry.val, true);
                        self.p(");\n", .{});
                    } else if (entry.key) |key| {
                        if (key == .int and key.int >= 1) {
                            self.p("lua_table_set_raw_i64(tmp, {d}, ", .{key.int});
                            try self.emit_comptime_value(entry.val, true);
                            self.p(");\n", .{});
                        } else {
                            self.p("lua_table_set_raw(tmp, ", .{});
                            try self.emit_comptime_value(key, true);
                            self.p(", ", .{});
                            try self.emit_comptime_value(entry.val, true);
                            self.p(");\n", .{});
                        }
                    } else {
                        self.p("lua_table_set_raw(tmp, ", .{});
                        self.p("lua_val_nil()", .{});
                        self.p(", ", .{});
                        try self.emit_comptime_value(entry.val, true);
                        self.p(");\n", .{});
                    }
                }
                self.ind();
                self.p("tmp;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .func => unreachable,
        }
    }

    /// Emit GCC-style inline assembly from __asm("template") or
    /// __asm("template", "output_constraints", "input_constraints", "clobbers").
    /// Uses existing Duo call syntax — no new keywords required.
    /// Example: __asm("nop")
    /// Example: __asm("mov %0, %1", "=r(result)", "r(input)", "memory")
    fn emit_inline_asm(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len == 0) return;
        if (args[0].* != .quoted) {
            self.p("/* __asm: first arg must be string literal */", .{});
            return;
        }
        const template = args[0].quoted.val;
        self.p("__asm__ volatile(\"{s}\"", .{template});
        // Output constraints
        if (args.len >= 2 and args[1].* == .quoted) {
            self.p(" : \"{s}\"", .{args[1].quoted.val});
        } else {
            self.p(" :", .{});
        }
        // Input constraints
        if (args.len >= 3 and args[2].* == .quoted) {
            self.p(" : \"{s}\"", .{args[2].quoted.val});
        } else {
            self.p(" :", .{});
        }
        // Clobbers
        if (args.len >= 4 and args[3].* == .quoted) {
            self.p(" : \"{s}\"", .{args[3].quoted.val});
        }
        self.p(")", .{});
    }

    /// __comptimefold(start, stop, step, "init", "body")
    /// Unrolls a loop at compile time. In body: %i → index, %a → accumulator.
    /// Example: __comptimefold(0, 4, 1, "0", "%a + arr[%i]")
    /// → ((((0) + arr[0]) + arr[1]) + arr[2]) + arr[3])
    fn emit_comptimefold(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 5) {
            self.p("/* __comptimefold: needs 5 args (start, stop, step, init, body) */0", .{});
            return;
        }
        // Evaluate start, stop, step at compile time
        const start_val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: start must be comptime */0", .{});
            return;
        };
        const stop_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: stop must be comptime */0", .{});
            return;
        };
        const step_val = comptime_eval.evalWithBindings(args[2], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefold: step must be comptime */0", .{});
            return;
        };
        if (start_val != .int or stop_val != .int or step_val != .int) {
            self.p("/* __comptimefold: bounds must be integers */0", .{});
            return;
        }
        if (args[3].* != .quoted or args[4].* != .quoted) {
            self.p("/* __comptimefold: init and body must be string literals */0", .{});
            return;
        }
        const init_str = args[3].quoted.val;
        const body_tmpl = args[4].quoted.val;
        const start = start_val.int;
        const stop = stop_val.int;
        const step = step_val.int;
        if (step == 0 or (step > 0 and start > stop) or (step < 0 and start < stop)) {
            self.p("{s}", .{init_str});
            return;
        }
        // Generate the unrolled fold
        var acc_str: []const u8 = init_str;
        var i = start;
        var iterations: usize = 0;
        while ((step > 0 and i < stop) or (step < 0 and i > stop)) : ({
            i += step;
            iterations += 1;
        }) {
            if (iterations > 1024) break; // Safety limit
            // Substitute %i and %a in body template
            var idx_buf: [24]u8 = undefined;
            const idx_str = std.fmt.bufPrint(&idx_buf, "{d}", .{i}) catch break;
            const with_i = std.mem.replaceOwned(u8, self.alloc, body_tmpl, "%i", idx_str) catch break;
            acc_str = std.mem.replaceOwned(u8, self.alloc, with_i, "%a", acc_str) catch break;
        }
        self.p("({s})", .{acc_str});
    }

    /// __comptimefor(start, stop, "body_template")
    /// Generates a sequence of statements at compile time. %i → index.
    /// When used as an expression, generates a comma-expression.
    /// Example: __comptimefor(0, 3, "arr[%i] = %i;")
    /// → arr[0] = 0; arr[1] = 1; arr[2] = 2;
    fn emit_comptimefor(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 3) {
            self.p("/* __comptimefor: needs 3 args (start, stop, body) */0", .{});
            return;
        }
        const start_val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefor: start must be comptime */0", .{});
            return;
        };
        const stop_val = comptime_eval.evalWithBindings(args[1], self.comptime_bindings(), self.comptime_eval_options()) catch {
            self.p("/* __comptimefor: stop must be comptime */0", .{});
            return;
        };
        if (start_val != .int or stop_val != .int) {
            self.p("/* __comptimefor: bounds must be integers */0", .{});
            return;
        }
        if (args[2].* != .quoted) {
            self.p("/* __comptimefor: body must be string literal */0", .{});
            return;
        }
        const body_tmpl = args[2].quoted.val;
        const start = start_val.int;
        const stop = stop_val.int;
        if (start >= stop) {
            self.p("0", .{});
            return;
        }
        // Generate unrolled iterations as a compound expression
        self.p("(", .{});
        var first = true;
        var i = start;
        var iterations: usize = 0;
        while (i < stop) : ({
            i += 1;
            iterations += 1;
        }) {
            if (iterations > 1024) break; // Safety limit
            if (!first) self.p(", ", .{});
            first = false;
            var idx_buf: [24]u8 = undefined;
            const idx_str = std.fmt.bufPrint(&idx_buf, "{d}", .{i}) catch break;
            const expanded = std.mem.replaceOwned(u8, self.alloc, body_tmpl, "%i", idx_str) catch break;
            self.p("{s}", .{expanded});
        }
        self.p(")", .{});
    }

    fn emit_comptime_expr(self: *CodeGen, expr: *const ast.Expr, as_lua_value: bool) E!void {
        const value = comptime_eval.evalWithBindings(expr, self.comptime_bindings(), self.comptime_eval_options()) catch {
            if (as_lua_value) {
                try self.emit_as_lua_value(expr);
            } else {
                try self.emit_expr(expr);
            }
            return;
        };
        try self.emit_comptime_value(value, as_lua_value);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // METAPROGRAMMING HELPER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    const MessageLevel = enum { info, warning, err };

    /// __fields(T) — emit a comptime table of {name, type, offset, size} for each field
    fn emit_fields_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const rt = self.expr_type(args[0]);
        switch (rt) {
            .table_type => |t| {
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __ft = lua_table_new_with_capacity({d}, 0);\n", .{t.fields.len});
                for (t.fields, 0..) |field, i| {
                    self.ind();
                    self.p("lua_table_set_raw_i64(__ft, {d}, ({{\n", .{i + 1});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __e = lua_table_new_with_capacity(0, 4);\n", .{});
                    self.ind();
                    const name_hash = calc_lua_hash(field.name);
                    self.p("lua_table_set_raw_lit(__e, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), field.name });
                    self.ind();
                    var buf: [128]u8 = undefined;
                    const type_name = field.typ.c_type(&buf);
                    self.p("lua_table_set_raw_lit(__e, \"type\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("type"), type_name });
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"index\", {d}, 5, lua_val_from_int({d}));\n", .{ calc_lua_hash("index"), i });
                    self.ind();
                    _ = name_hash;
                    self.p("__e;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}}));\n", .{});
                }
                self.ind();
                self.p("__ft;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            .enum_type => |et| {
                // For enums, return variant info as "fields"
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __ft = lua_table_new_with_capacity({d}, 0);\n", .{et.variants.len});
                for (et.variants, 0..) |v, i| {
                    self.ind();
                    self.p("lua_table_set_raw_i64(__ft, {d}, ({{\n", .{i + 1});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __e = lua_table_new_with_capacity(0, 3);\n", .{});
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), v.name });
                    self.ind();
                    const has_payload: i64 = if (v.payload != null) 1 else 0;
                    self.p("lua_table_set_raw_lit(__e, \"has_payload\", {d}, 11, lua_val_from_bool({s}));\n", .{ calc_lua_hash("has_payload"), if (has_payload == 1) "true" else "false" });
                    self.ind();
                    self.p("lua_table_set_raw_lit(__e, \"tag\", {d}, 3, lua_val_from_int({d}));\n", .{ calc_lua_hash("tag"), i });
                    self.ind();
                    self.p("__e;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}}));\n", .{});
                }
                self.ind();
                self.p("__ft;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
            },
            else => self.p("lua_val_nil()", .{}),
        }
    }

    /// __concept_methods("Concept") — compile-time table of required method signatures
    fn emit_concept_methods_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .methods);
    }

    fn emit_concept_fields_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .fields);
    }

    fn emit_concept_members_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        try self.emit_concept_members_table(args, .all);
    }

    const ConceptMemberSet = enum { methods, fields, all };

    fn find_current_concept_def(self: *CodeGen, name: []const u8) ?*const ast.ConceptDef {
        const mod = self.current_module orelse return null;
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .concept_def) continue;
            if (std.mem.eql(u8, stmt.concept_def.name, name)) return &stmt.concept_def;
        }
        return null;
    }

    fn emit_type_expr_string(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        const text: []const u8 = switch (type_expr) {
            .inferred => "any",
            .named => |name| name,
            .optional => |child| switch (child.*) {
                .named => |name| name,
                .inferred => "any",
                else => "any",
            },
            else => "any",
        };
        try self.emit_c_string_literal(text);
    }

    fn emit_resolved_type_name_string(self: *CodeGen, rt: RT) E!void {
        // DERIVED, NOT TABULATED. This roster was a ninth statement of the scalar
        // identity->source-spelling correspondence `types.reflectName` (over
        // `duo_name`) owns; `reflectName(rt) orelse "any"` is the retired roster's
        // answer for every `rt`, so a scalar identity added to the union reports
        // its real word here instead of silently widening to `"any"`.
        const text: []const u8 = types.reflectName(rt) orelse "any";
        try self.emit_c_string_literal(text);
    }

    fn emit_concept_field_row(
        self: *CodeGen,
        field: sema.ConceptInfo.FieldRequirement,
        ast_field: ?ast.ConceptDef.RequiredField,
    ) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __m = lua_table_new_with_capacity(0, 3);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"name\", {d}, 4, lua_val_from_str(\"", .{calc_lua_hash("name")});
        try self.emit_string_escaped(field.name);
        self.p("\"));\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"kind\", {d}, 4, lua_val_from_str(\"field\"));\n", .{calc_lua_hash("kind")});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"type\", {d}, 4, lua_val_from_str(", .{calc_lua_hash("type")});
        if (ast_field) |source_field| {
            try self.emit_type_expr_string(source_field.typ);
        } else {
            try self.emit_resolved_type_name_string(field.typ);
        }
        self.p("));\n", .{});
        self.ind();
        self.p("__m;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_concept_method_row(
        self: *CodeGen,
        method: sema.ConceptInfo.MethodRequirement,
        ast_method: ?ast.FuncSignature,
    ) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __m = lua_table_new_with_capacity(0, 5);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"name\", {d}, 4, lua_val_from_str(\"", .{calc_lua_hash("name")});
        try self.emit_string_escaped(method.name);
        self.p("\"));\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"kind\", {d}, 4, lua_val_from_str(\"method\"));\n", .{calc_lua_hash("kind")});
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"param_count\", {d}, 11, lua_val_from_int({d}));\n", .{ calc_lua_hash("param_count"), method.param_count });
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"ret\", {d}, 3, lua_val_from_str(", .{calc_lua_hash("ret")});
        if (ast_method) |sig| {
            try self.emit_type_expr_string(sig.ret_type);
        } else {
            try self.emit_resolved_type_name_string(method.ret_type);
        }
        self.p("));\n", .{});
        self.ind();
        self.p("lua_Value __params = lua_table_new_with_capacity({d}, 0);\n", .{method.param_count});
        if (ast_method) |sig| {
            for (sig.params, 0..) |param, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(", .{i + 1});
                try self.emit_type_expr_string(param.typ);
                self.p("));\n", .{});
            }
        } else if (method.param_types.len > 0) {
            for (method.param_types, 0..) |pt, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(", .{i + 1});
                try self.emit_resolved_type_name_string(pt);
                self.p("));\n", .{});
            }
        } else {
            var i: usize = 0;
            while (i < method.param_count) : (i += 1) {
                self.ind();
                self.p("lua_table_set_raw_i64(__params, {d}, lua_val_from_str(\"any\"));\n", .{i + 1});
            }
        }
        self.ind();
        self.p("lua_table_set_raw_lit(__m, \"params\", {d}, 6, __params);\n", .{calc_lua_hash("params")});
        self.ind();
        self.p("__m;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn ast_concept_method(def: ?*const ast.ConceptDef, name: []const u8) ?ast.FuncSignature {
        const concept = def orelse return null;
        for (concept.required_methods) |method| {
            if (std.mem.eql(u8, method.name, name)) return method;
        }
        return null;
    }

    fn ast_concept_field(def: ?*const ast.ConceptDef, name: []const u8) ?ast.ConceptDef.RequiredField {
        const concept = def orelse return null;
        for (concept.required_fields) |field| {
            if (std.mem.eql(u8, field.name, name)) return field;
        }
        return null;
    }

    fn emit_concept_members_table(self: *CodeGen, args: []const *ast.Expr, set: ConceptMemberSet) E!void {
        if (args.len < 1 or args[0].* != .quoted) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const concept_name = args[0].quoted.val;
        const concepts = self.concepts orelse {
            self.p("lua_val_nil()", .{});
            return;
        };
        const concept = concepts.get(concept_name) orelse {
            self.p("lua_val_nil()", .{});
            return;
        };
        const total = switch (set) {
            .methods => concept.required_methods.len,
            .fields => concept.required_fields.len,
            .all => concept.required_methods.len + concept.required_fields.len,
        };
        const ast_def = self.find_current_concept_def(concept_name);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __cm = lua_table_new_with_capacity({d}, 0);\n", .{total});
        var idx: usize = 1;
        if (set == .methods or set == .all) {
            for (concept.required_methods) |method| {
                self.ind();
                self.p("lua_table_set_raw_i64(__cm, {d}, ", .{idx});
                try self.emit_concept_method_row(method, ast_concept_method(ast_def, method.name));
                self.p(");\n", .{});
                idx += 1;
            }
        }
        if (set == .fields or set == .all) {
            for (concept.required_fields) |field| {
                self.ind();
                self.p("lua_table_set_raw_i64(__cm, {d}, ", .{idx});
                try self.emit_concept_field_row(field, ast_concept_field(ast_def, field.name));
                self.p(");\n", .{});
                idx += 1;
            }
        }
        self.ind();
        self.p("__cm;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __methods(T) — emit comptime table of method names for a type
    fn emit_methods_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        // Look up the type name in alias_defs which tracks methods
        const rt = self.expr_type(args[0]);
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => if (args[0].* == .quoted) args[0].quoted.val else if (args[0].* == .name) args[0].name.ident else null,
        };
        if (type_name) |tname| {
            if (self.table_methods) |tm| {
                if (tm.get(tname)) |tmethods| {
                    self.p("({{\n", .{});
                    self.indent += 1;
                    self.ind();
                    self.p("lua_Value __mt = lua_table_new_with_capacity({d}, 0);\n", .{tmethods.items.len});
                    for (tmethods.items, 0..) |method, i| {
                        self.ind();
                        self.p("lua_table_set_raw_i64(__mt, {d}, lua_val_from_str(\"{s}\"));\n", .{ i + 1, method });
                    }
                    self.ind();
                    self.p("__mt;\n", .{});
                    self.indent -= 1;
                    self.ind();
                    self.p("}})", .{});
                    return;
                }
            }
            if (self.alias_defs.get(tname)) |alias_def| {
                self.p("({{\n", .{});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __mt = lua_table_new_with_capacity({d}, 0);\n", .{alias_def.methods.len});
                for (alias_def.methods, 0..) |method, i| {
                    self.ind();
                    const mname = if (method.path.len > 0) method.path[method.path.len - 1] else "?";
                    self.p("lua_table_set_raw_i64(__mt, {d}, lua_val_from_str(\"{s}\"));\n", .{ i + 1, mname });
                }
                self.ind();
                self.p("__mt;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}})", .{});
                return;
            }
        }
        self.p("lua_val_nil()", .{});
    }

    /// __variants(EnumT) — emit comptime table of variant descriptors
    fn emit_variants_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1) {
            self.p("lua_val_nil()", .{});
            return;
        }
        const rt = self.expr_type(args[0]);
        if (rt == .enum_type) {
            const et = rt.enum_type;
            self.p("({{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("lua_Value __vt = lua_table_new_with_capacity({d}, 0);\n", .{et.variants.len});
            for (et.variants, 0..) |v, i| {
                self.ind();
                self.p("lua_table_set_raw_i64(__vt, {d}, ({{\n", .{i + 1});
                self.indent += 1;
                self.ind();
                self.p("lua_Value __v = lua_table_new_with_capacity(0, 3);\n", .{});
                self.ind();
                self.p("lua_table_set_raw_lit(__v, \"name\", {d}, 4, lua_val_from_str(\"{s}\"));\n", .{ calc_lua_hash("name"), v.name });
                self.ind();
                self.p("lua_table_set_raw_lit(__v, \"tag\", {d}, 3, lua_val_from_int({d}));\n", .{ calc_lua_hash("tag"), i });
                self.ind();
                if (v.payload) |payload| {
                    self.p("lua_table_set_raw_lit(__v, \"arity\", {d}, 5, lua_val_from_int({d}));\n", .{ calc_lua_hash("arity"), payload.len });
                } else {
                    self.p("lua_table_set_raw_lit(__v, \"arity\", {d}, 5, lua_val_from_int(0));\n", .{calc_lua_hash("arity")});
                }
                self.ind();
                self.p("__v;\n", .{});
                self.indent -= 1;
                self.ind();
                self.p("}}));\n", .{});
            }
            self.ind();
            self.p("__vt;\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}})", .{});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    /// __has_field(T, "name") — compile-time check if type has a named field
    fn emit_has_field_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("false", .{});
            return;
        };
        const found = switch (rt) {
            .table_type => |t| blk: {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
        self.p("{s}", .{if (found) "true" else "false"});
    }

    /// __has_method(T, "name") — compile-time check if type has a named method
    fn emit_has_method_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const method_name = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("false", .{});
            return;
        };
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => null,
        };
        if (type_name) |tname| {
            if (self.alias_defs.get(tname)) |alias_def| {
                if (sema.AliasRegistry.hasmethod(alias_def, method_name)) {
                    self.p("true", .{});
                    return;
                }
            }
        }
        self.p("false", .{});
    }

    /// __has_metamethod(T, "__index") — compile-time check for metamethod presence
    fn emit_has_metamethod_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        // At compile time we can check if the type is known to have a metatable
        // For now, this is a runtime check emitted as C
        if (args[1].* == .quoted) {
            const raw = args[1].quoted.val;
            const mm_name = if (lua_metamethod.parse(raw)) |known| known.text() else raw;
            const mm_hash = calc_lua_hash(mm_name);
            self.p("(lua_get_metafield_lit(", .{});
            try self.emit_as_lua_value(args[0]);
            self.p(", \"{s}\", {d}u, {d}).type != VAL_NIL)", .{ mm_name, mm_hash, mm_name.len });
        } else {
            self.p("false", .{});
        }
    }

    /// __satisfies(T, "concept") — compile-time concept membership check.
    fn emit_satisfies_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (self.eval_satisfies(args)) |known| {
            self.p("{s}", .{if (known) "true" else "false"});
            return;
        }
        self.p("false", .{});
    }

    fn eval_satisfies(self: *CodeGen, args: []const *ast.Expr) ?bool {
        if (args.len != 2) return null;
        const concept_name = if (args[1].* == .quoted) args[1].quoted.val else return null;
        const concepts = self.concepts orelse return null;
        const concept = concepts.get(concept_name) orelse return null;

        // One decision procedure, shared with `Sema.type_satisfies_concept`.
        // This function used to carry its own copy of the descriptor field walk
        // and its own two-branch satisfaction loop, and the copy had drifted: the
        // `.name` branch consulted the descriptor OR the `fun T:m()` method list,
        // never both, so a concept met jointly by a descriptor's fields and a
        // separately-declared method answered `false` here and `true` in sema.
        // Both now ask `sema.AliasRegistry.satisfies`.
        if (args[0].* == .name) {
            const type_name = args[0].name.ident;
            const alias_def = self.alias_defs.get(type_name);
            const methods: ?[]const []const u8 = if (self.table_methods) |tm|
                if (tm.get(type_name)) |ms| ms.items else null
            else
                null;
            // Nothing known about this name — no answer, as before.
            if (alias_def == null and methods == null) return null;
            return sema.AliasRegistry.satisfies(
                alias_def,
                methods,
                .{ .@"struct" = .{ .name = type_name } },
                concept,
            );
        }

        const rt = self.expr_type(args[0]);
        const type_name: ?[]const u8 = switch (rt) {
            .@"struct" => |s| s.name,
            .enum_type => |et| et.name,
            else => null,
        };
        const alias_def = if (type_name) |tname| self.alias_defs.get(tname) else null;
        const methods: ?[]const []const u8 = if (type_name) |tname|
            if (self.table_methods) |tm|
                if (tm.get(tname)) |ms| ms.items else null
            else
                null
        else
            null;
        return sema.AliasRegistry.satisfies(alias_def, methods, rt, concept);
    }

    /// __field_type(T, "name") — returns C type name of a field as string literal
    fn emit_field_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("\"unknown\"", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        var buf: [128]u8 = undefined;
                        const ctype = f.typ.c_type(&buf);
                        self.p("\"{s}\"", .{ctype});
                        return;
                    }
                }
            },
            else => {},
        }
        self.p("\"unknown\"", .{});
    }

    /// __type_name(expr) — returns the Duo type name as a compile-time string
    fn emit_type_name_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        var buf: [128]u8 = undefined;
        const name = rt.c_type(&buf);
        self.p("\"{s}\"", .{name});
    }

    fn resolveStorageClass(self: *CodeGen, rt: RT) types.StorageClass {
        if (types.tableStorageClass(rt)) |sc| return sc;
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                if (types.tableStorageClass(alias_rt)) |sc| return sc;
            }
        }
        return .dynamic;
    }

    fn resolveTableRecordType(self: *CodeGen, rt: RT) ?RT {
        if (types.tableStorageClass(rt)) |_| return rt;
        if (rt == .@"struct") {
            if (self.record_aliases.get(rt.@"struct".name)) |alias_rt| {
                if (types.tableStorageClass(alias_rt)) |_| return alias_rt;
            }
        }
        return null;
    }

    /// __type_shape(expr) — returns table storage class as compile-time string
    fn emit_type_shape_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const sc = self.resolveStorageClass(self.expr_type(args[0]));
        const label = types.storageClassName(sc);
        self.logTransformProvenance("comp.type.shape", .emit_call, "expr", label);
        self.p("\"{s}\"", .{label});
    }

    /// __why_shape(expr) — factual storage-class explanation
    fn emit_why_shape_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const table_rt = self.resolveTableRecordType(rt) orelse rt;
        const explanation = types.explainStorageClass(table_rt);
        self.logTransformProvenance("comp.why.shape", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn exprBoundaryFacts(self: *CodeGen, expr: *const ast.Expr) dynamic_boundary.ExprFacts {
        const rt = self.expr_type(expr);
        const fn_name = self.current_func_name;
        const func_native = if (fn_name) |n| self.funcUsesNativeLowering(n) else false;
        return .{
            .rt = rt,
            .knowledge = self.exprKnowledge(expr),
            .storage_class = self.resolveStorageClass(rt),
            .module_native = self.moduleUsesFullNativeLowering(),
            .func_native = func_native,
            .lowers_native = self.exprLowersToNativeC(rt),
            .module_needs_runtime = self.moduleNeedsLuaRuntime(),
        };
    }

    fn emit_why_boxed_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainBoxed(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.why.boxed", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn emit_why_not_native_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainNotNative(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.why.not.native", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    fn emit_representation_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = dynamic_boundary.explainRepresentation(self.exprBoundaryFacts(args[0]));
        self.logTransformProvenance("comp.representation", .emit_call, "expr", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    /// __why(expr) — general specialization explanation (table shapes; honest fallback)
    fn emit_why_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        if (self.resolveTableRecordType(rt)) |table_rt| {
            const explanation = types.explainStorageClass(table_rt);
            self.logTransformProvenance("comp.why", .emit_call, "expr", explanation);
            self.p("\"{s}\"", .{explanation});
            return;
        }
        const fallback = "no compiler explanation available for this expression kind yet";
        self.logTransformProvenance("comp.why", .emit_call, "expr", fallback);
        self.p("\"{s}\"", .{fallback});
    }

    /// __why_module(binding) — L1 module sealing witness string.
    fn emit_why_module_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const explanation = blk: {
            if (args[0].* != .name) break :blk "module_sealed=n/a; operand is not a module binding name";
            const name = args[0].name.ident;
            const has_req = self.req_module_bindings.contains(name);
            const sealed = self.module_sealed_bindings.contains(name);
            if (has_req and sealed) {
                break :blk "module_sealed=true; req binding frozen after load; cross-module calls may devirtualize";
            }
            if (has_req) {
                break :blk "module_sealed=false; req binding mutated after load; guarded dynamic fallback";
            }
            break :blk "module_sealed=n/a; not a req module binding";
        };
        self.logTransformProvenance("comp.why.module", .emit_call, "binding", explanation);
        self.p("\"{s}\"", .{explanation});
    }

    /// __origin(expr) — compact provenance: storage_class + shape_id for typed records
    fn emit_origin_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        if (self.resolveTableRecordType(rt)) |table_rt| {
            const sc = types.storageClassName(self.resolveStorageClass(table_rt));
            const sid = types.tableShapeIdentityHash(table_rt) orelse 0;
            var buf: [128]u8 = undefined;
            const origin = std.fmt.bufPrint(&buf, "storage_class={s};shape_id={d}", .{ sc, sid }) catch "storage_class=unknown";
            self.logTransformProvenance("comp.origin", .emit_call, "expr", origin);
            self.p("\"{s}\"", .{origin});
            return;
        }
        if (self.enum_name_of(rt)) |ename| {
            var buf: [64]u8 = undefined;
            const origin = std.fmt.bufPrint(&buf, "kind=enum;name={s}", .{ename}) catch "kind=enum";
            self.logTransformProvenance("comp.origin", .emit_call, "expr", origin);
            self.p("\"{s}\"", .{origin});
            return;
        }
        const fallback = "kind=dynamic";
        self.logTransformProvenance("comp.origin", .emit_call, "expr", fallback);
        self.p("\"{s}\"", .{fallback});
    }

    fn metaStringFromExpr(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (self.meta_combinator_fold_depth > 0) {
            return switch (expr.*) {
                // Producer quote owns the face (GAP-145 O5).
                .quoted => |s| if (ast.quotedLiteralIsByteSequence(s.quote)) null else s.val,
                .name => |n| blk: {
                    const value = self.comptime_bindings().get(n.ident) orelse break :blk null;
                    break :blk if (value == .string) value.string else null;
                },
                else => null,
            };
        }
        return switch (expr.*) {
            // Producer quote owns the face (GAP-145 O5).
            .quoted => |s| if (ast.quotedLiteralIsByteSequence(s.quote)) null else s.val,
            else => self.fold_meta_string_expr(expr),
        };
    }

    fn metaStringFromExprOrFold(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        if (self.metaStringFromExpr(expr)) |s| return s;
        const saved = self.meta_combinator_fold_depth;
        self.meta_combinator_fold_depth = 0;
        defer self.meta_combinator_fold_depth = saved;
        return self.fold_meta_string_expr(expr);
    }

    fn deriveNameValueFromExpr(expr: *const ast.Expr) ?comptime_eval.Value {
        return switch (expr.*) {
            .name => |n| .{ .string = n.ident },
            // Producer quote owns the face (GAP-145 O5).
            .quoted => |s| if (ast.quotedLiteralIsByteSequence(s.quote)) null else .{ .string = s.val },
            else => null,
        };
    }

    fn buildMetaCombinatorValues(
        self: *CodeGen,
        internal: []const u8,
        args: []const *ast.Expr,
        storage: *[8]comptime_eval.Value,
    ) ?usize {
        const opts = self.comptime_eval_options();
        const bindings = self.comptime_bindings();

        const simple_two_arg = struct {
            name: []const u8,
            wants_callback: bool,
        };
        const two_arg_specs = [_]simple_two_arg{
            .{ .name = "__comptimemap", .wants_callback = true },
            .{ .name = "__comptimeeach", .wants_callback = true },
            .{ .name = "__comptimematch", .wants_callback = true },
            .{ .name = "__comptimepower", .wants_callback = true },
            .{ .name = "__comptimepermute", .wants_callback = true },
            .{ .name = "__comptimenfold", .wants_callback = true },
            .{ .name = "__metagrammar", .wants_callback = true },
            .{ .name = "__derivemap", .wants_callback = false },
            .{ .name = "__derivepower", .wants_callback = false },
            .{ .name = "__derivenfold", .wants_callback = false },
            .{ .name = "__derivepermute", .wants_callback = false },
            .{ .name = "__derivetower", .wants_callback = false },
        };
        if (args.len == 2) {
            for (two_arg_specs) |spec| {
                if (!std.mem.eql(u8, internal, spec.name)) continue;
                storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
                if (spec.wants_callback) {
                    storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
                    if (storage[1] != .func) return null;
                } else {
                    storage[1] = deriveNameValueFromExpr(args[1]) orelse return null;
                }
                return 2;
            }
        }
        if (std.mem.eql(u8, internal, "__metaweave") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }

        if (std.mem.eql(u8, internal, "__comptimechoose") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__derivechoose") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = deriveNameValueFromExpr(args[2]) orelse return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimefanout") and args.len == 3) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            storage[1] = switch (args[1].*) {
                .int_lit => .{ .int = args[1].int_lit.val },
                else => return null,
            };
            storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        if (std.mem.eql(u8, internal, "__comptimetabulate") and args.len == 2) {
            storage[0] = switch (args[0].*) {
                .int_lit => .{ .int = args[0].int_lit.val },
