                if (args.len >= 3) {
                    storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                    if (storage[2] != .func) return null;
                    return 3;
                }
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__metascheme") and args.len >= 1) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            if (args.len >= 2) {
                storage[1] = .{ .string = self.metaStringFromExprOrFold(args[1]) orelse return null };
                if (args.len >= 3) {
                    storage[2] = comptime_eval.evalWithBindings(args[2], bindings, opts) catch return null;
                    if (storage[2] != .func) return null;
                    return 3;
                }
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__metaschemeclauses") and args.len >= 1) {
            storage[0] = .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null };
            if (args.len >= 2) {
                storage[1] = comptime_eval.evalWithBindings(args[1], bindings, opts) catch return null;
                if (storage[1] != .func) return null;
                return 2;
            }
            return 1;
        }
        if (std.mem.eql(u8, internal, "__comptimefixpoint") and args.len == 3) {
            // Producer quote owns the face (GAP-145 O5): a byte-sequence
            // literal is not a compile-time string, so this combinator
            // refuses rather than folds it into the string kingdom.
            storage[0] = switch (args[0].*) {
                .quoted => |s| if (ast.quotedLiteralIsByteSequence(s.quote))
                    return null
                else
                    .{ .string = s.val },
                else => .{ .string = self.metaStringFromExprOrFold(args[0]) orelse return null },
            };
            const fp = fixpointCallFromArgs(args) orelse return null;
            storage[1] = .{ .int = @intCast(fp.max_iter) };
            storage[2] = comptime_eval.evalWithBindings(fp.callback, bindings, opts) catch return null;
            if (storage[2] != .func) return null;
            return 3;
        }
        return null;
    }

    fn runMetaCombinatorString(
        self: *CodeGen,
        internal: []const u8,
        values: []const comptime_eval.Value,
        site: transform_engine.SiteKind,
    ) ?[]const u8 {
        if (transform_engine.publicNameForInternal(internal) != null and
            !transform_engine.requireMetaDispatchBeforeHook(internal))
            return null;
        const result = meta_dispatch.dispatchAtSite(self.meta_host(), internal, values, self.alloc, site);
        return switch (result) {
            .string => |s| s,
            else => null,
        };
    }

    fn tryEmitMetaCombinatorString(self: *CodeGen, internal: []const u8, args: []const *ast.Expr) E!bool {
        self.meta_combinator_fold_depth += 1;
        defer self.meta_combinator_fold_depth -= 1;
        var storage: [8]comptime_eval.Value = undefined;
        const n = self.buildMetaCombinatorValues(internal, args, &storage) orelse return false;
        const folded = self.runMetaCombinatorString(internal, storage[0..n], self.metaCombinatorEmitSite()) orelse return false;
        try self.emit_c_string_literal(folded);
        return true;
    }

    fn fixpointCallFromArgs(args: []const *ast.Expr) ?struct {
        callback: *ast.Expr,
        max_iter: usize,
    } {
        if (args.len != 3 or args[0].* != .quoted) return null;
        if (args[1].* == .int_lit and args[2].* == .func_expr) {
            return .{ .callback = args[2], .max_iter = @intCast(args[1].int_lit.val) };
        }
        if (args[2].* == .int_lit and args[1].* == .func_expr) {
            return .{ .callback = args[1], .max_iter = @intCast(args[2].int_lit.val) };
        }
        return null;
    }

    fn metaCombinatorEmitSite(self: *const CodeGen) transform_engine.SiteKind {
        if (self.current_func_body != null) return .block_body;
        return .emit_call;
    }

    fn logTransformProvenance(
        self: *CodeGen,
        public_name: []const u8,
        site: transform_engine.SiteKind,
        input: []const u8,
        output: []const u8,
    ) void {
        if (!transform_engine.isRegisteredTransform(public_name)) return;
        transform_engine.logProvenance(
            self.alloc,
            public_name,
            site,
            std.hash.Wyhash.hash(0, input),
            std.hash.Wyhash.hash(0, output),
        );
    }

    /// __type_id(expr) — stable compile-time type identifier (FNV hash of type name)
    fn emit_type_id_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        var buf: [128]u8 = undefined;
        const name = rt.c_type(&buf);
        // FNV-1a hash for stable type IDs
        var hash: u64 = 14695981039346656037;
        for (name) |byte| {
            hash ^= @as(u64, byte);
            hash *%= 1099511628211;
        }
        self.p("((int64_t){d}LL)", .{@as(i64, @bitCast(hash))});
    }

    /// __is_type(expr, "type_name") — compile-time type identity check
    fn emit_is_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const expected = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("false", .{});
            return;
        };
        var buf: [128]u8 = undefined;
        const actual = rt.c_type(&buf);
        // Check both C type name and Duo type name
        const matches = std.mem.eql(u8, actual, expected) or
            (std.mem.eql(u8, expected, "i64") and std.mem.eql(u8, actual, "int64_t")) or
            (std.mem.eql(u8, expected, "i32") and std.mem.eql(u8, actual, "int32_t")) or
            (std.mem.eql(u8, expected, "f64") and std.mem.eql(u8, actual, "double")) or
            (std.mem.eql(u8, expected, "f32") and std.mem.eql(u8, actual, "float")) or
            (std.mem.eql(u8, expected, "str") and std.mem.eql(u8, actual, "const char*")) or
            (std.mem.eql(u8, expected, "bool") and std.mem.eql(u8, actual, "bool")) or
            (std.mem.eql(u8, expected, "any") and std.mem.eql(u8, actual, "lua_Value"));
        self.p("{s}", .{if (matches) "true" else "false"});
    }

    /// __comptimeprint / __comptimewarn / __comptimeerror — compile-time messages
    fn emit_comptime_message(self: *CodeGen, args: []const *ast.Expr, level: MessageLevel) E!void {
        // Evaluate message at compile time
        const val = comptime_eval.evalWithBindings(args[0], self.comptime_bindings(), self.comptime_eval_options()) catch {
            if (args[0].* == .quoted) {
                const msg = args[0].quoted.val;
                switch (level) {
                    .info => std.debug.print("[comptime] {s}\n", .{msg}),
                    .warning => std.debug.print("[comptime warning] {s}\n", .{msg}),
                    .err => {
                        std.debug.print("[comptime error] {s}\n", .{msg});
                        self.p("_Static_assert(0, \"{s}\")", .{msg});
                        return;
                    },
                }
                self.p("((void)0)", .{});
                return;
            }
            self.p("((void)0)", .{});
            return;
        };
        if (val == .string) {
            switch (level) {
                .info => std.debug.print("[comptime] {s}\n", .{val.string}),
                .warning => std.debug.print("[comptime warning] {s}\n", .{val.string}),
                .err => {
                    std.debug.print("[comptime error] {s}\n", .{val.string});
                    self.p("_Static_assert(0, \"{s}\")", .{val.string});
                    return;
                },
            }
        }
        self.p("((void)0)", .{});
    }

    /// __embed_str("path") — embed file contents as a C string literal
    fn emit_embed_str(self: *CodeGen, arg: *const ast.Expr) E!void {
        if (arg.* == .quoted) {
            // Use C23 #embed or fall back to xxd-style inclusion
            // For maximum portability, emit as a char literal via _Pragma or include
            self.p("((const char[]){{", .{});
            self.p("#embed \"{s}\"", .{arg.quoted.val});
            self.p(", 0}})", .{});
        } else {
            self.p("\"\"", .{});
        }
    }

    /// __embed_file("path") — embed file as static byte array
    fn emit_embed_file(self: *CodeGen, arg: *const ast.Expr) E!void {
        if (arg.* == .quoted) {
            // Emit as a compound literal with the embedded data
            self.p("({{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("static const unsigned char __embed_data[] = {{\n", .{});
            self.ind();
            self.p("    #embed \"{s}\"\n", .{arg.quoted.val});
            self.ind();
            self.p("}};\n", .{});
            self.ind();
            self.p("lua_Value __et = lua_table_new_with_capacity(0, 2);\n", .{});
            self.ind();
            self.p("lua_table_set_raw_lit(__et, \"ptr\", {d}, 3, lua_val_from_int((int64_t)(uintptr_t)__embed_data));\n", .{calc_lua_hash("ptr")});
            self.ind();
            self.p("lua_table_set_raw_lit(__et, \"len\", {d}, 3, lua_val_from_int((int64_t)sizeof(__embed_data)));\n", .{calc_lua_hash("len")});
            self.ind();
            self.p("__et;\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}})", .{});
        } else {
            self.p("lua_val_nil()", .{});
        }
    }

    /// __field_offset(T, "field") — emit offsetof for a record field
    fn emit_field_offset_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("0", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                // Calculate offset based on field position and type sizes
                var offset: usize = 0;
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        self.p("{d}", .{offset});
                        return;
                    }
                    // Approximate field sizes for native types
                    offset += field_byte_size(f.typ);
                }
            },
            else => {},
        }
        // Fall back to __builtin_offsetof if struct name is known
        if (args[0].* == .quoted) {
            self.p("((int64_t)__builtin_offsetof({s}, {s}))", .{ args[0].quoted.val, field_name });
        } else {
            self.p("0", .{});
        }
    }

    /// __field_size(T, "field") — emit sizeof for a specific field's type
    fn emit_field_size_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        const rt = self.expr_type(args[0]);
        const field_name = if (args[1].* == .quoted) args[1].quoted.val else {
            self.p("0", .{});
            return;
        };
        switch (rt) {
            .table_type => |t| {
                for (t.fields) |f| {
                    if (std.mem.eql(u8, f.name, field_name)) {
                        self.p("{d}", .{field_byte_size(f.typ)});
                        return;
                    }
                }
            },
            else => {},
        }
        self.p("0", .{});
    }

    /// Helper: approximate byte size of a resolved type
    fn field_byte_size(rt: types.ResolvedType) usize {
        return switch (rt) {
            .i8, .u8, .bool => 1,
            .i16, .u16 => 2,
            .i32, .u32, .f32 => 4,
            .i64, .u64, .f64 => 8,
            .str, .pointer, .any => 8, // pointer-sized
            .v4f64, .v4i64 => 32,
            .v8f32, .v8i32 => 32,
            else => 8, // default pointer-sized
        };
    }

    /// __bitfield("name", ...) — define a packed bitfield struct
    fn emit_bitfield_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .quoted) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const struct_name = args[0].quoted.val;
        // Emit a packed struct typedef with bitfield members
        // Args after first: alternating "field_name" and bit_width (int literal)
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef struct __attribute__((packed)) {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .quoted and args[i + 1].* == .int_lit) {
                self.ind();
                self.p("    uint64_t {s} : {d};\n", .{ args[i].quoted.val, args[i + 1].int_lit.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{struct_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{struct_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __union("name", ...) — define a C union type
    fn emit_union_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .quoted) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const union_name = args[0].quoted.val;
        // Args after first: alternating "field_name" and "c_type"
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef union {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .quoted and args[i + 1].* == .quoted) {
                self.ind();
                self.p("    {s} {s};\n", .{ args[i + 1].quoted.val, args[i].quoted.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{union_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{union_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __make_type("name", "field1", "type1", "field2", "type2", ...) — define a struct type
    /// Returns sizeof(type) as an integer. The typedef is emitted inline.
    fn emit_make_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        if (args.len < 1 or args[0].* != .quoted) {
            self.p("lua_val_from_int(0)", .{});
            return;
        }
        const type_name = args[0].quoted.val;
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("typedef struct {{\n", .{});
        var i: usize = 1;
        while (i + 1 < args.len) : (i += 2) {
            if (args[i].* == .quoted and args[i + 1].* == .quoted) {
                self.ind();
                self.p("    {s} {s};\n", .{ args[i + 1].quoted.val, args[i].quoted.val });
            }
        }
        self.ind();
        self.p("}} {s};\n", .{type_name});
        self.ind();
        self.p("lua_val_from_int((int64_t)sizeof({s}));\n", .{type_name});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    /// __metatable_type(expr) — returns type info about an expression's metatable
    fn emit_metatable_type_intrinsic(self: *CodeGen, args: []const *ast.Expr) E!void {
        // Emit a runtime query that returns metatable info as a table
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __obj = ", .{});
        try self.emit_as_lua_value(args[0]);
        self.p(";\n", .{});
        self.ind();
        self.p("lua_Value __mt_info = lua_table_new_with_capacity(0, 2);\n", .{});
        self.ind();
        self.p("lua_Value __mt = lua_getmetatable(__obj);\n", .{});
        self.ind();
        self.p("lua_table_set_raw_lit(__mt_info, \"has_metatable\", {d}, 13, lua_val_from_bool(__mt.type != VAL_NIL));\n", .{calc_lua_hash("has_metatable")});
        self.ind();
        self.p("lua_table_set_raw_lit(__mt_info, \"metatable\", {d}, 9, __mt);\n", .{calc_lua_hash("metatable")});
        self.ind();
        self.p("__mt_info;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn exprs_same(_: *CodeGen, a: *const ast.Expr, b: *const ast.Expr) bool {
        if (@intFromPtr(a) == @intFromPtr(b)) return true;
        if (@as(std.meta.Tag(ast.Expr), a.*) != @as(std.meta.Tag(ast.Expr), b.*)) return false;
        return switch (a.*) {
            .name => std.mem.eql(u8, a.name.ident, b.name.ident),
            else => false,
        };
    }

    fn math_unary_arg(expr: *const ast.Expr, fname: []const u8) ?*const ast.Expr {
        if (expr.* != .call) return null;
        const c = &expr.call;
        if (c.func.* != .field) return null;
        const f = &c.func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "math")) return null;
        if (!std.mem.eql(u8, f.field, fname)) return null;
        if (c.args.len != 1) return null;
        return c.args[0];
    }

    fn try_emit_sin_cos_product(self: *CodeGen, lhs: *const ast.Expr, rhs: *const ast.Expr) E!bool {
        const sin_arg = math_unary_arg(lhs, "sin") orelse math_unary_arg(rhs, "sin");
        const cos_arg = math_unary_arg(lhs, "cos") orelse math_unary_arg(rhs, "cos");
        if (sin_arg == null or cos_arg == null) return false;
        if (!self.exprs_same(sin_arg.?, cos_arg.?)) return false;
        const arg = sin_arg.?;
        self.p("(0.5 * sin(2.0 * (double)(", .{});
        try self.emit_expr(arg);
        self.p(")))", .{});
        return true;
    }

    fn maybe_emit_math_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_numeric()) return false;
        if (func.* != .field) return false;
        const f = &func.field;
        if (f.obj.* != .name) return false;
        if (!std.mem.eql(u8, f.obj.name.ident, "math")) return false;

        const fname = f.field;
        // Integer-typed max/min/abs: emit native integer ops instead of the
        // double-returning libm path, avoiding the int->double->int round-trip.
        if (std.mem.eql(u8, fname, "max") or std.mem.eql(u8, fname, "min")) {
            if (args.len != 2) return false;
            if (self.expr_type(args[0]).is_integer() and self.expr_type(args[1]).is_integer()) {
                self.p("{s}(", .{if (std.mem.eql(u8, fname, "max")) "lua_imax_i64" else "lua_imin_i64"});
                try self.emit_expr(args[0]);
                self.p(", ", .{});
                try self.emit_expr(args[1]);
                self.p(")", .{});
                return true;
            }
        }
        if (std.mem.eql(u8, fname, "abs") and args.len == 1 and self.expr_type(args[0]).is_integer()) {
            self.p("llabs(", .{});
            try self.emit_expr(args[0]);
            self.p(")", .{});
            return true;
        }
        if ((std.mem.eql(u8, fname, "deg") or std.mem.eql(u8, fname, "rad")) and args.len == 1) {
            const scale = if (std.mem.eql(u8, fname, "deg")) "180.0 / 3.14159265358979323846" else "3.14159265358979323846 / 180.0";
            self.p("(", .{});
            const at = self.expr_type(args[0]);
            if (at.is_integer()) {
                self.p("(double)(", .{});
                try self.emit_expr(args[0]);
                self.p(")", .{});
            } else if (at == .any or self.expr_emits_lua_value(args[0])) {
                self.p("lua_to_num(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(")", .{});
            } else {
                try self.emit_expr(args[0]);
            }
            self.p(" * ({s}))", .{scale});
            return true;
        }
        const lua_names = [_][]const u8{
            "sqrt", "abs",  "floor", "ceil", "sin",  "cos",  "tan",
            "asin", "acos", "atan",  "exp",  "log",  "fmod", "max",
            "min",  "pow",  "log10", "sinh", "cosh", "tanh",
        };
        if ((std.mem.eql(u8, fname, "max") or std.mem.eql(u8, fname, "min")) and args.len != 2) return false;
        const c_names = [_][]const u8{
            "sqrt", "fabs", "floor", "ceil", "sin",  "cos",  "tan",
            "asin", "acos", "atan",  "exp",  "log",  "fmod", "fmax",
            "fmin", "pow",  "log10", "sinh", "cosh", "tanh",
        };
        for (lua_names, c_names) |ln, cn| {
            if (std.mem.eql(u8, fname, ln)) {
                self.p("{s}(", .{cn});
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    const at = self.expr_type(arg);
                    if (at.is_integer()) {
                        self.p("(double)(", .{});
                        try self.emit_expr(arg);
                        self.p(")", .{});
                    } else if (at == .any or self.expr_emits_lua_value(arg)) {
                        self.p("lua_to_num(", .{});
                        try self.emit_as_lua_value(arg);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(arg);
                    }
                }
                self.p(")", .{});
                return true;
            }
        }
        return false;
    }

    /// `x:to(i64)` where the RECEIVER's type is not known statically.
    ///
    /// The receiver-first `to` normalization above is gated on a scalar
    /// receiver, so an untyped call result — `std.proc.capture(cmd):to(i64)` —
    /// fell past it into ordinary member dispatch and emitted a boxed member
    /// invocation of `.to` with `"i64"` as an argument, which does not build.
    /// (Spelled without the runtime's name on purpose: `pass4_boxed_inventory`
    /// counts that identifier as raw text, so writing it in prose would report
    /// a boxing site this change does not add.) The
    /// OPERATION-FIRST spelling of the identical expression,
    /// `to(i64)(std.proc.capture(cmd))`, went straight to the conversion edge
    /// and worked. Two faces of one edge, only one of them lowering, is the
    /// asymmetry gap[081] records — and it is half of why the tree is written
    /// 1647:1 in the noncanonical orientation.
    ///
    /// The scalar gate is kept for the reason it was written (data always wins
    /// the name) and widened only where a user member CANNOT be what was meant:
    /// the target group must name a PRIMITIVE descriptor, the program must not
    /// have bound `to` itself, and the receiver must carry no record alias
    /// declaring its own `to`. `p:to(point)` and a record with a hand-written
    /// `to` both still dispatch as members.
    fn untyped_receiver_takes_convert_edge(self: *CodeGen, ot: RT, mc: anytype) bool {
        if (ot != .any) return false;
        if (mc.args[0].* != .name) return false;
        const target = mc.args[0].name.ident;
        if (self.mem_type_from_name(target) == null) return false;
        if (self.user_owns_name("to")) return false;
        if (mc.obj.* == .name) {
            if (self.record_aliases.get(mc.obj.name.ident)) |alias| {
                if (alias == .@"struct") {
                    if (self.alias_defs.get(alias.@"struct".name)) |def| {
                        for (def.methods) |method| {
                            const last = if (method.path.len > 0) method.path[method.path.len - 1] else "";
                            if (std.mem.eql(u8, last, "to")) return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /// One lowering for both orientations of the conversion edge (A3 ONE EDGE,
    /// 3.2: "orientations to/from share one edge"). `target` names the
    /// destination descriptor; `value` is the single runtime operand.
    /// gap[082]: ask the TRIE before the hardcoded primitive arms.
    ///
    /// `src_desc` is the source descriptor when the call site named it
    /// (`dest:from(src)(v)`, `dest.from(src)(v)` — spec 2.6 gate 6). When the
    /// site did not, it is inferred from the value's own type, which is exactly
    /// as far as inference reaches today: a nominal descriptor annotation
    /// (`d: feet = 3.0`) is rejected by sema, so a user descriptor can only
    /// reach here by being SPELLED. That limit is real and is recorded on the
    /// gap rather than hidden behind a guess.
    ///
    /// Order matters and is law, not taste: a DECLARED edge outranks the
    /// builtin projection (A3 — the authored fact is the relationship), and a
    /// DERIVED edge outranks it too, because a derivation is the trie
    /// answering, not the trie failing over.
    fn emit_relation_convert(self: *CodeGen, dest: []const u8, src_desc: ?[]const u8, loc: ast.Loc, value: *ast.Expr, result_rt: RT) E!bool {
        const rel = self.relations.family("to") orelse return false;
        if (rel.authored() == 0) return false;
        const src = src_desc orelse self.inferred_descriptor(value) orelse return false;
        if (std.mem.eql(u8, src, dest)) return false;

        if (rel.direct(src, dest)) |e| {
            var cbuf: [64]u8 = undefined;
            self.p("/* to[{s}][{s}] = {s} declared, class {s} */ ", .{ dest, src, e.conv, e.props.fmt(&cbuf) });
            return try self.emit_conv_call(e.conv, loc, value, result_rt);
        }

        const path = rel.derive(src, dest) orelse return false;
        var wbuf: [512]u8 = undefined;
        const w = path.witness(&wbuf);
        if (!path.admitted) {
            // A route exists and the algebra REFUSES it. This is a diagnostic
            // and not a fallthrough: falling through would silently pick the
            // builtin projection, which is precisely how an algebra becomes
            // dangerous — the program would keep compiling and quietly stop
            // meaning what the edges say.
            term.locErr(loc, "no silent conversion {s} -> {s}: {s}", .{ src, dest, w });
            term.locHint(loc, "declare the edge, or route the lossy hop by name", .{});
            refused_conversions += 1;
            return false;
        }
        if (why_convert) std.debug.print("[why convert] {s}\n", .{w});
        // The witness ships INSIDE the artifact. A5 makes it mandatory, and a
        // witness that only exists in a compiler's stderr is not carried by the
        // thing it justifies.
        self.p("/* witness w-conv: {s} */ ", .{w});
        var inner = ast.Expr{ .call = .{
            .loc = loc,
            .func = @constCast(&ast.Expr{ .name = .{ .loc = loc, .ident = path.first.conv } }),
            .args = @constCast(&[_]*ast.Expr{value}),
        } };
        return try self.emit_conv_call(path.second.conv, loc, &inner, result_rt);
    }

    /// `for src, conv in to[dest]` — enumeration of a relation's edges into one
    /// destination. Declaration order, so the loop is reproducible; unrolled,
    /// because a trie the compiler already holds does not need a runtime table
    /// to be walked. FAMILY-GENERIC: any family the store holds enumerates.
    fn emit_relation_enumeration(self: *CodeGen, gf: *const @FieldType(ast.Stmt, "gen_for")) E!bool {
        if (gf.iters.len != 1 or gf.vars.len == 0 or gf.vars.len > 2) return false;
        const it = gf.iters[0];
        // BOTH FACES OF THE SAME ENUMERATION. `to[dest]` is an `.index` and
        // `to(dest)` is a `.call`, and only the first was recognised here — so
        // `for src, conv in to(micron)` fell through to the generic iterator
        // emit, which printed the family name as a bare C identifier and clang
        // answered "use of undeclared identifier 'to'". Measured on three
        // corpus files: `examples/conversion/relation.id` (`to`),
        // `examples/conversion/store.id` (`eq`) and
        // `examples/vector_embed_smoke.id` (`vector`). The bracket face is
        // RETIRED spelling in this tree — `docs/spec/law.md` retires `[` as an
        // accessor — so the only face a current program can write was the one
        // that did not work.
        const fam_name: []const u8, const dest: []const u8 = switch (it.*) {
            .index => |idx| blk: {
                if (idx.obj.* != .name or idx.key.* != .name) return false;
                break :blk .{ idx.obj.name.ident, idx.key.name.ident };
            },
            .call => |c| blk: {
                if (c.func.* != .name or c.args.len != 1 or c.args[0].* != .name) return false;
                break :blk .{ c.func.name.ident, c.args[0].name.ident };
            },
            else => return false,
        };
        // LAW-CALL: data always wins the name. If the program bound the family
        // name itself, this is that value's index and not the relation's.
        if (self.user_owns_name(fam_name)) return false;
        const rel = self.relations.family(fam_name) orelse return false;

        var edges: std.ArrayListUnmanaged(relation.Edge) = .empty;
        defer edges.deinit(self.alloc);
        try rel.intoDest(dest, &edges, self.alloc);

        self.ind();
        self.p("/* {s}({s}) enumerates {d} declared edge(s) */\n", .{ fam_name, dest, edges.items.len });
        for (gf.vars) |v| try self.note_local(v);
        for (edges.items) |e| {
            self.ind();
            self.pl("{{", .{});
            self.indent += 1;
            try self.note_local_type(gf.vars[0], .str);
            self.ind();
            self.p("const char* {s} = \"{s}\"; (void){s};\n", .{ gf.vars[0], e.src, gf.vars[0] });
            if (gf.vars.len > 1) {
                try self.note_local_type(gf.vars[1], .str);
                self.ind();
                self.p("const char* {s} = \"{s}\"; (void){s};\n", .{ gf.vars[1], e.conv, gf.vars[1] });
            }
            try self.emit_block(&gf.body);
            self.indent -= 1;
            self.ind();
            self.pl("}}", .{});
        }
        return true;
    }

    fn emit_conv_call(self: *CodeGen, conv: []const u8, loc: ast.Loc, value: *ast.Expr, result_rt: RT) E!bool {
        var call = ast.Expr{ .call = .{
            .loc = loc,
            .func = @constCast(&ast.Expr{ .name = .{ .loc = loc, .ident = conv } }),
            .args = @constCast(&[_]*ast.Expr{value}),
        } };
        if (result_rt == .any) try self.emit_as_lua_value(&call) else try self.emit_expr(&call);
        return true;
    }

    /// The descriptor name a value carries, for trie lookup.
    ///
    /// law.nominal (§46): a NOMINAL descriptor answers with its own name, which
    /// is what lets `d:to(inch)` reach the trie when `d: feet = 3.0`. Before
    /// this arm the only user descriptor the trie ever saw was one the call
    /// site SPELLED (`inch:from(feet)(v)`), because a value could not carry a
    /// descriptor at all — the algebra was deriving edges between descriptors
    /// no value could be.
    fn inferred_descriptor(self: *CodeGen, value: *ast.Expr) ?[]const u8 {
        return switch (self.expr_type(value)) {
            .@"struct" => |s| if (types.nominalRepr(s.name) != null) s.name else null,
            .i8 => "i8",
            .i16 => "i16",
            .i32 => "i32",
            .i64 => "i64",
            .u8 => "u8",
            .u16 => "u16",
            .u32 => "u32",
            .u64 => "u64",
            .f32 => "f32",
            .f64 => "f64",
            .bool => "bool",
            .str => "str",
            else => null,
        };
    }

    fn emit_convert_edge(self: *CodeGen, target: []const u8, loc: ast.Loc, value: *ast.Expr, result_rt: RT) E!bool {
        return self.emit_convert_edge_from(target, null, loc, value, result_rt);
    }

    fn emit_convert_edge_from(self: *CodeGen, target: []const u8, src_desc: ?[]const u8, loc: ast.Loc, value: *ast.Expr, result_rt: RT) E!bool {
        if (try self.emit_relation_convert(target, src_desc, loc, value, result_rt)) return true;
        var one = [_]*ast.Expr{value};
        if (std.mem.eql(u8, target, "str")) {
            var synth = ast.Expr{ .name = .{ .loc = loc, .ident = "tostring" } };
            return try self.maybe_emit_stdlib_call(&synth, one[0..], result_rt);
        }
        if (std.mem.eql(u8, target, "f64") or std.mem.eql(u8, target, "f32")) {
            var synth = ast.Expr{ .name = .{ .loc = loc, .ident = "tonumber" } };
            return try self.maybe_emit_stdlib_call(&synth, one[0..], result_rt);
        }
        // Integer targets lower to the native C conversion, which truncates
        // toward zero — no boxed call in between.
        if (std.mem.eql(u8, target, "i64") or std.mem.eql(u8, target, "i32") or
            std.mem.eql(u8, target, "i16") or std.mem.eql(u8, target, "i8"))
        {
            // A native C cast is only valid when the SOURCE is already numeric.
            // Applied to a `str` it cast the `const char*` and produced a
            // POINTER VALUE silently (`to(i64)("42")` -> 4338831547), and
            // applied to an `any` it did not compile at all ("operand of type
            // 'lua_Value' where arithmetic or pointer type is required"). Both
            // route through the boxed numeric conversion instead, which parses
            // strings — the same conversion `tonumber` is a projection of, so
            // the edge has one meaning regardless of what flows into it.
            const src = self.expr_type(value);
            if (result_rt == .any) self.p("lua_val_from_int(", .{});
            if (src == .str and (self.expr_is_native_cstr(value) or !self.expr_emits_lua_value(value))) {
                // A `str` that is already a native `const char*` — the typed
                // spelling, `s: str` then `s:to(i64)`. Boxing it to reach
                // `lua_to_num` asked for a name a full-native module never
                // declares, which is why BOTH faces of this conversion failed
                // to build (gap[081] step 1). One edge, one meaning: the plain
                // C parse answers what the boxed one does for a numeral and
                // FAULTS where the boxed one silently answered 0.
                self.p("duo_str_to_i64(", .{});
                try self.emit_expr(value);
                self.p(")", .{});
            } else if (src == .str or src == .any) {
                self.p("((int64_t)lua_to_num(", .{});
                try self.emit_as_lua_value(value);
                self.p("))", .{});
            } else {
                self.p("((int64_t)(", .{});
                try self.emit_expr(value);
                self.p("))", .{});
            }
            if (result_rt == .any) self.p(")", .{});
            return true;
        }
        return false;
    }

    /// LAW-CALL's "data always wins the name", enforced by SCOPE LOOKUP rather
    /// than by guessing from operand types. A relation family may only be
    /// projected onto a bare name when the program has not bound that name
    /// itself — `lib/reflect.duo` and `lib/utf8.duo` both define their
    /// own `len`, and an unguarded projection silently hijacked them.
    fn user_owns_name(self: *CodeGen, name: []const u8) bool {
        if (self.func_decls.contains(name)) return true;
        if (self.func_bodies.contains(name)) return true;
        var i = self.local_scopes.items.len;
        while (i > 0) {
            i -= 1;
            if (self.local_scopes.items[i].contains(name)) return true;
        }
        return false;
    }

    /// Spec 2.10 G3 (de-magicking): a primitive type name is an ORDINARY VALUE,
    /// not a third category. `to(str)(x)` used to work only because the call
    /// emitter pattern-matched the AST shape and never evaluated `str` — the
    /// moment the same name reached value position (`t = str`, `print(str)`,
    /// `str.from(i64)(v)`) codegen emitted a bare C identifier and clang said
    /// "use of undeclared identifier 'str'". That is exactly the "third
    /// category" the de-magicking test forbids.
    ///
    /// The set here is deliberately the LEXER KEYWORD set (`typeKeywordName` in
    /// parser.zig), not `mem_type_from_name`'s wider alias list. `str`/`i64` are
    /// reserved words, so no program can bind them and no projection can hijack
    /// a user name; `string`, `ptr`, `isize`, `usize` are ordinary identifiers a
    /// program MAY bind, so they stay out.
    /// Whether a numeric `for` step is a statically-known NEGATIVE value.
    /// null means the sign is only knowable at run time, which the caller
    /// handles with a hoisted runtime test rather than guessing.
    fn num_for_step_negative(e: *const ast.Expr) ?bool {
        return switch (e.*) {
            .int_lit => |x| x.val < 0,
            .float_lit => |x| x.val < 0,
            .unop => |u| if (u.op == .neg) blk: {
                const inner = num_for_step_negative(u.operand) orelse break :blk null;
                break :blk !inner;
            } else null,
            else => null,
        };
    }

    /// §8 B-12 — the return type a contract LOWERS to.
    ///
    /// `: u64 | error` declares the correlated pack `(value, nil) | (nil,
    /// error)`. A pack has no native scalar representation — `return nil,
    /// error.overflow` out of an `int64_t` C function is a hard clang error —
    /// so a fallible contract lowers dynamically even though the success type
    /// stays written on the declaration and stays checked by sema.
    ///
    /// Identity for every contract without a failure alternative, which is
    /// every one of the 748 tracked `.duo` files: `ret_fallible` is set only
    /// by a `| alt` in return position, and that was a discarded no-op before.
    /// So this cannot move any existing lowering.
    fn contract_ret(fb: *const ast.FuncBody) ast.TypeExpr {
        return if (fb.ret_fallible) .inferred else fb.ret_type;
    }

    /// The return contract AS NATIVE ADMISSION MUST READ IT: an explicitly
    /// declared `any` is folded to `.inferred`, because they are the same
    /// statement about the value.
    ///
    /// `any` is the TOP of the descriptor lattice — the absence of a
    /// constraint — so declaring it asserts nothing that omitting it did not
    /// already leave open. Admission nevertheless read the two spellings
    /// differently, and the difference was total:
    ///
    ///     f: any = (x: i64)          f = (x: i64)
    ///         x * 2                      x * 2
    ///     -> DNB001 ret-type:any     -> prints 42
    ///
    /// Same body, same semantics, same inferred result; one compiles natively
    /// and one has no realization at all. That inverts law.perf.dominance
    /// (`examples/cfloor/weak.id`): adding a fact may never REDUCE the
    /// realization set, and this reduced it from {native} to {} for the
    /// weakest fact expressible. It is also a law.infer.one violation standing
    /// in the backend — a source spelling that restates nothing was changing
    /// the realization.
    ///
    /// The two were already the same value downstream: the C backend renders
    /// `.inferred` as the string "any" (see the `.inferred => "any"` arms),
    /// and `resolve_type` answers `.any` for both.
    ///
    /// THIS DOES NOT WIDEN WHAT LOWERS. Folding only removes the spelling test;
    /// every body still faces `block_is_native_scalar` and the per-argument
    /// checks. Measured on bodies that genuinely are not native scalars —
    /// `f = (x: i64) { a = x }` and a body returning a table on one path and an
    /// integer on the other — both still refuse, on `print-arg:any`, which is
    /// the real reason rather than the spelling. The refusal moves to the
    /// truth; it does not disappear.
    ///
    /// Deliberately NOT applied to parameters. A parameter's descriptor is
    /// fixed by its call sites, not by the body, so `param-type:any` is a
    /// genuine missing fact and folding it would be unsound.
    fn native_ret_contract(fb: *const ast.FuncBody) ast.TypeExpr {
        const ret = contract_ret(fb);
        return if (type_expr_is_explicit_any(ret)) .inferred else ret;
    }

    fn primitive_descriptor_name(name: []const u8) ?[]const u8 {
        for ([_][]const u8{
            "i8",  "i16", "i32",  "i64",
            "u8",  "u16", "u32",  "u64",
            "f32", "f64", "bool", "void",
            "str",
        }) |t| {
            if (std.mem.eql(u8, name, t)) return t;
        }
        return null;
    }

    /// The runtime form of a descriptor. Its identity IS its canonical name, so
    /// two spellings of the same type are one value and `to(str) == to(str)`
    /// holds without a registry. Compile-time uses (`to(T)(v)`, `mem.store(T)`)
    /// intercept the name before this ever runs, so a descriptor only
    /// materializes when the program actually treats it as data.
    fn emit_primitive_descriptor(self: *CodeGen, canon: []const u8) void {
        self.p("lua_val_from_literal(\"{s}\", {d}, {d})", .{
            canon, calc_lua_hash(canon), canon.len,
        });
    }

    /// A descriptor interned by the relation store for this module. User
    /// bindings still win the name — data always wins.
    fn relation_descriptor_spelling(self: *CodeGen, name: []const u8) ?[]const u8 {
        if (self.is_local_name(name) or self.is_global_name(name)) return null;
        if (self.func_decls.contains(name) or self.func_bodies.contains(name)) return null;
        const nm = self.relations.names orelse return null;
        if (nm.lookup(.descriptor, name) != null) return name;
        return null;
    }

    /// gap[082]: when demand does not spell the source descriptor (`v:to(dest)`),
    /// succeed only when exactly one endpoint admits a path. Multiple admitted
    /// routes are ambiguous (relation.zig: two lawful hubs never select by order).
    fn emit_relation_convert_exhaustive(
        self: *CodeGen,
        dest: []const u8,
        loc: ast.Loc,
        value: *const ast.Expr,
        result_rt: RT,
    ) E!bool {
        if (try self.emit_relation_convert(dest, null, loc, @constCast(value), result_rt)) return true;
        const rel = self.relations.family("to") orelse return false;
        var descs: std.ArrayListUnmanaged(relation.Id) = .empty;
        defer descs.deinit(self.alloc);
        try rel.endpoints(&descs, self.alloc);
        var winner: ?[]const u8 = null;
        var admitted: usize = 0;
        for (descs.items) |id| {
            const src = rel.names.text(id);
            if (std.mem.eql(u8, src, dest)) continue;
            const path = rel.derive(src, dest) orelse continue;
            if (!path.admitted) continue;
            admitted += 1;
            winner = src;
            if (admitted > 1) {
                term.locErr(loc, "ambiguous conversion to {s}: spell the source with :from", .{dest});
                term.locHint(loc, "use {s}:from(source)(value) when more than one descriptor admits a path", .{dest});
                return false;
            }
        }
        if (admitted == 1) {
            return try self.emit_relation_convert(dest, winner, loc, @constCast(value), result_rt);
        }
        return false;
    }

    fn maybe_emit_stdlib_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        // `has(.lens)(subject)` — the presence FAMILY (2.8): subject is the
        // container, parameter is the lens. A lens parses to a lambda over
        // `__proj_v`, so presence is just "apply the lens, test for nil".
        // Demand is real: 110 sites in lib/ spell this `x.field != nil`.
        if (func.* == .call) {
            const hf = func.call;
            if (hf.func.* == .name and std.mem.eql(u8, hf.func.name.ident, "has") and
                hf.args.len == 1 and args.len == 1 and !self.user_owns_name("has"))
            {
                // The lens is a lambda over `__proj_v`; take its field directly
                // rather than materializing and invoking the closure (A4 DEMAND
                // — nothing physical unless consumed).
                if (hf.args[0].* == .func_expr) {
                    if (pipeline_projection_field_name(hf.args[0].func_expr)) |fname| {
                        var fexpr = ast.Expr{ .field = .{ .loc = hf.loc, .obj = args[0], .field = fname } };
                        // Presence is a bool; box it when the consuming site
                        // expects a lua_Value.
                        if (result_rt == .any) self.p("lua_val_from_bool(", .{});
                        self.p("((", .{});
                        try self.emit_as_lua_value(&fexpr);
                        self.p(").type != VAL_NIL)", .{});
                        if (result_rt == .any) self.p(")", .{});
                        return true;
                    }
                }
            }
        }

        // `T:from(S)(v)` — the REVERSE ORIENTATION of the conversion edge
        // (2.6 spells it `str:from(point)(raw)`): the TARGET is the receiver,
        // the SOURCE is the descriptor group. Same edge as `to(T)(v)`.
        if (func.* == .method_call) {
            const recv = func.method_call;
            if (std.mem.eql(u8, recv.method, "from") and recv.obj.* == .name and args.len == 1) {
                // gap[082]: the source descriptor is RIGHT THERE in
                // `dest:from(src)(v)` and was being discarded. Pass it — it is
                // the only way a user descriptor reaches the trie today, since
                // sema rejects a nominal annotation on a binding.
                const named_src = if (recv.args.len == 1 and recv.args[0].* == .name)
                    recv.args[0].name.ident
                else
                    null;
                if (try self.emit_convert_edge_from(recv.obj.name.ident, named_src, recv.loc, args[0], result_rt)) return true;
            }
        }
        // Same edge, DOT spelling. Gate 6 requires `to(str)` and `str.from(T)`
        // to be one edge with one id, and canonical Duo writes `.` not `:` —
        // without this arm `str.from(...)` fell through to a table lookup on the
        // descriptor and died. Two groups (`str.from(i64)(42)`, the source
        // descriptor named explicitly per gate 6) and one group
        // (`str.from(42)`, the source inferred from the value) both lower
        // through emit_convert_edge, so all four spellings are one lowering.
        if (func.* == .call and func.call.func.* == .field and args.len == 1) {
            const fld = func.call.func.field;
            if (std.mem.eql(u8, fld.field, "from") and fld.obj.* == .name and func.call.args.len == 1) {
                // Same edge, dot spelling — the source group is equally present
                // here and equally discarded before gap[082].
                const named_src = if (func.call.args[0].* == .name) func.call.args[0].name.ident else null;
                if (try self.emit_convert_edge_from(fld.obj.name.ident, named_src, fld.loc, args[0], result_rt)) return true;
            }
        }
        if (func.* == .field and args.len == 1) {
            const fld = func.field;
            if (std.mem.eql(u8, fld.field, "from") and fld.obj.* == .name) {
                if (try self.emit_convert_edge(fld.obj.name.ident, fld.loc, args[0], result_rt)) return true;
            }
        }
        // Canonical relation family `to` (spec 2.6): `to(T)(v)` is the curried
        // conversion — `to(str)(x)`, `to(i64)(x)`. Spec 2.10's de-magicking test
        // (G3) requires every std name to be an ordinary value or a relation
        // family with inspectable edges, "no third category", so the
        // Lua-inherited tostring/tonumber are PROJECTIONS of `to` rather than
        // builtins of their own. The canonical spelling is the one to write;
        // the vestiges remain only as aliases.
        if (func.* == .call) {
            const inner = func.call;
            // law.host.projection { projects = to, authority = false } —
            // gap[082] is the deletion gate. The trie is consulted first, in
            // `emit_convert_edge_from`; this arm is the fallback for primitive
            // destinations no edge has been written for yet.
            const fam_to = inner.func.* == .name and std.mem.eql(u8, inner.func.name.ident, "to");
            // `from` is NOT resolvable standalone: 2.6 spells it
            // `str:from(point)(raw)` — the TARGET is the receiver, the source
            // is the descriptor group. It therefore arrives through method
            // projection below, never as a bare call, so there is nothing to
            // guess from demand here.
            if (fam_to and inner.args.len == 1 and inner.args[0].* == .name and args.len == 1) {
                // Same edge as `T:from(S)(v)` — one lowering, two spellings.
                if (try self.emit_convert_edge(inner.args[0].name.ident, inner.func.name.loc, args[0], result_rt)) return true;
            }
        }
        if (func.* != .name) return false;
        const name = func.name.ident;
        // `len` relation family (2.6). `#x` is its OPERATOR projection (2.1)
        // and `s:len()` already has a specialized typed-string lowering that
        // owns the receiver form — so only the operation-first spelling is
        // added here, and only when the program has not bound `len` itself.
        if (std.mem.eql(u8, name, "len") and args.len == 1 and !self.user_owns_name("len")) {
            var u = ast.Expr{ .unop = .{ .loc = func.name.loc, .op = .len, .operand = args[0] } };
            try self.emit_expr(&u);
            return true;
        }
        if (std.mem.eql(u8, name, "assert")) {
            self.p("lua_assert(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(", ", .{});
            if (args.len > 1) {
                self.p("lua_to_str(", .{});
                try self.emit_as_lua_value(args[1]);
                self.p(")", .{});
            } else {
                self.p("NULL", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "require") or std.mem.eql(u8, name, "req")) {
            // Don't intercept req/require if the user defined their own function.
            var name_buf: [256]u8 = undefined;
            const mangled = self.mangled_name(name, &name_buf);
            if (self.func_bodies.contains(mangled)) {
                return false; // Let the normal call path handle it
            }
            self.p("lua_require(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "select")) {
            const n = if (args.len > 1) args.len - 1 else 0;
            if (result_rt.is_integer() and args.len > 0 and args[0].* == .quoted and
                std.mem.eql(u8, args[0].quoted.val, "#") and !self.args_contain_vararg(args[1..]))
            {
                self.p("{d}", .{n});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_select_v(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", {d}", .{n});
            var i: usize = 1;
            while (i < args.len) : (i += 1) {
                self.p(", ", .{});
                try self.emit_as_lua_value(args[i]);
            }
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "error")) {
            try self.emit_fatal_error(if (args.len > 0) args[0] else null);
            return true;
        } else if (std.mem.eql(u8, name, "pcall")) {
            const want_bool = result_rt == .bool;
            var coerced = false;
            if (!want_bool) {
                coerced = self.emit_lua_result_coerce_prefix(result_rt);
            }
            if (args.len > 2) {
                self.p("{s}({d}, (lua_Value[]){{", .{ if (want_bool) "lua_pcall_argv_bool" else "lua_pcall_argv_fn", args.len });
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    try self.emit_as_lua_value(arg);
                }
                self.p("}})", .{});
            } else {
                self.p("{s}(", .{if (want_bool) "lua_pcall_bool" else "lua_pcall"});
                if (args.len > 0) {
                    try self.emit_as_lua_value(args[0]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(", ", .{});
                if (args.len > 1) {
                    try self.emit_as_lua_value(args[1]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
                self.p(")", .{});
            }
            if (coerced) {
                self.emit_lua_result_coerce_suffix(result_rt);
            }
            return true;
        } else if (std.mem.eql(u8, name, "next")) {
            self.p("lua_next(", .{});
            if (args.len > 0) {
                try self.emit_as_lua_value(args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(", ", .{});
            if (args.len > 1) {
                try self.emit_as_lua_value(args[1]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "unpack")) {
            self.p("lua_tbl_unpack(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "setmetatable")) {
            self.p("lua_setmetatable(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "getmetatable")) {
            self.p("lua_getmetatable(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawget")) {
            self.p("lua_rawget(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawset")) {
            self.p("lua_rawset(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawlen")) {
            if (result_rt.is_integer()) {
                if (args.len > 0 and args[0].* == .quoted) {
                    self.p("{d}", .{args[0].quoted.val.len});
                    return true;
                }
                if (args.len > 0 and self.expr_type(args[0]) == .str) {
                    self.p("((int64_t)strlen(", .{});
                    try self.emit_expr(args[0]);
                    self.p("))", .{});
                    return true;
                }
                self.p("lua_rawlen_i64(", .{});
            } else {
                const coerced = self.emit_lua_result_coerce_prefix(result_rt);
                self.p("lua_rawlen(", .{});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p(")", .{});
                if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
                return true;
            }
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "rawequal")) {
            if (result_rt == .bool) {
                self.p("({{ lua_Value _duo_a = ", .{});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p("; lua_Value _duo_b = ", .{});
                if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
                self.p("; lua_raweq_value(_duo_a, _duo_b); }})", .{});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_rawequal(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "collectgarbage")) {
            if (args.len == 0 and (result_rt == .f64 or result_rt == .f32)) {
                self.p("({{ duo_run_gc_finalizers(); 0.0; }})", .{});
                return true;
            }
            if (args.len > 0 and args[0].* == .quoted) {
                const opt = args[0].quoted.val;
                if ((result_rt == .f64 or result_rt == .f32) and std.mem.eql(u8, opt, "count")) {
                    self.p("((double)duo_gc_kbytes)", .{});
                    return true;
                }
                if ((result_rt == .f64 or result_rt == .f32) and std.mem.eql(u8, opt, "collect")) {
                    self.p("({{ duo_run_gc_finalizers(); 0.0; }})", .{});
                    return true;
                }
                if (result_rt == .bool and (std.mem.eql(u8, opt, "stop") or std.mem.eql(u8, opt, "restart"))) {
                    self.p("true", .{});
                    return true;
                }
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("lua_collectgarbage(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "warn")) {
            self.p("lua_warn(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "xpcall")) {
            const want_bool = result_rt == .bool;
            var coerced = false;
            if (!want_bool) {
                coerced = self.emit_lua_result_coerce_prefix(result_rt);
            }
            if (args.len > 3) {
                self.p("{s}({d}, (lua_Value[]){{", .{ if (want_bool) "lua_xpcall_argv_bool" else "lua_xpcall_argv_fn", args.len });
                for (args, 0..) |arg, i| {
                    if (i > 0) self.p(", ", .{});
                    try self.emit_as_lua_value(arg);
                }
                self.p("}})", .{});
            } else {
                self.p("{s}(", .{if (want_bool) "lua_xpcall_bool" else "lua_xpcall"});
                if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
                self.p(", ", .{});
                if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
                self.p(", ", .{});
                if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
                self.p(")", .{});
            }
            if (coerced) {
                self.emit_lua_result_coerce_suffix(result_rt);
            }
            return true;
        } else if (std.mem.eql(u8, name, "load")) {
            self.p("lua_load(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 3) try self.emit_as_lua_value(args[3]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "loadfile")) {
            self.p("lua_loadfile(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 1) try self.emit_as_lua_value(args[1]) else self.p("lua_val_nil()", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "dofile")) {
            self.p("lua_dofile(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "tostring")) {
            if (args.len > 0) {
                if (self.expr_enum_name(args[0])) |enum_name| {
                    if (self.enum_has_derive(enum_name, "Display") and self.enum_is_payload_free(enum_name)) {
                        if (result_rt == .any) self.p("lua_val_lit(", .{});
                        self.p("duo_{s}_to_string(", .{enum_name});
                        try self.emit_expr(args[0]);
                        self.p(")", .{});
                        if (result_rt == .any) self.p(")", .{});
                        return true;
                    }
                }
            }
            // `tostring` / `to(str)` in a full-native module: there is no
            // `lua_Value` to box into and no `tostring`/`lua_to_str` declared,
            // so emit the plain-C conversion instead of a call that cannot link.
            if (!self.moduleNeedsLuaRuntime()) {
                if (args.len > 0) {
                    try self.emit_native_display_cstr(args[0]);
                } else {
                    self.p("\"nil\"", .{});
                }
                return true;
            }
            const want_cstr = result_rt == .str;
            if (want_cstr) self.p("lua_to_str(", .{});
            self.p("tostring(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (want_cstr) self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "tonumber")) {
            // `tonumber(s, base)` is a DIFFERENT conversion from `tonumber(s)`:
            // it reads `s` as an unsigned-radix integer literal. Every branch
            // below is single-argument, and the fallback used to emit
            // `tonumber(s)` and drop the base on the floor — so `tonumber("ff",
            // 16)` decoded as decimal and produced 0. Route the two-argument
            // form to its own runtime helper before any of them can claim it.
            if (args.len >= 2) {
                const coerced_base = self.emit_lua_result_coerce_prefix(result_rt);
                self.p("tonumber_base(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(", ", .{});
                try self.emit_as_lua_value(args[1]);
                self.p(")", .{});
                if (coerced_base) self.emit_lua_result_coerce_suffix(result_rt);
                return true;
            }
            if (!self.moduleNeedsLuaRuntime() and args.len == 1 and self.expr_type(args[0]) == .str) {
                if (result_rt.is_integer()) self.p("((int64_t)(", .{});
                self.p("strtod(", .{});
                try self.emit_expr(args[0]);
                self.p(", NULL)", .{});
                if (result_rt.is_integer()) self.p(")", .{});
                return true;
            }
            if ((result_rt == .f64 or result_rt == .f32) and args.len == 1) {
                const at = self.expr_type(args[0]);
                if (at.is_numeric()) {
                    if (at.is_integer()) self.p("(double)(", .{});
                    try self.emit_expr(args[0]);
                    if (at.is_integer()) self.p(")", .{});
                    return true;
                }
                self.p("lua_to_num(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(")", .{});
                return true;
            }
            const coerced = self.emit_lua_result_coerce_prefix(result_rt);
            self.p("tonumber(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
            return true;
        } else if (std.mem.eql(u8, name, "pairs")) {
            self.p("lua_pairs(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "ipairs")) {
            self.p("lua_ipairs(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, name, "type")) {
            if (result_rt == .str and args.len == 1) {
                if (self.known_lua_type_name_without_eval(args[0])) |type_name| {
                    self.p("\"{s}\"", .{type_name});
                    return true;
                }
            }
            const want_cstr = result_rt == .str;
            if (want_cstr) self.p("lua_to_str(", .{});
            self.p("type(", .{});
            if (args.len > 0) try self.emit_as_lua_value(args[0]) else self.p("lua_val_nil()", .{});
            self.p(")", .{});
            if (want_cstr) self.p(")", .{});
            return true;
        }
        return false;
    }

    fn known_lua_type_name_without_eval(self: *CodeGen, expr: *const ast.Expr) ?[]const u8 {
        return switch (expr.*) {
            .nil => "nil",
            .true_lit, .false_lit => "boolean",
            .int_lit, .float_lit => "number",
            // GAP-145 `law.text.byte`: `type()` names a member of the Lua
            // kingdom and a byte sequence is not one. The `.name` arm two
            // lines down already answers this correctly -- it asks the
            // DESCRIPTOR and declines to fold when the answer is not str,
            // numeric or bool -- while this arm read the NODE and answered
            // "string" for every quote face, including the one whose element
            // descriptor is `byte`. Declining is the same mechanism reached by
            // asking the producer's quote instead of the syntax, and it hands
            // the question to the runtime `type()` below rather than inventing
            // a name here.
            .quoted => |lit| if (ast.quotedLiteralIsByteSequence(lit.quote)) null else "string",
            .name => |name| blk: {
                if (is_runtime_global(name.ident)) break :blk null;
                const rt = self.expr_type(expr);
                if (rt.is_numeric()) break :blk "number";
                if (rt == .bool) break :blk "boolean";
                if (rt == .str) break :blk "string";
                break :blk null;
            },
            else => null,
        };
    }

    fn args_contain_vararg(_: *CodeGen, args: []*ast.Expr) bool {
        for (args) |arg| {
            if (arg.* == .vararg) return true;
        }
        return false;
    }

    fn expr_is_native_cstr(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .quoted => true,
            .name => self.expr_type(e) == .str,
            // `env(k)` lowers to `getenv(k)`, which IS a `const char*`. Without
            // this arm every consumer wrapped it in `lua_to_str(...)` — a
            // function a no-lua translation unit never declares.
            .index => self.env_projection_key(e) != null or
                (self.expr_type(e) == .str and (self.is_native_dense_module_index(e.index.obj) or
                    self.req_module_dense_index_info(e.index.obj) != null)),
            // A typed call returning str lowers to a native `const char*` when
            // the module uses native lowering (native_scalar_mode or module
            // knowledge >= native). In that mode emit directly; otherwise the
            // call may still return a boxed value.
            .call => blk: {
                if (self.infer_req_module_call_return_type(e)) |rt| {
                    if (rt == .str) break :blk true;
                }
                if (self.expr_type(e) != .str) break :blk false;
                if (self.moduleUsesFullNativeLowering()) break :blk true;
                if (self.current_func_name) |name| break :blk self.funcUsesNativeLowering(name);
                break :blk false;
            },
            // Receiver face of the same fact. `s:sub(a, b)` lowers to
            // `duo_str_sub_cstr(...)`, which ALREADY returns `const char*`, but
            // without this arm the comparison path treated it as boxed and
            // wrapped it — `strcmp(lua_to_str(duo_str_sub_cstr(...)), "…")`,
            // a name a full-native module never declares, with an
            // int-to-pointer error behind it. Same shape and same cause as the
            // `to(i64)` defect gap[081] is about: the operation-first spelling
            // of a fact was taught to the emitter and the subject-first one was
            // not. When the two faces disagree, authors write the one that
            // builds, and the census reads as taste.
            .method_call => blk: {
                if (self.expr_type(e) != .str) break :blk false;
                if (self.moduleUsesFullNativeLowering()) break :blk true;
                if (self.current_func_name) |name| break :blk self.funcUsesNativeLowering(name);
                break :blk false;
            },
            // `a or b` / `a and b` yield an OPERAND, not a truth value, so the
            // result is a `const char*` exactly when both arms are — which is
            // what `try_emit_native_str_and_or` emits. Without this arm the
            // comparison path wrapped that statement-expression in
            // `lua_to_str(...)`, a name a no-lua translation unit never
            // declares, so `env(k) or fallback` compared against a literal was
            // a hard C error. The mirror of the arm `dnir_lower.exprIsStr`
            // carries for the same two operators.
            .binop => |bb| switch (bb.op) {
                .@"and", .@"or" => self.expr_is_native_cstr(bb.lhs) and
                    self.expr_is_native_cstr(bb.rhs),
                // `a .. b` of native-cstr operands lowers through
                // `try_emit_native_str_concat` to `duo_str_concat(...)`,
                // which returns `char*` — the concat IS a native cstr
                // exactly when every collected part is, which is the same
                // condition that emitter tests. Without this arm a concat
                // argument reached statement position (`os.execute("mkdir -p "
                // .. dest_dir)` in lib/tar.id) and `emit_cstr_arg` wrapped it
                // in `lua_to_str(duo_str_concat(...))` — an undeclared name
                // in a no-lua `--lib` unit, then `-Wint-conversion` handing
                // its int to `system`. Bound concats never saw this because
                // the binding path notes the local `.str` first.
                .concat => self.concat_tree_is_native_cstr(e),
                else => false,
            },
            else => false,
        };
    }

    /// Emit `strcmp(lhs, rhs)` where a native operand emits directly as
    /// `const char*` and a dynamic operand is unwrapped via `lua_to_str`.
    /// Shared by ==/!=/< etc. string comparison paths (no boxed dispatch).
    fn emitStrCompareOperands(
        self: *CodeGen,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lhs_c: bool,
        rhs_c: bool,
    ) !void {
        self.p("strcmp(", .{});
        if (lhs_c) {
            try self.emit_expr(lhs);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(lhs);
            self.p(")", .{});
        }
        self.p(", ", .{});
        if (rhs_c) {
            try self.emit_expr(rhs);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(rhs);
            self.p(")", .{});
        }
        self.p(")", .{});
    }

    fn emitTextContainsOperand(self: *CodeGen, value: *const ast.Expr, native_cstr: bool) !void {
        if (native_cstr) {
            try self.emit_expr(value);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(value);
            self.p(")", .{});
        }
    }

    fn expr_is_raw_c_intrinsic(_: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .name) return false;
        const name = e.call.func.name.ident;
        return std.mem.eql(u8, name, "__emit") or
            std.mem.eql(u8, name, "__c_call") or
            std.mem.eql(u8, name, "__as") or
            std.mem.eql(u8, name, "__as_type") or
            std.mem.eql(u8, name, "__sizeof") or
            std.mem.eql(u8, name, "__alignof") or
            std.mem.eql(u8, name, "__offsetof") or
            std.mem.eql(u8, name, "__bitcast") or
            std.mem.eql(u8, name, "__volatile");
    }

    fn expr_is_recognized_stdlib_module(self: *CodeGen, name: []const u8) bool {
        _ = self;
        const modules = [_][]const u8{
            "math",      "string", "table", "io",  "os",  "utf8",   "debug",
            "coroutine", "jit",    "ffi",   "net", "mem", "atomic", "fmt",
            "package",
        };
        for (modules) |m| {
            if (std.mem.eql(u8, name, m)) return true;
        }
        return false;
    }

    /// True when `emit_expr(e)` produces a pointer into a boxed lua_String
    /// (whose length header duo_str_len_hdr can read): generic lua_Value-emitting
    /// exprs coerced via lua_to_str, or recognized stdlib string-module calls
    /// (string.char/sub/rep/...) that lower through lua_str_* and are unwrapped
    /// with lua_to_str. Plain native strings (concat, params, native calls,
    /// literals) are NOT lua_String-backed.
    fn expr_is_boxed_string_ptr(self: *CodeGen, e: *const ast.Expr) bool {
        if (self.expr_emits_lua_value(e)) return true;
        if (e.* != .call or e.call.func.* != .field) return false;
        const f = e.call.func.field;
        if (f.obj.* != .name or !self.expr_is_recognized_stdlib_module(f.obj.name.ident)) return false;
        // ... EXCEPT when that stdlib string call is itself lowered natively.
        // string.rep/sub/lower/upper/reverse have native emitters that return a
        // bare malloc'd char* with no lua_String in front of it, so reading the
        // header off one is an out-of-bounds read of whatever the allocator left
        // 8 bytes earlier. `string.len(string.rep("b", 3))` returned 0, and the
        // benchmark's str_chain row returned a DIFFERENT wrong total on every
        // run (17641902 / 17642000 against C's 5027500).
        if (self.stdlib_string_call_emits_native_cstr(e)) return false;
        return self.expr_type(e) == .str;
    }

    /// True when a `string.*` call is lowered by try_emit_native_string_call /
    /// try_emit_native_string_transform to a plain `char*` (duo_str_rep,
    /// duo_str_sub_cstr, duo_str_{lower,upper,reverse}_cstr) rather than through
    /// lua_str_* unwrapped with lua_to_str. Mirrors the admission conditions in
    /// those two emitters; keep the two in step.
    fn stdlib_string_call_emits_native_cstr(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .field) return false;
        const f = e.call.func.field;
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "string")) return false;
        if (self.expr_type(e) != .str) return false;
        const args = e.call.args;
        if (std.mem.eql(u8, f.field, "rep")) {
            if (args.len < 2 or args.len > 3) return false;
            const pat_t = self.expr_type(args[0]);
            const cnt_t = self.expr_type(args[1]);
            return (pat_t == .str or args[0].* == .quoted) and cnt_t.is_integer();
        }
        if (std.mem.eql(u8, f.field, "lower") or std.mem.eql(u8, f.field, "upper") or
            std.mem.eql(u8, f.field, "reverse")) return args.len == 1;
        if (std.mem.eql(u8, f.field, "sub")) return args.len >= 2 and args.len <= 3;
        // `string.char` joined that family when it got a native arm, and was not
        // registered here. The header read was then applied to a plain literal:
        // `string.len(string.char(0))` emitted `duo_str_len_hdr("\000")`, which
        // ran off the front of a .rodata literal (0 on the native backend) and
        // did not even compile under --backend=c, where duo_str_len_hdr is not
        // declared in a module that carries no boxed runtime.
        if (std.mem.eql(u8, f.field, "char")) return self.native_char_arm_admits(args, .str);
        return false;
    }

    /// The admission test for the native `string.char(n)` arm in
    /// try_emit_native_string_call, factored out so the emitter and the two
    /// predicates that must agree with it cannot drift apart again.
    ///
    /// When it admits, the arm emits EXACTLY ONE BYTE: a folded one-character C
    /// literal, or `duo_str_char_cstr`, which writes `code & 0xFF` and a
    /// terminator. So the byte length is 1 for every code — INCLUDING 0, which
    /// is the case NUL termination cannot report and which `strlen` reads as 0.
    fn native_char_arm_admits(self: *CodeGen, args: []const *ast.Expr, result_rt: RT) bool {
        if (args.len != 1 or result_rt != .str) return false;
        if (self.moduleNeedsLuaRuntime()) return false;
        if (args[0].* == .int_lit) return true;
        return self.expr_type(args[0]).is_integer();
    }

    /// Byte length of `e` when it is a `string.char(n)` application that the
    /// native arm will lower, else null. Always 1 — see native_char_arm_admits.
    fn native_char_call_byte_len(self: *CodeGen, e: *const ast.Expr) ?usize {
        if (e.* != .call or e.call.func.* != .field) return null;
        const f = e.call.func.field;
        if (!std.mem.eql(u8, f.field, "char")) return null;
        // `string.char` only. `utf8.char` is a DIFFERENT relation with a
        // different answer (it encodes, so it is 1..4 bytes), and it is routed
        // elsewhere; it must never pick up this constant.
        if (f.obj.* != .name or !std.mem.eql(u8, f.obj.name.ident, "string")) return null;
        if (!self.native_char_arm_admits(e.call.args, self.expr_type(e))) return null;
        return 1;
    }

    fn expr_emits_lua_value(self: *CodeGen, e: *const ast.Expr) bool {
        if (self.expr_is_raw_c_intrinsic(e)) return false;
        // Field-call on any-typed object goes through lua_invoke -> returns lua_Value
        // regardless of what expr_type resolved the return type to (from function signatures).
        // Exception: recognized stdlib module calls (string.*, table.*, io.*, math.*, etc.)
        // go through emit_boxed_runtime_call which applies coercion -> native C.
        if (e.* == .call and e.call.func.* == .field and
            self.expr_type(e.call.func.field.obj) == .any and
            !(e.call.func.field.obj.* == .name and
                self.expr_is_recognized_stdlib_module(e.call.func.field.obj.name.ident)))
        {
            // A call through a req-module binding lowers to a direct C call
            // returning a native value, not a lua_Value — same exception as the
            // recognized stdlib modules above. Claiming otherwise makes callers
            // wrap it in lua_to_num(), which does not accept an int64_t.
            // gap[100] part 1, third site. The receiver test that used to guard
            // this — `.name` bound in `req_module_bindings` — is redundant now
            // that `infer_req_module_call_return_type` answers for BOTH
            // spellings: it returns null unless the call really does resolve to
            // a module function, so asking it directly is both simpler and
            // correct for the ambient path. With the guard in place the ambient
            // call folded to a native symbol and was still reported as emitting
            // a lua_Value, so `print` wrapped it —
            // `lua_to_str(std_compiler_symbol__root("q"))` — which is the very
            // failure the comment above warns about, one spelling over.
            if (self.infer_req_module_call_return_type(e)) |crt| {
                if (crt != .any and self.type_lowers_native(crt)) return false;
            }
            return true;
        }
        if (self.expr_type(e) == .any) {
            // Binops on dynamic table field reads produce native C values
            // (e.g. lua_table_get_str_num returns double), not lua_Value.
            if (e.* == .binop) {
                if (self.expr_is_dynamic_table_field(e.binop.lhs) or
                    self.expr_is_dynamic_table_field(e.binop.rhs))
                    return false;
                if (self.dynamic_binop_operand_is_safe_native_unbox(e.binop.lhs) and
                    self.dynamic_binop_operand_is_safe_native_unbox(e.binop.rhs))
                    return false;
                if (e.binop.lhs.* == .binop and !self.expr_emits_lua_value(e.binop.lhs)) return false;
                if (e.binop.rhs.* == .binop and !self.expr_emits_lua_value(e.binop.rhs)) return false;
            }
            // Dynamic table field reads (lua_table_get_str_num/cstr/bool) return native C types.
            if (self.expr_is_dynamic_table_field(e)) return false;
            // Native math calls (math.sqrt etc.) emit native C (sqrt), not lua_Value.
            if (e.* == .call and e.call.func.* == .field and
                e.call.func.field.obj.* == .name and
                std.mem.eql(u8, e.call.func.field.obj.name.ident, "math"))
                return false;
            return true;
        }
        return false;
    }

    fn emit_mem_size_arg(self: *CodeGen, args: []*ast.Expr, index: usize, fallback: []const u8) E!void {
        if (index >= args.len) {
            self.p("{s}", .{fallback});
            return;
        }
        self.p("(size_t)(", .{});
        if (self.expr_type(args[index]) == .any and !self.expr_is_raw_c_intrinsic(args[index])) {
            self.p("lua_to_num(", .{});
            try self.emit_as_lua_value(args[index]);
            self.p(")", .{});
        } else {
            try self.emit_expr(args[index]);
        }
        self.p(")", .{});
    }

    fn emit_mem_integer_arg(self: *CodeGen, args: []*ast.Expr, index: usize, fallback: []const u8) E!void {
        if (index >= args.len) {
            self.p("{s}", .{fallback});
            return;
        }
        if (self.expr_type(args[index]) == .any and !self.expr_is_raw_c_intrinsic(args[index])) {
            self.p("(int64_t)lua_to_num(", .{});
            try self.emit_as_lua_value(args[index]);
            self.p(")", .{});
        } else {
            try self.emit_expr(args[index]);
        }
    }

    fn emit_mem_ptr_arg(self: *CodeGen, args: []*ast.Expr, index: usize, is_const: bool) E!void {
        self.p("({s}void*)(", .{if (is_const) "const " else ""});
        if (index < args.len) try self.emit_expr(args[index]) else self.p("NULL", .{});
        self.p(")", .{});
    }

    fn emit_mem_value_as(self: *CodeGen, arg: *ast.Expr, rt: RT) E!void {
        const at = self.expr_type(arg);
        if (at == .any and !self.expr_is_raw_c_intrinsic(arg)) {
            if (rt == .bool) {
                self.p("lua_to_bool(", .{});
                try self.emit_as_lua_value(arg);
                self.p(")", .{});
                return;
            }
            if (rt == .str) {
                self.p("lua_to_str(", .{});
                try self.emit_as_lua_value(arg);
                self.p(")", .{});
                return;
            }
            if (rt.is_numeric()) {
                var buf: [64]u8 = undefined;
                self.p("({s})lua_to_num(", .{rt.c_type(&buf)});
                try self.emit_as_lua_value(arg);
                self.p(")", .{});
                return;
            }
        }
        try self.emit_expr(arg);
    }

    fn emit_time_arg(self: *CodeGen, arg: *const ast.Expr) E!void {
        const rt = self.expr_type(arg);
        if (rt.is_numeric()) {
            try self.emit_expr(arg);
        } else {
            self.p("lua_to_num(", .{});
            try self.emit_as_lua_value(arg);
            self.p(")", .{});
        }
    }

    fn emit_cstr_arg(self: *CodeGen, arg: *const ast.Expr) E!void {
        if (self.expr_is_native_cstr(arg)) {
            try self.emit_expr(arg);
        } else {
            self.p("lua_to_str(", .{});
            try self.emit_as_lua_value(arg);
            self.p(")", .{});
        }
    }

    fn maybe_emit_mem_call(self: *CodeGen, func: *const ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        // LAW-STRATA (spec 4.2): every application group is single-kind —
        // descriptor/semantic parameters never share a group with runtime
        // operands. The canonical spelling is `mem.store(i32)(p, v)`, never
        // `mem.store(i32, p, v)`; the curry boundary IS the specialization
        // boundary, visibly. Splice the descriptor group back onto the operand
        // group so the existing lowering serves the canonical form.
        if (func.* == .call and func.call.args.len == 1 and func.call.func.* != .call) {
            const inner = func.call;
            var buf: [8]*ast.Expr = undefined;
            if (args.len + 1 <= buf.len) {
                buf[0] = inner.args[0];
                for (args, 0..) |a, i| buf[i + 1] = a;
                return try self.maybe_emit_mem_call(inner.func, buf[0 .. args.len + 1], result_rt);
            }
        }
        // Canonical curried form: `mem.store("i64")(ptr, val)`. A type selector
        // is its own curry level and must never share a parameter list with
        // values (§2.6 application schemas; idiom 2, operation-first
        // invocation). Normalize `f(type)(rest…)` to the flat `f(type, rest…)`
        // vector the emitters below already take, so both spellings lower
        // identically and the canonical one costs nothing.
        if (func.* == .call) {
            const inner = func.call;
            if (self.mem_intrinsic_name(inner.func) != null and inner.args.len == 1) {
                var joined: std.ArrayList(*ast.Expr) = .empty;
                defer joined.deinit(self.alloc);
                try joined.append(self.alloc, inner.args[0]);
                try joined.appendSlice(self.alloc, args);
                return try self.maybe_emit_mem_call(inner.func, joined.items, result_rt);
            }
        }
        const fname = self.mem_intrinsic_name(func) orelse return false;

        if (std.mem.eql(u8, fname, "alloc")) {
            try self.guardNoAlloc("mem.alloc");
            self.p("((uint8_t*)malloc(", .{});
            try self.emit_mem_size_arg(args, 0, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "calloc")) {
            try self.guardNoAlloc("mem.calloc");
            self.p("((uint8_t*)calloc(", .{});
            try self.emit_mem_size_arg(args, 0, "0");
            self.p(", ", .{});
            try self.emit_mem_size_arg(args, 1, "1");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "realloc")) {
            try self.guardNoAlloc("mem.realloc");
            self.p("((", .{});
            self.typ(result_rt);
            self.p(")realloc(", .{});
            try self.emit_mem_ptr_arg(args, 0, false);
            self.p(", ", .{});
            try self.emit_mem_size_arg(args, 1, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "free")) {
            self.p("free(", .{});
            try self.emit_mem_ptr_arg(args, 0, false);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "cast") or std.mem.eql(u8, fname, "ptr_cast")) {
            const target = if (result_rt == .pointer) result_rt else self.mem_call_result_type(func, args) orelse (self.mem_pointer_to(.void) orelse result_rt);
            self.p("((", .{});
            self.typ(target);
            self.p(")(void*)(", .{});
            if (args.len > 1) try self.emit_expr(args[1]) else self.p("NULL", .{});
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "ptr_from_addr") or std.mem.eql(u8, fname, "ptrfromaddr")) {
            const target = if (result_rt == .pointer) result_rt else self.mem_call_result_type(func, args) orelse (self.mem_pointer_to(.void) orelse result_rt);
            self.p("((", .{});
            self.typ(target);
            self.p(")(uintptr_t)(", .{});
            try self.emit_mem_integer_arg(args, 1, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "addr")) {
            self.p("((uint64_t)(uintptr_t)(", .{});
            if (args.len > 0) try self.emit_expr(args[0]) else self.p("NULL", .{});
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "add")) {
            self.p("((", .{});
            if (args.len > 0) try self.emit_expr(args[0]) else self.p("NULL", .{});
            self.p(") + (ptrdiff_t)(", .{});
            try self.emit_mem_integer_arg(args, 1, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "byte_add")) {
            self.p("((uint8_t*)(void*)(", .{});
            if (args.len > 0) try self.emit_expr(args[0]) else self.p("NULL", .{});
            self.p(") + (ptrdiff_t)(", .{});
            try self.emit_mem_integer_arg(args, 1, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "load") or std.mem.eql(u8, fname, "volatile_load")) {
            const rt = self.mem_type_arg(args, 0) orelse result_rt;
            self.p("(*(", .{});
            if (std.mem.eql(u8, fname, "volatile_load")) self.p("volatile ", .{});
            self.typ(rt);
            self.p("*)", .{});
            try self.emit_mem_ptr_arg(args, 1, false);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "store") or std.mem.eql(u8, fname, "volatile_store")) {
            const rt = self.mem_type_arg(args, 0) orelse .u8;
            self.p("(*(", .{});
            if (std.mem.eql(u8, fname, "volatile_store")) self.p("volatile ", .{});
            self.typ(rt);
            self.p("*)", .{});
            try self.emit_mem_ptr_arg(args, 1, false);
            self.p(" = (", .{});
            self.typ(rt);
            self.p(")(", .{});
            if (args.len > 2) try self.emit_mem_value_as(args[2], rt) else self.p("0", .{});
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "copy") or std.mem.eql(u8, fname, "move")) {
            self.p("{s}(", .{if (std.mem.eql(u8, fname, "copy")) "memcpy" else "memmove"});
            try self.emit_mem_ptr_arg(args, 0, false);
            self.p(", ", .{});
            try self.emit_mem_ptr_arg(args, 1, true);
            self.p(", ", .{});
            try self.emit_mem_size_arg(args, 2, "0");
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "set")) {
            self.p("memset(", .{});
            try self.emit_mem_ptr_arg(args, 0, false);
            self.p(", (int)(", .{});
            try self.emit_mem_integer_arg(args, 1, "0");
            self.p("), ", .{});
            try self.emit_mem_size_arg(args, 2, "0");
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "zero")) {
            self.p("memset(", .{});
            try self.emit_mem_ptr_arg(args, 0, false);
            self.p(", 0, ", .{});
            try self.emit_mem_size_arg(args, 1, "0");
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "compare")) {
            self.p("((int64_t)memcmp(", .{});
            try self.emit_mem_ptr_arg(args, 0, true);
            self.p(", ", .{});
            try self.emit_mem_ptr_arg(args, 1, true);
            self.p(", ", .{});
            try self.emit_mem_size_arg(args, 2, "0");
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "sizeof") or std.mem.eql(u8, fname, "alignof")) {
            const rt = self.mem_type_arg(args, 0) orelse .u8;
            self.p("((uint64_t){s}(", .{if (std.mem.eql(u8, fname, "sizeof")) "sizeof" else "__alignof__"});
            self.typ(rt);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "is_null")) {
            self.p("((", .{});
            if (args.len > 0) try self.emit_expr(args[0]) else self.p("NULL", .{});
            self.p(") == NULL)", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fence")) {
            self.p("__sync_synchronize()", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "compiler_fence")) {
            self.p("({{ __asm__ __volatile__(\"\" ::: \"memory\"); }})", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "prefetch")) {
            self.p("__builtin_prefetch(", .{});
            try self.emit_mem_ptr_arg(args, 0, true);
            self.p(", ", .{});
            try self.emit_mem_integer_arg(args, 1, "0");
            self.p(", ", .{});
            try self.emit_mem_integer_arg(args, 2, "3");
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "assume")) {
            self.p("__builtin_assume(", .{});
            if (args.len > 0) {
                try self.emit_lua_truthy_expr(args[0]);
            } else {
