            self.p("), (const double*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[2]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "matmul_f32") and args.len >= 6) {
            self.p("duo_simd_matmul_f32((const float*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const float*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (float*)(", .{});
            try self.emit_expr(args[2]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[3]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[4]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[5]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "matmul_f64") and args.len >= 6) {
            self.p("duo_simd_matmul_f64((const double*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const double*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (double*)(", .{});
            try self.emit_expr(args[2]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[3]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[4]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[5]);
            self.p("))", .{});
            return true;
        }
        return false;
    }

    /// True when `e` is the `tonumber(s) or fallback` form that
    /// `try_emit_native_tonumber_or` lowers to a native strtod statement
    /// expression. Callers must not wrap such an expression in `lua_to_num()`:
    /// it already yields a `double`, and the full-native profile that selects
    /// this lowering never declares `lua_to_num`.
    fn expr_is_native_tonumber_or(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .binop) return false;
        const b = e.binop;
        if (b.op != .@"or" or self.moduleNeedsLuaRuntime()) return false;
        if (b.lhs.* != .call or b.lhs.call.func.* != .name) return false;
        if (!std.mem.eql(u8, b.lhs.call.func.name.ident, "tonumber")) return false;
        if (b.lhs.call.args.len != 1 or self.expr_type(b.lhs.call.args[0]) != .str) return false;
        return true;
    }

    fn try_emit_native_tonumber_or(self: *CodeGen, b: anytype) E!bool {
        if (b.op != .@"or" or self.moduleNeedsLuaRuntime()) return false;
        if (b.lhs.* != .call or b.lhs.call.func.* != .name) return false;
        if (!std.mem.eql(u8, b.lhs.call.func.name.ident, "tonumber")) return false;
        if (b.lhs.call.args.len != 1 or self.expr_type(b.lhs.call.args[0]) != .str) return false;
        self.p("({{ const char* _duo_s = ", .{});
        try self.emit_expr(b.lhs.call.args[0]);
        self.p("; char* _duo_ep; double _duo_v = strtod(_duo_s, &_duo_ep); (_duo_ep == _duo_s) ? (", .{});
        try self.emit_expr(b.rhs);
        self.p(") : _duo_v; }})", .{});
        return true;
    }

    fn try_emit_native_string_transform(self: *CodeGen, fname: []const u8, obj: *ast.Expr, args: []*ast.Expr, result_rt: RT) E!bool {
        if (result_rt != .str) return false;
        if (std.mem.eql(u8, fname, "lower") or std.mem.eql(u8, fname, "upper") or
            std.mem.eql(u8, fname, "reverse") or std.mem.eql(u8, fname, "trim"))
        {
            if (args.len != 0) return false;
            self.p("duo_str_{s}_cstr(", .{fname});
            try self.emit_mem_value_as(obj, .str);
            self.p(")", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "sub")) {
            if (args.len == 0 or args.len > 2) return false;
            self.p("duo_str_sub_cstr(", .{});
            try self.emit_mem_value_as(obj, .str);
            self.p(", ", .{});
            self.p("(int64_t)(", .{});
            try self.emit_mem_value_as(args[0], .i64);
            self.p(")", .{});
            if (args.len > 1) {
                self.p(", ", .{});
                self.p("(int64_t)(", .{});
                try self.emit_mem_value_as(args[1], .i64);
                self.p(")", .{});
            } else {
                self.p(", INT64_MAX", .{});
            }
            self.p(")", .{});
            return true;
        }
        return false;
    }

    fn try_emit_native_string_call(self: *CodeGen, fname: []const u8, args: []*ast.Expr, result_rt: RT) E!bool {
        if (std.mem.eql(u8, fname, "len")) {
            if (args.len == 0) return false;
            if (args[0].* == .quoted) {
                self.p("{d}", .{args[0].quoted.val.len});
                return true;
            }
            // A length KNOWN AT COMPILE TIME is emitted as that number, and NUL
            // termination never enters the question. This is what makes
            // `string.len(string.char(0))` answer 1 — Wasm opcode 0x00 is one
            // byte long, and a loader that reads it as an empty string stops
            // decoding. Neither `strlen` (0) nor a header read on a native
            // char* (garbage) can answer it.
            if (self.native_char_call_byte_len(args[0])) |n| {
                self.p("{d}", .{n});
                return true;
            }
            if (self.expr_type(args[0]) == .str) {
                // Boxed strings (lua_to_str(...) of a boxed value or a recognized
                // stdlib string call) carry a lua_String header whose len
                // duo_str_len_hdr reads directly. Plain native strings (concat
                // results, params, native calls, literals) are NOT lua_String-
                // backed — reading the header reads garbage, so use strlen.
                const is_boxed = self.expr_is_boxed_string_ptr(args[0]);
                if (result_rt.is_numeric()) {
                    var buf: [64]u8 = undefined;
                    self.p("(({s}){s}(", .{ result_rt.c_type(&buf), if (is_boxed) "duo_str_len_hdr" else "strlen" });
                } else {
                    self.p("((int64_t){s}(", .{if (is_boxed) "duo_str_len_hdr" else "strlen"});
                }
                try self.emit_expr(args[0]);
                self.p("))", .{});
                return true;
            }
            if (result_rt.is_integer()) {
                var buf: [64]u8 = undefined;
                self.p("(({s})lua_str_byte_len(", .{result_rt.c_type(&buf)});
                try self.emit_as_lua_value(args[0]);
                self.p("))", .{});
                return true;
            }
            return false;
        }
        if (std.mem.eql(u8, fname, "byte")) {
            if (args.len < 2) return false;
            if (args[0].* == .quoted and args[1].* == .int_lit) {
                const s = args[0].quoted.val;
                const idx = args[1].int_lit.val;
                if (idx >= 1 and idx <= @as(i64, @intCast(s.len)))
                    self.p("{d}", .{@as(i64, s[@intCast(idx - 1)])})
                else
                    self.p("0", .{});
                return true;
            }
            if (self.expr_type(args[0]) == .str and self.expr_type(args[1]).is_integer()) {
                var buf: [64]u8 = undefined;
                const cast_rt = if (result_rt.is_numeric()) result_rt else RT.i64;
                self.p("(({s})(unsigned char)(", .{cast_rt.c_type(&buf)});
                try self.emit_expr(args[0]);
                self.p("[", .{});
                try self.emit_expr(args[1]);
                self.p(" - 1]))", .{});
                return true;
            }
            if (result_rt.is_integer()) {
                var buf: [64]u8 = undefined;
                self.p("(({s})", .{result_rt.c_type(&buf)});
                self.p("lua_str_byte_i64(", .{});
                try self.emit_as_lua_value(args[0]);
                self.p(", ", .{});
                try self.emit_as_lua_value(args[1]);
                self.p(", ", .{});
                if (args.len > 2) try self.emit_as_lua_value(args[2]) else self.p("lua_val_nil()", .{});
                self.p("))", .{});
                return true;
            }
            return false;
        }
        // `string.char(n)` / `n:char()`. Both faces arrive here — the
        // subject-first spelling is rebuilt into this one by
        // tryEmitSubjectHomeFace — so there is a single lowering to be right or
        // wrong about. A literal folds; anything else with an integer argument
        // takes the native helper. Without this arm the native-scalar precheck
        // admitted the call and the emitter then reached for `lua_str_char` in a
        // module that has no Lua runtime.
        if (std.mem.eql(u8, fname, "char") and result_rt == .str and args.len == 1) {
            // ONLY when the module has no Lua runtime. A native string is a
            // NUL-terminated `char*`, so it cannot carry `char(0)` — and
            // `string.len(string.char(0))` must answer 1, because that is Wasm
            // opcode 0x00 and a loader that reads it as an empty string stops
            // decoding. Where the boxed runtime exists, `lua_str_char` plus the
            // header-length read already gets that right and keeps it; this arm
            // exists only for the modules where reaching for `lua_str_char`
            // named an undeclared function. Same reason the rest of the
            // `duo_str_*_cstr` family is confined to that mode.
            if (self.moduleNeedsLuaRuntime()) return false;
            if (args[0].* == .int_lit) {
                const code = args[0].int_lit.val;
                if (code >= 0 and code <= 255) {
                    const byte: u8 = @intCast(code);
                    // A one-byte literal: printable ASCII goes through verbatim,
                    // everything else through an octal escape, so a quote, a
                    // backslash or a NUL cannot end the literal early.
                    if (byte >= 32 and byte < 127 and byte != '"' and byte != '\\') {
                        self.p("\"{c}\"", .{byte});
                    } else {
                        self.p("\"\\{o:0>3}\"", .{byte});
                    }
                    return true;
                }
            }
            if (self.expr_type(args[0]).is_integer()) {
                self.p("duo_str_char_cstr((int64_t)(", .{});
                try self.emit_expr(args[0]);
                self.p("))", .{});
                return true;
            }
            return false;
        }
        if ((std.mem.eql(u8, fname, "starts_with") or std.mem.eql(u8, fname, "ends_with")) and
            result_rt == .bool and args.len == 2)
        {
            return try self.try_emit_native_string_affix(fname, args[0], args[1]);
        }
        if (std.mem.eql(u8, fname, "rep") and result_rt == .str) {
            if (args.len < 2 or args.len > 3) return false;
            const pat_t = self.expr_type(args[0]);
            const cnt_t = self.expr_type(args[1]);
            if ((pat_t == .str or args[0].* == .quoted) and cnt_t.is_integer()) {
                self.p("duo_str_rep(", .{});
                try self.emit_expr(args[0]);
                self.p(", ", .{});
                try self.emit_expr(args[1]);
                self.p(")", .{});
                return true;
            }
            return false;
        }
        if (args.len > 0) {
            if (try self.try_emit_native_string_transform(fname, args[0], args[1..], result_rt)) return true;
        }
        return false;
    }

    fn utf8_literal_len(s: []const u8) i64 {
        var len: i64 = 0;
        for (s) |c| {
            if ((c & 0xC0) != 0x80) len += 1;
        }
        return len;
    }

    fn try_emit_native_utf8_len(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 1) return false;
        if (args[0].* == .quoted) {
            self.p("{d}", .{utf8_literal_len(args[0].quoted.val)});
            return true;
        }
        if (self.expr_type(args[0]) == .str) {
            self.p("({{ const unsigned char* _duo_s = (const unsigned char*)(", .{});
            try self.emit_expr(args[0]);
            self.p("); int64_t _duo_len = 0; while (*_duo_s) {{ if ((*_duo_s & 0xC0) != 0x80) _duo_len++; _duo_s++; }} _duo_len; }})", .{});
            return true;
        }
        return false;
    }

    fn try_emit_native_string_affix(self: *CodeGen, fname: []const u8, s_expr: *const ast.Expr, part_expr: *const ast.Expr) E!bool {
        if (!self.expr_is_native_cstr(s_expr) or !self.expr_is_native_cstr(part_expr)) return false;
        const is_suffix = std.mem.eql(u8, fname, "ends_with");
        if (!is_suffix and !std.mem.eql(u8, fname, "starts_with")) return false;

        self.p("({{ const char* _duo_s = ", .{});
        try self.emit_expr(s_expr);
        self.p("; const char* _duo_part = ", .{});
        try self.emit_expr(part_expr);
        self.p("; size_t _duo_slen = strlen(_duo_s); size_t _duo_plen = strlen(_duo_part); _duo_plen <= _duo_slen && memcmp(", .{});
        if (is_suffix) {
            self.p("_duo_s + _duo_slen - _duo_plen", .{});
        } else {
            self.p("_duo_s", .{});
        }
        self.p(", _duo_part, _duo_plen) == 0; }})", .{});
        return true;
    }

    // The result-coercion pair unwraps a boxed runtime call's `lua_Value`
    // result back into a native place — the SAME scalar→coercion-wrapper fact
    // `emit_lua_value_coercion_start`/`_end` already read off the one owner
    // `types.luaCoerceClass`. It stood here as a fourth statement of that fact:
    // a per-tag switch listing `str`/`bool` and every numeric scalar spelling,
    // with a nominal descriptor (a `.struct` tag) and `any` falling to `else`
    // and emitting no wrapper. `luaCoerceClass` withholds the nominal on purpose
    // (`law.nominal` §46 — it is an identity, not a representation) and returns
    // null for `any` (already a `lua_Value`, coerced by identity), so the
    // `orelse` here reproduces the retired `else` arm exactly. A scalar identity
    // added to the union now gains its coercion wrapper here rather than
    // silently taking the box-less tail.
    fn emit_lua_result_coerce_prefix(self: *CodeGen, result_rt: RT) bool {
        const cls = types.luaCoerceClass(result_rt) orelse return false;
        var buf: [160]u8 = undefined;
        self.p("{s}", .{cls.open(&buf)});
        return true;
    }

    fn emit_lua_result_coerce_suffix(self: *CodeGen, result_rt: RT) void {
        const cls = types.luaCoerceClass(result_rt) orelse return;
        self.p("{s}", .{cls.close()});
    }

    fn emit_boxed_runtime_call(self: *CodeGen, mapped: []const u8, args: []*ast.Expr, expected: usize, result_rt: RT) E!void {
        const coerced = self.emit_lua_result_coerce_prefix(result_rt);
        self.p("{s}(", .{mapped});
        var i: usize = 0;
        while (i < expected) : (i += 1) {
            if (i > 0) self.p(", ", .{});
            if (i < args.len) {
                try self.emit_as_lua_value(args[i]);
            } else {
                self.p("lua_val_nil()", .{});
            }
        }
        self.p(")", .{});
        if (coerced) self.emit_lua_result_coerce_suffix(result_rt);
    }

    fn expr_is_dynamic_table_field(self: *CodeGen, e: *const ast.Expr) bool {
        return e.* == .field and self.expr_is_dynamic_table(e.field.obj);
    }

    /// `a(i) = v` — the RETIRED index-assign spelling, in PLACE position.
    ///
    /// CURRENT LAW: `[]` is computed projection and `()` is ordinary
    /// application. `a(i)` as an index is RETIRED — the direct-native path
    /// refuses it (`DNB001 assign-target` on a write, `DNB011
    /// unresolved-application-facts` on a read) and `src/pretty.zig` no longer
    /// rewrites `a[i]` into it. This function survives only so that the retired
    /// AST/Lua backend can still lower legacy sources that were written under
    /// the old ruling (762e2bff, which had canonicalized 6065 -> 2804 sites the
    /// other way); nothing generates the spelling any more.
    ///
    /// `src/table_apply.zig` converges the READ back onto
    /// `.index`. It converts nothing in place position that its two
    /// recognizers cannot see: `calleeIsArray` needs sema to have resolved the
    /// callee to `.array`, and `nameIsPositionalTable` needs a bare name bound
    /// to an ALL-POSITIONAL, NON-EMPTY table literal. So `xs = {}` (empty, and
    /// therefore marked callable and disqualified) and `self._bufs` (a field,
    /// which neither recognizer accepts at all) stayed `.call` — and a `.call`
    /// place fell through `emit_lvalue` to `emit_expr`, emitting
    /// `({ … lua_invoke(__fn, 1, duo_args); }) = v` and
    /// "error: expression is not assignable". Measured: `xs = {} / xs(1) = "A"`
    /// refused on BOTH backends while `xs[1] = "A"` — the canonical spelling —
    /// ran, and
    /// `lib/mem.id` could not be `req`d at all because its arena and pool
    /// allocators write `self._bufs(self._bufs:len() + 1) = new_buf`.
    ///
    /// NOTHING WORKING CAN REGRESS HERE. A `.call` in place position is a hard
    /// C compile error today, in every shape, so any lowering is strictly an
    /// improvement — this is not the silent-wrong-answer trade `table_apply`
    /// declines to make on the READ side, where a genuine call would be
    /// converted into an index. A DECLARED RELATION is still refused, so
    /// `foo(1) = 2` keeps its diagnostic rather than becoming a no-op store.
    fn try_emit_call_form_index_assign(
        self: *CodeGen,
        tgt: *const ast.Expr,
        val: ?*const ast.Expr,
    ) E!bool {
        if (tgt.* != .call) return false;
        const c = &tgt.call;
        if (c.args.len != 1) return false;
        if (c.func.* == .name) {
            var tbuf: [256]u8 = undefined;
            if (self.func_decls.get(c.func.name.ident) != null) return false;
            if (self.func_decls.get(self.mangled_name(c.func.name.ident, &tbuf)) != null) return false;
        }
        if (!self.expr_is_dynamic_table(c.func)) return false;
        const key = c.args[0];
        if (positive_int_key(key)) |k| {
            self.p("lua_table_set_i64(", .{});
            try self.emit_expr(c.func);
            self.p(", {d}, ", .{k});
        } else if (self.is_integer_key(key)) {
            self.p("lua_table_set_i64(", .{});
            try self.emit_expr(c.func);
            self.p(", ", .{});
            try self.emit_i64_index_key(key);
            self.p(", ", .{});
        } else {
            self.p("lua_table_set(", .{});
            try self.emit_expr(c.func);
            self.p(", ", .{});
            try self.emit_as_lua_value(key);
            self.p(", ", .{});
        }
        if (val) |v| try self.emit_as_lua_value(v) else self.p("lua_val_nil()", .{});
        self.p(");\n", .{});
        return true;
    }

    fn try_emit_native_net_send(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 2) return false;
        if (!self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        if (!self.expr_is_native_cstr(args[1])) return false;

        self.p("((int64_t)send((int)(", .{});
        try self.emit_expr(args[0]);
        self.p("), ", .{});
        try self.emit_expr(args[1]);
        self.p(", ", .{});
        if (args[1].* == .quoted) {
            self.p("{d}", .{args[1].quoted.val.len});
        } else {
            self.p("strlen(", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
        }
        self.p(", 0))", .{});
        return true;
    }

    fn try_emit_native_net_close(self: *CodeGen, args: []*ast.Expr) E!bool {
        if (args.len != 1 or !self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        self.p("close((int)(", .{});
        try self.emit_expr(args[0]);
        self.p("))", .{});
        return true;
    }

    fn try_emit_native_net_udp_sendto(self: *CodeGen, args: []*ast.Expr, result_rt: RT) E!bool {
        if (!result_rt.is_integer() or args.len != 4) return false;
        if (!self.expr_type(args[0]).is_integer()) return false;
        if (self.expr_is_dynamic_table_field(args[0])) return false;
        if (!self.expr_is_native_cstr(args[1])) return false;
        if (!self.expr_is_native_cstr(args[2])) return false;
        if (!self.expr_type(args[3]).is_integer()) return false;

        self.p("duo_net_udp_sendto_native((int64_t)(", .{});
        try self.emit_expr(args[0]);
        self.p("), ", .{});
        try self.emit_expr(args[1]);
        self.p(", ", .{});
        if (args[1].* == .quoted) {
            self.p("{d}", .{args[1].quoted.val.len});
        } else {
            self.p("strlen(", .{});
            try self.emit_expr(args[1]);
            self.p(")", .{});
        }
        self.p(", ", .{});
        try self.emit_expr(args[2]);
        self.p(", (int64_t)(", .{});
        try self.emit_expr(args[3]);
        self.p("))", .{});
        return true;
    }

    fn try_emit_math_fast_call(self: *CodeGen, fname: []const u8, args: []*ast.Expr, result_rt: RT) E!bool {
        var buf: [64]u8 = undefined;
        const ct = result_rt.c_type(&buf);

        if (std.mem.eql(u8, fname, "fast_popcount") and args.len == 1) {
            self.p("((int64_t)__builtin_popcountll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_clz") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 64 : (int64_t)__builtin_clzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_ctz") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 64 : (int64_t)__builtin_ctzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "fast_bit_length") and args.len == 1) {
            self.p("((", .{});
            self.p("{s}", .{ct});
            self.p(")(", .{});
            try self.emit_expr(args[0]);
            self.p(") == 0 ? 0 : 64 - (int64_t)__builtin_clzll((unsigned long long)(", .{});
            try self.emit_expr(args[0]);
            self.p(")))", .{});
            return true;
        }
