// ── Tests ─────────────────────────────────────────────────────────────────

const testing = std.testing;

test "native scalar eligibility is source-law independent and resets refusal evidence" {
    var type_map = sema.TypeMap.init(testing.allocator);
    defer type_map.deinit();

    var first = CodeGen.init(testing.allocator, undefined, &type_map, null, undefined, 0, null, null);
    var second = CodeGen.init(testing.allocator, undefined, &type_map, null, undefined, 0, null, null);
    first.nativeDiagFail("first");
    second.nativeDiagFailFmt("second:{d}", .{2});

    var first_buf: [64]u8 = undefined;
    var second_buf: [64]u8 = undefined;
    try testing.expectEqualStrings("first", first.nativeScalarReason(&first_buf).?);
    try testing.expectEqualStrings("second:2", second.nativeScalarReason(&second_buf).?);

    const module: ast.Module = .{
        .file = "test.id",
        .body = .{
            .loc = .{ .file = "test.id", .line = 1, .col = 1 },
            .stmts = &.{},
        },
    };
    try testing.expect(first.can_emit_native_scalar_module(&module));
    try testing.expect(first.nativeScalarReason(&first_buf) == null);
    try testing.expectEqualStrings("second:2", second.nativeScalarReason(&second_buf).?);
}

test "source law preserves floored integer relations while facts select the runtime" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const fixtures = [_]struct {
        path: []const u8,
        law: lexer_bridge.SourceLaw,
        source: []const u8,
        full_native: bool,
        floor_helpers: bool,
    }{
        .{
            .path = "fixture.lua",
            .law = .lua,
            .source =
            \\local counter: i64 = 0
            \\
            \\local function evaluate(): i64
            \\    counter = counter + 1
            \\    return (-7 % 2) + (7 % -2) + (-7 // 2) + (7 // -2) + counter
            \\end
            \\
            \\function main(): i64
            \\    return 0
            \\end
            \\
            \\print(evaluate())
            ,
            .full_native = true,
            .floor_helpers = true,
        },
        .{
            .path = "fixture.id",
            .law = .idol,
            .source =
            \\counter: i64 = 0
            \\
            \\evaluate: i64 = ()
            \\  counter = counter + 1
            \\  (-7 % 2) + (7 % -2) + (-7 // 2) + (7 // -2) + counter
            \\
            \\main: i64 = ()
            \\  print("{evaluate()}\n")
            \\  0
            ,
            .full_native = true,
            .floor_helpers = true,
        },
        .{
            .path = "fixture.lua",
            .law = .lua,
            .source =
            \\local counter: i64 = 0
            \\
            \\local function bump(value: any): any
            \\    counter = counter + 1
            \\    return value
            \\end
            \\
            \\function main(): i64
            \\    return counter + 1
            \\end
            \\
            \\print(bump(main()))
            ,
            .full_native = false,
            .floor_helpers = false,
        },
    };

    for (fixtures) |fixture| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const alloc = arena.allocator();
        var lex = Lexer.initFacts(fixture.source, fixture.path, lexer_bridge.sourceFacts(fixture.path));
        try testing.expect(routeEmbedThroughDuoLexer(alloc, &lex, fixture.source, fixture.path));
        try testing.expectEqual(fixture.law, lex.source_law);
        var parser = Parser.init(&lex, alloc);
        parser.idol_mode = lex.family == lexer_bridge.family_canon;
        try testing.expectEqual(fixture.law == .idol, parser.idol_mode);
        var module = try parser.parse_module();
        var semantic = sema.Sema.init(alloc);
        defer semantic.deinit();
        semantic.lua55_mode = lex.source_law == .lua;
        semantic.idol_mode = lex.source_law == .idol;
        try semantic.check_module(&module);

        var aw: std.Io.Writer.Allocating = .init(alloc);
        defer aw.deinit();
        var cg = CodeGen.init(alloc, std.testing.io, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
        cg.src_path = fixture.path;
        cg.idol_mode = lex.source_law == .idol;
        try cg.emit_module(&module);
        try testing.expectEqual(fixture.full_native, cg.usesFullNativeLowering());
        try testing.expectEqual(fixture.full_native, std.mem.indexOf(u8, aw.written(), "lua_Value") == null);
        if (fixture.floor_helpers) {
            try testing.expect(std.mem.indexOf(u8, aw.written(), "lua_idiv_i64") != null);
            try testing.expect(std.mem.indexOf(u8, aw.written(), "lua_imod_i64") != null);
        }
    }
}

const HelperDemandFixture = struct {
    output: []u8,
    split: bool,
    fstream: bool,
};

fn emitHelperDemandFixture(alloc: std.mem.Allocator, source: []const u8) !HelperDemandFixture {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const held = arena.allocator();
    var lex = Lexer.initFacts(source, "helper.id", lexer_bridge.sourceFacts("helper.id"));
    try testing.expect(routeEmbedThroughDuoLexer(held, &lex, source, "helper.id"));
    var parser = Parser.init(&lex, held);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(held);
    defer semantic.deinit();
    semantic.idol_mode = true;
    try semantic.check_module(&module);
    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(held, std.testing.io, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    cg.src_path = "helper.id";
    cg.idol_mode = true;
    // These are library fixtures: mirror the production `dump-c --lib` route
    // whose generated helper prelude the regression is asserting.
    cg.lib_mode = true;
    cg.checked_sema = &semantic;
    cg.foreign_records = &semantic.foreign_records;
    cg.foreign_functions = &semantic.foreign_functions;
    const split = cg.block_needs_native_helper(module.body, .split);
    const fstream = cg.block_needs_native_helper(module.body, .fstream);
    try cg.emit_module(&module);
    return .{
        .output = try alloc.dupe(u8, aw.written()),
        .split = split,
        .fstream = fstream,
    };
}

test "codegen: native helper prelude follows exact module demand" {
    const alloc = testing.allocator;
    const plain = try emitHelperDemandFixture(alloc,
        \\answer: i64 = ()
        \\    42
    );
    defer alloc.free(plain.output);
    try testing.expect(!plain.split);
    try testing.expect(!plain.fstream);
    try testing.expect(std.mem.indexOf(u8, plain.output, "duo_str_split_cstr") == null);
    try testing.expect(std.mem.indexOf(u8, plain.output, "duo_fstream_readline") == null);
    try testing.expect(std.mem.indexOf(u8, plain.output, "_DUO_popen") == null);

    const split = try emitHelperDemandFixture(alloc,
        \\lines: i64 = (text: str)
        \\    parts = text:split("\\n")
        \\    n: i64 = parts:len()
        \\    if n > 0
        \\        last: str = parts[n]
        \\        if last == ""
        \\            n -= 1
        \\    n
    );
    defer alloc.free(split.output);
    try testing.expect(split.split);
    try testing.expect(!split.fstream);
    // This minimal sample is scanner-only: native precheck names
    // method-unresolved:split. The real full-native positive emission is the
    // byte-identity Tree-sitter projection exercised by its projection gate.
    try testing.expect(std.mem.indexOf(u8, split.output, "duo_str_split_cstr") == null);
    try testing.expect(std.mem.indexOf(u8, split.output, "duo_fstream_readline") == null);

    const defaults = try emitHelperDemandFixture(alloc,
        \\count: i64 = (parts: any = "a,b":split(","))
        \\    parts:len()
    );
    defer alloc.free(defaults.output);
    try testing.expect(defaults.split);
    try testing.expect(!defaults.fstream);

    const nested_open = try emitHelperDemandFixture(alloc,
        \\identity: any = (value: any)
        \\    value
        \\
        \\open: any = (path: str)
        \\    identity(io.open(path, "r"))
    );
    defer alloc.free(nested_open.output);
    // The outer call scans every argument; its inner io.open call must remain
    // a load-bearing fstream demand even though the field is not the outer
    // callee. This is a scanner fact independent of the module realization.
    try testing.expect(nested_open.fstream);
    try testing.expect(!nested_open.split);

    const process = try emitHelperDemandFixture(alloc,
        \\capture: str = (command: str)
        \\    stream = io.popen(command, "r")
        \\    if stream == nil
        \\        return ""
        \\    line = stream:read()
        \\    stream:close()
        \\    line
    );
    defer alloc.free(process.output);
    try testing.expect(process.fstream);
    try testing.expect(!process.split);
    try testing.expect(std.mem.indexOf(u8, process.output, "duo_fstream_readline") != null);
    try testing.expect(std.mem.indexOf(u8, process.output, "_DUO_popen") != null);
    try testing.expect(std.mem.indexOf(u8, process.output, "duo_str_split_cstr") == null);
}

test "codegen: boxed io handles keep boxed representation and stream dispatch" {
    const alloc = testing.allocator;
    const boxed = try emitHelperDemandFixture(alloc,
        \\slurp: str = (path: str)
        \\    f = io.open(path, "r")
        \\    body: str = ""
        \\    if f
        \\        body = f:read("a")
        \\        f:close()
        \\    body
        \\
        \\slurp("/tmp/idol-boxed-handle")
    );
    defer alloc.free(boxed.output);
    try testing.expect(std.mem.indexOf(u8, boxed.output, "lua_Value f = lua_io_open(") != null);
    try testing.expect(std.mem.indexOf(u8, boxed.output, "lua_file_read_method(f,") != null);
    try testing.expect(std.mem.indexOf(u8, boxed.output, "void* f = lua_io_open(") == null);
    try testing.expect(std.mem.indexOf(u8, boxed.output, "f__read(") == null);
}

