test "runtime: DUO_POLL enum is defined" {
    // emitPollEnum writes this; verify it would be compatible with the runtime.
    // The poll enum is NOT in duo_runtime itself but emitted separately when
    // async functions are present. Verify the naming convention is consistent.
    const needle = "DUO_POLL_PENDING";
    // Poll enum is emitted by emitPollEnum, not embedded in duo_runtime.
    // Verify via the async_lower module instead.
    const AsyncLower = @import("async_lower.zig");
    var aw: std.Io.Writer.Allocating = .init(testing.allocator);
    defer aw.deinit();
    try AsyncLower.AsyncLower.emitPollEnum(&aw.writer);
    try testing.expect(std.mem.indexOf(u8, aw.written(), needle) != null);
}

test "runtime: async frame step function returns DUO_POLL_PENDING or READY" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const Sema = @import("sema.zig").Sema;
    const AsyncLower = @import("async_lower.zig");

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init("async fun f() -> i64\n  return 1\nend", "test");
    var p = Parser.init(&lex, alloc);
    var mod = try p.parse_module();
    var s = Sema.init(alloc);
    try s.check_module(&mod);

    var al = AsyncLower.AsyncLower.init(alloc, &s.type_map);
    defer al.deinit();
    try al.run(&mod);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    try AsyncLower.AsyncLower.emitStepFunc(&al.getAll()[0], &aw.writer);
    try testing.expect(std.mem.indexOf(u8, aw.written(), "DUO_POLL_READY") != null);
}

test "codegen: async declarations remain directly callable while emitting frames" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const Sema = @import("sema.zig").Sema;
    const AsyncLower = @import("async_lower.zig");

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\async fun answer(): i64
        \\    return 42
        \\end
        \\print(answer())
    , "test");
    var p = Parser.init(&lex, alloc);
    var mod = try p.parse_module();
    var s = Sema.init(alloc);
    defer s.deinit();
    try s.check_module(&mod);

    var al = AsyncLower.AsyncLower.init(alloc, &s.type_map);
    defer al.deinit();
    try al.run(&mod);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &s.type_map, &s.module_globals, &aw.writer, s.next_closure_id, &s.table_field_types, &s.concepts);
    cg.async_lower = &al;
    try cg.emit_module(&mod);
    const output = aw.written();

    try testing.expect(std.mem.indexOf(u8, output, "static inline int64_t answer(void);") != null);
    try testing.expect(std.mem.indexOf(u8, output, "static inline int64_t answer(void)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "printf(\"%lld\\n\", answer());") != null);
    try testing.expect(std.mem.indexOf(u8, output, "typedef struct duo_frame_answer_") != null);
    try testing.expect(std.mem.indexOf(u8, output, "static duo_Poll duo_step_answer_") != null);
}

test "codegen: generic specialization calls use typed argument coercion" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    const Sema = @import("sema.zig").Sema;

    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    var lex = Lexer.init(
        \\fun pick<T>(fallback: T, value: T): T
        \\    value
        \\end
        \\print(pick(1.5, 2))
    , "test");
    var p = Parser.init(&lex, alloc);
    var mod = try p.parse_module();
    var s = Sema.init(alloc);
    defer s.deinit();
    try s.check_module(&mod);

    var mono_pass = mono.Monomorphizer.init(alloc, &s.type_map);
    defer mono_pass.deinit();
    try mono_pass.run(&mod);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &s.type_map, &s.module_globals, &aw.writer, s.next_closure_id, &s.table_field_types, &s.concepts);
    cg.mono = &mono_pass;
    try cg.emit_module(&mod);
    const output = aw.written();

    try testing.expect(std.mem.indexOf(u8, output, "static inline double duo_pick_f64(double fallback, double value)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_pick_f64(1.5e0, (double)(2))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_val_from_num((double)(2))") == null);
}

