test "codegen: typed string buffer len lowers to native i64" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\local buf = string.buffer.new()
        \\buf:put("duo")
        \\local n: i64 = buf:len()
        \\print(n)
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();
    // `lua_any_len_i64`, not `lua_str_buf_len_i64`: the receiver's static type
    // here is `any`, which covers string, table AND str-buf, and the str-buf
    // face answers 0 for the other two. Emitting it unconditionally is what
    // made a wasm loader whose guard is `bytes:len() < 8` reject every module
    // as bad magic. What this test is FOR is unchanged and is carried by the
    // two negatives below — the binding is a native `int64_t`, with no boxed
    // value and no `lua_to_num` round-trip. The positive names whichever helper
    // currently answers; it is the lowering's shape that is pinned, not the
    // spelling of a helper that turned out to be the wrong one.
    try testing.expect(std.mem.indexOf(u8, output, "int64_t n = lua_any_len_i64(buf);") != null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_Value n = ") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_num(lua_str_buf_len(") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_num(lua_any_len(") == null);
}

test "codegen: typed global builtins unbox boxed runtime results" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\local kind: str = type({})
        \\local num_kind: str = type(42)
        \\local bool_kind: str = type(true)
        \\local str_kind: str = type("duo")
        \\local nil_kind: str = type(nil)
        \\local text: str = tostring(42)
        \\local num: f64 = tonumber("42")
        \\local native_num: f64 = 42.0
        \\local native_cast: f64 = tonumber(native_num)
        \\local len: i64 = rawlen({1, 2, 3})
        \\local s: str = "duo"
        \\local slen: i64 = rawlen(s)
        \\local lit_len: i64 = rawlen("language")
        \\local same: bool = rawequal("x", "x")
        \\local ok: bool = pcall(function() 1)
        \\local xok: bool = xpcall(function() 1, function(e) e)
        \\print(kind, num_kind, bool_kind, str_kind, nil_kind, text, num, native_cast, len, slen, lit_len, same, ok, xok)
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();
    try testing.expect(std.mem.indexOf(u8, output, "const char* kind = lua_to_str(type(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* num_kind = \"number\";") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* bool_kind = \"boolean\";") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* str_kind = \"string\";") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* nil_kind = \"nil\";") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* text = lua_to_str(tostring(") != null);
    // `tonumber` is a CONVERSION THAT CAN FAIL, and `builtin_return_type` types
    // it `.any` for exactly that reason (see its comment): it answers nil for a
    // string that is not a complete numeral. This test used to require
    // `double num = lua_to_num(lua_val_from_literal("42"` — the old fold that
    // bypassed `tonumber` entirely and converted the literal directly — and to
    // FORBID `lua_to_num(tonumber(`. Under that rule `tonumber("abc")` became 0
    // before any caller could test it, which is the defect the `.any` typing
    // fixed. So the two rows below assert the current law, and the negative row
    // that forbade the correct lowering is gone.
    //
    // Verified by value, not by shape: `tonumber("42")` prints 42,
    // `tonumber(42.0)` prints 42, and `tonumber("abc") or -1.0` prints -1 —
    // the nil survives, which is the whole point.
