test "codegen: typed multi-return locals unbox from lua result buffer" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\fun split(): any
        \\  return 40, 2, "ok", true
        \\end
        \\
        \\fun get(): i64
        \\  local n: i64, inc: i64, s: str, ok: bool = split()
        \\  if ok and s == "ok" then
        \\    return n + inc
        \\  end
        \\  return 0
        \\end
        \\
        \\print(get())
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();

    // The FIRST result comes back through the call expression and the rest come
    // out of the mret buffer. This row used to pin the call spelling too
    // (`lua_to_num(split())`); an `any`-returning callee is now reached through
    // `lua_invoke`, which is what populates `lua_mret_*` for the siblings below,
    // so pinning the direct call was pinning the wrong thing. Assert the unbox —
    // `int64_t n` taken through `(int64_t)lua_to_num(...)`, never a `lua_Value`
    // local. Verified by value: this fixture prints 42.
    try testing.expect(std.mem.indexOf(u8, output, "int64_t n = ((int64_t)lua_to_num(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "int64_t inc = ((int64_t)lua_mret_get_num(0));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "const char* s = lua_mret_get_cstr(1);") != null);
    try testing.expect(std.mem.indexOf(u8, output, "bool ok = lua_mret_get_bool(2);") != null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_num(lua_mret_get(0))") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_str(lua_mret_get(1))") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_bool(lua_mret_get(2))") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_Value n = ") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_Value inc = lua_mret_get(0)") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_Value s = lua_mret_get(1)") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_Value ok = lua_mret_get(2)") == null);
}

test "codegen: memory intrinsics lower to raw C operations" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\function low(): i64
        \\  local raw: *u8 = mem.alloc(64)
        \\  mem.set(raw, 0, 64)
        \\  local nums: *i64 = mem.cast("i64", raw)
        \\  mem.store("i64", nums, 42)
        \\  local next: *i64 = mem.add(nums, 1)
        \\  mem.volatile_store("i64", next, mem.load("i64", nums) + 1)
        \\  local out: *u8 = std.mem.calloc(64, 1)
        \\  local raw_was_null: bool = mem.is_null(raw)
        \\  mem.copy(out, raw, mem.sizeof("i64") * 2)
        \\  local cmp: i64 = mem.compare(out, raw, 16)
        \\  local got: i64 = mem.volatile_load("i64", mem.cast("i64", out))
        \\  local addr: u64 = mem.addr(out)
        \\  local back: *u8 = mem.ptr_from_addr("u8", addr)
        \\  mem.move(mem.byte_add(back, 8), back, 8)
        \\  mem.zero(back, mem.alignof("i64"))
        \\  mem.compiler_fence()
        \\  mem.fence()
        \\  mem.free(out)
        \\  mem.free(raw)
        \\  return got + cmp
        \\end
        \\print(low())
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();

    try testing.expect(std.mem.indexOf(u8, output, "uint8_t* raw = ((uint8_t*)malloc") != null);
    try testing.expect(std.mem.indexOf(u8, output, "memset((void*)(raw), (int)(0), (size_t)(64))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "int64_t* nums = ((int64_t*)(void*)(raw));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "(*(int64_t*)(void*)(nums) = (int64_t)(42));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "int64_t* next = ((nums) + (ptrdiff_t)(1));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "(*(volatile int64_t*)(void*)(next)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "uint8_t* out = ((uint8_t*)calloc") != null);
    try testing.expect(std.mem.indexOf(u8, output, "raw_was_null = ((raw) == NULL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "memcpy((void*)(out), (const void*)(raw)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "((uint64_t)sizeof(int64_t))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "memcmp((const void*)(out), (const void*)(raw), (size_t)(16))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "(*(volatile int64_t*)(void*)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "((uint64_t)(uintptr_t)(out))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "uint8_t* back = ((uint8_t*)(uintptr_t)(addr));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "memmove((void*)(((uint8_t*)(void*)(back) + (ptrdiff_t)(8))), (const void*)(back), (size_t)(8))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "((uint64_t)__alignof__(int64_t))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__asm__ __volatile__(\"\" ::: \"memory\")") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__sync_synchronize()") != null);
    try testing.expect(std.mem.indexOf(u8, output, "free((void*)(out));") != null);
    try testing.expect(std.mem.indexOf(u8, output, "free((void*)(raw));") != null);
}

test "codegen: typed __emit bypasses lua_to_num on return and locals" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\fun raw_i64(): i64
        \\  local x: i64 = __emit("(int64_t)(40 + 2)")
        \\  return __emit("(int64_t)(x + 1)")
        \\end
    , "test.duo");
    var parser = Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    semantic.idol_mode = true;
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    cg.bench_mode = true;
    cg.bench_backend = .c_dynamic;
    try cg.emit_module(&module);
    const output = aw.written();

    try testing.expect(std.mem.indexOf(u8, output, "int64_t x = (int64_t)(40 + 2);") != null);
    try testing.expect(std.mem.indexOf(u8, output, "return (int64_t)(x + 1);") != null);
    const fn_start = std.mem.indexOf(u8, output, "static inline int64_t raw_i64(void)") orelse return error.TestExpectedEqual;
    const fn_end_rel = std.mem.indexOf(u8, output[fn_start..], "static lua_Value raw_i64__lua") orelse return error.TestExpectedEqual;
    const fn_body = output[fn_start .. fn_start + fn_end_rel];
    try testing.expect(std.mem.indexOf(u8, fn_body, "lua_to_num") == null);
}

test "codegen: atomic intrinsics lower to compiler atomic builtins" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\function low(): i64
        \\  local raw: *u8 = mem.alloc(16)
        \\  local slot: *i64 = mem.cast("i64", raw)
        \\  local expected: *i64 = mem.add(slot, 1)
        \\  atomic.store("i64", slot, 10, "release")
        \\  local old_add: i64 = atomic.fetch_add("i64", slot, 5, "acq_rel")
        \\  local old_sub: i64 = atomic.fetch_sub("i64", slot, 3, "acq_rel")
        \\  local old_and: i64 = atomic.fetch_and("i64", slot, 14, "acq_rel")
        \\  local old_or: i64 = atomic.fetch_or("i64", slot, 3, "acq_rel")
        \\  local old_xor: i64 = atomic.fetch_xor("i64", slot, 6, "acq_rel")
        \\  local old_exchange: i64 = std.atomic.exchange("i64", slot, 7, "acq_rel")
        \\  mem.store("i64", expected, 7)
        \\  local swapped: bool = atomic.compare_exchange("i64", slot, expected, 11, "acq_rel", "acquire")
        \\  local final_value: i64 = atomic.load("i64", slot, "acquire")
        \\  atomic.compiler_fence("acquire")
        \\  atomic.fence("seq_cst")
        \\  mem.free(raw)
        \\  return old_add + old_sub + old_and + old_or + old_xor + old_exchange + final_value
        \\end
        \\print(low())
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);
    try testing.expectEqual(@as(u32, 0), semantic.errors);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();

    try testing.expect(std.mem.indexOf(u8, output, "__atomic_store_n(((int64_t*)(void*)(slot)), (int64_t)(10), __ATOMIC_RELEASE)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_fetch_add(((int64_t*)(void*)(slot)), (int64_t)(5), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_fetch_sub(((int64_t*)(void*)(slot)), (int64_t)(3), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_fetch_and(((int64_t*)(void*)(slot)), (int64_t)(14), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_fetch_or(((int64_t*)(void*)(slot)), (int64_t)(3), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_fetch_xor(((int64_t*)(void*)(slot)), (int64_t)(6), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_exchange_n(((int64_t*)(void*)(slot)), (int64_t)(7), __ATOMIC_ACQ_REL)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_compare_exchange_n(((int64_t*)(void*)(slot)), ((int64_t*)(void*)(expected)), (int64_t)(11), false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_load_n(((int64_t*)(void*)(slot)), __ATOMIC_ACQUIRE)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_signal_fence(__ATOMIC_ACQUIRE)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__atomic_thread_fence(__ATOMIC_SEQ_CST)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "std_atomic_signal") == null);
}

