// ── Feature-test macro block ──────────────────────────────────────────────

// The two tests that used to stand here asked NOTHING. Each recomputed the
// emitter's condition inline —
//
//     const emit_xopen = !std.mem.eql(u8, t, "wasm32-wasi");
//     try testing.expect(emit_xopen);
//
// — and then asserted its own arithmetic. They passed while the block they
// named emitted a Darwin-only macro set that made the tracked artifact fail to
// compile on every glibc host, and they would have passed had the block emitted
// nothing at all. That is the failure class `AGENTS.md` records as a control
// that cannot fail, so the repair is not the condition: it is asking the real
// emitter what it wrote, over both arms.
test "emit: the feature-macro block exposes what the runtime it ships calls" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;

    // The DEMAND side, read off the runtime rather than restated. Both of these
    // are hidden by `_XOPEN_SOURCE 600` on glibc, and both are called, so the
    // prologue owes them a macro that reveals them.
    try testing.expect(std.mem.indexOf(u8, duo_runtime, "mkdtemp(") != null);
    try testing.expect(std.mem.indexOf(u8, duo_runtime, "mkstemps(") != null);

    const cases = [_]struct {
        target: []const u8,
        macros: bool,
    }{
        .{ .target = "native", .macros = true },
        .{ .target = "x86_64-linux-gnu", .macros = true },
        .{ .target = "aarch64-macos", .macros = true },
        // wasm32-wasi takes the stub arm instead: wasi-libc has no such
        // surface to reveal, and defining the macros there re-declares it.
        .{ .target = "wasm32-wasi", .macros = false },
    };

    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const alloc = arena.allocator();

        // A Lua-law fixture, because the macro block is emitted exactly when
        // the module is NOT plain native scalar — the arm the tracked lexer
        // artifact takes.
        const source =
            \\local function bump(value: any): any
            \\    return value
            \\end
            \\
            \\print(bump(1))
            \\
        ;
        const path = "fixture.lua";
        var lex = Lexer.initFacts(source, path, lexer_bridge.sourceFacts(path));
        try testing.expect(routeEmbedThroughDuoLexer(alloc, &lex, source, path));
        var parser = Parser.init(&lex, alloc);
        var module = try parser.parse_module();
        var semantic = sema.Sema.init(alloc);
        defer semantic.deinit();
        semantic.lua55_mode = true;
        try semantic.check_module(&module);

        var aw: std.Io.Writer.Allocating = .init(alloc);
        defer aw.deinit();
        var cg = CodeGen.init(alloc, std.testing.io, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
        cg.src_path = path;
        cg.target = case.target;
        try cg.emit_module(&module);
        const emitted = aw.written();

        try testing.expect(std.mem.indexOf(u8, emitted, "lua_Value") != null);
        for ([_][]const u8{
            "#define _XOPEN_SOURCE 600",
            "#define _DEFAULT_SOURCE",
            "#define _DARWIN_C_SOURCE",
        }) |macro| {
            try testing.expectEqual(
                case.macros,
                std.mem.indexOf(u8, emitted, macro) != null,
            );
        }
    }
}

