// The test "gcd specialization emits affine-periodic divisor reduction" was
// here. It required the literal string
// `duo_sum_affine_periodic_gcd_i64(n, 10000, 7, 3)` -- the entire body, one
// call, no loop, with the period, the multiplier and the offset all frozen.
// RELEASE_STATUS.md §4 had already named the row as a fold the classifier's
// ratio only just declined. The emitter is gone.

test "gcd prelude uses coprime affine divisor iteration with fallback" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init("print(1)", "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    cg.bench_mode = true;
    cg.bench_backend = .c_dynamic;
    try cg.emit_module(&module);
    const output = aw.written();
    try testing.expect(std.mem.indexOf(u8, output, "duo_gcd_i64(mul_mod, period) == 1") != null);
    try testing.expect(std.mem.indexOf(u8, output, "for (int64_t divisor = 1; divisor <= period; ++divisor)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "for (int64_t v = divisor; v <= period; v += divisor)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "for (int64_t r = 1; r <= last; ++r)") != null);
}

