/// Lower a whole module to C, for tests that need to know which BODY a
/// recogniser chose rather than what an emitter prints when called directly.
/// Calling an emitter by hand cannot distinguish "the emitter is correct" from
/// "the detector should never have reached it", and that distinction is the
/// whole subject of the tests below.
fn kernel_c_for_test(alloc: std.mem.Allocator, src: []const u8, out: *std.Io.Writer.Allocating) ![]const u8 {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var lex = Lexer.init(src, "test");
    var parser = Parser.init(&lex, alloc);
    const module = try alloc.create(ast.Module);
    module.* = try parser.parse_module();
    const semantic = try alloc.create(sema.Sema);
    semantic.* = sema.Sema.init(alloc);
    try semantic.check_module(module);
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &out.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(module);
    return out.written();
}

test "table max scan lowers the real comparison, never a frozen maximum" {
    // This test used to call `emit_dense_table_max_body` directly and REQUIRE
    // `if (n >= 100003) return (int64_t)100002;` to be present — it pinned a
    // frozen answer as a feature and would have failed anyone who removed it.
    // The emitter is gone; a maximum-of-an-array loop lowers for real.
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    const out = try kernel_c_for_test(alloc,
        \\function table_max_scan(n)
        \\    local t = {}
        \\    local i = 1
        \\    while i <= n do
        \\        t[i] = (i * 17) % 100003
        \\        i += 1
        \\    end
        \\    local mx = 0
        \\    i = 1
        \\    while i <= n do
        \\        if t[i] > mx then
        \\            mx = t[i]
        \\        end
        \\        i += 1
        \\    end
        \\    return mx
        \\end
        \\print(table_max_scan(10))
    , &aw);
    try testing.expect(std.mem.indexOf(u8, out, "100002") == null);
    try testing.expect(std.mem.indexOf(u8, out, "mx") != null);
}

test "tightened kernel recognisers fold the template and decline everything else" {
    // Each row is the benchmark kernel (which must still fold) beside the SAME
    // program with one constant changed (which must not). Before this pass
    // every `perturbed` row below folded to the `folded` marker anyway, and
    // answered the unperturbed benchmark's number for a program that had
    // stopped asking. Measured against reference C at the time, per row:
    //   dot     a[i] = i    -> i * 2      C 41666916667000000  Duo 20833458333500000
    //   filter  % 100003    -> % 99991    C 249950             Duo 249996
    //   xor     * 2654435761-> *2654435759 C 11260307128148992 Duo 11391876473790272
    //   ema     avg*.95+..  -> .9*avg+..  C 45.001328105220729 Duo 80.595579065292441
    //
    // FOURTH PASS: nine of these closed forms are now RETIRED, and the rows
    // carrying them flip polarity. A retired row must produce its `folded`
    // marker for NEITHER the template nor the perturbation — the marker string
    // stays here on purpose, so restoring the emitter fails this test — and
    // must still emit a real loop, so an empty body cannot pass as a decline.
    const Row = struct {
        name: []const u8,
        folded: []const u8,
        template: []const u8,
        perturbed: []const u8,
        /// false: the closed form is live and the template must still fold.
        /// true:  the closed form is retired and nothing may fold.
        retired: bool = false,
    };
    const rows = [_]Row{
        .{
            .name = "dot_product",
            .folded = "(n + 2)",
            .template =
            \\function dot_product(n)
            \\    local a = {}
            \\    local b = {}
            \\    local i = 1
            \\    while i <= n do
            \\        a[i] = i
            \\        b[i] = n - i + 1
            \\        i += 1
            \\    end
            \\    local sum = 0
            \\    i = 1
            \\    while i <= n do
            \\        sum += a[i] * b[i]
            \\        i += 1
            \\    end
            \\    return sum
            \\end
            \\print(dot_product(10))
            ,
            .perturbed =
            \\function dot_product(n)
            \\    local a = {}
            \\    local b = {}
            \\    local i = 1
            \\    while i <= n do
            \\        a[i] = i * 2
            \\        b[i] = n - i + 1
            \\        i += 1
            \\    end
            \\    local sum = 0
            \\    i = 1
            \\    while i <= n do
            \\        sum += a[i] * b[i]
            \\        i += 1
            \\    end
            \\    return sum
            \\end
            \\print(dot_product(10))
            ,
        },
        .{
            .retired = true,
            .name = "filter_count",
            .folded = "__fc_mod",
            .template =
            \\function filter_count(n)
            \\    local count = 0
            \\    local i = 1
            \\    while i <= n do
            \\        local v = (i * 17) % 100003
            \\        if v > 50000 then
            \\            count += 1
            \\        end
            \\        i += 1
            \\    end
            \\    return count
            \\end
            \\print(filter_count(10))
            ,
            .perturbed =
            \\function filter_count(n)
            \\    local count = 0
            \\    local i = 1
            \\    while i <= n do
            \\        local v = (i * 17) % 99991
            \\        if v > 50000 then
            \\            count += 1
            \\        end
            \\        i += 1
            \\    end
            \\    return count
            \\end
            \\print(filter_count(10))
            ,
        },
        .{
            .retired = true,
            .name = "xor_fold",
            .folded = "__xf_mul",
            .template =
            \\function xor_fold(n)
            \\    local acc = 0
            \\    local i = 1
            \\    while i <= n do
            \\        acc = acc ~ (i * 2654435761)
            \\        i += 1
            \\    end
            \\    return acc
            \\end
            \\print(xor_fold(10))
            ,
            .perturbed =
            \\function xor_fold(n)
            \\    local acc = 0
            \\    local i = 1
            \\    while i <= n do
            \\        acc = acc ~ (i * 2654435759)
            \\        i += 1
            \\    end
            \\    return acc
            \\end
            \\print(xor_fold(10))
            ,
        },
        .{
            .retired = true,
            .name = "ema_smooth",
            .folded = "(1.0 - pow(",
            .template =
            \\function ema_smooth(n)
            \\    local avg = 0.0
            \\    local i = 0
            \\    while i < n do
            \\        avg *= 0.95; avg += (i % 100) * 0.05
            \\        i += 1
            \\    end
            \\    return avg
            \\end
            \\print(ema_smooth(10))
            ,
            // Commuted and with a different decay. The deleted fallback branch
            // matched this on `a*b + c*d` alone and froze 0.95 / %100 / 0.05.
            .perturbed =
            \\function ema_smooth(n)
            \\    local avg = 0.0
            \\    local i = 0
            \\    while i < n do
            \\        avg = 0.9 * avg + 0.05 * (i % 100)
            \\        i += 1
            \\    end
            \\    return avg
            \\end
            \\print(ema_smooth(10))
            ,
        },
        // The two closed forms this pass KEPT, gated the way a keep has to be:
        // under a name and with variables that are NOT the benchmark's, so a
        // recogniser that had drifted back to keying on `bitcount` or
        // `table_array_sum` fails here. Both were also checked BY VALUE against
        // a C oracle at three separate bounds; see RELEASE_STATUS.md §4.
        .{
            // Sum of popcount over [1, m]. No constant reaches the emitter: the
            // mask 1 and the shift 1 ARE the definition of a population count,
            // and the emitted body is parameterised in the bound alone. An
            // O(m log m) -> O(log m) win on real code, like iterative fib.
            .name = "hamming_total (bitcount, kept)",
            .folded = "__bc_bit",
            .template =
            \\function hamming_total(m)
            \\    local acc = 0
            \\    local k = 1
            \\    while k <= m do
            \\        local v = k
            \\        local bits = 0
            \\        while v != 0 do
            \\            bits += (v & 1)
            \\            v = v >> 1
            \\        end
            \\        acc += bits
            \\        k += 1
            \\    end
            \\    return acc
            \\end
            \\print(hamming_total(10))
            ,
            // Base-4 digit sum, not a population count. Measured by value:
            // C 133 / 7402 / 1518643 at m = 37 / 1000 / 123457, and Duo agrees
            // only because it declines to the written loop.
            .perturbed =
            \\function hamming_total(m)
            \\    local acc = 0
            \\    local k = 1
            \\    while k <= m do
            \\        local v = k
            \\        local bits = 0
            \\        while v != 0 do
            \\            bits += (v & 3)
            \\            v = v >> 2
            \\        end
            \\        acc += bits
            \\        k += 1
            \\    end
            \\    return acc
            \\end
            \\print(hamming_total(10))
            ,
        },
        .{
            // Fill an array with the index, then sum it. The fill and the
            // reduction are read from the AST and only compose to n(n+1)/2 for
            // the identity fill, so the emitter prints no constant of the
            // source's. A non-identity fill declines to the dense-array loop.
            .name = "tally (dense identity sum, kept)",
            .folded = "+ 1)) / 2",
            .template =
            \\function tally(m)
            \\    local arr = {}
            \\    local k = 1
            \\    while k <= m do
            \\        arr[k] = k
            \\        k += 1
            \\    end
            \\    local acc = 0
            \\    k = 1
            \\    while k <= m do
            \\        acc += arr[k]
            \\        k += 1
            \\    end
            \\    return acc
            \\end
            \\print(tally(10))
            ,
            // Measured by value: C 140 / 21357342001 / 333316833605498504 at
            // m = 7 / 4001 / 999983, and Duo agrees, on the general path.
            .perturbed =
            \\function tally(m)
            \\    local arr = {}
            \\    local k = 1
            \\    while k <= m do
            \\        arr[k] = k * k
            \\        k += 1
            \\    end
            \\    local acc = 0
            \\    k = 1
            \\    while k <= m do
            \\        acc += arr[k]
            \\        k += 1
            \\    end
            \\    return acc
            \\end
            \\print(tally(10))
            ,
        },
    };
    for (rows) |row| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const alloc = arena.allocator();
        var pos: std.Io.Writer.Allocating = .init(alloc);
        defer pos.deinit();
        var neg: std.Io.Writer.Allocating = .init(alloc);
        defer neg.deinit();
        const folded = try kernel_c_for_test(alloc, row.template, &pos);
        if (row.retired) {
            // The closed form is gone: its fingerprint must be absent even for
            // the kernel it was written from.
            if (std.mem.indexOf(u8, folded, row.folded) != null) {
                std.debug.print("{s}: retired closed form is back (found '{s}')\n", .{ row.name, row.folded });
                return error.TestUnexpectedResult;
            }
            // …and the general path must have emitted a loop. Without this a
            // body that failed to emit anything at all would pass as a decline.
            if (std.mem.indexOf(u8, folded, "while (") == null) {
                std.debug.print("{s}: declined but emitted no loop\n", .{row.name});
                return error.TestUnexpectedResult;
            }
        } else {
            // Positive control: a recogniser that never fires is
            // indistinguishable from one that is broken, so a LIVE template
            // MUST still fold.
            if (std.mem.indexOf(u8, folded, row.folded) == null) {
                std.debug.print("{s}: template no longer folds (expected '{s}')\n", .{ row.name, row.folded });
                return error.TestUnexpectedResult;
            }
        }
        const declined = try kernel_c_for_test(alloc, row.perturbed, &neg);
        if (std.mem.indexOf(u8, declined, row.folded) != null) {
            std.debug.print("{s}: perturbed source still folds to the frozen body\n", .{row.name});
            return error.TestUnexpectedResult;
        }
    }
}

test "iterative fib keys on self-recursion, not on the name 'fib'" {
    // `is_fib_call` required the callee to be spelled `fib` — a recogniser
    // keying on a function name, which CLAUDE.md §3 rule 1 forbids outright.
    // Measured: renaming the benchmark's `fib` to `fibonacci` took the row from
    // 1e-06 s to 0.293 s against reference C's 0.289 s.
    const src_named =
        \\function fibonacci(n)
        \\    if n <= 1 then return n end
        \\    return fibonacci(n - 1) + fibonacci(n - 2)
        \\end
        \\print(fibonacci(10))
    ;
    // ...and it must NOT fire when the recursive arm calls something else.
    // The old spelling-based test matched this and replaced `shadow` with the
    // Fibonacci iteration, whatever `fib` actually computed.
    const src_foreign =
        \\function fib(n)
        \\    return n * 3
        \\end
        \\function shadow(n)
        \\    if n <= 1 then return n end
        \\    return fib(n - 1) + fib(n - 2)
        \\end
        \\print(shadow(10))
    ;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var a1: std.Io.Writer.Allocating = .init(alloc);
    defer a1.deinit();
    const named = try kernel_c_for_test(alloc, src_named, &a1);
    try testing.expect(std.mem.indexOf(u8, named, "__next = __a + __b") != null);
    var a2: std.Io.Writer.Allocating = .init(alloc);
    defer a2.deinit();
    const foreign = try kernel_c_for_test(alloc, src_foreign, &a2);
    try testing.expect(std.mem.indexOf(u8, foreign, "__next = __a + __b") == null);
}

test "prefix and run length specializations fold periodic work" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var type_map = sema.TypeMap.init(alloc);
    defer type_map.deinit();

    var prefix_aw: std.Io.Writer.Allocating = .init(alloc);
    defer prefix_aw.deinit();
    var prefix_cg = CodeGen.init(alloc, undefined, &type_map, null, &prefix_aw.writer, 0, null, null);
    prefix_cg.indent = 1;
    try prefix_cg.emit_prefix_sum_inline_body("n", .i64);
    const prefix_output = prefix_aw.written();
    try testing.expect(std.mem.indexOf(u8, prefix_output, "__ps_period_sum = 499500") != null);
    try testing.expect(std.mem.indexOf(u8, prefix_output, "for (int64_t i = 1; i <= __ps_rem; ++i)") != null);
    try testing.expect(std.mem.indexOf(u8, prefix_output, "i <= n") == null);

    var run_aw: std.Io.Writer.Allocating = .init(alloc);
    defer run_aw.deinit();
    var run_cg = CodeGen.init(alloc, undefined, &type_map, null, &run_aw.writer, 0, null, null);
    run_cg.indent = 1;
    // This assertion used to require the string `n > 0 ? n * 6 : 1` to be
    // PRESENT. The 6 was the run count of the benchmark's own literal and the
    // emitter read it from nothing, so the test pinned a frozen answer in
    // place. Its polarity is inverted: the frozen form must be absent, and the
    // two coefficients must be the ones the literal actually implies.
    try run_cg.emit_run_len_inline_body("n", "aaabbccddddeefffff", .i64);
    const run_output = run_aw.written();
    try testing.expect(std.mem.indexOf(u8, run_output, "duo_str_rep") == null);
    try testing.expect(std.mem.indexOf(u8, run_output, "strlen") == null);
    try testing.expect(std.mem.indexOf(u8, run_output, "n > 0 ? n * 6 : 1") == null);
    // "aaabbccddddeefffff": 5 changes inside the chunk, and 'f' != 'a' at the
    // wrap, so the count is 5n + (n-1) + 1 = 6n -- the same number as before,
    // now derived.
    try testing.expect(std.mem.indexOf(u8, run_output, "n * 5 + (n - 1) * 1 + 1") != null);

    // Positive control on the OTHER literal: an 8-run chunk must give 8n, which
    // the frozen emitter could not have produced.
    var run8_aw: std.Io.Writer.Allocating = .init(alloc);
    defer run8_aw.deinit();
    var run8_cg = CodeGen.init(alloc, undefined, &type_map, null, &run8_aw.writer, 0, null, null);
    run8_cg.indent = 1;
    try run8_cg.emit_run_len_inline_body("n", "aabbccddeeffgghh", .i64);
    try testing.expect(std.mem.indexOf(u8, run8_aw.written(), "n * 7 + (n - 1) * 1 + 1") != null);
}

// The test "matmul specialization removes redundant repetitions" was here. It
// asserted that emit_matmul_native_body printed `__mm_col_a` / `__mm_row_b` --
// the row/column sums of a 200x200 problem filled with `i % 100` and
// `(i * 7) % 100`, four constants the detector never read. Changing the b fill
// to `(i * 5) % 100` made reference C report 18810000000 while Duo returned
// 19602000000, the unperturbed benchmark's answer. The emitter is gone; there
// is nothing left to assert about it.

// The test "life specialization keeps generalized simulation body" was here.
// "Generalized" was only true of the Life RULE: the board was fixed at 128x128
// and seeded from `(i * 31337) % 3 == 0`, all four constants frozen. Changing
// the seed to `% 4` made reference C report 980 while Duo returned 170. The
// emitter is gone.

test "interpolation specialization uses recurrence instead of per-iteration fmod" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var type_map = sema.TypeMap.init(alloc);
    defer type_map.deinit();
    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &type_map, null, &aw.writer, 0, null, null);
    cg.indent = 1;

    try cg.emit_interp_inline_body("n", .f64);
    const output = aw.written();
    try testing.expect(std.mem.indexOf(u8, output, "fmod(") == null);
    try testing.expect(std.mem.indexOf(u8, output, "while (__is_remaining > 0)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "int64_t __is_chunk") != null);
    try testing.expect(std.mem.indexOf(u8, output, "__is_step * __is_m * (__is_m - 1.0) * 0.5") != null);
    try testing.expect(std.mem.indexOf(u8, output, "x += __is_step * __is_m;") != null);
    try testing.expect(std.mem.indexOf(u8, output, "if (x >= __is_period) x -= __is_period;") != null);
    try testing.expect(std.mem.indexOf(u8, output, "for (int64_t i = 0; i < n; ++i)") == null);
}

