test "codegen: typed string transformations lower to native C-string helpers" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\local s: str = "Hello World"
        \\local l: str = string.lower(s)
        \\local u: str = string.upper(s)
        \\local r: str = string.reverse(s)
        \\local sub1: str = string.sub(s, 2, 5)
        \\local sub2: str = s:sub(7)
        \\local sub3: str = string.lower(s):sub(3, 8)
        \\print(l, u, r, sub1, sub2, sub3)
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();
    // The typed path moved off lua_str_*_cstr onto duo_str_*_cstr, which is
    // STRICTLY more native: the lua_ helpers round-trip through
    // lua_val_from_str_len/lua_to_str, the duo_ ones are plain C on char*. The
    // old names still exist in the prelude, so asserting them would have kept
    // passing on a definition the typed path no longer calls. Verified by value:
    // the fixture prints `hello world / HELLO WORLD / dlroW olleH / ello / World
    // / llo wo`.
    try testing.expect(std.mem.indexOf(u8, output, "duo_str_lower_cstr(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_str_upper_cstr(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_str_reverse_cstr(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_str_sub_cstr(") != null);
    try testing.expect(std.mem.indexOf(u8, output, "duo_str_sub_cstr(duo_str_lower_cstr(s), (int64_t)(3), (int64_t)(8))") != null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_str_lower(lua_val_from_str") == null);
    try testing.expect(std.mem.indexOf(u8, output, "lua_to_str(lua_str_lower") == null);
}

test "codegen: gap[021] native and/or yields the operand, not a C boolean" {
    const Lexer = @import("lexer.zig").Lexer;
    const Parser = @import("parser.zig").Parser;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    var lex = Lexer.init(
        \\local a: f64 = 2.5
        \\local r: f64 = a or 1.5
        \\local n: i64 = 7
        \\local j: i64 = n or 3
        \\local u: f64 = a and 4.25
        \\print(r, j, u)
    , "test");
    var parser = Parser.init(&lex, alloc);
    var module = try parser.parse_module();
    var semantic = sema.Sema.init(alloc);
    defer semantic.deinit();
    try semantic.check_module(&module);

    var aw: std.Io.Writer.Allocating = .init(alloc);
    defer aw.deinit();
    var cg = CodeGen.init(alloc, undefined, &semantic.type_map, &semantic.module_globals, &aw.writer, semantic.next_closure_id, &semantic.table_field_types, &semantic.concepts);
    try cg.emit_module(&module);
    const output = aw.written();
    // A native numeric is always truthy (B-2), so `or` IS the left operand and
    // `and` IS the right one. C's `||`/`&&` would have collapsed both to 1.
    try testing.expect(std.mem.indexOf(u8, output, "(a || 1.5e0)") == null);
    try testing.expect(std.mem.indexOf(u8, output, "(n || 3)") == null);
    try testing.expect(std.mem.indexOf(u8, output, "(a && 4.25e0)") == null);
    try testing.expect(std.mem.indexOf(u8, output, "double r = (a)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "int64_t j = (n)") != null);
    try testing.expect(std.mem.indexOf(u8, output, "double u = ((void)(a), (4.25e0))") != null);
}

